قَالَ أبو داود: الصَّحِيحُ قَوْلُ ابْنِ عُمَرَ، لَيْسَ بِمَرْفُوعٍ. (خ,د)', 'ഇബ്നുഉമർ(റ): അദ്ദേഹം നിസ്കാരത്തിൽ പ്രവേശിക്കുമ്പോൾ തക്ബീർ ചൊല്ലുകയും കൈകൾ ഉയർത്തുകയും ചെയ്യുമായിരുന്നു. റുകൂഇലേക്കു പോകുമ്പോഴും, ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നു പറയുമ്പോഴും രണ്ട് റക്അത്തുകൾ കഴിഞ്ഞ് എഴുന്നേൽക്കുമ്പോഴും അദ്ദേഹം തന്റെ ഇരുകൈകളും ഉയർത്തും. അക്കാര്യം തരുമേനി(സ)യിലേക്ക് അദ്ദേഹം ചേർത്തിപ്പറയും. അബുദാവൂദ് പറയുന്നു: ഇത് ഇബ്നുഉമറിന്റെ വാക്കാണ് എന്നതാണ് ശരിയായത്. നബി(സ)യിലേക്ക് ചേർത്തപ്പെട്ടിട്ടില്ല. (ബു,ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['خ','د']::text[], array['ബു','ദ']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
