insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 1, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ رَفَعَ يَدَيْهِ حَتَّى تَكُونَ حَذْوَ مَنْكِبَيْهِ، ثُمَّ كَبَّرَ وَهُمَا كَذَلِكَ فَيَرْكَعُ، ثُمَّ إِذَا أَرَادَ أَنْ يَرْفَعَ صُلْبَهُ، رَفَعَهُمَا حَتَّى تَكُونَ حَذْوَ مَنْكِبَيْهِ، ثُمَّ قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". وَلَا يَرْفَعُ فِي السُّجُودِ، وَيَرْفَعُهُمَا فِي كُلِّ تَكْبِيرَةٍ يُكَبِّرُهَا قَبْلَ الرُّكُوعِ حَتَّى تَنْقَضِيَ صَلَاتُهُ. (ق,د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) നിസ്കാരത്തിനു നിന്നാൽ തന്റെ കൈകൾ തോളറ്റം വരെ ഉയർത്തും. അപ്രകാരംതന്നെ തക്ബീർ ചൊല്ലി റുകൂഅ് നിർവ്വഹിക്കും. തന്റെ മുതുക് ഉയർത്താനുദ്ദേശിക്കുമ്പോഴും കൈ ചുമലിനു നേരെയാകുംവരെ ഉയർത്തും. എന്നിട്ട് ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്നു പറയും, സുജൂദിൽ ഉയർത്താറില്ല. നിസ്കാരം കഴിയുന്നതുവരെ റുകൂഇന്ന് മുമ്പുള്ള എല്ലാ തക്ബീറുകളിലും നബി(സ) അപ്രകാരം ഉയർത്തിയിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 2, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ إِذَا كَبَّرَ رَفَعَ يَدَيْهِ، ثُمَّ الْتَحَفَ، ثُمَّ أَخَذَ شِمَالَهُ بِيَمِينِهِ، وَأَدْخَلَ يَدَيْهِ فِي ثَوْبِهِ، قَالَ: فَإِذَا أَرَادَ أَنْ يَرْكَعَ أَخْرَجَ يَدَيْهِ، ثُمَّ رَفَعَهُمَا، وَإِذَا أَرَادَ أَنْ يَرْفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَ يَدَيْهِ، ثُمَّ سَجَدَ. وَوَضَعَ وَجْهَهُ بَيْنَ كَفَّيْهِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ أَيْضًا رَفَعَ يَدَيْهِ، حَتَّى فَرَغَ مِنْ صَلَاتِهِ. وَفِي رِوَايَةٍ: لَمْ يَذْكُرِ الرَّفْعَ مَعَ الرَّفْعِ مِنَ السُّجُودِ. (د)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. നബി(സ) തക്ബീർ ചൊല്ലുമ്പോൾ കൈ ഉയർത്തിയിരുന്നു. പിന്നെ താഴ്ത്തി, ഇടതു കൈ വലത്തേത് കൊണ്ട് പിടിച്ചു കൈ രണ്ടും വസ്ത്രത്തിനുള്ളിൽ പ്രവേശിപ്പിച്ചു. റുകൂഅ് ചെയ്തപ്പോൾ കൈ പുറത്തെടുത്ത് വീണ്ടും ഉയർത്തി. റുകൂഇൽ നിന്ന് ഉയരുമ്പോഴും കൈ ഉയർത്തി. പിന്നെ സുജൂദ് ചെയ്തു. അപ്പോൾ മുഖം മുൻകൈകൾക്കിടയിലായി വെച്ചു. സുജൂദിൽ നിന്ന് തല ഉയർത്തിയപ്പോൾ വീണ്ടും കൈ ഉയർത്തി. നിസ്കാരത്തിൽ നിന്ന് വിരമിക്കും വരെ (ഇപ്രകാരം ചെയ്തു). മറ്റൊരു റിപ്പോർട്ടിൽ: സുജൂദിൽ നിന്നുയർത്തലിന്റെ കൂടെ കൈ ഉയർത്തൽ പറഞ്ഞിട്ടില്ല. (ദ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=2), 1, 'وَفِي رِوَايَةٍ: لَمْ يَذْكُرِ الرَّفْعَ مَعَ الرَّفْعِ مِنَ السُّجُودِ. (د)', 'മറ്റൊരു നിവേദനിൽ: സുജൂദിൽ നിന്നുയർത്തലിന്റെ കൂടെ കൈ ഉയർത്തൽ പറഞ്ഞിട്ടില്ല. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 3, 'عَنْ وَائِلٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ أَبْصَرَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ قَامَ إِلَي الصَّلَاةِ: رَفَعَ يَدَيْهِ حَتَّى كَانَتَا بِحَيَالِ مَنْكِبَيْهِ، وَحَاذَي بِابْهَامَيْهِ أُذُنَيْهِ، ثُمَّ كَبَّرَ. وَفِي رِوَايَةٍ: أَنَّهُ رَأَي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُ يَدَيْهِ مَعَ التَّكْبِيرَةِ. (د)', 'വാഇൽ(റ): നബി(സ) നിസ്കാരത്തിൽ രണ്ട് കൈകളും തോൾ വരെ ഉയർത്തി. ചൂണ്ടുവിരലുകൾ ചെവിക്കുനേരെയാക്കി. പിന്നെ തക്ബീർ ചൊല്ലി. മറ്റൊരു റിപ്പോർട്ടിൽ: നബി(സ) തക്ബീറിൽ കൈ ഉയർത്തുന്നത് അദ്ദേഹം കണ്ടിട്ടുണ്ട്. (ദ)', 'وَائِلٍ', 'വാഇൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 439, 439, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=3), 1, 'وَفِي رِوَايَةٍ: أَنَّهُ رَأَي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُ يَدَيْهِ مَعَ التَّكْبِيرَةِ. (د)', 'മറ്റൊരു നിവേദനിൽ: നബി(സ) തക്ബീറിൽ കൈ ഉയർത്തുന്നത് അദ്ദേഹം കണ്ടിട്ടുണ്ട്. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 4, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: لَأَنْظُرَنَّ إِلَى صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَيْفَ يُصَلِّي، قَالَ: فَقَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاسْتَقْبَلَ الْقِبْلَةَ، فَكَبَّرَ فَرَفَعَ يَدَيْهِ حَتَّى حَاذَتَا أُذُنَيْهِ، ثُمَّ أَخَذَ شمالُه بيمينه، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ رَفَعَهُمَا مِثْلَ ذَلِكَ، ثُمَّ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا مِثْلَ ذَلِكَ، فَلَمَّا سَجَدَ وَضَعَ رَأْسَهُ بِذَلِكَ الْمَنْزِلِ مِنْ بَيْنِ يَدَيْهِ، ثُمَّ جَلَسَ: فَافْتَرَشَ رِجْلَهُ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَحَدَّ مِرْفَقَهُ الْأَيْمَنَ عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ ثِنْتَيْنِ وَحَلَّقَ حَلْقَةً، وَرَأَيْتُهُ يَقُولُ هَكَذَا: وَحَلَّقَ بِشْرٌ الْإِبْهَامَ وَالْوُسْطَى وَأَشَارَ بِالسَّبَّابَةِ.
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=4), 1, 'وَفِي رِوَايَةٍ: ثُمَّ وَضَعَ يَدَهُ الْيُمْنَى عَلَى ظَهْرِ كَفِّهِ الْيُسْرَى وَالرُّسْغِ وَالسَّاعِدِ، وَقَالَ فِيهِ: ثُمَّ جِئْتُ بَعْدَ ذَلِكَ فِي زَمَانٍ فِيهِ بَرْدٌ شَدِيدٌ، فَرَأَيْتُ النَّاسَ عَلَيْهِمْ جُلُّ الثِّيَابِ، تَحَرَّكُ أَيْدِيهِمْ تَحْتَ الثِّيَابِ. (د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: വലതുകൈ ഇടത് കൈയ്യിന്റെ പുറകിലും, മണിബന്ധത്തിലും മുഴംകൈയിലും വെക്കും. അതിനുശേഷം തണുപ്പുള്ള സമയത്ത് ജനങ്ങൾ വസ്ത്രം കൊണ്ട് പൊതിഞ്ഞതായി ഞാൻ കണ്ടു, വസ്ത്രങ്ങൾക്കുള്ളിൽ വെച്ച് അവരുടെ കൈകൾ വിറക്കുന്നുണ്ടായിരുന്നു. (ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 5, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَفَعَ يَدَيْهِ فِي صَلَاتِهِ، وَإِذَا رَكَعَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، وَإِذَا سَجَدَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ، حَتَّى يُحَاذِيَ بِهِمَا فُرُوعَ أُذُنَيْهِ. وَفِي رِوَايَةٍ: كَانَ إِذَا دَخَلَ فِي الصَّلَاةِ فَذَكَرَ نَحْوَهُ، وَزَادَ فِيهِ: وَإِذَا رَكَعَ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ فَعَلَ مِثْلَ ذَلِكَ. (ق,د,ن,جه)', 'മാലികുബ്നുൽ ഹുവൈരിഥ്(റ): നബി(സ) നിസ്കാരത്തി(ന്റെ ആരംഭത്തി)ൽ തന്റെ ഇരുകൈകളും ചെവിക്കുറ്റിക്കു നേരെയാകും വിധം ഉയർത്തുന്നതു ഞാൻ കണ്ടു. റുകൂഇലേക്കു പോയപ്പോഴും, റുകൂഇൽ നിന്ന് തലയുയർത്തിയപ്പോഴും, സുജൂദിലേക്കു പോയപ്പോഴും, സുജൂദിൽനിന്നു തലയുയർത്തിയപ്പോഴും, അപ്രകാരം ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ: തിരുമേനി(സ) നിസ്കാരത്തിൽ പ്രവേശിച്ചപ്പോൾ...... മേലുദ്ധരിച്ച ഹദീസ് പറഞ്ഞു........ അതിൽ ഇപ്രകാരം അധികം വന്നിട്ടുണ്ട്. റുകൂഇലേക്കു പോയപ്പോൾ അപ്രകാരം ചെയ്തു. റുകൂഇൽ നിന്ന് തലയുർത്തിയപ്പോഴും അപ്രകാരം ചെയ്തു. സുജൂദിൽ നിന്ന് തലയുർത്തിയപ്പോൾ അപ്രകാരം ചെയ്തു. (ബു,മു,ദ,ന,ജ)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിഥ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 440, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=5), 1, 'وَفِي رِوَايَةٍ: كَانَ إِذَا دَخَلَ فِي الصَّلَاةِ فَذَكَرَ نَحْوَهُ، وَزَادَ فِيهِ: وَإِذَا رَكَعَ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ فَعَلَ مِثْلَ ذَلِكَ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: തിരുമേനി(സ) നിസ്കാരത്തിൽ പ്രവേശിച്ചപ്പോൾ...... മേലുദ്ധരിച്ച ഹദീസ് പറഞ്ഞു........ അതിൽ ഇപ്രകാരം അധികം വന്നിട്ടുണ്ട്. റുകൂഇലേക്കു പോയപ്പോൾ അപ്രകാരം ചെയ്തു. റുകൂഇൽ നിന്ന് തലയുർത്തിയപ്പോഴും അപ്രകാരം ചെയ്തു. സുജൂദിൽ നിന്ന് തലയുർത്തിയപ്പോൾ അപ്രകാരം ചെയ്തു. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 6, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حِينَ افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ حِيَالَ أُذُنَيْهِ، قَالَ: ثُمَّ أَتَيْتُهُمْ فَرَأَيْتُهُمْ يَرْفَعُونَ أَيْدِيَهُمْ إِلَى صُدُورِهِمْ فِي افْتِتَاحِ الصَّلَاةِ، وَعَلَيْهِمْ بَرَانِسُ وَأَكْسِيَةٌ . (د,ن)', 'വാഇലുബ്നു ഹുജർ(റ): നിസ്കാരം തുടങ്ങുമ്പോൾ നബി(സ) തന്റെ കൈകൾ ചെവിക്കുറ്റി വരെ ഉയർത്തുന്നത് ഞാൻ കണ്ടു. പിന്നെ ഞാനവരെ സമീപിച്ചപ്പോൾ കൈകൾ അവരുടെ നെഞ്ച് വരെ ഉയർത്തുന്നത് ഞാൻ കണ്ടു. (കാരണം) അവരുടെ മേലിൽ പുതപ്പുകളുണ്ടായിരുന്നു. (ദ,ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജർ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 440, 440, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 7, 'عَنْ مُطَرِّف قَالَ: صَلَّيْتُ أَنَا وَعِمْرَانُ ابْنُ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا خَلْفَ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ، فَكَانَ إِذَا سَجَدَ كَبَّرَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ كَبَّرَ، وَإِذَا نَهَضَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ، فَلَمَّا قَضَى أَخَذَ عِمْرَانُ بِيَدِي فَقَالَ: لَقَدْ ذَكَّرَنِي هَذَا قَالَ كَلِمَةً يَعْنِي صَلَاةَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'മുത്വാരിഫ്: ഞാനും ഇംറാനുബ്നു ഹുസൈൻ(റ)വും അലി(റ)യുടെ പിറകിൽ നിസ്കരിച്ചു. അദ്ദേഹം സുജൂദിലേക്കു പോയപ്പോൾ തക്ബീർ ചൊല്ലി. സുജൂദിൽ നിന്ന് തല ഉയർത്തിയപ്പോൾ തക്ബീർ ചൊല്ലി. രണ്ട് റക്അത്ത് നിർവ്വഹിച്ച ശേഷം ഉയർന്നപ്പോഴും തക്ബീർ ചൊല്ലി. നിസ്കാരം കഴിഞ്ഞപ്പോൾ എന്റെ കൈക്കു പിടിച്ചു കൊണ്ട് ഇംറാൻ പറഞ്ഞു: ഇത് എന്നെ ഇക്കാര്യം - അതായത് നബി(സ)യുടെ നമസ്കാരത്തെ - ഓർമിപ്പിച്ചു. (ന)', 'مُطَرِّف قَالَ', 'മുത്വാരിഫ്', null, null, array['ن']::text[], array['ന']::text[], null, null, 440, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 8, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكَبِّرُ فِي كُلِّ خَفْضٍ وَرَفْعٍ، وَيُسَلِّمُ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ، وَكَانَ أَبُو بَكْرٍ وَعُمَرُ رَضِيَ اللهُ عَنْهُمَا يَفْعَلَانِهِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ ഓരോ പ്രാവശ്യം ഉയരുമ്പോഴും താഴുമ്പോഴും തക്ബീർ ചൊല്ലും. അവിടുന്ന് തന്റെ വലത്തോട്ടും ഇടത്തോട്ടും സലാം ചൊല്ലും. അബൂബക്കറും(റ) ഉമറും(റ) ഇപ്രകാരം തന്നെ ചെയ്തു. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=1 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 9, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ وَرَفَعَ يَدَيْهِ. (د)', 'ഇബ്നുഉമർ(റ): നബി(സ) രണ്ട് റക്അത്തിന് ശേഷം എഴുന്നേൽക്കുമ്പോൾ തക്ബീർ ചൊല്ലുകയും കൈ ഉയർത്തുകയും ചെയ്തിരുന്നു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 10, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ كَانَ إِذَا قَامَ إِلَى الصَّلَاةِ الْمَكْتُوبَةِ كَبَّرَ وَرَفَعَ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ، وَيَصْنَعُ مِثْلَ ذَلِكَ إِذَا قَضَى قِرَاءَتَهُ وَأَرَادَ أَنْ يَرْكَعَ، وَيَصْنَعُهُ إِذَا رَفَعَ مِنَ الرُّكُوعِ، وَلَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ صَلَاتِهِ وَهُوَ قَاعِدٌ، وَإِذَا قَامَ مِنَ السَّجْدَتَيْنِ رَفَعَ يَدَيْهِ كَذَلِكَ وَكَبَّرَ. (د,ت,ن,جه)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ) ഫർള് നിസ്കാരം നിർവ്വഹിക്കാൻ വേണ്ടി എഴുന്നേറ്റാൽ തക്ബീർ ചൊല്ലി രണ്ട് ചുമലറ്റം വരെ കൈ ഉയർത്തിയിരുന്നു. ഖുർആൻ പാരായണശേഷം റുകൂഇലേക്ക് പോകുമ്പോഴും അപ്രകാരം ചെയ്തിരുന്നു. റുകൂഇൽ നിന്ന് ഉയരുമ്പോഴും അത് ആവർത്തിച്ചു. ഇരിക്കുന്ന അവസ്ഥയിൽ ഒരിക്കലും കൈ ഉയർത്തിയിരുന്നില്ല. സുജൂദിൽ നിന്ന് എഴുന്നേൽക്കുമ്പോഴും അപ്രകാരം തക്ബീർ ചൊല്ലി കൈ ഉയർത്തിയിരുന്നു. (ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 11, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: لَوْ كُنْتُ قُدَّامَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَرَأَيْتُ إِبِطَيْهِ، يَعْنِي إِذَا كَبَّرَ رَفَعَ يَدَيْهِ. (د,ن)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)ക്ക് മുൻഭാഗത്തായിരുന്നെങ്കിൽ എനിക്ക് നബി(സ)യുടെ ഇരുകക്ഷങ്ങളും കാണുമായിരുന്നു. തക്ബീർ ചൊല്ലുമ്പോൾ കൈ ഉയർത്തുന്ന (അവസരത്തിൽ നബി(സ)യുടെ ഇരു കക്ഷങ്ങളും കാണുന്ന)തിനെയാണ് ഉദ്ദേശിച്ചത്. (ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 12, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَلَا أُصَلِّي بِكُمْ صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: فَصَلَّى فَلَمْ يَرْفَعْ يَدَيْهِ إِلَّا مَرَّةً. قَالَ أبو دَاود: وَلَيْسَ هُوَ بصَحِيحٍ عَلَى هَذَا اللَّفْظِ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബിനു മസ്ഊദ്(റ): ഞാൻ നിങ്ങൾക്ക് നബി(സ)യുടെ നിസ്കാരം കാണിച്ചുതരട്ടെയോ? അങ്ങനെ അദ്ദേഹം നിസ്കരിച്ചു. ഒരിക്കലല്ലാതെ അദ്ദേഹം കൈ ഉയർത്തിയില്ല. (അബൂദാവൂദ് പറഞ്ഞു: ഈ വചനത്തിലൂടെയുള്ള ഈ ഹദീസ് സഹീഹല്ല.) (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബിനു മസ്ഊദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 441, 441, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 13, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا افْتَتَحَ الصَّلَاةَ رَفَعَ يَدَيْهِ إِلَى قَرِيبٍ مِنْ أُذُنَيْهِ، ثُمَّ لَا يَعُودُ. وَفِي رِوَايَةٍ: لَمْ يَقُلْ: ثُمَّ لَا يَعُودُ. وَفِي رِوَايَةٍ: فَرَفَعَ يَدَيْهِ فِي أَوَّلِ مَرَّةٍ. (د)', 'ബറാഅ്(റ): നബി(സ) നിസ്കാരം ആരംഭിക്കുമ്പോൾ ചെവിയുടെ അടുത്തുവരെ കൈ ഉയർത്താറുണ്ടായിരുന്നു. പിന്നീട് അത് ആവർത്തിക്കാറില്ല. മറ്റൊരു നിവേദനത്തിൽ പിന്നീടത് ആവർത്തിക്കാറില്ലെന്ന് പറഞ്ഞിട്ടില്ല. മറ്റൊരു റിപ്പോർട്ടിൽ: ഒന്നാം പ്രാവശ്യം നബി(സ) കൈ ഉയർത്തി. (ദ)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=13), 1, 'وَفِي رِوَايَةٍ: لَمْ يَقُلْ: ثُمَّ لَا يَعُودُ.', 'മറ്റൊരു നിവേദനത്തിൽ പിന്നീടത് ആവർത്തിക്കാറില്ലെന്ന് പറഞ്ഞിട്ടില്ല.');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=13), 2, 'وَفِي رِوَايَةٍ: فَرَفَعَ يَدَيْهِ فِي أَوَّلِ مَرَّةٍ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഒന്നാം പ്രാവശ്യം നബി(സ) കൈ ഉയർത്തി. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 14, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَفَعَ يَدَيْهِ حِينَ افْتَتَحَ الصَّلَاةَ، ثُمَّ لَمْ يَرْفَعْهُمَا حَتَّى انْصَرَفَ. قَالَ أبو داود: هَذَا الْحَدِيثُ لَيْسَ بصَحِيح. (د)', 'ബറാഅ്ബിൻ ആസിബ്(റ): നബി(സ) നിസ്കാരത്തിന്റെ തുടക്കത്തിൽ കൈ ഉയർത്തുന്നത് ഞാൻ കണ്ടു. പിന്നീട് കഴിയുന്നവരെ അവ രണ്ടും ഉയർത്താറില്ല. (ഈ ഹദീസ് സഹീഹല്ലെന്ന് അബൂദാവൂദ് പ്രസ്താവിച്ചിട്ടുണ്ട്). (ദ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ്ബിൻ ആസിബ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 15, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ فِي الصَّلَاةِ رَفَعَ يَدَيْهِ مَدًّا. (د,ت,ن)', 'അബീഹുറൈറ(റ): റസൂൽ(സ) നിസ്കാരത്തിൽ പ്രവേശിക്കുമ്പോൾ തന്റെ കൈ നീട്ടികൊണ്ട് ഉയർത്തുമായിരുന്നു. (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബീഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=2 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 16, 'عَنْ أَبِي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ عَلِيًّا رَضِيَ اللهُ عَنْهُ قَالَ: مِنَ السُّنَّةِ وَضْعُ الْكَفِّ عَلَى الْكَفِّ فِي الصَّلَاةِ تَحْتَ السُّرَّةِ. (د)', 'അബൂജുഹൈഫ(റ): അലി(റ)പറഞ്ഞു: നിസ്കാരത്തിൽ മുൻകൈ മറ്റേ മുൻകയ്യിന് മുകളിൽ പൊക്കിളിന് താഴെ വെക്കൽ നബിചര്യയിൽ പെട്ടതാണ്. (ദ)', 'أَبِي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 17, 'عَنْ جَرِيرٍ الضَّبِّيِّ قَالَ: رَأَيْتُ عَلِيًّا رَضِيَ اللهُ عَنْهُ يُمْسِكُ شِمَالَهُ بِيَمِينِهِ عَلَى الرُّسْغِ فَوْقَ السُّرَّةِ. (د)', 'ജരീരുള്ളബിയ്യ്(റ): അലി(റ) തന്റെ ഇടത്തെ കൈ വലത്തെതിനെ കൊണ്ട് മണിബന്ധത്തിൽ പിടിച്ച് പൊക്കിളിന്നു മേലെ വെക്കുന്നത് ഞാൻ കണ്ടു. (ദ)', 'جَرِيرٍ الضَّبِّيِّ قَالَ', 'ജരീരുള്ളബിയ്യ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 442, 442, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 18, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ: لَأَنْظُرَنَّ إِلَى صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَيْفَ يُصَلِّي. فَنَظَرْتُ إِلَيْهِ: فَقَامَ فَكَبَّرَ، وَرَفَعَ يَدَيْهِ حَتَّى حَاذَتَا بِأُذُنَيْهِ، ثُمَّ وَضَعَ يَدَهُ الْيُمْنَى عَلَى كَفِّهِ الْيُسْرَى وَالرُّسْغِ وَالسَّاعِدِ، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ رَفَعَ يَدَيْهِ مِثْلَهَا، قَالَ: وَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، ثُمَّ لَمَّا رَفَعَ رَأْسَهُ رَفَعَ يَدَيْهِ مِثْلَهَا، ثُمَّ سَجَدَ، فَجَعَلَ كَفَّيْهِ بِحِذَاءِ أُذُنَيْهِ، ثُمَّ قَعَدَ وَافْتَرَشَ رِجْلَهُ الْيُسْرَى، وَوَضَعَ كَفَّهُ الْيُسْرَى عَلَى فَخِذِهِ وَرُكْبَتِهِ الْيُسْرَى، وَجَعَلَ حَدَّ مِرْفَقِهِ الْأَيْمَنِ عَلَى فَخِذِهِ الْيُمْنَى، ثُمَّ قَبَضَ اثْنَتَيْنِ مِنْ أَصَابِعِهِ وَحَلَّقَ حَلْقَةً، ثُمَّ رَفَعَ إِصْبَعَهُ، فَرَأَيْتُهُ يُحَرِّكُهَا يَدْعُو بِهَا. (ن)', 'വാഇലുബ്നു ഹുജ്ർ: ഞാനൊരിക്കൽ പറഞ്ഞു: തിരുമേനി(സ) എങ്ങനെയാണ് നിസ്ക്കരിക്കുന്നതെന്ന് ഞാൻ നിരീക്ഷിക്കുക തന്നെ ചെയ്യും. അങ്ങനെ ഞാൻ തിരുമേനിയുടെ നിസ്കാരം നിരീക്ഷിച്ചു. തിരുമേനി(സ) എഴുന്നേറ്റ് തക്ബീർ ചൊല്ലുകയും, തന്റെ ഇരുകൈകൾ ചെവികൾക്ക് നേരെ ഉയർത്തുകയും ചെയ്തു. പിന്നീട് തന്റെ വലതു കൈ ഇടതു കയ്യിന്മേൽ വെച്ചു. അവിടുന്ന് റുകൂഇലേക്കു പോയപ്പോൾ തക്ബീറത്തുൽ ഇഹ്റാമിലേതുപോലെ കൈകളുയർത്തുകയും ചെയ്തു. (റുകൂഅ് ചെയ്തപ്പോൾ) തന്റെ ഇരു കൈപ്പടങ്ങളും ഇരു കാൽമുട്ടുകളിന്മേൽ വെച്ചു. അവിടുന്ന് തല ഉയർത്തിയപ്പോൾ ഇരുകൈകൾ ആദ്യത്തേതുപോലെ ഉയർത്തി. പിന്നെ സുജൂദിലേക്ക് പോയി. അപ്പോൾ അവിടുത്തെ ഇരു കൈപ്പടങ്ങൾ തന്റെ ചെവിക്കുനേരെയായി വെച്ചു. പിന്നെ ഇരിക്കുകയും ഇടതുകാൽ പരത്തിവെക്കുകയും ചെയ്തു. തന്റെ ഇടതു കൈ തന്റെ ഇടുതു കാൽ മുട്ടിന്മേലും തുടക്കുമേലുമായി വെക്കുകയും വലതു കൈ വലത്തെ തുടക്കുമേലായി വെക്കുകയും രണ്ടു വിരലുകൾ പിടിക്കുകയും വൃത്താകൃതിയിൽ ആക്കുകയും ചൂണ്ടുവിരൽ ഉയർത്തിപ്പിടിക്കുകയും ചെയ്തു. അതിനെ തിരുമേനി(സ) (ചൂണ്ടുവിരൽ) ചലിപ്പിക്കുന്നതായും അതുകൊണ്ട് പ്രാർത്ഥിക്കുന്നതായും ഞാൻ കണ്ടു. (ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ', null, null, array['ن']::text[], array['ന']::text[], null, null, 442, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 19, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَخْذُ الْأَكُفِّ عَلَى الْأَكُفِّ فِي الصَّلَاةِ تَحْتَ السُّرَّةِ. (د)', 'അബൂഹുറൈറ(റ): നിസ്കാരത്തിൽ ഒരു കൈപ്പടം കൊണ്ട് മറ്റൊന്നിനു മേലെയായി പിടിച്ച് കൊണ്ട് പൊക്കിളിന്ന് താഴെയാണ് കൈ കെട്ടേണ്ടത്. (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 20, 'عَنْ طَاوُسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضَعُ يَدَهُ الْيُمْنَى عَلَى الْيُسْرَى، ثُمَّ يَشُدُّ بَيْنَهُمَا عَلَى صَدْرِهِ، وَهُوَ فِي الصَّلَاةِ. (د)', 'ത്വാവൂസ്(റ): നബി(സ) വലതു കൈ ഇടതു കയ്യിനു മീതെ വെച്ചു. പിന്നെ അവ നെഞ്ചിന്മേൽ വെച്ചു. നിസ്കാരത്തിൽ ഇപ്രകാരമാണ് ചെയ്തത്. (ദ)', 'طَاوُسٍ', 'ത്വാവൂസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 21, 'عَنْ هُلْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَؤُمُّنَا، فَيَأْخُذُ شِمَالَهُ بِيَمِينِهِ. (ت,جه)', 'ഹുൽബ്(റ): നബി(സ) ഞങ്ങൾക്ക് ഇമാമാകുമ്പോൾ തന്റെ ഇടതു കൈ വലതുകൈ കൊണ്ട് പിടിക്കാറുണ്ട്. (തു,ജ)', 'هُلْبٍ', 'ഹുൽബ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 22, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ بِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَنَا وَاضِعٌ يَدِي الْيُسْرَى عَلَى الْيُمْنَى، فَأَخَذَ بِيَدِي الْيُمْنَى فَوَضَعَهَا عَلَى الْيُسْرَى. (د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞാൻ നിസ്കരിക്കുമ്പോൾ നബി(സ) എന്റെ അരികിലൂടെ നടന്നു. ഞാനാകട്ടെ, അന്നേരം എന്റെ ഇടതു കൈ വലതു കൈയുടെ മുകളിൽ വെച്ചിരുന്നു. അപ്പോൾ നബി(സ) എന്റെ വലതു കൈ എടുക്കുകയും എന്നിട്ട് അതിനെ ഇടത് കൈയുടെ മുകളിൽ വെക്കുകയും ചെയ്തു. (ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=3 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 23, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الشِّتَاءِ، فَرَأَيْتُ أَصْحَابَهُ يَرْفَعُونَ أَيْدِيَهُمْ فِي ثِيَابِهِمْ فِي الصَّلَاةِ. (د)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ ശൈത്യകാലത്ത് പ്രവാചക(സ)ന്റെ അടുത്ത് ചെന്നു. തിമേനിയുടെ അനുചരന്മാർ (തണുപ്പിന്റെ കാഠിന്യത്താൽ) നിസ്കാരത്തിൽ അവരുടെ വസ്ത്രങ്ങൾക്കുള്ളിലായി അവരുടെ കൈകൾ ഉയർത്തുന്നത് ഞാൻ കണ്ടു. (ദ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 443, 443, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 24, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ – فِي عَشْرَةٍ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْهُمْ أَبُو قَتَادَةَ – قَالَ أبو حُمَيْد: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالُوا: فَلِمَ؟ فَوَاللهِ مَا كُنْتَ بِأَكْثَرِنَا لَهُ تَبَعَةً وَلَا أَقْدَمِنَا لَهُ صُحْبَةً. قَالَ: بَلَى، قَالُوا: فَاعْرِضْ. قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ يَرْفَعُ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ، ثُمَّ يُكَبِّرُ حَتَّى يَقِرَّ كُلُّ عَظْمٍ فِي مَوْضِعِهِ مُعْتَدِلًا، ثُمَّ يَقْرَأُ، ثُمَّ يُكَبِّرُ، فَيَرْفَعُ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ، ثُمَّ يَرْكَعُ وَيَضَعُ رَاحَتَيْهِ عَلَى رُكْبَتَيْهِ، ثُمَّ يَعْتَدِلُ فَلَا يَصُبُّ رَأْسَهُ وَلَا يُقْنِعُ، ثُمَّ يَرْفَعُ رَأْسَهُ فَيَقُولُ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". ثُمَّ يَرْفَعُ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ مُعْتَدِلًا، ثُمَّ يَقُولُ: "اللهُ أَكْبَرُ". ثُمَّ يَهْوِي إِلَى الْأَرْضِ فَيُجَافِي يَدَيْهِ عَنْ جَنْبَيْهِ، ثُمَّ يَرْفَعُ رَأْسَهُ وَيَثْنِي رِجْلَهُ الْيُسْرَى فَيَقْعُدُ عَلَيْهَا، وَيَفْتَحُ أَصَابِعَ رِجْلَيْهِ إِذَا سَجَدَ، وَيَسْجُدُ ثُمَّ يَقُولُ: "اللهُ أَكْبَرُ". وَيَرْفَعُ رَأْسَهُ وَيَثْنِي رِجْلَهُ الْيُسْرَى فَيَقْعُدُ عَلَيْهَا، حَتَّى يَرْجِعَ كُلُّ عَظْمٍ إِلَى مَوْضِعِهِ، ثُمَّ يَصْنَعُ فِي الْأُخْرَى مِثْلَ ذَلِكَ. ثُمَّ إِذَا قَامَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ وَرَفَعَ يَدَيْهِ حَتَّى يُحَاذِيَ بِهِمَا مَنْكِبَيْهِ، كَمَا كَبَّرَ عِنْدَ افْتِتَاحِ الصَّلَاةِ، ثُمَّ يَصْنَعُ ذَلِكَ فِي بَقِيَّةِ صَلَاتِهِ، حَتَّى إِذَا كَانَتِ السَّجْدَةُ الَّتِي فِيهَا التَّسْلِيمُ أَخَّرَ رِجْلَهُ الْيُسْرَى، وَقَعَدَ مُتَوَرِّكًا عَلَى شِقِّهِ الْأَيْسَرِ. قَالُوا: صَدَقْتَ، هَكَذَا كَانَ يُصَلِّي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (خ,د,ت,ن,جه)', 'അബൂഹുമൈദുസ്വാഇദീ(റ): അദ്ദേഹം അബൂഖത്താദ(റ)യുൾപ്പെടുന്ന തിരുമേനി(സ)യുടെ പത്ത് അനുചരന്മാരോട് പറഞ്ഞു: ''നിങ്ങളിൽ തിരുമേനി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ഏറ്റവും കൂടുതലറിയുന്നവൻ ഞാനാകുന്നു''. അവർ ചോദിച്ചു: എന്തുകൊണ്ട്? അല്ലാഹുവാണെ, താങ്കൾ ഞങ്ങളേക്കാൾ തിരുമേനി(സ)യെ പിൻതുടർന്നിട്ടില്ല. ഞങ്ങളെക്കാൾ മുമ്പായി താങ്കൾ തിരുമേനിയുമായി സഹവസിക്കാൻ തുടങ്ങിയിട്ടുമില്ല. അദ്ദേഹം പറഞ്ഞു: ''(നിങ്ങൾ പറഞ്ഞതു) ശരി''. അവർ പറഞ്ഞു: എന്നാൽ (തിരുമേനി(സ) നിസ്കരിച്ചത് എപ്രകാരമായിരുന്നുവെന്ന്) താങ്കൾ വിവരിച്ചുതരിക! തിരുമേനി(സ) നിസ്കാരത്തിനു നിന്നാൽ ഇരുകൈകളും തന്റെ ഇരുചുമലുകൾക്കുനേരെയായി വെക്കും. തന്റെ ഇരുചുമലുകൾക്കു നേരെയായിവരും വിധം ഉയർത്തും. ശേഷം തക്ബീർ ചെല്ലും. അങ്ങനെ അവിടുത്തെ ഓരോ എല്ലുകളും അതിന്റെ സ്ഥാനത്തായി നിൽക്കും. ശേഷം (ഖുർആൻ) പാരായണം ചെയ്യും. തുടർന്ന് കൈ ഇരുചുമലുകൾക്കു നേരെയാവും വിധം ഉയർത്തിക്കൊണ്ട് തക്ബീർ ചൊല്ലും. പിന്നെ റുകൂഇലേക്കും പോവുകയും ഇരുകൈകളും കൈൽമുട്ടുകളിൽമേൽ വെക്കുകയും ചെയ്യും. അതിൽ തല ഉയർത്തുകയോ താഴ്ത്തുകയോ ചെയ്യാതെ നേരെയാക്കും. പിന്നെ തല ഉയർത്തുകയും ''സമിഅല്ലാഹു ലിമൻ ഇമിദഹു'' എന്നു പറയുകയും, തന്റെ ഇരു ചുമലുൾക്കു നേരെ കൃത്യമായി വരും വിധം ഇരു കൈകളുമുയർത്തുകയും ചെയ്യും. പിന്നെ തക്ബീർ ചൊല്ലിക്കൊണ്ട് നിലത്തേക്ക് താഴുകയും (സുജൂദ് ചെയ്യുകയും) ഇരു കൈകളും തന്റെ ഇരുഭാഗത്തും അകറ്റിവെക്കുകയും ചെയ്യും. പിന്നെ തലയുയർത്തുകയും ഇടതുകാൽ വളച്ച് (കിടത്തി) വെച്ച് അതിന്മേൽ ഉരിക്കുകയും ചെയ്യും. സുജൂദു ചെയ്യുമ്പോൾ തന്റെ ഇരുകാലുകളുടെയും വിരലുകൾ തുറന്ന നിലയിൽ (വിടർത്തി) വെക്കും. അങ്ങനെ സുജൂദിലേക്കു പോവുകയും ''അല്ലാഹു അക്ബർ'' എന്നു പറയുകയും ചെയ്യും. പിന്നെ തലയുയർത്തുകയും ഇടതുകാൽ വളച്ചു വെക്കുകയും അതിന്മേൽ ഇരിക്കുകയും ചെയ്യും. അങ്ങനെ ഓരോ എല്ലും അതിന്റെതായ സ്ഥാനത്തേക്ക് തിരിച്ചുവരും. പിന്നെ മറ്റ് ഓരോന്നിലും (ഓരോ റക്അത്തിലും) ഇപ്രകാരം തന്നെ ചെയ്യും. രണ്ടു റക്അത്തുകൾ കഴിഞ്ഞ് എഴുന്നേൽക്കുമ്പോൾ, നിസ്കാരത്തിന്റെ തുടക്കത്തിൽ ചെയ്തതു പോലെ തിരുമേനി(സ) തന്റെ ചുമലുകൾക്കു നേരെയാകും വിധം ഇരുകൈകളും ഉയർത്തും. പിന്നെ തിരുമേനി(സ) തന്റെ ശേഷിക്കുന്ന നിസ്കാരത്തിലും (റക്അത്തുകളിലും) അപ്രകാരം തന്നെ ചെയ്തു. പീന്നീട് സലാം വീട്ടേണ്ട സുജൂദു ചെയ്തു കഴിഞ്ഞാൽ (അവസാനത്തെ സുജൂദ്) ഇടതുകാൽ നീക്കിവെക്കുകയും തന്റെ ഇടതുഭാഗത്തിന്മേലായി തവർറുക്കി¹ ന്റെ ഇരുത്തം ഇരിക്കുകയും ചെയ്തു. അവർ പറഞ്ഞു: താങ്കൾ സത്യം പറഞ്ഞു. തിരുമേനി(സ) ഇപ്രകാരമാണ് നിസ്കരിച്ചത്. (ബു,ദ,തു,ന,ജ)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദുസ്വാഇദീ(റ)', '¹. ഇടതു ചന്തി നിലത്തൂന്നി, വലതു പാദം നാട്ടിവെച്ച് ഇരിക്കൽ', null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 443, 444, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 25, 'عَنْ مُحَمَّدِ بْنِ عَمْرٍو الْعَامِرِيِّ قَالَ: كُنْتُ فِي مَجْلِسٍ مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَتَذَاكَرُوا صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو حُمَيْدٍ – فَذَكَرَ بَعْضَ هَذَا الْحَدِيثِ – وَقَالَ: فَإِذَا رَكَعَ أَمْكَنَ كَفَّيْهِ مِنْ رُكْبَتَيْهِ وَفَرَّجَ بَيْنَ أَصَابِعِهِ، ثُمَّ هَصَرَ ظَهْرَهُ غَيْرَ مُقْنِعٍ رَأْسَهُ وَلَا صَافِحٍ بِخَدِّهِ، وَقَالَ: فَإِذَا قَعَدَ فِي الرَّكْعَتَيْنِ قَعَدَ عَلَى بَطْنِ قَدَمِهِ الْيُسْرَى وَنَصَبَ الْيُمْنَى، فَإِذَا كَانَ فِي الرَّابِعَةِ أَفْضَى بِوَرِكِهِ الْيُسْرَى إِلَى الْأَرْضِ، وَأَخْرَجَ قَدَمَيْهِ مِنْ نَاحِيَةٍ وَاحِدَةٍ. وَفِي رِوَايَةٍ: قَالَ: فَإِذَا سَجَدَ وَضَعَ يَدَيْهِ غَيْرَ مُفْتَرِشٍ وَلَا قَابِضِهِمَا، وَاسْتَقْبَلَ بِأَطْرَافِ أَصَابِعِهِ الْقِبْلَةَ. (د)', 'മുഹമ്മദുബ്നു അംറ്(റ): ഞാൻ തിരുമേനി(സ)യുടെ അനുചരന്മാരുടെ സദസ്സിലായിരുന്നു. അന്നേരം അവർ തിരുമേനി(സ)യുടെ നിസ്കാരത്തെ സംബന്ധിച്ച് പരസ്പരം ചർച്ചചെയ്തു. - അബൂഹുമൈദ്(റ) നിവേദനം ചെയ്ത ഹദീസിൽ വന്നതുപോലെത്തന്നെ അദ്ദേഹം വിവരിച്ചു - അദ്ദേഹം ഇപ്രകാരം പറയുകയും ചെയ്തു: തിരുമേനി(സ) റുകൂഅ് ചെയ്തപ്പോൾ തന്റെ ഇരുകൈകളും മുട്ടിന്മേൽ വെക്കുകയും വിരലുകൾ വിടർത്തുകയും ചെയ്തു. തലതാഴ്ത്തുകയോ കവിൾ(മുഖം) തിരിക്കുകയോ ചെയ്യാതെ പുറം നിവർത്തിവെച്ചു. അദ്ദേഹം തുടർന്ന് പറഞ്ഞു: തിരുമേനി രണ്ടു റക്അത്തുകളുടെ അവസാനത്തിൽ ഇരുന്നപ്പോൾ തന്റെ ഇടതു പാദത്തിന്റെ പള്ളഭാഗത്തിന്മേൽ ഇരിക്കുകയും വലതുകാൽ നാട്ടിവെക്കുകയും ചെയ്തു. നാലാമത്തെ റക്അത്തായാൽ അവിടുന്ന് തന്റെ വലതുചന്തി നിലത്തോട് ചേർത്തി വെക്കുകയും ഇരുപാദങ്ങളും ഒരു ഭാഗത്തേക്കാക്കി വെക്കുകയും ചെയ്യും. മറ്റൊരു റിപ്പോർട്ടിൽ: അവിടുന്ന് സുജൂദുചെയ്യുമ്പോൾ തന്റെ ഇരുകൈകളും കിടത്താത്ത നിലയിലും, എന്നാൽ എടുക്കാത്ത നിലയിലും, വിരലറ്റങ്ങൾ ഖിബ്ലക്കഭിമുഖമാക്കിക്കൊണ്ടും വെച്ചു. (ദ)', 'مُحَمَّدِ بْنِ عَمْرٍو الْعَامِرِيِّ قَالَ', 'മുഹമ്മദുബ്നു അംറ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 444, 445, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=25), 1, 'وَفِي رِوَايَةٍ: قَالَ: فَإِذَا سَجَدَ وَضَعَ يَدَيْهِ غَيْرَ مُفْتَرِشٍ وَلَا قَابِضِهِمَا، وَاسْتَقْبَلَ بِأَطْرَافِ أَصَابِعِهِ الْقِبْلَةَ. (د)', 'മറ്റൊരു നിവേദനിൽ: അവിടുന്ന് സുജൂദുചെയ്യുമ്പോൾ തന്റെ ഇരുകൈകളും കിടത്താത്ത നിലയിലും, എന്നാൽ എടുക്കാത്ത നിലയിലും, വിരലറ്റങ്ങൾ ഖിബ്ലക്കഭിമുഖമാക്കിക്കൊണ്ടും വെച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 26, 'عَنْ عَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ: أَنَّهُ كَانَ فِي مَجْلِسٍ فِيهِ أَبُوهُ، وَكَانَ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَفِي الْمَجْلِسِ أَبُو هُرَيْرَةَ وَأَبُو حُمَيْدٍ السَّاعِدِيُّ وَأَبُو أُسَيْدٍ، بِهَذَا الْخَبَرِ يَزِيدُ أَوْ يَنْقُصُ، قَالَ فِيهِ: ثُمَّ رَفَعَ رَأْسَهُ – يَعْنِي مِنَ الرُّكُوعِ – فَقَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ، اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ". وَرَفَعَ يَدَيْهِ ثُمَّ قَالَ: "اللهُ أَكْبَرُ". فَسَجَدَ فَانْتَصَبَ عَلَى كَفَّيْهِ وَرُكْبَتَيْهِ وَصُدُورِ قَدَمَيْهِ وَهُوَ سَاجِدٌ، ثُمَّ كَبَّرَ فَجَلَسَ فَتَوَرَّكَ وَنَصَبَ قَدَمَهُ الْأُخْرَى، ثُمَّ كَبَّرَ فَسَجَدَ، ثُمَّ كَبَّرَ فَقَامَ وَلَمْ يَتَوَرَّكْ، ثُمَّ سَاقَ الْحَدِيثَ، قَالَ: ثُمَّ جَلَسَ بَعْدَ الرَّكْعَتَيْنِ، حَتَّى إِذَا هُوَ أَرَادَ أَنْ يَنْهَضَ لِلْقِيَامِ قَامَ بِتَكْبِيرَةٍ، ثُمَّ رَكَعَ الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ. وَلَمْ يَذْكُرِ التَّوَرُّكَ فِي التَّشَهُّدِ. (د)', 'അബാസുബ്നു സഹ്ലുസ്സാഇദീ(റ): - അദ്ദേഹം തന്റെ പിതാവടങ്ങുന്ന ഒരു സദസ്സിലായിരുന്നു. അദ്ദേഹം (പിതാവ്) പ്രവാചക(സ)ന്റെ അനുചരന്മാരിൽപ്പെട്ടവനായിരുന്നു. സദസ്സിൽ അബൂഹുറൈ(റ), അബൂഹുമൈദുസ്സാഇദീ(റ), അബൂഉസൈദ്(റ) എന്നിവരുണ്ടായിരുന്നു - ഇവ്വിഷയകമായി (നബി(സ)യുടെ നിസ്കാരത്തിന്റെ രൂപവുമായി ബന്ധപ്പെട്ട്) മുമ്പ് വന്ന റിപ്പോർട്ടിനേക്കാൾ അധികമോ കുറവോ ആയനിലയിൽ റിപ്പോർട്ട് ചെയ്തു. ഈ റിപ്പോർട്ടിൽ അദ്ദേഹം പറയുന്നു: പിന്നെ തിരുമേനി(സ) - റുകൂഇൽനിന്ന് - തന്റെ തല ഉയർത്തി. എന്നിട്ട് ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു അല്ലാഹുമ്മ റബ്ബനാലകൽഹംദു'' (അല്ലാഹുവിന്റെ സ്തുതിച്ചവനുവേണ്ടി അല്ലാഹു കേൾക്കട്ടെ. ഞങ്ങളുടെ നാഥനായ അല്ലാഹുവേ നിനക്കാകുന്നു സർവ്വസ്തുതിയും) എന്നു പറയുകയും ചെയ്തു. ശേഷം അവിടുന്ന് തന്റെ ഇരുകൈകളുമുയർത്തുകയും ''അല്ലാഹു അക്ബർ'' എന്നു പറയുകയും സുജൂദിലേക്കു പോവുകയും ചെയ്തു, സുജൂദിൽ തന്റെ പാദങ്ങളുടെ അകങ്ങളും, ഇരുമുട്ടുകളും ഇരുകൈപ്പത്തികളും നിലത്തൂന്നി. പിന്നെ തക്ബീർ ചൊല്ലുകയും (ഇടതു) പൃഷ്ടം നിലത്തുപതിച്ച് ഇരിക്കുകയും മറ്റെഭാഗത്തെക്കാൾ നാട്ടി വെക്കുകയും ചെയ്തു. പിന്നെ തക്ബീർ ചൊല്ലുകയും സുജൂദുചെയ്യുകയും ചെയ്തു. ശേഷം എഴുന്നേൽക്കുകയും ചെയ്തു. എന്നാൽ പൃഷ്ടം പതിച്ച് ഇരുന്നില്ല...... നിവേദകൻ ഹദീസ് തുടർന്നു വിവരിച്ചു...... നിവേദകൻ വീണ്ടും പറയുന്നു: തിരുമേനി(സ) രണ്ട് റക്അത്തുകൾക്കുശേഷം ഇരുന്നു. അവിടുന്ന് രണ്ട് റക്അത്തുകൾക്കു ശേഷം ഏഴുന്നേൽക്കാൻ ഉദ്ദേശിച്ചാൽ തക്ബീർ ചൊല്ലി എഴുന്നേൽക്കും. ശേഷം മറ്റു രണ്ടു റക്അത്തുകൾ കൂടി നിർവ്വഹിക്കും. അദ്ദേഹം (റിപ്പോർട്ടർ) തശഹ്ഹുദിൽ തവർറുക്കിന്റെ ഇരുത്തം ഇരിക്കുന്നതിനെ സംബന്ധിച്ചു ഒന്നും പറഞ്ഞിട്ടില്ല. (ദ)', 'عَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ', 'അബാസുബ്നു സഹ്ലുസ്സാഇദീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 445, 445, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 27, 'عَنْ عَبَّاسِ بْنِ سَهْلٍ قَالَ: اجْتَمَعَ أَبُو حُمَيْدٍ وَأَبُو أُسَيْدٍ وَسَهْلُ بْنُ سَعْدٍ وَمُحَمَّدُ بْنُ مَسْلَمَةَ، فَذَكَرُوا صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو حُمَيْدٍ: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ بَعْضَ هَذَا، قَالَ: ثُمَّ رَكَعَ فَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ كَأَنَّهُ قَابِضٌ عَلَيْهِمَا، وَوَتَّرَ يَدَيْهِ فَتَجَافَى عَنْ جَنْبَيْهِ، قَالَ: ثُمَّ سَجَدَ فَأَمْكَنَ أَنْفَهُ وَجَبْهَتَهُ، وَنَحَّى يَدَيْهِ عَنْ جَنْبَيْهِ، وَوَضَعَ كَفَّيْهِ حَذْوَ مَنْكِبَيْهِ، ثُمَّ رَفَعَ رَأْسَهُ حَتَّى رَجَعَ كُلُّ عَظْمٍ فِي مَوْضِعِهِ، حَتَّى فَرَغَ، ثُمَّ جَلَسَ فَافْتَرَشَ رِجْلَهُ الْيُسْرَى، وَأَقْبَلَ بِصَدْرِ الْيُمْنَى عَلَى قِبْلَتِهِ، وَوَضَعَ كَفَّهُ الْيُمْنَى عَلَى رُكْبَتِهِ الْيُمْنَى، وَكَفَّهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَأَشَارَ بِأُصْبُعِهِ. (د)', 'അബ്ബാസുബ്നു സഹ്ല്(റ): അബൂഹുമൈദ്, അബൂഉസൈദ്, സഹ്ലുബ്നു സഅ്ദ്, മുഹമ്മദുബ്നു മസ്ലമ(റ) എന്നിവർ ഒരുമിച്ചുകൂടി തിരുമേനി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ചർച്ചചെയ്തു. അപ്പോൾ അബൂഹുമൈദ് പറഞ്ഞു: നിങ്ങളിൽ തിരുമേനി(സ)യുടെ നിസ്കാരത്തെ സംബന്ധിച്ച് ഏറ്റവും കൂടുതലറിയുന്നവൻ ഞാനാകുന്നു. എന്നിട്ട് (മുൻ ഹദീസിലെപ്പോലെ) അതേപ്പറ്റി, ചിലകാര്യങ്ങൾ പറഞ്ഞു: അദ്ദേഹം പറഞ്ഞു: ശേഷം തിരുമേനി(സ) റുകൂഅ് ചൊയ്യുകയും തന്റെ ഇരുകൈകളും മുട്ടിന്മേൽ പിടിച്ചിട്ടുള്ളതുപോലെ വെക്കുകയും കൈകൾ വളച്ചുപിടിക്കുകയും, അവ ഇരുവശത്തേക്ക് അകറ്റി വെക്കുകയും ചെയ്തു. അദ്ദേഹം പറയുന്നു: പിന്നീട് തിരുമേനി(സ) സുജൂദു ചെയ്തു. അന്നേരം അവിടുന്ന് തന്റെ മൂക്കും, നെറ്റിത്തടവും നിലത്ത് വെക്കുകയും കൈകൾ ഇരുവശങ്ങലേക്കകറ്റുകയും, ഇരു മുൻകൈകളും തന്റെ ചുമലുകൾക്കുനേരെ (നിലത്ത്) വെക്കുകയും ചെയ്തു. പിന്നെ തിരുമേനി(സ) തന്റെ ഓരോ എല്ലുകളും അതിന്റെതായ സ്ഥാനത്തുമടങ്ങിവരും വിധം തന്റെ തലയുയർത്തുകയും (എന്നിട്ടു രണ്ടാമത്തെ സുജൂദു നിർവ്വഹിക്കുകയും) അങ്ങനെ (അതിൽനിന്നും) വിരമിക്കുകുകയും ചെയ്തു. പിന്നെ വലതുകാൽ നാട്ടിവെച്ച് ഇടതുകാൽ വിരിച്ചുവെച്ച് അതിന്റെ പള്ള ഭാഗത്ത് ഇരിക്കുകയും വലതു കാലിന്റെ അറ്റം ഖിബ്ലക്കു നേരെയാക്കുകയും, വലതുകൈപ്പടം വലതു കാൽമുട്ടിന്മേലും ഇടതു കൈപ്പടം ഇടതു കാൽമുട്ടിന്മേലുമായി വെക്കുകയും, വിരൽ ചൂണ്ടുകയും ചെയ്തു. (ദ)', 'عَبَّاسِ بْنِ سَهْلٍ قَالَ', 'അബ്ബാസുബ്നു സഹ്ല്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 28, 'عَنِ الْعَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ، عَنْ أَبِي حُمَيْدٍ رَضِيَ اللهُ عَنْهُ، بِهَذَا الْحَدِيثِ، قَالَ: وَإِذَا سَجَدَ فَرَّجَ بَيْنَ فَخِذَيْهِ، غَيْرَ حَامِلٍ بَطْنَهُ عَلَى شَيْءٍ مِنْ فَخِذَيْهِ. (د)', 'അബ്ബാസ്ബ്നുസഹ്ലുസ്സാഇദീ(റ) അബൂഹുറൈദി(റ)ൽ നിന്നും മേൽ ഹദീസ് വിവരിച്ചു. ഇതിൽ ഇപ്രകാരം കൂടി പറഞ്ഞു: തിരുമേനി(സ) സുജൂദ് ചെയ്യുമ്പോൾ ഇരു തുടകൾ വിടർത്തി വെക്കും, തന്റെ വയറിനെ തന്റെ തുടകൾ വഹിക്കാനിടയാകാത്ത വിധമായിരുന്നു അത്. (ദ)', 'الْعَبَّاسِ بْنِ سَهْلٍ السَّاعِدِيِّ، عَنْ أَبِي حُمَيْدٍ', 'അബ്ബാസ്ബ്നുസഹ്ലുസ്സാഇദീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 29, 'عَنْ وَائِلٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – فِي هَذَا الْحَدِيثِ – قَالَ: فَلَمَّا سَجَدَ وَقَعَتَا رُكْبَتَاهُ إِلَى الْأَرْضِ قَبْلَ أَنْ تَقَعَ كَفَّاهُ، قَالَ: فَلَمَّا سَجَدَ وَضَعَ جَبْهَتَهُ بَيْنَ كَفَّيْهِ وَجَافَى عَنْ إِبِطَيْهِ، وَإِذَا نَهَضَ نَهَضَ عَلَى رُكْبَتَيْهِ وَاعْتَمَدَ عَلَى فَخِذِهِ. (د)', 'വാഇൽ(റ): പ്രവാചക(സ)ന്റെ നിസ്കാരത്തെ സംബന്ധിച്ച് ഹദീസ് മുൻപ് വന്നിട്ടുണ്ട്. ഈ റിപ്പോർട്ടിൽ വാഇൽ(റ) പറയുന്നു: തിരുമേനി(സ) സുജൂദ് ചെയ്തപ്പോൾ അവിടുത്തെ കൈപ്പടങ്ങൾ നിലത്തു പതിക്കുന്നതിന് മുമ്പ് അവിടുത്തെ ഇരുകാൽ മുട്ടുകളും നിലത്തു പതിച്ചു. അദ്ദേഹം തുടർന്നു പറഞ്ഞു: തിരുമേനി(സ) സുജൂദ് ചെയ്തപ്പോൾ തന്റെ നെറ്റിത്തടം ഇരു കൈപ്പടങ്ങൾക്കിടയിലായി വെക്കുകയും കക്ഷങ്ങൾ വിടർത്തുകയും എഴുന്നേൽക്കുമ്പോൾ കാൽമുട്ടുകളിന്മേൽ എഴുന്നേൽക്കുകയും തുടക്കുമേൽ ഊന്നുകയും ചെയ്തു. (ദ)', 'وَائِلٍ', 'വാഇൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 446, 446, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 30, 'عَنْ وَائِلٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْفَعُ إِبْهَامَيْهِ فِي الصَّلَاةِ إِلَى شَحْمَةِ أُذُنَيْهِ. (ن)', 'വാഇൽ(റ): പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ തന്റെ തള്ളവിലരുകൾ ചെവിക്കുന്നിക്കുനേരെയാകും വിധം ഉയർത്തുന്നത് ഞാൻ കണ്ടു. (ന)', 'وَائِلٍ', 'വാഇൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 446, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 31, 'عَنْ مَيْمُونٍ الْمَكِّيِّ: أَنَّهُ رَأَى عَبْدَ اللهِ بْنَ الزُّبَيْرِ – رَضِيَ اللهُ عَنْهُمَا – وَصَلَّى بِهِمْ يُشِيرُ بِكَفَّيْهِ: حِينَ يَقُومُ، وَحِينَ يَرْكَعُ، وَحِينَ يَسْجُدُ، وَحِينَ يَنْهَضُ لِلْقِيَامِ، فَيَقُومُ فَيُشِيرُ بِيَدَيْهِ، فَانْطَلَقْتُ إِلَى ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فَقُلْتُ: إِنِّي رَأَيْتُ ابْنَ الزُّبَيْرِ صَلَّى صَلَاةً لَمْ أَرَ أَحَدًا يُصَلِّيهَا، فَوَصَفْتُ لَهُ هَذِهِ الْإِشَارَةَ، فَقَالَ: إِنْ أَحْبَبْتَ أَنْ تَنْظُرَ إِلَى صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَاقْتَدِ بِصَلَاةِ عَبْدِ اللهِ بْنِ الزُّبَيْرِ. (د)', 'മൈമുനുൽ മക്കീ: അവർ അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) ജനങ്ങൾക്കിമാമായി നിസ്കരിക്കന്നത് കണ്ടു. അതിൽ അദ്ദേഹം എഴുന്നേറ്റപ്പോഴും, റുകൂഇലേക്കു പോയപ്പോഴും, സുജൂദിലേക്കു പോയപ്പോഴും, സുജൂദുകഴിഞ്ഞ് എഴുന്നേറ്റപ്പോഴും, തന്റെ കൈകൾ കൊണ്ട് ആഗ്യം കാണിച്ചതു (തന്റെ കൈകൾ ചുമലിനു നേരെ ഉയർത്തിയത്) ഞാൻ കണ്ടു. അങ്ങനെ ഞാൻ ഇബ്നുഅബ്ബാസി(റ)ന്റെ അടുക്കൽ പോയി പറഞ്ഞു: ''ഞാൻ ഇബ്നുസുബൈർ നിസ്കരിക്കുന്നത് കണ്ടു. അപ്രകാരം നിസ്കരിക്കുന്നതായി ഞാൻ മറ്റാരെയും കണ്ടിട്ടില്ല''. - എന്നിട്ടു ഞാൻ അദ്ദേഹം കൈകൾ കൊണ്ട് ആംഗ്യം കാണിച്ചതിനെപ്പറ്റി (കൈകൾ ഉയർത്തിയതിനെക്കുറിച്ച്) വിവരിച്ചു കൊടുത്തു-. അദ്ദേഹം പറഞ്ഞു: നീ തിരുമേനി(സ)യുടെ നിസ്കാരത്തെ വീക്ഷിക്കാനിഷ്ടപ്പെടുന്നുവെങ്കിൽ അബ്ദുല്ലാഹിബ്നു സുബൈറിന്റെ നിസ്കാരത്തെ അനുധാവനം ചെയ്തുകൊള്ളുക (ദ)', 'مَيْمُونٍ الْمَكِّيِّ', 'മൈമുനുൽ മക്കീ', null, null, array['د']::text[], array['ദ']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 32, 'عَنِ النَّضْرِ بْنِ كَثِيرٍ – يَعْنِي السَّعْدِيَّ – قَالَ: صَلَّى إِلَى جَنْبِي عَبْدُ اللهِ بْنُ طَاوُسٍ فِي مَسْجِدِ الْخَيْفِ، فَكَانَ إِذَا سَجَدَ السَّجْدَةَ الْأُولَى فَرَفَعَ رَأْسَهُ مِنْهَا رَفَعَ يَدَيْهِ تِلْقَاءَ وَجْهِهِ، فَأَنْكَرْتُ ذَلِكَ، فَقُلْتُ لِوُهَيْبِ بْنِ خَالِدٍ، فَقَالَ لَهُ وُهَيْبُ بْنُ خَالِدٍ: تَصْنَعُ شَيْئًا لَمْ أَرَ أَحَدًا يَصْنَعُهُ؟ فَقَالَ ابْنُ طَاوُسٍ: رَأَيْتُ أَبِي يَصْنَعُهُ، وَقَالَ أَبِي: رَأَيْتُ ابْنَ عَبَّاسٍ يَصْنَعُهُ، وَلَا أَعْلَمُ إِلَّا أَنَّهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُهُ. (د,ن)', 'നള്റുബ്നു കഥീറുസ്സഅ്ദീ: അൽവൈഫ് പള്ളിയിൽ എന്റെ അരികിൽ അബ്ദുല്ലാഹിബ്നു താഊസ് നിസ്കരിച്ചു. അദ്ദേഹം ഒന്നാമത്തെ സുജൂദ് നിർവ്വഹിച്ചപ്പോൾ തന്റെ തലയുയർത്തുകയും, തന്റെ മുഖത്തിനു നേരെ ഇരു കൈകളുമുയർത്തുകയും ചെയ്തു; അങ്ങനെ ഞാൻ അക്കാര്യം വുഹൈബ്ബ്നു ഖാലിദിനോട് പറഞ്ഞു: അപ്പോൾ വുഹൈബ്ബ്നു ഖാലിദ് അബ്ദുല്ലാഹിബ്നു താഈസിനോട് പറഞ്ഞു: ഒരാളും ചെയ്യുന്നതായി ഞാൻ കണ്ടിട്ടില്ലാത്ത കാര്യമാണല്ലോ താങ്കൾ ചെയ്യുന്നത്? അപ്പോൾ ഇബ്നുത്വാഈസ് പറഞ്ഞു: എന്റെ പിതാവ് അപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. എന്റെ പിതാവ് പറഞ്ഞു: ഇബ്നുഅബ്ബാസ്(റ) അപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. തിരുമേനി(സ) ഇപ്രകാരം ചെയ്തിട്ടുണ്ട് എന്ന് അദ്ദേഹം പറഞ്ഞു എന്നതിലുപരിയായി(ഇക്കാര്യത്തിൽ) എനിക്ക് മറ്റൊന്നുമറിയില്ല. (ദ,ന)', 'النَّضْرِ بْنِ كَثِيرٍ – يَعْنِي السَّعْدِيَّ – قَالَ', 'നള്റുബ്നു കഥീറുസ്സഅ്ദീ', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 447, 447, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=4 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 33, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهَا: أَنَّهُ كَانَ إِذَا دَخَلَ فِي الصَّلَاةِ كَبَّرَ وَرَفَعَ يَدَيْهِ، وَإِذَا رَكَعَ، وَإِذَا قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". وَإِذَا قَامَ مِنَ الرَّكْعَتَيْنِ رَفَعَ يَدَيْهِ، وَيَرْفَعُ ذَلِكَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 34, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ اسْتَقْبَلَ الْقِبْلَةَ، وَرَفَعَ يَدَيْهِ وَقَالَ: اللهُ أَكْبَرُ. (خ,د,ت,ن,جه)', 'അബൂഹുമൈദിസ്സാഇദീ(റ): നബി(സ) നിസ്കാരത്തിന് നിന്നാൽ ഖിബ്ലയെ അഭിമുഖീകരിക്കും. കൈ ഉയർത്തി അല്ലാഹു അക്ബർ എന്ന് പറയും. (ബു,ദ,തു,ന,ജ)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദിസ്സാഇദീ(റ)', null, null, array['خ','د','ت','ن','جه']::text[], array['ബു','ദ','തു','ന','ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 35, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَبَّرَ سَكَتَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ. قَالَ: فَقُلْتُ: بِأَبِي أَنْتَ وَأُمِّي، أَرَأَيْتَ سُكُوتَكَ بَيْنَ التَّكْبِيرِ وَالْقِرَاءَةِ، فَأَخْبِرْنِي مَا تَقُولُ؟ قَالَ: أَقُولُ: "اللَّهُمَّ بَاعِدْ بَيْنِي وَبَيْنَ خَطَايَايَ كَمَا بَاعَدْتَ بَيْنَ الْمَشْرِقِ وَالْمَغْرِبِ، اللَّهُمَّ نَقِّنِي مِنْ خَطَايَايَ كَالثَّوْبِ الْأَبْيَضِ مِنَ الدَّنَسِ، اللَّهُمَّ اغْسِلْنِي مِنْ خَطَايَايَ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ". (ق,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) തക്ബീർ ചൊല്ലിക്കൊണ്ട് നിസ്കാരത്തിൽ പ്രവേശിച്ചാൽ ആ തക്ബീറിന്റെയും ഖുർആൻ പാരായണത്തിന്റെയും ഇടയിൽ മൗനം പാലിച്ചിരുന്നു. അപ്പോൾ ഞാൻ ചോദിച്ചു. എന്റെ മാതാപിതാക്കൾ അങ്ങയ്ക്കു ദണ്ഢമാകുന്നു.² പ്രവാചകരേ അങ്ങ് തക്ബീറിന്റെയും ഖുർആൻ പാരായണത്തിന്റെയും ഇടയിൽ മൗനം പാലിക്കുന്നതായി ഞാൻ കാണുന്നു. താങ്കൾ എന്താണ് അപ്പോൾ ചൊല്ലുന്നത്? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ എനിക്കും എന്റെ പാപങ്ങൾക്കും ഇടയിൽ നീ വിദൂരതയുണ്ടാക്കേണമേ. കിഴക്കിന്റെയും പടിഞ്ഞാറിന്റെയും ഇടയിലെ വിദൂരത പോലെ, അഴുക്കിൽ നിന്ന് വെള്ള വസ്ത്രം ശുദ്ധീകരിക്കുന്നതു പോലെ എന്നെ പാപത്തിൽ നിന്ന് ശുദ്ധീകരിക്കേണമേ. എന്റെ പാപങ്ങളെ നീ വെള്ളം കൊണ്ടും മഞ്ഞു കൊണ്ടും ഹിമം കൊണ്ടും കഴുകേണമേ." (ബു,മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', '². ഇതൊരു അറബി ഭാഷാ ശൈലിയാണ്.', null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 36, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا افْتَتَحَ الصَّلَاةَ قَالَ: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، تَبَارَكَ اسْمُكَ، وَتَعَالَى جَدُّكَ، وَلَا إِلَهَ غَيْرُكَ". (د,ت,ن,جه)', 'ആഇശ(റ): നബി(സ) നിസ്കാരം തുടങ്ങുമ്പോൾ; "അല്ലാഹുവേ നീ പരിശുദ്ധനാകുന്നു. നിന്നെ സ്തുതിക്കുന്നു. നിന്റെ നാമം ഉൽകൃഷ്ഠമാകുന്നു. നിന്റെ പ്രതാപം അത്യുന്നതമാകുന്നു. നീ അല്ലാതെ യാതൊരു ദൈവവുമില്ല." എന്ന് പറയാറുണ്ടായിരുന്നു. (ദ,തു,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 37, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَرْفَعُ يَدَيْهِ حَذْوَ مَنْكِبَيْهِ إِذَا افْتَتَحَ الصَّلَاةَ وَإِذَا كَبَّرَ لِلرُّكُوعِ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ رَفَعَهُمَا كَذَلِكَ أَيْضًا، وَقَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ رَبَّنَا وَلَكَ الْحَمْدُ". وَكَانَ لَا يَفْعَلُ ذَلِكَ فِي السُّجُودِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): നബി(സ) തന്റെ തോളറ്റം വരെ കൈ ഉയർത്തിയിരുന്നു, നിസ്കാരത്തിന്റെ പ്രാരംഭത്തിലും റുകൂഇലേക്ക് പോവുമ്പോഴും റുകൂഇൽ നിന്ന് തല ഉയർത്തുമ്പോഴും (കൈ ഉയർത്താറുണ്ടായിരുന്നു). പിന്നെ പറയും: "അല്ലാഹുവിനെ സ്തുതിച്ചവന്റെ സ്തുതി അവൻ കേട്ടിരിക്കുന്നു. ഞങ്ങളുടെ രക്ഷിതാവേ! സർവ്വ സ്തുതിയും നിനക്കാണ്." എന്നാൽ സുജൂദിൽ അപ്രകാരം ചെയ്തിരുന്നില്ല. (ബു)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 448, 448, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 38, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَمَا نَحْنُ نُصَلِّي مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: اللهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ للهِ كَثِيرًا، وَسُبْحَانَ اللهِ بُكْرَةً وَأَصِيلًا. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنِ الْقَائِلُ كَلِمَةً كَذَا وَكَذَا؟" فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا يَا رَسُولَ اللهِ. قَالَ: "عَجِبْتُ لَهَا". وَذَكَرَ كَلِمَةً مَعْنَاهَا: فُتِحَتْ لَهَا أَبْوَابُ السَّمَاءِ. قَالَ ابْنُ عُمَرَ: مَا تَرَكْتُهُ مُنْذُ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُهُ. (د,ن,ت)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഞങ്ങൾ റസൂലിനൊപ്പം നിസ്കരിക്കുമ്പോൾ കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: ''അല്ലാഹു വലിയവരിൽ ഏറ്റവും വലിയവനാകുന്നു. അവന് ധാരാളം സ്തുതി. പ്രഭാത പ്രദോഷങ്ങളിൽ അവൻ എത്ര പരിശുദ്ധൻ.'' നബി(സ) ചോദിച്ചു: "ആരാണത് പറഞ്ഞത്?" കൂട്ടത്തിൽ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ, ഞാനാണ്. നബി(സ) പറഞ്ഞു: "ആ വചനം അത്ഭുതകരം." ശേഷം ''ആ വചനം കാരണത്താൽ ആകാശ കവാടങ്ങൾ തുറക്കപ്പെട്ടു'' എന്ന അർത്ഥത്തിൽ എന്തോ നബി(സ) പറഞ്ഞു. ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി(സ)യിൽ നിന്ന് ആ വചനം കേട്ടതു മുതൽ ഇന്നുവരെ ഞാനത് ഉപേക്ഷിച്ചിട്ടില്ല. (ദ,തു,ന)', 'ابْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ن','ت']::text[], array['ദ','തു','ന']::text[], null, null, 448, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 39, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا، إِذْ جَاءَ رَجُلٌ فَدَخَلَ الْمَسْجِدَ، وَقَدْ حَفَزَهُ النَّفَسُ، فَقَالَ: اللهُ أَكْبَرُ، الْحَمْدُ للهِ حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ. فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ قَالَ: "أَيُّكُمُ الَّذِي تَكَلَّمَ بِكَلِمَاتٍ". فَأَرَمَّ الْقَوْمُ، قَالَ: "إِنَّهُ لَمْ يَقُلْ بَأْسًا". قَالَ: أَنَا يَا رَسُولَ اللهِ، جِئْتُ وَقَدْ حَفَزَنِي النَّفَسُ، فَقُلْتُهَا. قَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَقَدْ رَأَيْتُ اثْنَيْ عَشَرَ مَلَكًا يَبْتَدِرُونَهَا أَيُّهُمْ يَرْفَعُهَا". (م,د,ن)', 'അനസ്(റ): നബി(സ) ഞങ്ങളോടൊന്നിച്ച് നിസ്കരിക്കുകയായിരുന്നു. അപ്പോൾ ഒരാൾ പള്ളിയിലേക്ക് പ്രവേശിച്ചു. അദ്ദേഹത്തിന് ശ്വാസതടസ്സം അനുഭവപ്പെട്ടിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: ''അല്ലാഹു ഏറ്റവും വലിയവനാകുന്നു. അല്ലാഹുവിന് പരിശുദ്ധവും അനുഗ്രഹീതവുമായ ധാരാളം സ്തുതി.'' നിസ്കാരശേഷം നബി(സ) ചോദിച്ചു: "ആരാണത് പറഞ്ഞത്?." അപ്പോൾ എല്ലാവരും നിശ്ശബ്ദരായി. നബി(സ) പറഞ്ഞു: "അതിൽ തെറ്റൊന്നുമില്ല." അപ്പോൾ ഒരാൾ പറഞ്ഞു: അല്ലാഹുവിന്റെ റസൂലേ ഞാനാണ്. ഞാൻ വന്നപ്പോൾ എനിക്ക് ശ്വാസ തടസ്സമുണ്ടായി. അപ്പോഴാണ് ഞാനത് പറഞ്ഞത്. നബി(സ) പറഞ്ഞു: "അത് ആരാണ് ഉയർത്തേണ്ടത് എന്നകാര്യത്തിൽ തർക്കിക്കുന്ന പന്ത്രണ്ട് മലക്കുകൾ അതേറ്റെടുക്കാൻ മത്സരിക്കുന്നത് ഞാൻ കണ്ടു." (മു,ദ,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 40, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَفْتَحَ الصَّلَاةَ كَبَّرَ، ثُمَّ قَالَ: "إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا مِنَ الْمُسْلِمِينَ. اللَّهُمَّ اهْدِنِي لِأَحْسَنِ الْأَعْمَالِ وَأَحْسَنِ الْأَخْلَاقِ، لَا يَهْدِي لِأَحْسَنِهَا إِلَّا أَنْتَ، وَقِنِي سَيِّئَ الْأَعْمَالِ وَسَيِّئَ الْأَخْلَاقِ، لَا يَقِي سَيِّئَهَا إِلَّا أَنْتَ". (ن)', 'ജാബിറുബിനു അബ്ദുല്ല(റ): നബി(സ) നിസ്കാരം തുടങ്ങിയാൽ തക്ബീർ ചൊല്ലും. പിന്നെ ഇപ്രകാരം പറയും: "എന്റെ ജീവിതവും എന്റെ മരണവും ലോകരക്ഷിതാവായ അല്ലാഹുവിനാകുന്നു. അവന്ന് പങ്കുകാരില്ല. അതാണ് എന്നോട് കൽപിച്ചത്. ഞാൻ മുസ്ലിംകളിൽ പെട്ടവനാകുന്നു. അല്ലാഹുവേ, നീ എന്നെ സൽപ്രവർത്തിയിലേക്കും സൽസ്വഭാവത്തിലേക്കും നയിക്കേണമേ. നീയല്ലാതെ നല്ലതിലേക്ക് നയിക്കുന്നവനില്ല. നീ എന്നെ ദു:സ്വഭാവത്തിൽ നിന്നും ദുഷ്പ്രവൃത്തിയിൽ നിന്നും രക്ഷിക്കേണമേ. നീ അല്ലാതെ ചീത്തയിൽ നിന്നും രക്ഷിക്കുന്നവനില്ല." (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബിനു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 449, 449, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 41, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ كَبَّرَ ثُمَّ قَالَ: "وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا مُسْلِمًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ. إِنَّ صَلَاتِي وَنُسُكِي ومحياي ومماتي لله رب العالمين. لا شريك له وبذلك أُمِرت وأنا أَوَّلُ المُسلمين. اللهم أنت الملك لا إله لي إلَّا أنت، ربي وأنا عبدك، ظلمت نفسي، واعترفت بذنبي، فاغفر لي ذنوبي جميعا، إنه لا يغفر الذنوب إلا أنت. واهدني لأحسن الأخلاق لا يهدي لأحسنها إلا أنت، واصرف عني سيئها لا يصرف سيئها إلا أنت. لبيك وسعديك، والخير كله في يديك، والشر ليس إليك. أنا بك وإليك تباركت وتعاليت، أستغفرك وأتوب إليك". وَإِذَا رَكَعَ قَالَ: "اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَمُخِّي وَعِظَامِي وَعَصَبِي". وَإِذَا رَفَعَ قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَالْأَرْضِ، وَمِلْءَ مَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ". وَإِذَا سَجَدَ قَالَ: "اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ فَأَحْسَنَ صُورَتَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، وَتَبَارَكَ اللهُ أَحْسَنُ الْخَالِقِينَ". وَإِذَا سَلَّمَ مِنَ الصَّلَاةِ قَالَ: "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَالْمُؤَخِّرُ، لَا إِلَهَ إِلَّا أَنْتَ". (م,د,ت,ن,جه)', 'അലി(റ): നബി(സ) നിസ്കാരത്തിൽ പ്രവേശിച്ചാൽ തക്ബീർ ചൊല്ലും. പിന്നെ പറയും: "ആകാശ ഭൂമികളുടെ പരിപാലകനിലേക്ക് ഞാൻ എന്റെ മുഖത്തെ ഋജുമാനസനായി തിരിച്ചിരിക്കുന്നു. ഞാൻ ബഹുദൈവ ആരാധകരിൽ പെട്ടവനല്ല. എന്റെ നിസ്കാരവും ആരാധനയും ജീവിതവും മരണവും ലോക രക്ഷിതാവായ അല്ലാഹുവിനാകുന്നു. അവന് പങ്കുകാരില്ല. അതാണ് എന്നോട് കൽപിച്ചത്. ഞാൻ മുസ്ലിംകളിൽപെട്ടവനാകുന്നു. അല്ലാഹുവേ, നീ അധിപനാകുന്നു. നീയല്ലാതെ ആരാധ്യനില്ല. ഞാൻ നിന്റെ അടിമയാകുന്നു. ഞാൻ എന്നോട് തന്നെ അതിക്രമം പ്രവർത്തിച്ചിരിക്കുന്നു. എന്റെ പാപങ്ങൾ സമ്മതിക്കുന്നു. എന്റെ പാപങ്ങൾ എല്ലാം പൊറുത്തുതരേണമേ. നീ അല്ലാതെ പാപം പൊറുക്കുന്നവനില്ല. നീ എന്നെ സൽസ്വഭാവത്തിലേക്ക് നയിക്കേണമേ. നീയല്ലാതെ അതിലേക്ക് നയിക്കുന്നവനില്ല. അതിന്റെ ദൂഷ്യത്തിൽ നിന്നും നീ എന്നെ അകറ്റേണമേ. നീ അല്ലാതെ അതിൽ നിന്നകറ്റുന്നവനില്ല. നിന്റെ വിളിക്കും സൗഭാഗ്യത്തിനും ഞാൻ ഉത്തരം നൽകിയിരിക്കുന്നു. എല്ലാ നന്മയും നിന്നിൽ നിന്നാകുന്നു. തിന്മ നിന്നിലേക്കല്ല. ഞാൻ നിന്നിൽ നിന്നും നിന്നിലേക്കുമാണ്. നീ പരിശുദ്ധനും മഹോന്നതനുമാകുന്നു. ഞാൻ നിന്നോട് പാപമോചനം തേടുകയും നിന്നിലേക്ക് പശ്ചാത്തപിച്ചു മടങ്ങുകയും ചെയ്യുന്നു." റുകൂഇലേക്കു പോയാൽ ഇപ്രകാരം പറയും: "അല്ലാഹുവേ, നിനക്കു ഞാൻ റുകൂഅ് ചെയ്തിരിക്കുന്നു. നിന്നിൽ ഞാൻ വിശ്വസിക്കുകയും നിനക്ക് കീഴ്പ്പെടുകയും ചെയ്തിരിക്കുന്നു. എന്റെ കണ്ണും, കാതും, മജ്ജയും, അസ്ഥിയും, ഞരമ്പും നിന്നോട് വിനയം കാണിച്ചിരിക്കുന്നു." റുകൂഇൽ നിന്നും ഉയരുമ്പോൾ "സമിഅല്ലാഹു ലിമൻ ഹമിദ (അല്ലാഹുവിനെ വിളിച്ചവനെ വിളി അവൻ കേട്ടിരിക്കുന്നു) എന്നും, (ശേഷം) ''ഞങ്ങളുടെ നാഥാ! ആകാശങ്ങളും ഭൂമിയും അവയ്ക്കിടയിലുള്ളവയും, നീ ഉദ്ദേശിച്ച മറ്റെല്ലാ വസ്തുക്കളും നിറയെ നിനക്ക് സ്തുതി!" എന്നും പറയും. സുജൂദിൽ ഇപ്രകാരം പറയും: "അല്ലാഹുവേ! നിനക്കു ഞാൻ സ്രാഷ്ടാംഗം ചെയ്തിരിക്കുന്നു! നിന്നിൽ ഞാൻ വിശ്വസിക്കുകയും നിനക്കു ഞാൻ കീഴ്പ്പെടുകയും ചെയ്തിക്കുന്നു. എന്റെ മുഖം അതിനെ സൃഷ്ടിക്കുകയും അതിനെ രൂപപ്പെടുത്തുകയും അതിന് ഉത്തമ രൂപം നൽകുകയും, കേൾവിയും കാഴ്ചയും ഉണ്ടാക്കുകയും ചെയ്തവന് സ്രാഷ്ടാംഗം ചെയ്തിരിക്കുന്നു. ഏറ്റവും ഉത്തമ സ്രൃഷ്ടാവായ അല്ലാഹു അനുഗ്രഹപൂർണ്ണനായിരിക്കുന്നു." സലാം വീട്ടുമ്പോൾ ഇപ്രകാരം പ്രാർത്ഥിക്കുമായിരുന്നു: "അല്ലാഹുവേ, ഞാൻ മുമ്പേ ചെയ്തതും, പിന്തിച്ചു ചെയ്തതും, രഹസ്യമായി ചെയ്തതും, പരസ്യമായി ചെയ്തതും, ഞാൻ അമിതമായി ചെയ്തതും, എന്നെക്കാൾ നീ അിറയുന്നതായ(എന്റെ പാപങ്ങളും)വയും നീ എനിക്കു പൊറുത്തുതരേണമേ! നീയാണ് മുന്തിക്കുന്നവനും പിന്തിക്കുന്നവനും. നീയല്ലാതെ ഒരു ആരാധ്യനും ഇല്ല." (മു,ദ,തു,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 449, 450, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 42, 'عَنْ مُحَمَّدِ بْنِ مَسْلَمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ يُصَلِّي تَطَوُّعًا قَالَ: "اللهُ أَكْبَرُ، وَجَّهْتُ وَجْهِيَ لِلَّذِي فَطَرَ السَّمَوَاتِ وَالْأَرْضَ حَنِيفًا مُسْلِمًا وَمَا أَنَا مِنَ الْمُشْرِكِينَ. إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ، لَا شَرِيكَ لَهُ، وَبِذَلِكَ أُمِرْتُ وَأَنَا أَوَّلُ الْمُسْلِمِينَ. اللَّهُمَّ أَنْتَ الْمَلِكُ لَا إِلَهَ إِلَّا أَنْتَ، سُبْحَانَكَ وَبِحَمْدِكَ". ثُمَّ يَقْرَأُ. (ن)', 'മുഹമ്മദ്ബ്നു മസ്ലമ(റ): നബി(സ) സുന്നത്ത് നിസ്കാരത്തിനു നിന്നാൽ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹു മഹാനാകുന്നു. ആകാശ ഭൂമികളുടെ പരിപാലകനിലേക്ക് ഋജുമാനസനായും കീഴ്പ്പെട്ടവനായും കൊണ്ട് ഞാനെന്റെ മുഖം തിരിച്ചിരിക്കുന്നു. ഞാൻ ബഹുദൈവാരാധകരിൽ പെട്ടവനല്ല. എന്റെ നിസ്കാരവും ആരാധനയും ജീവിതവും മരണവും ലോക രക്ഷിതാവായ അല്ലാഹുവിനാകുന്നു. അവന് പങ്കുകാരില്ല. അതാണ് എന്നോട് കൽപിക്കപ്പെട്ടിട്ടുള്ളത്. ഞാൻ ഒന്നാമതായി മുസ്ലിംകളിൽ പെട്ടവനാകുന്നു. അല്ലാഹുവേ, നീ അധിപനാകുന്നു. നീ അല്ലാതെ യാതൊരു ദൈവവുമില്ല. നീ പരിശുദ്ധനാകുന്നു. നിനക്കാണ് സ്തുതി." ശേഷം ഖുർആൻ പാരായണം ചെയ്യും. (ന)', 'مُحَمَّدِ بْنِ مَسْلَمَةَ', 'മുഹമ്മദ്ബ്നു മസ്ലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 450, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=5 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 43, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى لِلَّهِ أَرْبَعِينَ يَوْمًا فِي جَمَاعَةٍ، يُدْرِكُ التَّكْبِيرَةَ الْأُولَى، كُتِبَتْ لَهُ بَرَاءَتَانِ: بَرَاءَةٌ مِنَ النَّارِ، وَبَرَاءَةٌ مِنَ النِّفَاقِ". (ت)', 'അനസുബ്നു മാലിക്(റ): നബി(സ)പറഞ്ഞു: "ആരെങ്കിലും നാൽപത് ദിവസം ജമാഅത്തായി നമസ്കരിക്കുകയും ഒന്നാമത്തെ തക്ബീർ മുതൽ തുടരുകയും ചെയ്താൽ രണ്ട് മോചനങ്ങൾ അയാളുടെമേൽ നിർബന്ധമായി. നരകത്തിൽ നിന്നുള്ള മോചനവും, കാപട്യത്തിൽ നിന്നുള്ള വിമോചനവും." (തു)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=6 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 44, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مفتاح الصَّلَاةِ الطُّهُورُ، وَتَحْرِيمُهَا التَّكْبِيرُ، وَتَحْلِيلُهَا التَّسْلِيمُ، وَلَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِالْحَمْدِ وَسُورَةٍ، فِي فَرِيضَةٍ أَوْ غَيْرِهَا". حسن (ت,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറഞ്ഞു: "ശുദ്ധിയാണ് നിസ്കാരത്തിന്റെ താക്കോൽ. അതിൽ പ്രവേശിക്കൽ തക്ബീറും, വിരമിക്കൽ സലാം ചൊല്ലലുമാണ്. അൽഹംദു(ഫാത്തിഹ)വും, സൂറത്തും ഓതാത്തവന് നിസ്കാരമില്ല. ഫർളായാലും അല്ലാത്തതായാലും ശരി." (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു,ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=7 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 45, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا كَبَّرَ لِلصَّلَاةِ نَشَرَ أَصَابِعَهُ. وعنه قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَاقَامَ إِلَي الصَّلَاةِ رَفَعَ يَدَيْهِ مَدًّا. (ن)', 'അബൂഹുറൈറ(റ): നബി(സ) നിസ്കാരത്തിന് തക്ബീർ ചൊല്ലിയാൽ വിരലുകൾ വിടർത്തുമായിരുന്നു. അദ്ദേഹം പറയുന്നു: നബി(സ) നിസ്കാരത്തിനു നിന്നാൽ കൈ നീട്ടിക്കൊണ്ട് ഉയർത്താറുണ്ടായിരുന്നു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 451, 451, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=8 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 46, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: وَقَدْ جَاءَ إِلَى مَسْجِدِ بَنِي زُرَيْقٍ فَقَالَ ثَلَاثٌ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْمَلُ بِهِنَّ تَرَكَهُنَّ النَّاسُ: كَانَ يَرْفَعُ يَدَيْهِ فِي الصَّلَاةِ مَدًّا، وَيَسْكُتُ هُنَيْهَةً، وَيُكَبِّرُ إِذَا سَجَدَ وَإِذَا رَفَعَ. (ن)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം ബനൂസുറൈഖ് പള്ളിയിൽ വന്നപ്പോൾ പറഞ്ഞു: നബി(സ) ചെയ്തിരുന്നതും ജനങ്ങൾ ഉപേക്ഷിച്ചതുമായ മൂന്നു കാര്യങ്ങളുണ്ട്: നബി(സ) നിസ്കാരത്തിൽ കൈകൾ നീട്ടി ഉയർത്തിയിരുന്നു, അൽപ സമയം മൗനം പാലിച്ചിരുന്നു, സുജൂദിൽ പോവുമ്പോഴും ഉയരുമ്പോഴും തക്ബീർ ചൊല്ലിയിരുന്നു. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=9 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 47, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ إِلَى الصَّلَاةِ يُكَبِّرُ حِينَ يَقُومُ، ثُمَّ يُكَبِّرُ حِينَ يَرْكَعُ، ثُمَّ يَقُولُ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ" حِينَ يَرْفَعُ صُلْبَهُ مِنَ الرُّكُوعِ، ثُمَّ يَقُولُ وَهُوَ قَائِمٌ: "رَبَّنَا وَلَكَ الْحَمْدُ". ثُمَّ يُكَبِّرُ حِينَ يَهْوِي سَاجِدًا، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يُكَبِّرُ حِينَ يَسْجُدُ، ثُمَّ يُكَبِّرُ حِينَ يَرْفَعُ رَأْسَهُ، ثُمَّ يَفْعَلُ مِثْلَ ذَلِكَ فِي الصَّلَاةِ كُلِّهَا حَتَّى يَقْضِيَهَا، وَيُكَبِّرُ حِينَ يَقُومُ مِنَ الْمَثْنَى بَعْدَ الْجُلُوسِ، ثُمَّ يَقُولُ أَبُو هُرَيْرَةَ: إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) നിസ്കാരത്തിനായി വന്നാൽ നിൽക്കുമ്പോൾ തക്ബീർ ചൊല്ലും. ശേഷം റുകൂഅ് ചെയ്യുമ്പോൾ തക്ബീർ ചൊല്ലും. പിന്നെ പറയും: "അല്ലാഹുവിനെ സ്തുതിച്ചവന്റെ വിളി അവൻ കേട്ടിരിക്കുന്നു." റുകൂഇൽ നിന്നും മുതുകിനെ ഉയർത്തുമ്പോൾ എഴുന്നേറ്റു നിന്ന് പറയും: "അല്ലാഹുവേ നിനക്കാണ് സ്തുതി." സുജൂദിലേക്ക് കുനിയുമ്പോഴും അതിൽനിന്നും തല ഉയർത്തുമ്പോഴും തക്ബീർ ചൊല്ലും. വീണ്ടും സുജൂദ് ചെയ്യുമ്പോഴും ശേഷം തല ഉയർത്തുമ്പോഴും തക്ബീർ ചൊല്ലും. നിസ്കാരം തീരുന്നതുവരെ അങ്ങനെ ചെയ്യും. രണ്ട് റക്അത്തിന് ശേഷം ഇരുന്ന് എഴുന്നേൽക്കുമ്പോഴും തക്ബീർ ചൊല്ലും. അബൂഹുറൈറ(റ) തുടർന്നു പറഞ്ഞു: നബി(സ)യുടെ നിസ്കരത്തിന് ഏറ്റവും സാദൃശ്യമുള്ളവൻ നിങ്ങളിൽ ഞാനാണ്. (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 48, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّهُ يُصَلِّي: فَلَمَّا رَكَعَ كَبَّرَ، فَلَمَّا رَفَعَ رَأْسَهُ قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ، ثُمَّ سَجَدَ وَكَبَّرَ، وَرَفَعَ رَأْسَهُ وَكَبَّرَ، ثُمَّ كَبَّرَ حِينَ قَامَ مِنَ الرَّكْعَةِ، ثُمَّ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَقْرَبُكُمْ شَبَهًا بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، مَا زَالَتْ هَذِهِ صَلَاتُهُ حَتَّى فَارَقَ الدُّنْيَا. (ن)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം നിസ്കരിച്ചു. റുകൂഇലേക്കു പോയപ്പോൾ തക്ബീർ ചൊല്ലി. റുകൂഈൽ നിന്നും ഉയർന്നപ്പോൾ ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' ''റബ്ബനാ വലകൽ ഹംദു'' (അല്ലാഹുവിനെ സ്തുതിച്ചവന്റെ വിളി അവൻ കേൾക്കട്ടെ, ഞങ്ങളുടെ നാഥാ! നിനക്കാകുന്നു സ്തുതി മുഴുവനും) എന്നു പറഞ്ഞു: ശേഷം സുജൂദിലേക്കു പോയപ്പോൾ തക്ബീർ ചൊല്ലി, അതിൽ നിന്നും തല ഉയർത്തിയപ്പോഴും തക്ബീർ ചൊല്ലി, ഒരു റക്അത്ത് പൂർത്തിയാക്കി എഴുന്നേറ്റപ്പോഴും തക്ബീർ ചൊല്ലി. ശേഷം പറഞ്ഞു: ''എന്റെ ആത്മാവുടയവൻ തന്നെ സത്യം, റസൂലി(സ)ന്റെ നിസ്കാരത്തോട് നിങ്ങളിൽ ഏറ്റവും സാദൃശ്യമുള്ളവൻ ഞാനാണ്'' ഇഹലോകവാസം വെടിയും വരെ ഇപ്രകാരമാണ് അദ്ദേഹം നിസ്കരിച്ചത്. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 452, 452, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 49, 'عَنْ مُطَرِّفٍ قَالَ: صَلَّيْتُ أَنَا وَعِمْرَانُ بْنُ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا خَلْفَ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: فَكَانَ إِذَا سَجَدَ كَبَّرَ، وَإِذَا رَكَعَ كَبَّرَ، وَإِذَا نَهَضَ مِنَ الرَّكْعَتَيْنِ كَبَّرَ، فَلَمَّا انْصَرَفْنَا أَخَذَ عِمْرَانُ بِيَدِي وَقَالَ: لَقَدْ صَلَّى هَذَا قَبْلُ – أَوْ قَالَ: لَقَدْ صَلَّى بِنَا هَذَا قَبْلُ – صَلَاةَ مُحَمَّدٍ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുത്വർരിഫ് പറഞ്ഞു: ഞാനും ഇംറാനുബ്നു ഹുസൈനും(റ) അലി(റ)യുടെ പിന്നിൽ നിസ്കരിച്ചു. അദ്ദേഹം സുജൂദിലേക്കു പോയപ്പോഴും, റുകൂഇലേക്കു പോയപ്പോഴും, രണ്ടു റക്അത്തുകൾ കഴിഞ്ഞ് എഴുന്നേറ്റപ്പോഴും തക്ബീർ ചെല്ലി. ഞങ്ങൾ (നിസ്കാരത്തിൽ നിന്ന്) വിരമിച്ചപ്പോൾ ഇംറാൻ എന്റെ കൈപിടിച്ച് പറഞ്ഞു: അദ്ദേഹം ഇപ്പോൾ ഞങ്ങളെയുമായി നിർവ്വഹിച്ച നിസ്കാരം നബി(സ)യുടെ നിസ്കാരത്തെപ്പോലെയാണ്. (ദ)', 'مُطَرِّفٍ قَالَ', 'മുത്വർരിഫ് പറഞ്ഞു', null, null, array['د']::text[], array['ദ']::text[], null, null, 452, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 50, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ لَا يُتِمُّ التَّكْبِيرَ. (د)', 'അബ്ദുർറഹ്മാനുബ്നു അബ്സാ(റ): അദ്ദേഹം തിരുമേനി(സ)യോടൊപ്പം നിസ്കരിച്ചു. അദ്ദേഹം തക്ബീർ പൂർത്തിയാക്കിയിരുന്നില്ല. (ദ)', 'عَبْدِ الرَّحْمَنِ بْنِ أَبْزَى', 'അബ്ദുർറഹ്മാനുബ്നു അബ്സാ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=10 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 51, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ الصَّلَاةَ بِالتَّكْبِيرِ، وَالْقِرَاءَةَ ب {الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ}. وَكَانَ إِذَا رَكَعَ لَمْ يُشْخِصْ رَأْسَهُ وَلَمْ يُصَوِّبْهُ وَلَكِنْ بَيْنَ ذَلِكَ، وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَائِمًا، وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَاعِدًا، وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ: "التَّحِيَّاتُ..." وَكَانَ إِذَا جَلَسَ يَفْرِشُ رِجْلَهُ الْيُسْرَى وَيَنْصِبُ رِجْلَهُ الْيُمْنَى، وَكَانَ يَنْهَى عَنْ عَقِبِ الشَّيْطَانِ وَعَنْ فَرْشَةِ السَّبُعِ، وَكَانَ يَخْتِمُ الصَّلَاةَ بِالتَّسْلِيمِ. (م,د,جه)', 'ആഇശ(റ): നബി(സ) തക്ബീർ കൊണ്ടായിരുന്നു നിസ്കാരം തുടങ്ങാറുണ്ടായിരുന്നത്. (നിസ്കാരത്തിൽ) ഖുർആൻ പാരായണം തുടങ്ങാറുള്ളത് ''അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ'' എന്നു പറഞ്ഞുകൊണ്ടായിരുന്നു. അവിടുന്ന് റുകൂഅ് ചെയ്യുമ്പോൾ തല ഉയർത്തുകയോ താഴ്തുകയോ ചെയ്യാറില്ല. രണ്ടിന്റെയും ഇടയിലായിട്ടായിരിക്കും. റുകൂഇൽ നിന്നുയർന്നാൽ നേരെ നിവർന്ന് നിന്ന ശേഷം മാത്രമാണ് സുജൂദ് ചെയ്യുക. സുജൂദിൽ നിന്ന് തലയുയർത്തിയാൽ നിവർന്ന് ഇരുന്ന ശേഷം മാത്രമാണ് (അടുത്ത) സുജൂദ് ചെയ്യുക. ഓരോ രണ്ടു റക്അതുകളിലും അവിടുന്ന് അത്തഹിയ്യാത്ത് ഓതും. ഇരിക്കുമ്പോൾ ഇടത്തേകാൽ പരത്തി വെച്ച് വലത്തേകാൽ (പാദം) നാട്ടിവെക്കും. പിശാചിന്റെ ഇരുത്തവും വന്യമൃഗങ്ങളുടേതുപോലെ കൈ പരത്തിവെച്ചുള്ള ഇരുത്തവും അവിടുന്ന് നിരോധിച്ചു. അവിടുന്ന് സലാം കൊണ്ടാണ് നിസ്കാരം അവസാനിപ്പിക്കാറുള്ളത്. (മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 52, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَأَبُو بَكْرٍ وَعُمَرُ يَفْتَتِحُونَ الْقِرَاءَةَ ب {الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ}. (ق,د,ت,ن,جه)', 'അനസ്ബ്നു മാലിക്(റ): നബി(സ)യും അബൂബക്കറും(റ) ഉമറും(റ) (നിസ്കാരത്തിൽ) ഖുർആൻ പാരായണം ആരംഭിച്ചത് അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ എന്ന് പറഞ്ഞുകൊണ്ടായിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്ബ്നു മാലിക്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 453, 453, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 53, 'عَنِ ابْنِ عَبْدِ اللهِ بْنِ الْمُغَفَّلِ، عَنْ أَبِيهِ رَضِيَ اللهُ عَنْهُ، قَالَ: وَقَلَّمَا رَأَيْتُ رَجُلًا أَشَدَّ عَلَيْهِ فِي الْإِسْلَامِ حَدَثًا مِنْهُ. فَسَمِعَنِي وَأَنَا أَقْرَأُ: {بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ}. فَقَالَ: أَيْ بُنَيَّ، إِيَّاكَ وَالْحَدَثَ، فَإِنِّي صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، وَمَعَ أَبِي بَكْرٍ، وَمَعَ عُمَرَ، وَمَعَ عُثْمَانَ، فَلَمْ أَسْمَعْ رَجُلًا مِنْهُمْ يَقُولُهُ، فَإِذَا قَرَأْتَ فَقُلْ: {الْحَمْدُ للهِ رَبِّ الْعَالَمِينَ}. (ت,ن,جه)', 'ഇബ്നുഅബ്ദുല്ല(റ) തന്റെ പിതാവിൽ നിന്ന്: ഇസ്ലാമിൽ പുതുതായി എന്തെങ്കിലും കടന്നുകൂടുന്നതിൽ അദ്ദേഹത്തോളം (പിതാവിനോളം) സൂക്ഷ്മതയുള്ളയാളെ ഞാൻ കണ്ടിട്ടില്ല. ഞാൻ ''ബിസ്മില്ലാഹിർറഹ്മാനിർ റഹീം'' എന്ന് ഓതുന്നത് അദ്ദേഹം കേട്ടു. അദ്ദേഹം പറഞ്ഞു: മോനേ, പുതുതായി കടന്നുകൂടുന്നത് നീ സൂക്ഷിക്കുക. ഞാൻ നബി(സ)യുടെയും അബൂബക്റി(റ)ന്റെയും ഉമറി(റ)ന്റെയും കൂടെ നിസ്കരിച്ചിട്ടുണ്ട്. അവരാരും അപ്രകാരം ഓതുന്നത് ഞാൻ കേട്ടിട്ടില്ല. നീ ഓതുമ്പോൾ ''അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ'' എന്ന് പറയുക. (തു,ന,ജ)', 'ابْنِ عَبْدِ اللهِ بْنِ الْمُغَفَّلِ، عَنْ أَبِيهِ', 'ഇബ്നുഅബ്ദുല്ല(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 453, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=11 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 54, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ بَيْنَ أَظْهُرِنَا إِذْ أَغْفَى إِغْفَاءَةً، ثُمَّ رَفَعَ رَأْسَهُ مُتَبَسِّمًا، فَقُلْنَا: مَا أَضْحَكَكَ يَا رَسُولَ اللهِ؟ قَالَ: "أُنْزِلَتْ عَلَيَّ آنِفًا سُورَةٌ، فَقَرَأَ: {بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ، فَصَلِّ لِرَبِّكَ وَانْحَرْ. إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ}. (م)', 'അനസ്(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പമായിരിക്കെ നബി(സ) പെട്ടെന്ന് തലതാഴ്ത്തി. പിന്നെ പുഞ്ചിരിച്ചുകൊണ്ട് തല ഉയർത്തി. ഞങ്ങൾ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ, അങ്ങ് എന്താണ് ചിരിക്കുന്നത്? നബ(സ) പറഞ്ഞു: "എനിക്ക് ഇപ്പോൾ ഒരു സൂറത്ത് മുഴുവനായും അവതരിച്ചിരിക്കുന്നു." എന്നിട്ട് ബിസ്മി ഓതിക്കൊണ്ട് അവിടുന്ന് സൂറത്തുൽകൗഥർ ഓതി. (മു)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 55, 'عَنْ نُعَيْمٍ الْمُجْمِرِ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ وَرَاءَ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ فَقَرَأَ: {بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ} ثُمَّ قَرَأَ بِأُمِّ الْقُرْآنِ، حَتَّى إِذَا بَلَغَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَقَالَ: آمِينَ. فَقَالَ النَّاسُ: آمِينَ. وَيَقُولُ كُلَّمَا سَجَدَ: اللهُ أَكْبَرُ، وَإِذَا قَامَ مِنَ الْجُلُوسِ فِي الِاثْنَتَيْنِ قَالَ: اللهُ أَكْبَرُ، وَإِذَا سَلَّمَ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، إِنِّي لَأَشْبَهُكُمْ صَلَاةً بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'നുഐമുൽമുജ്മിർ(റ): ഞാൻ അബൂഹുറൈറ(റ)ക്കു പിന്നിൽ നിസ്കരിച്ചു. അപ്പോൾ ബിസ്മി ഓതിക്കൊണ്ട് ഉമ്മുൽഖുർആൻ (ഫാതിഹ) ഓതി. അങ്ങനെ ''ഗൈരിൽ മഗ്ളുബി അലൈഹിം, വലല്ലാല്ലീൻ'' എത്തിയപ്പോൾ ''ആമീൻ'' പറഞ്ഞു. ജനങ്ങളും ആമീൻ പറഞ്ഞു. സുജൂദ് ചെയ്യുമ്പോഴൊക്കെ ''അല്ലാഹു അക്ബർ'' എന്നു പറഞ്ഞു. രണ്ടാമത്തെ റക്അത്തിൽ നിന്നുയരുമ്പോഴും ''അല്ലാഹു അക്ബർ'' എന്നു പറഞ്ഞു. എന്നിട്ട് സലാമിന് ശേഷം അബൂഹുറൈറ(റ) പറഞ്ഞു: ഞാൻ നിങ്ങളിൽ വെച്ച് നബി(സ)യുടെ നിസ്കാരത്തോട് ഏറ്റവും സാമ്യമുള്ളവനാണ്. (ന)', 'نُعَيْمٍ الْمُجْمِرِ', 'നുഐമുൽമുജ്മിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 56, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْتَتِحُ صَلَاتَهُ ب{بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ}. (خ,ت)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ''ബിസ്മില്ലാഹിർറഹ്മാനിർറഹീം'' എന്ന് ഓതിക്കൊണ്ട് നിസ്കാരം ആരംഭിക്കാറുണ്ടായിരുന്നു. (ബു,തു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ','ت']::text[], array['ബു','തു']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 57, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَا يَعْرِفُ فَصْلَ السُّورَةِ حَتَّى تَنْزِلَ عَلَيْهِ: {بِسْمِ اللهِ الرَّحْمَنِ الرَّحِيمِ}. (د)', 'ഇബ്നുഅബ്ബാസ്(റ): ''ബിസ്മി'' അവതരിക്കുന്നതുവരെ നബി(സ)ക്ക് സൂറത്തുകൾ തമ്മിലുള്ള വേർതിരിവ് അറിയുമായിരുന്നില്ല. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 454, 454, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=12 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 58, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي صَلَاةً فَقَالَ: "اللهُ أَكْبَرُ كَبِيرًا، اللهُ أَكْبَرُ كَبِيرًا، اللهُ أَكْبَرُ كَبِيرًا، وَالْحَمْدُ لله كَثِيرًا، وَالْحَمْدُ لله كَثِيرًا، وَسُبْحَانَ اللهِ بُكْرَةً وَأَصِيلًا" ثَلَاثًا. "أَعُوذُ بالله مِنَ الشَّيْطَانِ: مِنْ نَفْخِه وَنَفْثِه وَهَمْزِه". وَفِي رِوَايَةٍ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي التَّطَوُّعِ، ذَكَرَ نَحْوَهُ. (د,جه)', 'ജുബൈറ്ബ്നു മുത്ഇം(റ): നബി(സ) നിസ്കാരത്തിൽ പ്രവേശിച്ചാൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹു അക്ബർ കബീറാ (മൂന്ന് പ്രാവശ്യം), ''അൽഹംദുലില്ലാഹി കഥീറാ'' (മൂന്ന് പ്രാവശ്യം), ''സുബ്ഹാനല്ലാഹി ബുക്റതൻവഅസ്വീലാ'' (മൂന്ന് പ്രാവശ്യം)." പിന്നെ പറയും: "അല്ലാഹുവേ, ശപിക്കപ്പെട്ട പിശാചിൽ നിന്ന് ഞാൻ നിന്നിൽ ശരണം തേടുന്നു. അവന്റെ ദുർബോധനത്തിൽ നിന്നും മന്ത്രത്തിൽനിന്നും ഊത്തിൽ നിന്നും അവന്റെ ഉപദ്രവത്തിൽ നിന്നും (ഞാൻ നിന്നിൽ ശരണം തേടുന്നു)".
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=58), 1, 'وَفِي رِوَايَةٍ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي التَّطَوُّعِ، ذَكَرَ نَحْوَهُ. (د,جه)', 'മറ്റൊരു നിവേദനിൽ: റസൂൽ(സ) സുന്നത്ത് നിസ്കാരത്തിൽ ഇപ്രകാരം പറയുന്നതായി ഞാൻ കേട്ടിട്ടുണ്ട്..... (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 59, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا، زَوْجِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو فِي الصَّلَاةِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَ الْمَمَاتِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ". قَالَتْ: فَقَالَ لَهُ قَائِلٌ: مَا أَكْثَرَ مَا تَسْتَعِيذُ مِنَ الْمَغْرَمِ يَا رَسُولَ اللهِ؟ فَقَالَ: "إِنَّ الرَّجُلَ إِذَا غَرِمَ حَدَّثَ فَكَذَبَ، وَوَعَدَ فَأَخْلَفَ". (ق,د)', 'ആഇശ(റ): നബി(സ) നിസ്കാരത്തിൽ ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും, മസീഹുദ്ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്നും, ജീവിതത്തിലേയും മരണത്തിലേയും കുഴപ്പങ്ങളിൽ നിന്നും ഞാൻ രക്ഷ തേടുന്നു. അല്ലാഹുവേ, കുറ്റങ്ങളിൽ നിന്നും കടങ്ങളിൽ നിന്നും ഞാൻ നിന്നോട് രക്ഷ തേടുന്നു." ഒരാൾ ചോദിച്ചു: റസൂലേ, കടത്തിൽ നിന്ന് ഇത്രയധികം രക്ഷ തേടുന്നതെന്തിനാണ്? നബി(സ) പറഞ്ഞു: "ഒരാൾ കടക്കാരനായാൽ സംസാരത്തിൽ കളവു പറയും, കരാർ ചെയ്താൽ ലംഘിക്കും." (ബു,മു,ദ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د']::text[], array['ബു','മു','ദ']::text[], null, null, 455, 455, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=13 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 60, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ- ثَلَاثًا- غَيْر تَمَام". فَقِيلَ لِأَبِي هُرَيْرَةَ: إِنَّا نَكُونُ وَرَاءَ الْإِمَامِ؟ فَقَالَ: اقْرَأْ بِهَا فِي نَفْسِكَ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "قَالَ اللهُ تَعَالَى: قَسَمْتُ الصَّلَاةَ بَيْنِي وَبَيْنَ عَبْدِي نِصْفَيْنِ، وَلِعَبْدِي مَا سَأَلَ، فَإِذَا قَالَ الْعَبْدُ: {الْحَمْدُ لله رَبِّ الْعَالَمِينَ} قَالَ اللهُ تَعَالَى: حَمِدَنِي عَبْدِي. وَإِذَا قَالَ: {الرَّحْمَنِ الرَّحِيمِ} قَالَ اللهُ تَعَالَى: أَثْنَى عَلَيَّ عَبْدِي. وَإِذَا قَالَ: {مَالِكِ يَوْمِ الدِّينِ} قَالَ اللهُ: مَجَّدَنِي عَبْدِي - وَقَالَ مَرَّةً: فَوَّضَ إِلَيَّ عَبْدِي - فَإِذَا قَالَ: {إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ} قَالَ: هَذَا بَيْنِي وَبَيْنَ عَبْدِي، وَلِعَبْدِي مَا سَأَلَ. فَإِذَا قَالَ: {اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ. صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} قَالَ: هَذَا لِعَبْدِي، وَلِعَبْدِي مَا سَأَلَ". (م,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഉമ്മുൽ ഖുർആൻ (ഫാത്തിഹഃ) പാരായണം ചെയ്യാതെ ആരെങ്കിലും നിസ്കരിച്ചാൽ അത് അപൂർണ്ണമാണ്." അപ്പോൾ അബൂഹുറൈറ(റ)യോട് ചോദിച്ചു: ഞങ്ങൾ ഇമാമിന്ന് പിന്നിലാണെങ്കിലോ? അദ്ദേഹം പറഞ്ഞു: അത് നിങ്ങൾ മനസ്സിൽ ഓതുക. നബി(സ) പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹു പറഞ്ഞു: എനിക്കും അടിമക്കുമിടയിൽ നിസ്കാരത്തെ രണ്ട് ഭാഗമാക്കിയിട്ടുണ്ട്. എന്റെ അടിമക്ക് അവൻ ചോദിക്കുന്നതുണ്ട്. എന്റെ അടിമ ''അൽഹംദുലില്ലാഹി റബ്ബിൽ ആലമീൻ'' എന്നു പറഞ്ഞാൽ അല്ലാഹു പറയും: എന്റെ അടിമ എന്നെ വാഴ്ത്തിയിരിക്കുന്നു. അവൻ ''അർറഹ്മാനിർറഹീം'' എന്നുപറഞ്ഞാൽ അല്ലാഹു പറയും: ''എന്റെ അടിമ എന്നെ പ്രകീർത്തിച്ചിരിക്കുന്നു. അവൻ ''മാലികി യൗമിദ്ദീൻ'' എന്നു പറഞ്ഞാൽ അല്ലാഹു പറയും: എന്റെ അടിമ എന്നെ പ്രതാപവാനാക്കിയിരിക്കുന്നു. അവൻ ''ഇയ്യാകനഅ്ബുദു വഇയ്യാക നസ്തഈൻ'' എന്നു പറയുമ്പോൾ അവൻ പറയും: ഇത് എനിക്കും അടിമക്കും ഇടയിലുള്ളതാണ്. എന്റെ അടിമ ചോദിച്ചത് അവനുണ്ട്. അതിനു ശേഷം ''വലള്ളാല്ലീൻ'' വരെ ഓതിയാൽ അല്ലാഹു പറയും: ഇതെന്റെ അടിമക്കുള്ളതാണ്. അവൻ ചോദിച്ചത് അവനുണ്ട്." (മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 455, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 61, 'عَنْ مَحْمُودِ بْنِ الرَّبِيعِ رَضِيَ اللهُ عَنْهُ، عَنْ عُبَادَةَ بْنِ الصَّامِتِ رَضِيَ اللهُ عَنْهُ، يَبْلُغُ بِهِ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا صَلَاةَ لِمَنْ لَمْ يَقْرَأْ بِفَاتِحَةِ الْكِتَابِ فَصَاعِدًا". (ق,د,ت,ن,جه)', 'മുഹമ്മദുബ്ൻ റബീഅ(റ), ഉബാദത്തുബ്നു സ്സാമിത്ത്(റ): നബി(സ)യിൽ നിന്ന്: "ഫാത്തിഹ (ഖുർആനിലെ പ്രഥമ അദ്ധ്യായം) സൂറത്തോ അതിലുപരിയോ³ ഓതാത്തവന് നിസ്കാരമില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'مَحْمُودِ بْنِ الرَّبِيعِ', 'മുഹമ്മദുബ്ൻ റബീഅ(റ)', '³. ചുരുങ്ങിയ നിലയിൽ ഫാത്തിഹ സൂറത്തെങ്കിലും ഓതിയിരിക്കണമെന്ന് സാരം', null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=14 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 62, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بَيْنَمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ - وَعِنْدَهُ جِبْرِيلُ عَلَيْهِ السَّلَامُ - إِذْ سَمِعَ نَقِيضًا فَوْقَهُ، فَرَفَعَ جِبْرِيلُ عَلَيْهِ السَّلَامُ بَصَرَهُ إِلَى السَّمَاءِ فَقَالَ: "هَذَا بَابٌ قَدْ فُتِحَ مِنَ السَّمَاءِ مَا فُتِحَ قَطُّ." قَالَ: فَنَزَلَ مِنْهُ مَلَكٌ، فَأَتَى النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَبْشِرْ بِنُورَيْنِ أُوتِيتَهُمَا، لَمْ يُؤْتَهُمَا نَبِيٌّ قَبْلَكَ: فَاتِحَةُ الْكِتَابِ، وَخَوَاتِيمُ سُورَةِ الْبَقَرَةِ، لَمْ تَقْرَأْ حَرْفًا مِنْهُمَا إِلَّا أُعْطِيتَهُ". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ അടുത്ത് ജിബ്രീൽ ഉണ്ടായിരിക്കെ മുകളിൽ നിന്നൊരു ഞരക്കം കേട്ടു. അപ്പോൾ ജിബ്രീൽ(അ) കണ്ണുകൾ മേൽപ്പോട്ട് ഉയർത്തിപ്പറഞ്ഞു: "ഒരിക്കലും തുറന്നിട്ടില്ലാത്ത ഒരു വാതിൽ തുറന്നതിന്റെ ശബ്ദമാണത്." അതിൽ നിന്നൊരു മലക്ക് ഇറങ്ങി വന്ന് നബി(സ)യോട് പറഞ്ഞു: നിങ്ങൾക്ക് നൽകപ്പെട്ട രണ്ട് പ്രകാശത്തെ കുറിച്ച് നാം സന്തോഷ വാർത്ത അറിയിക്കുന്നു. താങ്കൾക്ക് മുമ്പ് ഒരു പ്രവാചകനും അത് നൽകപ്പെട്ടിട്ടില്ല. ഒന്ന് ഫാതിഹയും രണ്ട് സൂറത്തുൽ ബഖറയുടെ അവസാനവും. അതിൽ നിന്നൊരു വാക്കും നിങ്ങൾ പാരായണം ചെയ്യുന്നില്ല അത് നൽകപ്പെട്ടിട്ടല്ലാതെ." (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 63, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: أُمِرْنَا أَنْ نَقْرَأَ بِفَاتِحَةِ الْكِتَابِ وَمَا تَيَسَّرَ. (د)', 'അബൂസഈദിൽ ഖുദ്രി(റ): സൂറത്തുൽ ഫാതിഹയും, എളുപ്പമായവയും (എളുപ്പമുള്ള മറ്റു സൂറത്തുകളും) ഓതാൻ ഞങ്ങൾ കൽപിക്കപ്പെട്ടു. (ദ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 456, 456, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 64, 'عَنْ مَكْحُولٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ كَانَ يَقْرَأُ فِي الْمَغْرِبِ وَالْعِشَاءِ وَالصُّبْحِ بِفَاتِحَةِ الْكِتَابِ فِي كُلِّ رَكْعَةٍ سِرًّا، قَالَ مَكْحُولٌ: اقْرَأْ بِهَا فِيمَا جَهَرَ بِهِ الْإِمَامُ إِذَا قَرَأَ بِفَاتِحَةِ الْكِتَابِ وَسَكَتَ سِرًّا، فَإِنْ لَمْ يَسْكُتْ اقْرَأْ بِهَا قَبْلَهُ وَمَعَهُ وَبَعْدَهُ، لَا تَتْرُكْهَا عَلَى كُلِّ حَالٍ. (د)', 'മക്ഹൂൽ(റ): അദ്ദേഹം മഗ്രിബിലെയും, ഇശാഇലെയും, സുബ്ഹിലെയുമുള്ള എല്ലാ റക്അത്തുകളിലും ഫാത്തിഹ പതുക്കെ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. മക്ഹൂൽ പറഞ്ഞു: ഉച്ചത്തിൽ ഓതുന്ന നിസ്കാരത്തിൽ ഇമാം ഫാത്തിഹ ഓതി മൗനം പാലിച്ചാൽ നീ പതുക്കെ ഓതുക. ഇമാം മൗനം പാലിക്കുന്നില്ലെങ്കിൽ (പാരായണം തുടർന്നാൽ) ഇമാമിന് മുമ്പോ കൂടെയോ ശേഷമോ ഫാത്തിഹ ഓതുക. എങ്ങനെ ആയിരുന്നാലും അത് ഉപേക്ഷിക്കരുത്. (ദ)', 'مَكْحُولٍ', 'മക്ഹൂൽ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 456, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=15 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 65, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا قَالَ أَحَدُكُمْ آمِينَ، وَقَالَتِ الْمَلَائِكَةُ فِي السَّمَاءِ آمِينَ، فَوَافَقَتْ إِحْدَاهُمَا الْأُخْرَى، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (ن)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: ഒരാൾ ''ആമീൻ'' എന്നു ചൊല്ലുകയും മലക്കുകൾ ആകാശത്തുനിന്നും ''ആമീൻ'' ചൊല്ലുകയും അവ രണ്ടും പരസ്പരം യോജിച്ചു വരികയും ചെയ്താൽ അയാൾക്ക് അയാളുടെ മുൻകഴിഞ്ഞ പാപങ്ങൾ പൊറുത്തു കൊടുക്കുന്നതാണ്. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=16 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 66, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَأَنِّي أَسْمَعُ صَوْتَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي صَلَاةِ الْغَدَاةِ: {فَلَا أُقْسِمُ بِالْخُنَّسِ. الْجَوَارِي الْكُنَّسِ}. (م,د,جه)', 'അംറുബ്നു ഹുറൈസ്(റ): (സൂറ:അത്തക്വീറിലെ) ''ഫലാ ഉഖ്സിമു ബിൽ ഖുന്നസ്......'' (എന്ന ഭാഗം) പ്രഭാത നിസ്കാരത്തിൽ നബി(സ) പാരായണം ചെയ്യുന്നത് ഞാൻ ഇപ്പോഴും കേൾക്കുന്നതു പോലെയുണ്ട്. (മു,ദ,ജ)', 'عَمْرِو بْنِ حُرَيْثٍ', 'അംറുബ്നു ഹുറൈസ്(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 67, 'عَنْ سِمَاكِ بْنِ حَرْبٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ جَابِرَ بْنَ سَمُرَةَ رَضِيَ اللهُ عَنْهُ عَنْ صَلَاةِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: كَانَ يُخَفِّفُ الصَّلَاةَ، وَلَا يُصَلِّي صَلَاةَ هَؤُلَاءِ. قَالَ: وَأَنْبَأَنِي أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الْفَجْرِ ب{ق. وَالْقُرْآنِ الْمَجِيدِ} وَنَحْوِهَا. (م,ن)', 'സിമാകുബ്നു ഹർബ്(റ): ഞാൻ ജാബിറുബ്നു സമുറയോട് നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ചോദിച്ചു: അദ്ദേഹം പറഞ്ഞു: നബി(സ) നിസ്കാരം ലഘുവായി നിർവ്വഹിക്കുമായിരുന്നു. ഇവരെപ്പോലെയൊന്നും നിസ്കരിക്കുകയില്ല. നബി(സ) പ്രഭാത നിസ്കാരത്തിൽ ''ഖാഫ് വൽ ഖുർആനിൽ മജീദ്'' പോലുള്ളവയാണ് ഓതിയിരുന്നതെന്ന് എനിക്കറിയാം. (മു,ന)', 'سِمَاكِ بْنِ حَرْبٍ', 'സിമാകുബ്നു ഹർബ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 68, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: فِي كُلِّ صَلَاةٍ يُقْرَأُ فَمَا أَسْمَعَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَسْمَعْنَاكُمْ، وَمَا أَخْفَى عَنَّا أَخْفَيْنَا عَنْكُمْ، وَإِنْ لَمْ تَزِدْ عَلَى أُمِّ الْقُرْآنِ أَجْزَأَتْ وَإِنْ زِدْتَ فَهُوَ خَيْرٌ. (خ)', 'അബൂഹുറൈറ(റ): ഓരോ നിസ്കാരത്തിലും (ഖുർആൻ) ഓതാറുണ്ട്. നബി(സ) ഞങ്ങളെ കേൾപ്പിച്ചത് ഞങ്ങൾ നിങ്ങളെ കേൾപിക്കുകയും ഞങ്ങൾക്ക് മറച്ചത് (പതുക്കെ ഓതിയത്) നിങ്ങൾക്ക് മറക്കുകയും ചെയ്യുന്നു. ഉമ്മുൽ ഖുർആനല്ലാതെ (ഫാതിഹ) മറ്റൊന്നും പാരായണം ചെയ്തില്ലെങ്കിലും അത് മതി. മറ്റെന്തെങ്കിലും കൂടി പാരായണം ചെയ്താൽ അത് ഉത്തമം . (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 69, 'عَنْ أَبِي بَرْزَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الْفَجْرِ مَا بَيْنَ السِّتِّينَ إِلَى الْمِائَةِ. (م,ن,جه)', 'അബൂബർസ(റ): നബി(സ) പ്രഭാത നിസ്കാരത്തിൽ അറുപതിനും നൂറിനും ഇടയിൽ ആയത്തുകൾ പാരായണം ചെയ്തിരുന്നു. (മു,ന,ജ)', 'أَبِي بَرْزَةَ', 'അബൂബർസ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 457, 457, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 70, 'عَنْ عَبْدِ اللهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: قَرَأَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الصُّبْحِ ب{الْمُؤْمِنُونَ}. فَلَمَّا أَتَى عَلَى ذِكْرِ عِيسَى أَصَابَتْهُ شَرْقَةٌ فَرَكَعَ. يَعْنِي سَعْلَةً. (ق,د,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ): നബി(സ) പ്രഭാത നിസ്കാരത്തിൽ സൂറത്തു''അൽ മുഅ്മിനൂൻ'' പാരായണം ചെയ്തു. അങ്ങനെ ഈസാ(അ)യെക്കുറിച്ച വിവരണം എത്തിയപ്പോൾ ഒരു ചുമ അനുഭവപ്പെട്ടു. പിന്നെ റുകൂഅ് ചെയ്തു. (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ السَّائِبِ', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 71, 'عَنْ قُطْبَةَ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الصُّبْحِ: {وَالنَّخْلَ بَاسِقَاتٍ لَهَا طَلْعٌ نَضِيدٌ} [ق:١٠] (م,ت,ن,جه)', 'ഖുത്ബത്ബ്നു മാലിക്(റ): നബി(സ) സുബ്ഹിക്ക് ''വന്നഖ്ല ബാസിഖാതില്ലഹാ.....'' (സൂറ: ഖാഫ്. 10) എന്ന് പാരായണം ചെയ്യുന്നത് അദ്ദേഹം കേട്ടു. (മു,തു,ന,ജ)', 'قُطْبَةَ بْنِ مَالِكٍ', 'ഖുത്ബത്ബ്നു മാലിക്(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], 'ق:١٠', null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 72, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي رَكْعَتَيِ الْفَجْرِ: فِي الْأُولَى مِنْهُمَا الْآيَةَ الَّتِي فِي الْبَقَرَةِ: {قُولُوا آمَنَّا بِاللهِ وَمَا أُنْزِلَ إِلَيْنَا ..} إِلَى آخِرِ الْآيَةِ [الْبَقَرَة: ١٣٦]. وَفِي الْأُخْرَى: {آمَنَّا بِاللهِ وَاشْهَدْ بِأَنَّا مُسْلِمُونَ} [آل عمران:٥٢]. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഫജ്റിലെ രണ്ട് റക്അത്തുകളിലെ ആദ്യത്തേതിൽ സൂറത്തുൽ ബഖറയിലെ ''ഖൂലൂ ആമന്നാ ബില്ലാഹി വമാ ഉൻസില ഇലൈനാ.....'' (അൽബഖറ: 136) എന്ന ആയത്തും, അവസാനത്തേതിൽ ''ആമന്നാ ബില്ലാഹി.....'' (ആലുഇംറാൻ: 52) എന്ന സൂക്തവും ഓതുമായിരുന്നു. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], 'آل عمران:٥٢', null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 73, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي رَكْعَتَيِ الْفَجْرِ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ {قُلْ هُوَ اللهُ أَحَدٌ}. (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഫജ്റിലെ രണ്ട് റക്അത്തിൽ ''കുൽയാ അയ്യുഹൽ കാഫിറൂന''യും ''കുൽ ഹുവല്ലാഹു അഹദും'' ഓതി. (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 74, 'عَنْ عَمْرِو بْنِ حُرَيْثٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْفَجْرِ: {إِذَا الشَّمْسُ كُوِّرَتْ}. (ن)', 'അംറ്ബ്നു ഹുറൈസ്(റ): നബി(സ) ഫജ്റ് നിസ്കാരത്തിൽ ''ഇദ ശ്ശംസു കുവ്വിറത്'' ഓതുന്നത് ഞാൻ കേട്ടു. (ന)', 'عَمْرِو بْنِ حُرَيْثٍ', 'അംറ്ബ്നു ഹുറൈസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 75, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَأَلَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْمُعَوِّذَتَيْنِ؟ قَالَ عُقْبَةُ: فَأَمَّنَا بِهِمَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ الْفَجْرِ. (ن)', 'ഉഖ്ബത്ബ്നു ആമിർ(റ): അദ്ദേഹം നബി(സ)യോട് ''മുഅവ്വിദതൈനി''യെക്കുറിച്ച് ചോദിച്ചു. ഉഖ്ബ പറയുന്നു: അങ്ങനെ അവ ഓതിക്കൊണ്ട് ഫജ്റിൽ നബി(സ) ഞങ്ങൾക്ക് ഇമാമത്ത് നിന്നു. (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബത്ബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 458, 458, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 76, 'عَنْ شَبِيبٍ أَبِي رَوْحٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: أَنَّهُ صَلَّى صَلَاةَ الصُّبْحِ، فَقَرَأَ الرُّومَ، فَالْتَبَسَ عَلَيْهِ، فَلَمَّا صَلَّى قَالَ: "مَا بَالُ أَقْوَامٍ يُصَلُّونَ مَعَنَا لَا يُحْسِنُونَ الطُّهُورَ، فَإِنَّمَا يَلْبِسُ عَلَيْنَا الْقُرْآنَ أُولَئِكَ". (ن)', 'ശബീബ്(റ): സഹാബാക്കളിൽപ്പെട്ട ഒരാൾ പറഞ്ഞു: നബി(സ) പ്രഭാത നിസ്കാരത്തിൽ സൂറത്തുർറും ഓതിക്കൊണ്ട് നിസ്കരിച്ചു. (നിസ്കാരത്തിൽ) സംശയം വന്നു. നിസ്കാര ശേഷം പറഞ്ഞു "നല്ലവണ്ണം ശുദ്ധി വരുത്താതെ നമ്മോടൊപ്പം നിസ്കരിക്കുന്ന സമൂഹത്തിന്റെ അവസ്ഥ എന്ത്? ഖുർആൻ നമുക്ക് സംശയമാകുന്നത് അവർ മൂലമാണ്." (ന)', 'شَبِيبٍ أَبِي رَوْحٍ، عَنْ رَجُلٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ', 'ശബീബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 458, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 77, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي صَلَاةِ الْفَجْرِ يَوْمَ الْجُمُعَةِ: {تَنْزِيلُ} السَّجْدَةَ، وَ: {هَلْ أَتَى عَلَى الْإِنْسَانِ حِينٌ مِنَ الدَّهْرِ} وفي راية: في صَلَاةِ الْجُمُعَةِ بِسُورَةِ الْجُمُعَةِ وَ: {إِذَا جَاءَكَ الْمُنَافِقُونَ}. (م,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബസ്(റ): റസൂൽ(സ) വെള്ളിയാഴ്ച സുബ്ഹ് നമസ്കാരത്തിൽ സൂറത്തുസ്സജദയും, ഹൽ ഹതാ അലൽ ഇൻസാനി....യും ഓതാറുണ്ടായിരുന്നു. മറ്റൊരു റിപ്പോർട്ടിൽ: പ്രവാചകൻ(സ) ജുമുഅ നമസ്കാരത്തിൽ സൂറത്തുൽ ജുമുഅയും, ഇദാജാഅകൽ മുനാഫികൂന....യും ഓതാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 459, 459, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=17 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=77), 1, null, 'മറ്റൊരു നിവേദനിൽ: പ്രവാചകൻ(സ) ജുമുഅ നമസ്കാരത്തിൽ സൂറത്തുൽ ജുമുഅയും, ഇദാജാഅകൽ മുനാഫികൂന....യും ഓതാറുണ്ടായിരുന്നു. (മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 78, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: انْطَلَقَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي طَائِفَةٍ مِنْ أَصْحَابِهِ عَامِدِينَ إِلَى سُوقِ عُكَاظٍ، وَقَدْ حِيلَ بَيْنَ الشَّيَاطِينِ وَبَيْنَ خَبَرِ السَّمَاءِ، وَأُرْسِلَتْ عَلَيْهِمُ الشُّهُبُ فَرَجَعَتِ الشَّيَاطِينُ إِلَى قَوْمِهِمْ، فَقَالُوا مَا لَكُمْ؟ فَقَالُوا: حِيلَ بَيْنَنَا وَبَيْنَ خَبَرِ السَّمَاءِ وَأُرْسِلَتْ عَلَيْنَا الشُّهُبُ، قَالُوا: مَا حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ إِلَّا شَيْءٌ حَدَثَ فَاضْرِبُوا مَشَارِقَ الْأَرْضِ وَمَغَارِبَهَا فَانْظُرُوا مَا هَذَا الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ، فَانْصَرَفَ أُولَئِكَ الَّذِينَ تَوَجَّهُوا نَحْوَ تِهَامَةَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ بِنَخْلَةَ عَامِدِينَ إِلَى سُوقِ عُكَاظٍ وَهُوَ يُصَلِّي بِأَصْحَابِهِ الْفَجْرَ، فَلَمَّا سَمِعُوا الْقُرْآنَ اسْتَمَعُوا لَهُ، فَقَالُوا: هَذَا وَاللهِ الَّذِي حَالَ بَيْنَكُمْ وَبَيْنَ خَبَرِ السَّمَاءِ، فَهُنَالِكَ حِينَ رَجَعُوا إِلَى قَوْمِهِمْ، وَقَالُوا يَا قَوْمَنَا {إِنَّا سَمِعْنَا قُرْآنًا عَجَبًا يَهْدِي إِلَى الرُّشْدِ فَآمَنَّا بِهِ وَلَنْ نُشْرِكَ بِرَبِّنَا أَحَدًا} فَأَنْزَلَ اللهُ عَلَى نَبِيِّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ {قُلْ أُوحِيَ إِلَيَّ} وَإِنَّمَا أُوحِيَ إِلَيْهِ قَوْلُ الْجِنِّ. (خ)', 'ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: ''ഉക്കാള്'' ചന്തയെ ലക്ഷ്യമാക്കി ഒരിക്കൽ തിരുമേനി ഒരു സംഘം അനുചരന്മാരോടൊപ്പം പോയി. പിശാചുകൾക്ക് വാനലേകത്തെ വാർത്തകൾ കേൾക്കുന്നത് തടയപ്പെട്ട ഘട്ടമായിരുന്നു അത്. തന്നിമിത്തം അഗ്നിജ്വാലകൾക്കൊണ്ട് (അല്ലെങ്കിൽ പന്തങ്ങൾകൊണ്ട്) അവരെറിയപ്പെട്ടു. പിശാചുക്കൾ അവരുടെ ജനതയിലേക്കു മടങ്ങി. നിങ്ങൾക്കെന്തുപറ്റിയെന്ന് ആ ജനത പിശാചുക്കളോടു ചോദിച്ചു. പിശാചുക്കൾ പറഞ്ഞു: ഞങ്ങൾക്കും വാനലേകവാർത്തകൾക്കുമിടയിൽ തടസ്സം സൃഷ്ടിക്കപ്പെട്ടിരിക്കയാണ്; ഞങ്ങളുടെ നേരെ തീപ്പന്തങ്ങൾ എറിയപ്പെടുന്നു. ആ ജനത പറഞ്ഞു: നിങ്ങൾക്കും വാനലേകവാർത്തകൾക്കുമിടയിൽ തടസ്സം സൃഷ്ടിക്കുന്ന എന്തോ ഒരു സംഭവം ഉണ്ടായിട്ടുണ്ട്. അതിന്റെ യാഥാർത്ഥ്യം കണ്ടു പിടിക്കാൻ, നിങ്ങൾ കിഴക്കും പടിഞ്ഞാറുമുള്ള സ്ഥലങ്ങളിലെല്ലാം സഞ്ചരിക്കുക; നിങ്ങൾക്കും വാനലോകവാർത്തകൾക്കുമിടയിൽ വന്നുഭവിച്ച തടസ്സമെന്തെന്ന് കണ്ടുപിടിക്കുക. അങ്ങനെ ''തിഹാമ''യുടെ (മക്കയുടെ) ഭാഗത്തേക്കു (അന്വേഷണത്തിന്നായി) തിരിഞ്ഞവർ നബി(സ)യുടെ അടുക്കൽ എത്തിച്ചേർന്നു. തിരുമേനി(സ)യും കൂട്ടുകാരുമാവട്ടെ, ഉക്കാള് ചന്തയിലേക്കുള്ള വഴിമധ്യേ നഖ്ലത്ത് എന്ന പ്രദേശത്തായിരുന്നു. അക്കൂട്ടർ എത്തിച്ചേർന്നപ്പോൾ തിരുമേനി(സ) അനുചരന്മാരോടൊപ്പം സുബ്ഹ് നിസ്കരിക്കുകയാണ്. തിരുമേനി(സ) ഖുർആൻ ഓതുന്നതു അവർ ശ്രദ്ധിച്ചുകേട്ടു. വാനലോകത്തെ വാർത്തകൾ കേൾക്കുന്നതിൽ നമുക്ക് തടസ്സമുണ്ടാക്കിയത് ഈ സന്ദേശം തന്നെയാണെന്നു അവരന്യോന്യം പറഞ്ഞു. തങ്ങളുടെ ജനതയിലേക്കു തിരിച്ചുചെന്നപ്പോൾ അവർ പറഞ്ഞു: "ഞങ്ങളുടെ സമുദായമേ! അത്ഭുതകരമായൊരു ഖുർആനാണ് ഞങ്ങൾ കേട്ടത്. അത് മനുഷ്യന് നേർമാർഗ്ഗത്തിലേക്ക് വഴി കാണിക്കുന്നു. അതുകൊണ്ട് ഞങ്ങളിതാ അതിൽ വിശ്വസിച്ചുകഴിഞ്ഞിരിക്കുന്നു. ഞങ്ങളുടെ രക്ഷിതാവിന്റെ (അല്ലാഹുവിന്റെ) അധികാരാവകാശങ്ങളിൽ അവന്നു ഒരു പങ്കാളിയേയും ഞങ്ങൾ സ്ഥാപിക്കുകയില്ല. അന്നേരമാണ് "ഖുൽ ഊഹിയ ഇലയ്യ" എന്ന അദ്ധ്യായം അല്ലാഹു നബി(സ)ക്ക് അവതരിപ്പിച്ചുകൊടുത്തത്. തിരുമേനി(സ)ക്ക് അല്ലാഹു നൽകിയ സന്ദേശം ജിന്നുകളുടെ വാക്കായിരുന്നു. (ബു)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 459, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=18 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 79, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: إِنْ كُنْتُ لَأَرَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي رَكْعَتَيِ الْفَجْرِ، فَيُخَفِّفُهُمَا حَتَّى أَقُولَ: أَقَرَأَ فِيهِمَا بِأُمِّ الْكِتَابِ . (ن)', 'ആഇശ(റ): നബി(സ) ഫജ്റിന്റെ രണ്ട് റക്അത്ത് നമസ്കരിക്കുന്നത് ഞാൻ കാണാറുണ്ടായിരുന്നു. അത് വളരെ ലഘുവായിരുന്നു. (എത്രത്തോളമെന്നു വെച്ചാൽ) തിരുമേനി(സ) അതിൽ ഫാതിഹ ഓതിയിരുന്നോ? എന്നുപോലും ഞാൻ ചോദിച്ചു പോയി. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=19 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 80, 'عَنْ قَزَعَةَ بْنِ يَحْيَى رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ أَبَا سَعِيدٍ الْخُدْرِيَّ رَضِيَ اللهُ عَنْهُ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: لَيْسَ لَكَ فِي ذَلِكَ خَيْرٌ، قُلْتُ: بَيِّنْ، رَحِمَكَ اللهُ. قَالَ: كَانَتِ الصَّلَاةُ تُقَامُ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: الظُّهْرَ، فَيَخْرُجُ أَحَدُنَا إِلَى الْبَقِيعِ، فَيَقْضِي حَاجَتَهُ، فَيَجِيءُ فَيَتَوَضَّأُ، فَيَجِدُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الرَّكْعَةِ الْأُولَى مِنَ الظُّهْرِ. (م,ن,جه)', 'ഖസ്അത്തബ്നു യഹ്യ(റ): ഞാൻ അബൂസഈദിൽ ഖുദ്രി(റ)യോട് നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: നിനക്കതിൽ കാര്യമൊന്നുമില്ല. ഞാൻ പറഞ്ഞു: വിശദീകരിച്ചാലും! അല്ലാഹു നിങ്ങളെ അനുഗ്രഹിക്കട്ടെ. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ളുഹ്ർ നിസ്കാരത്തിനു നിൽക്കും. അപ്പോൾ ഞങ്ങളിലൊരാൾ താഴ്വരയിൽ ചെന്ന് ആവശ്യം നിർവ്വഹിച്ച് (വിസർജ്ജനാവശ്യം) വുദു ചെയ്ത് വന്നാലും നബി(സ) ഒന്നാമത്തെ റക്അത്തിൽ തന്നെയായിരിക്കും. (മു,ന,ജ)', 'قَزَعَةَ بْنِ يَحْيَى', 'ഖസ്അത്തബ്നു യഹ്യ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 81, 'عَنْ أَبِي مَعْمَرٍ عَبْدِ اللهِ بْنِ سَخْبَرَةَ الْأَزْدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْتُ لِخَبَّابٍ رَضِيَ اللهُ عَنْهُ: بِأَيِّ شَيْءٍ كُنْتُمْ تَعْرِفُونَ قِرَاءَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الظُّهْرِ وَالْعَصْرِ؟ قَالَ: بِاضْطِرَابِ لِحْيَتِهِ. (خ,د,جه)', 'അബൂമഅ്മർ അബ്ദുല്ല(റ): ഞാൻ ഖബ്ബാബി(റ)നോട് ചോദിച്ചു: ളുഹ്റിലെയും അസ്റിലെയും നബി(സ)യുടെ ഖിറാഅത്തിനെക്കുറിച്ച് നിങ്ങൾ എങ്ങിനെയാണ് മനസ്സിലാക്കുന്നത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ)യുടെ താടിയുടെ ഇളക്കത്തിൽ നിന്ന്. (ബു,ദ,ജ)', 'أَبِي مَعْمَرٍ عَبْدِ اللهِ بْنِ سَخْبَرَةَ الْأَزْدِيِّ', 'അബൂമഅ്മർ അബ്ദുല്ല(റ)', null, null, array['خ','د','جه']::text[], array['ബു','ദ','ജ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 82, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَا رَأَيْتُ أَحَدًا أَشْبَهَ صَلَاةً بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ فُلَانٍ. قَالَ: وَكَانَ يُطِيلُ الْأُولَيَيْنِ مِنَ الظُّهْرِ وَيُخَفِّفُ الْأُخْرَيَيْنِ، وَيُخَفِّفُ الْعَصْرَ. (ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ നിസ്കാരത്തോട് ഇത്രത്തോളം സാദൃശ്യമുള്ളതായി ഇന്ന വ്യക്തിയല്ലാതെ ഞാൻ മറ്റാരെയും കണ്ടിട്ടില്ല. നബി(സ) ളുഹ്റിൽ ആദ്യത്തെ രണ്ട് റക്അത്ത് ദീർഘിപ്പിക്കുകയും പിന്നെ അവസാനത്തെ രണ്ട് റക്അത്ത് ലഘൂകരിക്കുകയും ചെയ്തിരുന്നു. അസ്റിനെ ലഘുവാക്കുമായിരുന്നു. (ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 460, 460, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 83, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: اجْتَمَعَ ثَلَاثُونَ بَدْرِيًّا مِنْ أَصْحَابِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: تَعَالَوْا حَتَّى نَقِيسَ قِرَاءَةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا لَمْ يَجْهَرْ فِيهِ مِنَ الصَّلَاةِ. فَمَا اخْتَلَفَ مِنْهُمْ رَجُلَانِ، فَقَاسُوا قِرَاءَتَهُ فِي الرَّكْعَةِ الْأُولَى مِنَ الظُّهْرِ بِقَدْرِ ثَلَاثِينَ آيَةً، وَفِي الرَّكْعَةِ الْأُخْرَى قَدْرَ النِّصْفِ مِنْ ذَلِكَ، وَقَاسُوا ذَلِكَ فِي صَلَاةِ الْعَصْرِ عَلَى قَدْرِ النِّصْفِ مِنَ الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ مِنَ الظُّهْرِ. [ز:إسناده ضعيف] (جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ബദ്റിൽ പങ്കെടുത്ത മുപ്പതോളം സഹാബികൾ ഒരുമിച്ചുകൂടി പറഞ്ഞു: വരൂ, നമുക്ക് പതുക്കെ പാരായണം ചെയ്യുന്ന നിസ്കാരങ്ങളിൽ നബി(സ)യുടെ ഖുർആൻ പാരായാണത്തെ താരതമ്യപ്പെടുത്താം! അവരിൽ രണ്ടുപേർക്കുപോലും അഭിപ്രായാന്തരമുണ്ടായില്ല. ളുഹ്ർ ഒന്നാം റക്അത്തിൽ മുപ്പത് സൂക്തങ്ങൾക്ക് തുല്യവും, രണ്ടാം റക്അത്തിൽ അതിന്റെ പകുതിക്കും സമാനമായി അവർ സാദൃശ്യപ്പെടുത്തി. ളുഹ്റിന്റെ മറ്റ് രണ്ട് റക്അത്തുകളുടെ പകുതിക്ക് സമാനമായി അസ്റിലെ (പാരായണത്തെ) അവർ താരതമ്യപ്പെടുത്തി. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു). (ജ)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 460, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 84, 'عَنْ عَبْدِ اللهِ بْنِ عُبَيْدِ اللهِ قَالَ: دَخَلْتُ عَلَى ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا فِي شَبَابٍ مِنْ بَنِي هَاشِمٍ، فَقُلْنَا لِشَابٍّ مِنَّا: سَلِ ابْنَ عَبَّاسٍ: أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ؟ فَقَالَ: لَا، لَا. فَقِيلَ لَهُ: فَلَعَلَّهُ كَانَ يَقْرَأُ فِي نَفْسِهِ، فَقَالَ: خَمْشًا! هَذِهِ شَرٌّ مِنَ الْأُولَى، كَانَ عَبْدًا مَأْمُورًا بَلَّغَ مَا أُرْسِلَ بِهِ، وَمَا اخْتَصَّنَا دُونَ النَّاسِ بِشَيْءٍ إِلَّا بِثَلَاثِ خِصَالٍ: أَمَرَنَا أَنْ نُسْبِغَ الْوُضُوءَ، وَأَنْ لَا نَأْكُلَ الصَّدَقَةَ، وَأَنْ لَا نُنْزِيَ الْحِمَارَ عَلَى الْفَرَسِ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉബൈദുല്ല(റ): ബനൂ ഹാശിമിലെ ഒരു സംഘം യുവാക്കൾക്കൊപ്പം ഞങ്ങൾ ഇബ്നുഅബ്ബാസിന്റെ അടുക്കൽ കടന്നുചെന്നു. ഞങ്ങളുടെ കൂട്ടത്തിലെ ഒരു യുവാവിനോട് ഞങ്ങൾ പറഞ്ഞു: ''റസൂൽ(സ) ദുഹ്റിലും അസ്റിലും (ഖുർആൻ) പാരായണം ചെയ്യാറുണ്ടോ?'' എന്ന് നീ ഇബ്നുഅബ്ബാസിനോട് ചോദിക്കുക; (ചോദിച്ചപ്പോൾ) അദ്ദേഹം പറഞ്ഞു: ഇല്ല, ഇല്ല. അപ്പോൾ അദ്ദേഹത്തോട് പറയപ്പെട്ടു. തിരുമേനി(സ) മനസ്സിൽ (പതുക്കെ) ഓതിയതായിരിക്കാം. അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നിന്റെ മുഖത്തിന് പോറലേൽക്കട്ടെ! (ഒരു ശാപ വാക്ക്) ഇത് മുൻപ് പറഞ്ഞതിനേക്കാൾ ചീത്തയായതാണ്. തിരുമേനി(സ) അല്ലാഹുവിൽനിന്നും കൽപ്പന ലഭിക്കുന്ന അവന്റെ ഒരു ദാസനാണ്. ഏതൊരു സന്ദേശവുമായാണോ തിരുമേനി(സ) അയക്കപ്പെട്ടത്, അത് അവിടുന്ന് (ജനങ്ങൾക്ക്) എത്തിച്ചുകൊടുത്തിരിക്കുന്നു. ജനങ്ങൾക്കു പുറമെ ഞങ്ങൾക്ക് (ബനൂഹാശിമിന്) പ്രത്യേകമാക്കിയത് മൂന്നു കാര്യങ്ങളാണ്: ഞങ്ങളോട് വുദു പൂർണ്ണമായി ചെയ്യാൻ കൽപ്പിച്ചു. സകാത്തിന്റെ ധനത്തിൽനിന്നും ഭക്ഷിക്കരുതെന്നും കഴുതയെ കുതിരയെക്കൊണ്ട് ഇണചേർക്കരുതെന്നും ഞങ്ങളോട് നിർദ്ദേശിച്ചു. (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عُبَيْدِ اللهِ قَالَ', 'അബ്ദുല്ലാഹിബ്നു ഉബൈദുല്ല(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=20 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 85, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِنَا فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ مِنْ صَلَاةِ الظُّهْرِ، وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا. (ق,د,ن,جه)', 'അബൂഖത്താദ(റ): നബി(സ) ളുഹ്റിന്റെ ആദ്യ രണ്ട് റക്അത്തുകളിലും ഖുർആൻ പാരായണം ചെയ്തിരുന്നു. അതിലെ ആയത്തുകൾ ഇടക്കിടെ ഞങ്ങളെ കേൾപ്പിക്കും. (ബു,മു,ദ,ന,ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖത്താദ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 86, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا الظُّهْرَ، فَنَسْمَعُ مِنْهُ الْآيَةَ بَعْدَ الْآيَاتِ، مِنْ سُورَةِ لُقْمَانَ وَالذَّارِيَاتِ. (ن,جه)', 'ബറാഉബ്നു ആസിബ്(റ): നബി(സ) ഞങ്ങളുമായി ളുഹർ നിസ്കരിക്കും. അപ്പോൾ ഞങ്ങൾ ഇടക്കിടെ ആയത്തുകൾ കേട്ടുകൊണ്ടിരിക്കും. സൂറത്തു ലുഖ്മാനിൽ നിന്നും സൂറ:അദ്ദാരിയാത്തിൽ നിന്നുമായിരുന്നു അത് (ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 461, 461, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 87, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ بِ{وَالسَّمَاءِ وَالطَّارِقِ}، {وَالسَّمَاءِ ذَاتِ الْبُرُوجِ} وَنَحْوِهِمَا مِنَ السُّوَرِ. (د,ت,ن)', 'ജാബിറുബ്നു സുമുറ(റ): നബി(സ) ളുഹ്റിലും അസറിലും ''വസ്സമാഇ വത്ത്വാരിഖ്'', ''വസ്സമാഇ ദാതിൽ ബുറൂജ്'' പോലുള്ള സൂറത്തുകൾ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ദ,തു,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സുമുറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 88, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: لَا أَدْرِي أَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ أَمْ لَا. (د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ളുഹ്റിലും അസ്റിലും ഓതാറുണ്ടായിരുന്നോ ഇല്ലയോ എന്നെനിക്കറിയില്ല. (ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 89, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا دَحَضَتِ الشَّمْسُ صَلَّى الظُّهْرَ وَقَرَأَ بِنَحْوٍ مِنْ: {وَاللَّيْلِ إِذَا يَغْشَى} وَالْعَصْرَ كَذَلِكَ، وَالصَّلَوَاتِ كَذَلِكَ إِلَّا الصُّبْحَ فَإِنَّهُ كَانَ يُطِيلُهَا. (م,د,ن)', 'ജാബിറുബ്നു സമുറ(റ): നബി(സ) സൂര്യൻ മദ്ധ്യത്തിൽ നിന്ന് തെറ്റിയാൽ ളുഹ്ർ നിസ്കരിക്കും. ഏതാണ്ട് ''വല്ലൈലി ഇദാ യഗ്ശാ'' പോലെയുള്ളവ ഓതും. അസ്റിലും അത്ര തന്നെ ഓതിയിരുന്നു. സുബ്ഹ് ഒഴികെയുള്ള നിസ്കാരങ്ങൾ അപ്രകാരമാണ് നിർവ്വഹിക്കുക. സുബ്ഹിൽ ദീർഘിപ്പിച്ചിരുന്നു. (മു,ദ,ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 90, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا، فَيُطِيلُ فِي الرَّكْعَةِ الْأُولَى مِنَ الظُّهْرِ وَيُقَصِّرُ فِي الثَّانِيَةِ، وَكَذَلِكَ فِي الصُّبْحِ. (جه)', 'അബൂഖതാദ(റ): നബി(സ) ഞങ്ങളെയും കൊണ്ട് നിസ്കരിച്ചിരുന്നു, ളുഹ്റിൽ ഒന്നാമത്തെ റക്അത്ത് ദീർഘിപ്പിക്കും രണ്ടാമത്തേത് ചുരുക്കും. സുബ്ഹിലും അങ്ങനെയായിരുന്നു. (ജ)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 91, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي بِنَا، فَيَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ: فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ بِفَاتِحَةِ الْكِتَابِ وَسُورَةٍ، وَيُسْمِعُنَا الْآيَةَ أَحْيَانًا، وَيَقْرَأُ فِي الرَّكْعَتَيْنِ الْأُخْرَيَيْنِ بِفَاتِحَةِ الْكِتَابِ. (م)', 'അബൂഖതാദ(റ): നബി(സ) ഞങ്ങളേയുമായി നിസ്കരിക്കാറുണ്ടായിരുന്നു. ളുഹ്റിലും അസ്റിലും ഒന്നാമത്തെ രണ്ട് റക്അത്തിൽ ഫാതിഹയും സൂറത്തും ഓതും. ആയത്തുകൾ ഇടക്ക് ഞങ്ങളെ കേൾപ്പിച്ചിരുന്നു. അവസാനത്തെ രണ്ട് റക്അത്തുകളിൽ ഫാത്തിഹ മാത്രം ഓതും. (മു)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 92, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقْرَأُ فِي صَلَاةِ الظُّهْرِ: فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ فِي كُلِّ رَكْعَةٍ قَدْرَ ثَلَاثِينَ آيَةً، وَفِي الْأُخْرَيَيْنِ قَدْرَ خَمْسَ عَشْرَةَ آيَةً، أَوْ قَالَ: نِصْفَ ذَلِكَ. وَفِي الْعَصْرِ: فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ: فِي كُلِّ رَكْعَةٍ قَدْرَ قِرَاءَةِ خَمْسَ عَشْرَةَ آيَةً، وَفِي الْأُخْرَيَيْنِ قَدْرَ نِصْفِ ذَلِكَ. (م)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) ളുഹ്ർ നമസ്കാരത്തിലെ ആദ്യത്തെ രണ്ട് റക്അത്തുകളിൽ ഓരോ റക്അത്തിലും മുപ്പത് ആയത്തുകൾ ഓതുവാനെടുക്കുന്നത്ര ദീർഘ സമയം ഓതിയിരുന്നു, മറ്റ് രണ്ട് റക്അത്തുകളിൽ പതിനഞ്ച് ആയത്തുകൾ ഓതുന്നത്ര സമയവും ഓതി. അസ്റിൽ ആദ്യ രണ്ട് റക്അത്തുകളിൽ ഓരോ റക്അത്തിലും പതിനഞ്ച് ആയത്തുകൾ ഓതുന്നത്ര സമയം ഓതി. പിന്നീടുള്ള രണ്ടിൽ ഏതാണ്ട് അതിന്റെ പകുതിയും ഓതി. (മു)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 462, 462, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 93, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِنِّي صَلَّيْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الظُّهْرِ، فَقَرَأَ لَنَا بِهَاتَيْنِ السُّورَتَيْنِ، بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ {هَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ}. (ن)', 'അനസ്(റ): നബി(സ)യോടൊപ്പം ഞാൻ ളുഹ്ർ നിസ്കരിച്ചു. രണ്ട് റക്അത്തുകളിലായി ''സബ്ബിഹിസ്മ റബ്ബികൽ അഅ്ലാ'', ''ഹൽ ഹതാക ഹദീസുൽ ഗാശിയ'' സൂറത്തുകൾ ഓതി. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 94, 'عَنْ أَبِي قَتَادَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ فِي الرَّكْعَتَيْنِ الْأُولَيَيْنِ بِأُمِّ الْقُرْآنِ وَسُورَتَيْنِ، وَفِي الْأُخْرَيَيْنِ بِأُمِّ الْقُرْآنِ، وَكَانَ يُسْمِعُنَا الْآيَةَ أَحْيَانًا، وَكَانَ يُطِيلُ أَوَّلَ رَكْعَةٍ مِنْ صَلَاةِ الظُّهْرِ. (ن)', 'അബൂഖതാദ(റ): നബി(സ) ളുഹ്റിലും അസ്റിലും ഒന്നാമത്തെ രണ്ട് റക്അത്തുകളിൽ ഉമ്മുൽ ഖുർആനും (ഫാത്തിഹ) രണ്ട് സൂറത്തുകളും ഓതി. രണ്ടാമത്തെ രണ്ട് റക്അത്തിൽ ഉമ്മുൽ ഖുർആൻ മാത്രവും. ഇടക്ക് ആയത്തുകൾ ഞങ്ങളെ കേൾപ്പിക്കാറുണ്ട്, ളുഹറിന്റെ ഒന്നാമത്തെ റക്അത്ത് ദീർഘിപ്പിച്ചിരുന്നു. (ന)', 'أَبِي قَتَادَةَ', 'അബൂഖതാദ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=21 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 95, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ أُمِّهِ أُمِّ الْفَضْلِ رَضِيَ اللهُ عَنْهَا قَالَتْ: خَرَجَ إِلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ عَاصِبٌ رَأْسَهُ فِي مَرَضِهِ، فَصَلَّى الْمَغْرِبَ فَقَرَأَ بِ{الْمُرْسَلَاتِ} قَالَتْ: فَمَا صَلَّاهَا بَعْدُ حَتَّى لَقِيَ اللهَ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): തന്റെ മാതാവ് ഉമ്മുൽഫള്ൽ(റ)യിൽ നിന്ന്: അവർ പറഞ്ഞു: നബി(സ) തന്റെ രോഗവേളയിൽ തലയിൽ ബാന്റേജ് കെട്ടിക്കൊണ്ട് ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു. ''വൽമുർസലാത്ത്'' ഓതിക്കൊണ്ട് മഗ്രിബ് നിസ്കരിച്ചു. അവർ പറഞ്ഞു: അതിനു ശേഷം നബി(സ) അല്ലാഹുവിനെ കണ്ടുമുട്ടുന്നത് (വഫാത്ത്) വരെ അങ്ങനെ ചെയ്തിട്ടില്ല. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 96, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ أُمَّ الْفَضْلِ بِنْتَ الْحَارِثِ سَمِعَتْهُ وَهُوَ يَقْرَأُ: {وَالْمُرْسَلَاتِ عُرْفًا}. فَقَالَتْ: يَا بُنَيَّ، لَقَدْ ذَكَّرْتَنِي بِقِرَاءَتِكَ هَذِهِ السُّورَةَ، إِنَّهَا لَآخِرُ مَا سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِهَا فِي الْمَغْرِبِ. (ق,ت,ن,جه)', 'ഇബ്നുഅബ്ബ്സ്(റ): ഞാൻ ''വൽ മുർസലാത്തി ഉർഫാ.... '' ഓതുന്നതായി ഉമ്മുൽ ഫള്ൽ(റ) കേട്ടു അപ്പോൾ അവർ പറഞ്ഞു: മകനേ! ഈ സൂറത്ത് ഓതുന്ന കാര്യം നീ എന്നെ ഓർമ്മപ്പെടുത്തി. പ്രവാചകൻ(സ) അവസാനമായി മഗ്രിബ് നമസ്കാരത്തിൽ ഓതുന്നതായി ഞാൻ കേട്ടത് ഈ സൂറത്തായിരുന്നു. (ബു,മു,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബ്സ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','തു','ന','ജ']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 97, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا مِنَ الْمُفَصَّلِ سُورَةٌ – صَغِيرَةٌ وَلَا كَبِيرَةٌ – إِلَّا وَقَدْ سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَؤُمُّ النَّاسَ بِهَا فِي الصَّلَاةِ الْمَكْتُوبَةِ. (د)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നിർബന്ധ നിസ്കാരങ്ങളിൽ നബി(സ) പാരായണം ചെയതുകൊണ്ട് ജനങ്ങൾക്ക് ഇമാം നിൽക്കുമ്പോൾ ഞാൻ കേൾക്കാത്ത ചെറുതോ വലുതോ ആയ മുഫസ്സലിൽ⁴ പെട്ട ഒരു സൂറത്തുമില്ല. (ദ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', '⁴. സൂറത്തു ''ഖാഫ്'' മുതൽ അവസാന സൂറത്തു വരെ.', null, array['د']::text[], array['ദ']::text[], null, null, 463, 463, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 98, 'عَنْ أَبِي عُثْمَانَ النَّهْدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى خَلْفَ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ الْمَغْرِبَ، فَقَرَأَ بِ{قُلْ هُوَ اللهُ أَحَدٌ}. (د)', 'അബൂഉസ്മാനുബ്നു നഹ്ദി(റ): അദ്ദേഹം ഇബ്നു മസ്ഊദിന്റെ പിന്നിൽ നിന്ന് മഗ്രിബ് നിസ്കരിച്ചപ്പോൾ ഇബ്നുമസ്ഊദ്(റ) സൂറത്തു ഇഖ്ലാസ് ഓതി. (ദ)', 'أَبِي عُثْمَانَ النَّهْدِيِّ', 'അബൂഉസ്മാനുബ്നു നഹ്ദി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 99, 'عَنْ جُبَيْرِ بْنِ مُطْعِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ بِالطُّورِ فِي الْمَغْرِبِ. (ق,د,ن,جه)', 'ജുബൈറുബ്നു മുത്ഇം(റ): നബി(സ) മഗ്രിബ് നിസ്കാരത്തിൽ ''അത്തൂർ'' എന്ന സൂറത്ത് ഓതുന്നത് ഞാൻ കേട്ടു. (ബു,മു,ദ,ന,ജ)', 'جُبَيْرِ بْنِ مُطْعِمٍ', 'ജുബൈറുബ്നു മുത്ഇം(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 100, 'عَنْ مَرْوَانَ بْنِ الْحَكَمِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي زَيْدُ بْنُ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: مَا لَكَ تَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ الْمُفَصَّلِ، وَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْمَغْرِبِ بِطُولَى الطُّولَيَيْنِ؟ قَالَ: قُلْتُ: مَا طُولَى الطُّولَيَيْنِ؟ قَالَ: الْأَعْرَافُ وَالْأُخْرَى الْأَنْعَامُ. (خ,د,ن)', 'മർവാനുബ്നു ഹകം(റ): സൈദുബ്നു സാബിത്(റ) എന്നോട് പറഞ്ഞു: എന്താണ് താങ്കൾ മഗ്രിബിൽ ചെറിയ സൂറത്തുകൾ പാരായണം ചെയ്യുന്നത്, നബി(സ) മഗ്രിബിൽ അതി ദീർഘമായ രണ്ട് സൂറത്തുകളിൽ ഏറ്റവും ദീർഘമുള്ളതായ ഒന്ന് ഓതിയതായി ഞാൻ കണ്ടിട്ടുണ്ട്. (അദ്ദേഹം പറഞ്ഞു) ഞാൻ ചോദിച്ചു: അതി ദീർഘമായരണ്ടെണ്ണത്തിൽ ഏറ്റവും ദീർഘമുള്ള ഒന്ന് ഏതാകുന്നു?. അദ്ദേഹം പറഞ്ഞു: സൂറത്തുൽ അഅ്റാഫ് ആണ്(ഞാൻ ഉദ്ദേശിച്ചത്). മറ്റേത് സൂറത്തുൽ അൻആമുമാണ്. (ബു,ദ,ന)', 'مَرْوَانَ بْنِ الْحَكَمِ', 'മർവാനുബ്നു ഹകം(റ)', null, null, array['خ','د','ن']::text[], array['ബു','ദ','ന']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 101, 'عَنْ هِشَامِ بْنِ عُرْوَةَ: أَنَّ أَبَاهُ كَانَ يَقْرَأُ فِي صَلَاةِ الْمَغْرِبِ بِنَحْوِ مَا تَقْرَءُونَ: {وَالْعَادِيَاتِ} وَنَحْوِهَا مِنَ السُّوَرِ. (د)', 'ഹിശാമുബ്നു ഉർവ(റ): അദ്ദേഹത്തിന്റെ പിതാവ്, മഗ്രിബിൽ നിങ്ങൾ ഓതിക്കൊണ്ടിരുന്ന ''വൽ ആദിയാത്ത്'' പോലുള്ള സൂറത്തുകൾ ഓതുമായിരുന്നു. (ദ)', 'هِشَامِ بْنِ عُرْوَةَ', 'ഹിശാമുബ്നു ഉർവ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 102, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْمَغْرِبِ: {قُلْ يَا أَيُّهَا الْكَافِرُونَ} و {قُلْ هُوَ اللهُ أَحَدٌ}. (جه)', 'ഇബ്നുഉമർ(റ): നബി(സ) മഗ്രിബ് നിസ്കാരത്തിൽ ''ഖുൽ യാഅയ്യുഹൽ കാഫിറൂൻ, ഖുൽ ഹുവല്ലാഹു അഹദ്'' എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്യാറുണ്ടായിരുന്നു. (ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 103, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: مَا صَلَّيْتُ وَرَاءَ أَحَد أَشْبَهَ صَلَاةً بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ فُلَانٍ. فَصَلَّيْنَا وَرَاءَ ذَلِكَ الْإِنْسَانِ، وَكَانَ يُطِيلُ الْأُولَيَيْنِ مِنَ الظُّهْرِ وَيُخَفِّفُ فِي الْأُخْرَيَيْنِ، وَيُخَفِّفُ فِي الْعَصْرِ، يَقْرَأُ فِي الْمَغْرِبِ بِقِصَارِ الْمُفَصَّلِ، وَيَقْرَأُ فِي الْعِشَاءِ بِ{وَالشَّمْسِ وَضُحَاهَا} وَأَشْبَاهِهَا، وَيَقْرَأُ فِي الصُّبْحِ بِسُورَتَيْنِ طَوِيلَتَيْنِ. (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ ഒരാളുടെ പിന്നിലും നിസ്കരിച്ചിട്ടില്ല, റസൂലിന്റെ നിസ്കാരത്തോട് ഏറ്റവും സാദൃശ്യമുള്ളതായിട്ട്, ഒരാളുടെ പിന്നിലല്ലാതെ, അയാളുടെ പിന്നിൽ നിസ്കരിക്കുമ്പോൾ ളുഹ്റിന്റെ ആദ്യത്തെ രണ്ട് റക്അത്ത് ദീർഘിപ്പിക്കും. ശേഷമുള്ള റക്അത്ത് ലഘുവാക്കും. അസ്ർ ലഘുവാക്കും. മഗ്രിബിൽ ചെറിയ സൂറത്തുകൾ ഓതും, ഇശാഇൽ; ''വശ്ശംസി വളുഹാഹാ'' പോലുള്ളവ പാരായണം ചെയ്യും. സുബ്ഹിൽ ദീർഘമായ സൂറത്തുകൾ പാരായണം ചെയ്യും. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 464, 464, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 104, 'عَنْ عَبْدِ اللهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي صَلَاةِ الْمَغْرِبِ ب: {حم} الدُّخَانِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ): നബി(സ) മഗ്രിബിൽ ''ഹാമീം'' (സൂറത്തുദ്ദുഖാൻ) ഓതാറുണ്ടായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ عُتْبَةَ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു ഉത്ബ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 105, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي صَلَاةِ الْمَغْرِبِ بِسُورَةِ الْأَعْرَافِ، فَرَّقَهَا فِي رَكْعَتَيْنِ. (ن)', 'ആഇശ(റ): നബി(സ) മഗ്രിബ് നിസ്കാരത്തിൽ സൂറത്തു അഅ്റാഫ് ഓതി, രണ്ട് റക്അത്തുകളിലായി അതിനെ വിഭജിച്ചു. (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 106, 'عَنْ زَيْدِ بْنِ ثَابِتٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِمَرْوَانَ: يَا أَبَا عَبْدِ الْمَلِكِ، أَتَقْرَأُ فِي الْمَغْرِبِ بِ: {قُلْ هُوَ اللهُ أَحَدٌ} وَ {إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ}. قَالَ:نَعَمْ، قَالَ:فَمَحْلُوفَةٌ، لَقَدْ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِيهَا بِأَطْوَلِ الطُّولَيَيْنِ: {المص}. (ن)', 'സൈദുബ്നു സാബിത്(റ): അദ്ദേഹം മർവാനോട് ചോദിച്ചു: അബൂഅബ്ദിൽ മലികേ, താങ്കൾ മഗ്രിബിന്ന് ''ഖുൽഹുവല്ലാഹു അഹദ്, ഇന്നാ അഅ്ത്വൈനാക്കൽ ഖൗസർ'' എന്നീ സൂറത്തുകൾ ഓതാറുണ്ടോ? അദ്ദേഹം പറഞ്ഞു: അതെ. സൈദ്(റ) പറഞ്ഞു: എങ്കിൽ സത്യം, നിശ്ചയം നബി(സ) മഗ്രിബിൽ സുദീർഘമായ രണ്ടു സൂറത്തുകളിൽ കൂടുതൽ ദൈർഘ്യമുള്ളതായ അഅ്റാഫ് പാരായണം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ന)', 'زَيْدِ بْنِ ثَابِتٍ', 'സൈദുബ്നു സാബിത്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 107, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَرَّ رَجُلٌ مِنَ الْأَنْصَارِ بِنَاضِحَيْنِ عَلَى مُعَاذٍ رَضِيَ اللهُ عَنْهُ وَهُوَ يُصَلِّي الْمَغْرِبَ، فَافْتَتَحَ بِسُورَةِ الْبَقَرَةِ، فَصَلَّى الرَّجُلُ ثُمَّ ذَهَبَ، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "أَفَتَّانٌ يَا مُعَاذُ؟ أَفَتَّانٌ يَا مُعَاذُ؟ أَلَّا قَرَأْتَ بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ{الشَّمْسِ وَضُحَاهَا} وَنَحْوِهِمَا". (ن)', 'ജാബിർ(റ): അൻസാരികളിൽപെട്ട ഒരാൾ ''നാളിഹു''കളെ (കൃഷി ആവശ്യങ്ങൾക്കുപയോഗിക്കുന്ന ഒട്ടകങ്ങളെ) തെളിച്ചുകൊണ്ട് വന്നപ്പോൾ മുആദ്(റ) മഗ്രിബ് നിസ്കരിക്കുന്നതു കണ്ടു. മുആദ്(റ) സൂറത്തുൽ ബഖറ ഓതിത്തുടങ്ങി. (മുആദിനോടൊപ്പം) നിസ്കരിക്കാനാരംഭിച്ചു. ശേഷം അയാൾ (മുആദി(റ)നെ വിട്ട് തനിച്ചു നിസ്കരിച്ച്) പോയി. ആ വിവരം പ്രവാചകന്റെ(സ) അടുക്കലെത്തി. അവിടുന്ന് മുആദി(റ)നോടു പറഞ്ഞു: "മൂആദേ, നീ കുഴപ്പക്കാരനാണോ? മുആദേ നീ കുഴപ്പമുണ്ടാക്കുന്നവനാണോ? നിനക്ക് ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ''യും ''വശ്ശംസി വളുഹാഹാ''യും, അവയെപ്പോലുള്ളവയും പാരായണം ചെയ്തു കൂടായിരുന്നോ." (ന)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=22 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 108, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَمَقْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِشْرِينَ مَرَّةً، يَقْرَأُ فِي الرَّكْعَتَيْنِ بَعْدَ الْمَغْرِبِ وَفِي الرَّكْعَتَيْنِ قَبْلَ الْفَجْرِ {قُلْ يَا أَيُّهَا الْكَافِرُونَ} وَ{قُلْ هُوَ اللهُ أَحَدٌ }. (ن)', 'ഇബ്നുഉമർ(റ): ഇരുപത് പ്രാവശ്യം നബി(സ)യെ ഞാൻ നിരീക്ഷിച്ചു. മഗ്രിബ്നു ശേഷമുള്ള രണ്ട് റക്അത്തിലും ഫജ്റിന് മുമ്പുള്ള രണ്ട് റക്അത്തുകളിലും ''ഖുൽയാഅയ്യുഹൽ കാഫിറൂൻ, ഖുൽ ഹുവല്ലാഹു അഹദ്'' എന്നിവ അവിടുന്ന് ഓതി. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 465, 465, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=23 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 109, 'عَنْ بُرَيْدَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرَأُ فِي الْعِشَاءِ الْآخِرَةِ بِ{الشَّمْسِ وَضُحَاهَا} وَنَحْوِهَا مِنَ السُّوَرِ. حَسَنٌ. (ت,ن)', 'ബുറൈദ(റ): നബി(സ) അവസാന ഇശാ നിസ്കാരത്തിൽ ''വശ്ശംസി വളുഹാഹാ'' പോലുള്ള സുറത്തുകൾ ഓതി. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (തു,ന)', 'بُرَيْدَةَ', 'ബുറൈദ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 110, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَرَأَ فِي الْعِشَاءِ الْآخِرَةِ بِ{وَالتِّينِ وَالزَّيْتُونِ} حَسَنٌ صَحِيحٌ. (ق,د,ت,ن,جه)', 'ബറാഉബ്നു ആസിബ്(റ): നബി(സ) ഇശാ നിസ്കാരത്തിൽ സൂറത്തുത്തീൻ പാരായണം ചെയ്തു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ബു,മു,ദ,തു,ന,ജ)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 111, 'عَنْ جَابِرٍ رَضِيَ اللهُ عَنْهُ: أَنَّ مُعَاذَ بْنَ جَبَلٍ رَضِيَ اللهُ عَنْهُ صَلَّى بِأَصْحَابِهِ الْعِشَاءَ فَطَوَّلَ عَلَيْهِمْ، فَقَالَ لَهُ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اقْرَأْ بِ{وَالشَّمْسِ وَضُحَاهَا} وَ {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} وَ {وَاللَّيْلِ إِذَا يَغْشَى} وَ {اقْرَأْ بِاسْمِ رَبِّكَ}". (م,ن,جه)', 'ജാബിർ(റ): മുആദുബ്നു ജബൽ(റ) തന്റെ അനുയായികളുമായി ഇശാ നിസ്കരിച്ചു, അദ്ദേഹം നിസ്കാരം ദീർഘിപ്പിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ വശ്ശംസി വളുഹാഹാ, സബ്ബിഹിസ്മ റബികൽ അഅ്ലാ, വല്ലൈലി ഇദാ യഗ്ശാ, ഇഖ്റഅ് ബിസ്മി റബ്ബിക എന്നീ സൂറത്തുകൾ പാരായണം ചെയ്യുക." (മു,ന,ജ)', 'جَابِرٍ', 'ജാബിർ(റ)', null, null, array['م','ن','جه']::text[], array['മു','ന','ജ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 112, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ خَلْفَ أَبِي الْقَاسِمِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْعَتَمَةَ فَقَرَأَ {إِذَا السَّمَاءُ انْشَقَّتْ} فَسَجَدَ، فَلَا أَزَالُ أَسْجُدُ بِهَا حَتَّى أَلْقَاهُ. (خ)', 'അബൂഹുറൈറ(റ): ഞാൻ അബുൽ ഖാസിം(സ)ക്ക് (തിരുമേനിക്കു) പിന്നിൽ ഇശാ നിസ്കരിച്ചപ്പോൾ ''ഇദസ്സമാഉൻ ശഖ്ഖത്ത്'' ഓതി സുജൂദ് ചെയ്തു. ഞാൻ തിരുമേനി(സ)യെ സമീപിക്കുംവരെ ആ സൂറത്ത് ഓതി സുജൂദ് ചെയ്തുകൊണ്ടിരിക്കും. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=24 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 113, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ انْصَرَفَ مِنْ صَلَاةٍ جَهَرَ فِيهَا بِالْقِرَاءَةِ فَقَالَ: "هَلْ قَرَأَ مَعِيَ أَحَدٌ مِنْكُمْ آنِفًا؟". فَقَالَ رَجُلٌ: نَعَمْ يَا رَسُولَ اللهِ، قَالَ: "إِنِّي أَقُولُ مَا لِي أُنَازَعُ الْقُرْآنَ". قَالَ: فَانْتَهَى النَّاسُ عَنِ الْقِرَاءَةِ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِيمَا جَهَرَ فِيهِ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْقِرَاءَةِ مِنَ الصَّلَوَاتِ، حِينَ سَمِعُوا ذَلِكَ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. وَفِي رِوَايَةٍ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَظُنُّ أَنَّهَا الصُّبْحُ، بِمَعْنَاهُ... إِلَى قَوْلِهِ: "مَا لِي أُنَازِعُ الْقُرْآنَ". (د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഉറക്കെ പാരായണം നടത്തിയിരുന്ന ഒരു നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചപ്പോൾ പറഞ്ഞു: "നിങ്ങളാരെങ്കിലും ഇപ്പോൾ എന്നോടൊപ്പം ഓതിയോ?" ഒരാൾ പറഞ്ഞു: അതെ പ്രവാചകരേ, നബി(സ) പറഞ്ഞു: "ഖുർആനിനോട് തർക്കിക്കിക്കുന്നത് എനിക്ക് യോജിച്ചതല്ല എന്നു ഞാൻ പറയുന്നു." ഇതുകേട്ടപ്പോൾ നബി(സ) ശബ്ദമുയർത്തി ഓതുന്ന നിസ്കാരങ്ങളിൽ ജനങ്ങൾ പാരായണം അവസാനിപ്പിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഞങ്ങളെയുമായി തിരുമേനി(സ) നിർവ്വഹിച്ച ആ നിസ്കാരം സുബ്ഹിയാണെന്ന് തോന്നുന്നു എന്നതുമുതൽ "ഖുർആനിനോട് തർക്കിക്കുന്നത് എനിക്ക് യോജിച്ചതല്ല" എന്നതുവരെ. (ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 466, 466, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=113), 1, 'وَفِي رِوَايَةٍ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَظُنُّ أَنَّهَا الصُّبْحُ، بِمَعْنَاهُ... إِلَى قَوْلِهِ: "مَا لِي أُنَازِعُ الْقُرْآنَ". (د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: ഞങ്ങളെയുമായി തിരുമേനി(സ) നിർവ്വഹിച്ച ആ നിസ്കാരം സുബ്ഹിയാണെന്ന് തോന്നുന്നു എന്നതുമുതൽ "ഖുർആനിനോട് തർക്കിക്കുന്നത് എനിക്ക് യോജിച്ചതല്ല" എന്നതുവരെ. (ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 114, 'عَنْ نَافِعِ بْنِ مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ قَالَ: أَبْطَأَ عُبَادَةُ بْنُ الصَّامِتِ رَضِيَ اللهُ عَنْهُ عَنْ صَلَاةِ الصُّبْحِ، فَأَقَامَ أَبُو نُعَيْمٍ الْمُؤَذِّنُ الصَّلَاةَ، فَصَلَّى أَبُو نُعَيْمٍ بِالنَّاسِ، وَأَقْبَلَ عُبَادَةُ وَأَنَا مَعَهُ حَتَّى صَفَفْنَا خَلْفَ أَبِي نُعَيْمٍ وَأَبُو نُعَيْمٍ يَجْهَرُ بِالْقِرَاءَةِ، فَجَعَلَ عُبَادَةُ يَقْرَأُ أُمَّ الْقُرْآنِ، فَلَمَّا انْصَرَفَ قُلْتُ لِعُبَادَةَ: سَمِعْتُكَ تَقْرَأُ بِأُمِّ الْقُرْآنِ وَأَبُو نُعَيْمٍ يَجْهَرُ؟ قَالَ: أَجَلْ، صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعْضَ الصَّلَوَاتِ الَّتِي يَجْهَرُ فِيهَا بِالْقِرَاءَةِ، قَالَ: فَالْتَبَسَتْ عَلَيْهِ الْقِرَاءَةُ، فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ وَقَالَ: "هَلْ تَقْرَءُونَ إِذَا جَهَرْتُ بِالْقِرَاءَةِ". فَقَالَ بَعْضُنَا: إِنَّا نَصْنَعُ ذَلِكَ، قَالَ: "فَلَا، وَأَنَا أَقُولُ: مَا لِي يُنَازِعُنِي الْقُرْآنُ فَلَا تَقْرَءُوا بِشَيْءٍ مِنَ الْقُرْآنِ، إِذَا جَهَرْتُ إِلَّا بِأُمِّ الْقُرْآنِ". (د,ن)', 'നാഫിഅ്(റ): ഉബാദത്തുബ്നുസ്വാമിത്ത്(റ) സുബ്ഹ് നിസ്കാരത്തിന് വൈകി. മുഅദ്ദിനായ അബൂനുഐം ഇഖാമത്തു വിളിച്ച് ആളുകളെയുമായി നിസ്കരിക്കാൻ തുടങ്ങി. അങ്ങനെ ഉബാദത്തും കൂടെ ഞാനും (നിസ്കരിക്കാൻ) വന്നു. എന്നിട്ടു ഞങ്ങൾ അബൂനുഐമിന്റെ പിന്നിൽ അണിചേർന്നു. അബൂനുഐമാകട്ടെ, ഉച്ചത്തിൽ ഖുർആൻ ഓതുന്നുണ്ട്. അപ്പോൾ ഉബാദത്ത്(റ) ഫാത്തിഹ പാരായണം ചെയ്യാൻ തുടങ്ങി. നിസ്കാരത്തിൽ നിന്നും പിരിഞ്ഞപ്പോൾ ഞാൻ (നാഫിഅ്) ഉബാദയോടു ചോദിച്ചു: അബൂനുഐം(റ) ഉച്ചത്തിൽ പാരായണം ചെയ്തുകൊണ്ടിരിക്കെ താങ്കളും ഫാത്തിഹ പാരായണം ചെയ്യുന്നത് ഞാൻ കേട്ടുവല്ലോ? അദ്ദേഹം പറഞ്ഞു: അതെ (ഞാൻ ഓതിയിട്ടുണ്ട്). ഉച്ചത്തിൽ പാരായണം ചെയ്യേണ്ട ചില നിസ്കാരങ്ങൾ ഞങ്ങളെയുമായി തിരുമേനി(സ) നിസ്കാരം നിർവ്വഹിച്ചു. അങ്ങനെ അവിടുത്തേക്ക് (ഖുർആൻ) പാരായണം അലങ്കോലപ്പെട്ടു. (നിസ്കാരത്തിൽ നിന്ന്) വിരമിച്ചപ്പോൾ അവിടുന്ന് ഞങ്ങൾക്കഭിമുഖമായി നിന്നുകൊണ്ട് പറഞ്ഞു: "ഞാൻ ഉച്ചത്തിൽ പാരായണം ചെയ്യുമ്പോൾ നിങ്ങൾ പാരായണം ചെയ്യുകയാണോ?" അപ്പോൾ ഞങ്ങളിൽ ചിലർ പറഞ്ഞു: ഞങ്ങൾ അങ്ങനെ ചെയ്യുന്നുണ്ട്. തിരുമേനി(സ) പറഞ്ഞു: "എന്നാൽ അതു പാടില്ല. ഞാൻ (സ്വയം) പറയുന്നു: എനിക്കെന്താണ്! ഖുർആൻ എന്നോട് തർക്കിക്കുകയോ? ഞാൻ ഉച്ചത്തിൽ പാരായണം ചെയ്യുമ്പോൾ, നിങ്ങൾ ഖുർആനിൽ നിന്നും ഒന്നും തന്നെ പാരായണം ചെയ്യരുത്. ഫാത്തിഹ ഒഴികെ." (ദ,ന)', 'نَافِعِ بْنِ مَحْمُودِ بْنِ الرَّبِيعِ الْأَنْصَارِيِّ قَالَ', 'നാഫിഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 115, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّمَا جُعِلَ الْإِمَامُ لِيُؤْتَمَّ بِهِ: فَإِذَا كَبَّرَ فَكَبِّرُوا، وَإِذَا قَرَأَ فَأَنْصِتُوا، وَإِذَا قَالَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَقُولُوا: آمِينَ. وَإِذَا رَكَعَ فَارْكَعُوا، وَإِذَا قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ. وَإِذَا سَجَدَ فَاسْجُدُوا، وَإِذَا صَلَّى جَالِسًا فَصَلُّوا جُلُوسًا أَجْمَعِينَ". (د,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിശ്ചയം (നമസ്കാരത്തിന്) ഇമാമിനെ നിശ്ചയിച്ചിരിക്കുന്നത്, (മഅ്മൂമുകൾ) അദ്ദേഹത്തെ പിൻപറ്റുവാൻ വേണ്ടിയാണ്. അദ്ദേഹം തക്ബീർ ചൊല്ലിയാൽ നിങ്ങളും തക്ബീർ ചൊല്ലുക. അദ്ദേഹം (ഖുർആൻ) പാരായണം ചെയ്യുമ്പോൾ നിങ്ങൾ മൗനമവലംബി(ച്ച് (ശ്രദ്ധിച്ചുകേൾ)ക്കുക. അദ്ദേഹം ''ഗൈരിൽ മഗ്ളൂബി അലൈഹിം, വലള്ളാല്ലീൻ'' എന്നു ചൊല്ലിക്കഴിഞ്ഞാൽ നിങ്ങൾ ''ആമീൻ'' എന്നു ചൊല്ലുക. അദ്ദേഹം റുകൂഇലേക്കു പോയാൽ നിങ്ങൾ റുകൂഇലേക്കുപോകുക. അദ്ദേഹം ''സമിഅല്ലാഹുലിമൻ ഹമിദഹു'' എന്നു പറഞ്ഞാൽ നിങ്ങൾ ''അല്ലാഹുമ്മ റബ്ബനാലകൽ ഹംദു'' (ഞങ്ങളുടെ നാഥനായ അല്ലാഹുവേ നിനക്കാകുന്നു സർവ്വസ്തുതിയും) എന്നു പറയുക, അദ്ദേഹം സുജൂദിലേക്ക് പോയാൽ നിങ്ങൾ സുജൂദിലേക്ക് പോവുക, അദ്ദേഹം ഇരുന്ന് നിസ്കരിക്കുകയാണെങ്കിൽ നിങ്ങളെല്ലാവരും ഇരുന്നു നിസ്കരിക്കുക." (ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 467, 467, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 116, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا أَمَّنَ الْقَارِئُ فَأَمِّنُوا – وَفِي رِوَايَةٍ: فَإِنَّ الْمَلَائِكَةَ تُؤَمِّنُ – فَمَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (خ,ن,جه)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "(ഫാത്തിഹ) പാരായണം ചെയ്യുന്നവൻ (ഇമാം) ''ആമീൻ'' ചൊല്ലുമ്പോൾ നിങ്ങൾ കൂടെ ''ആമീൻ'' എന്ന് ചൊല്ലുക - മറ്റൊരു റിപ്പോർട്ടിൽ: നിശ്ചയം അന്നേരം മാലാഖമാരും ''ആമീൻ'' ചൊല്ലും - അതും മലക്കുകളുടെ ''ആമീൻ'' ചൊല്ലലും, യോജിച്ചു വന്നാൽ, അയാളുടെ മുൻപാപങ്ങൾ അയാൾക്ക് പൊറുത്തു കൊടുക്കുന്നതാണ്." (ബു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','ن','جه']::text[], array['ബു','ന','ജ']::text[], null, null, 467, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=116), 1, 'وَفِي رِوَايَةٍ: فَإِنَّ الْمَلَائِكَةَ تُؤَمِّنُ – فَمَنْ وَافَقَ تَأْمِينُهُ تَأْمِينَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (خ,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: നിശ്ചയം അന്നേരം മാലാഖമാരും ''ആമീൻ'' ചൊല്ലും - അതും മലക്കുകളുടെ ''ആമീൻ'' ചൊല്ലലും, യോജിച്ചു വന്നാൽ, അയാളുടെ മുൻപാപങ്ങൾ അയാൾക്ക് പൊറുത്തു കൊടുക്കുന്നതാണ്." (ബു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 117, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: تَرَكَ النَّاسُ التَّأْمِينَ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} قَالَ: "آمِينَ" حَتَّى يَسْمَعَهَا أَهْلُ الصَّفِّ الْأَوَّلِ، فَيَرْتَجُّ بِهَا الْمَسْجِدُ. (د,جه)', 'അബൂഹുറൈറ(റ): അദ്ദേഹം പറഞ്ഞു: ആളുകളിതാ ''ആമീൻ'' ചൊല്ലൽ ഉപേക്ഷിച്ചിരിക്കുന്നു. എന്നാൽ തിരുമേനി(സ) ''ഗൈരിൽ മഗ്ളൂബി അലൈഹിം വലള്ളാല്ലീൻ'' എന്നു ചൊല്ലിക്കഴിഞ്ഞാൽ ''ആമീൻ'' എന്നു ഒന്നാമത്തെ സ്വഫ്ഫിലെ ആളുകൾ കേൾക്കുമാറ് ചൊല്ലുമായിരുന്നു. അന്നേരം (ആളുകൾ ''ആമീൻ'' ചൊല്ലുന്നതിന്റെ ശബ്ദം കാരണത്താൽ) പള്ളി പ്രകമ്പനം കൊള്ളുമായിരുന്നു. (ദ,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 118, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: {وَلَا الضَّالِّينَ} قَالَ: "آمِينَ". فَسَمِعْنَاهَا. (جه)', 'അലി(റ): പ്രവാചകൻ(സ) ''വലള്ളാല്ലീൻ'' എന്നു പറഞ്ഞ ശേഷം ''ആമീൻ'' എന്നു ചൊല്ലുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്. ഞങ്ങൾക്കതു കേൾക്കുമായിരുന്നു. (ജ)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=25 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 119, 'عَنْ عَبْدِ اللهِ بْنِ السَّائِبِ رَضِيَ اللهُ عَنْهُ قَالَ: حَضَرْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْفَتْحِ، فَصَلَّى فِي قُبُلِ الْكَعْبَةِ، فَخَلَعَ نَعْلَيْهِ فَوَضَعَهُمَا عَنْ يَسَارِهِ، فَافْتَتَحَ بِسُورَةِ الْمُؤْمِنِينَ، فَلَمَّا جَاءَ ذِكْرُ مُوسَى أَوْ عِيسَى – عَلَيْهِمَا السَّلَامُ – أَخَذَتْهُ سَعْلَةٌ، فَرَكَعَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ): മക്കാവിജയ ദിനത്തിൽ നബി(സ) വന്ന് കഅ്ബക്ക് അഭിമുഖമായി നിസ്കരിച്ചു. അപ്പോൾ ചെരിപ്പഴിച്ച് തന്റെ ഇടതുഭാഗത്ത് വെച്ചു. എന്നിട്ട് സൂറത്തുൽമുഅ്മിനൂൻ ഓതിത്തുടങ്ങി. മൂസാ, ഈസാ(അ) എന്നിവരുടെ ചരിത്രങ്ങളുടെ ഭാഗത്ത് എത്തിയപ്പോൾ ഒരു ചുമ അനുഭവപ്പെട്ടു. പിന്നെ റുകൂഇൽ പോയി. (ന)', 'عَبْدِ اللهِ بْنِ السَّائِبِ', 'അബ്ദുല്ലാഹിബ്നു സാഇബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=26 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 120, 'عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ عُمَرُ لِسَعْدٍ رَضِيَ اللهُ عَنْهُمَا: قَدْ شَكَاكَ النَّاسُ فِي كُلِّ شَيْءٍ حَتَّى فِي الصَّلَاةِ. فَقَالَ سَعْدٌ: أَتَّئِدُ فِي الْأُولَيَيْنِ، وَأَحْذِفُ فِي الْأُخْرَيَيْنِ، وَمَا آلُو مَا اقْتَدَيْتُ بِهِ مِنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. قَالَ: ذَاكَ الظَّنُّ بِكَ. (ن)', 'ജാബിറുബിനു സമുറ(റ): ഉമർ(റ) സഅദി(റ)നോട് പറഞ്ഞു: നിസ്കാരം വരെയുള്ള എല്ലാ വിഷയങ്ങളിലും ജനങ്ങൾ താങ്കളെക്കുറിച്ച് വേവലാതി പറയുന്നുണ്ട്. സഅദ്(റ) പറഞ്ഞു: ആദ്യ രണ്ട് റക്അത്തുകളിൽ ഞാൻ ധൃതി കാണിക്കില്ല. അവസാന രണ്ട് റക്അത്തുകളിൽ ലഘുവാക്കും. നബി(സ)യുടെ നിസ്കാരത്തിൽ നിന്ന് അനുകരിച്ച ഒരു വിഷയത്തിലും ഞാൻ ചുരുക്കില്ല. ഉമർ(റ) പറഞ്ഞു: താങ്കളെക്കുറിച്ച് അതു തന്നെയാണ് ധാരണ. (ന)', 'جَابِرِ بْنِ سَمُرَةَ', 'ജാബിറുബിനു സമുറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 468, 468, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=27 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 121, 'عَنِ ابنِ مَسْعُود رَضِيَ اللهُ عَنْهُ: وَقَدْ قَالَ رَجُلٌ عِنْدَهُ: قَرَأْتُ الْمُفَصَّلَ فِي رَكْعَةٍ. قَالَ: هَذًّا كَهَذِّ الشِّعْرِ؟ لَقَدْ عَرَفْتُ النَّظَائِرَ الَّتِي كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقْرُنُ بَيْنَهُنَّ. فَذَكَرَ عِشْرِينَ سُورَةً مِنَ الْمُفَصَّلِ، سُورَتَيْنِ سُورَتَيْنِ فِي رَكْعَةٍ. (خ,ن)', 'ഇബ്നുമസ്ഊദ്(റ): ഒരാൾ അദ്ദേഹത്തിനടുത്ത് വന്ന് പറഞ്ഞു: ഞാൻ മുഫസ്വലായ അധ്യായം ഒരു റക്അത്തിൽ പാരായണം ചെയ്തു. ഇബ്നുമസ്ഊദ് പറഞ്ഞു: കവിത ചൊല്ലും പോലെയാണോ പാരായണം ചെയ്തത്? നബി(സ) പരസ്പരം യോജിപ്പിക്കാറുള്ള സമാന സ്വഭാവമുള്ള അദ്ധ്യായങ്ങൾ എനിക്കറിയാം. അങ്ങനെ മുഫസ്സലിൽപെട്ട ഇരുപത് അദ്ധ്യായങ്ങൾ അദ്ദേഹം പറഞ്ഞു. ഓരോ റക്അത്തിലും രണ്ട് വീതമാണ്. (പാരായണം ചെയ്തിരുന്നത്) (ബു,ന)', 'ابنِ مَسْعُود', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=28 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 122, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا :أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بَعَثَ رَجُلًا عَلَى سَرِيَّة، فَكَانَ يَقْرَأُ لأَصْحَابِهِ فِي صَلاَتِهِمْ، فَيَخْتِمُ بِ{قُلْ هُوَ اللهُ أَحَدٌ}. فَلَمَّا رَجَعُوا ذَكَرُوا ذَلِكَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "سَلُوهُ لأَيِّ شَيْءٍ فَعَلَ ذَلِكَ". فَسَأَلُوهُ فَقَالَ: لأَنَّهَا صِفَةُ الرَّحْمَنِ عَزَّ وَجَلَّ، فَأَنَا أُحِبُّ أَنْ أَقْرَأَ بِهَا. قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَخْبِرُوهُ: أَنَّ اللهَ عَزَّ وَجَلَّ يُحِبُّهُ". (ن)', 'ആഇശ(റ): നബി(സ) ഒരാളെ ഒരു സംഘത്തോടൊപ്പം നിയോഗിച്ചു. അദ്ദേഹം തന്റെ ആളുകൾക്കു വേണ്ടി നിസ്കാരത്തിൽ സൂറത്തു ഇഖ്ലാസ് ഓതി പാരായണം അവസാനിപ്പിച്ചു. അവർ തിരിച്ചുചെന്നപ്പോൾ ഇക്കാര്യം നബി(സ)യോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അങ്ങനെ ചെയ്യാൻ കാരണമെന്താണെന്ന് അദ്ദേഹത്തോട് ചോദിക്കുക." അതിനെക്കുറിച്ച് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: യുക്തിമാനും പ്രതാപിയുമായ അല്ലാഹുവിന്റെ വിശേഷണമാണത്. ഞാൻ അത് പാരായണം ചെയ്യാൻ ഇഷ്ടപ്പെടുന്നു. നബി(സ) പറഞ്ഞു: "നിശ്ചയം അല്ലാഹു അദ്ദേഹത്തെ ഇഷ്ടപ്പെടുന്നുവെന്ന് അദ്ദേഹത്തെ അറിയിക്കുക." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 123, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَقْبَلْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَسَمِعَ رَجُلًا يَقْرَأُ: {قُلْ هُوَ اللهُ أَحَدٌ. اللهُ الصَّمَدُ. لَمْ يَلِدْ وَلَمْ يُولَدْ. وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ} فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَجَبَتْ". فَسَأَلْتُهُ: مَاذَا يَا رَسُولَ اللهِ؟ قَالَ: "الْجَنَّةُ". (ن)', 'അബൂഹുറൈറ(റ): ഞാൻ നബി(സ)യോടൊപ്പം പോകുമ്പോൾ ഒരാൾ സൂറത്തുൽ ഇഖ്ലാസ് പാരായണം ചെയ്യുന്നതായി കേട്ടു. നബി(സ) പറഞ്ഞു: "നിർബന്ധമായിരിക്കുന്നു." അപ്പോൾ ഞാൻ ചോദിച്ചു: അല്ലാഹുവിന്റെ റസൂലേ എന്താണ് നിർബന്ധമായത്? നബി(സ) പറഞ്ഞു: "സ്വർഗ്ഗം." (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 469, 469, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 124, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا سَمِعَ رَجُلًا يَقْرَأُ: {قُلْ هُوَ اللهُ أَحَدٌ} يُرَدِّدُهَا، فَلَمَّا أَصْبَحَ جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَذَكَرَ ذَلِكَ لَهُ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّهَا لَتَعْدِلُ ثُلُثَ الْقُرْآنِ". (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഒരാൾ സൂറത്തു ഇഖ്ലാസ് ആവർത്തിച്ച് ഓതുന്നത് മറ്റൊരു മനുഷ്യൻ കേട്ടു. പ്രഭാതമായപ്പോൾ അയാൾ നബി(സ)യുടെ അടുത്തുചെന്ന് അതിനെക്കുറിച്ച് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "എന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻതന്നെ സത്യം, നിശ്ചയം അത് ഖുർനിന്റെ മൂന്നിലൊന്നിന് തുല്യമാണ്." (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 469, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 125, 'عَنْ أَبِي أَيُّوبَ رَضِيَ اللهُ عَنْهُ: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "{قُلْ هُوَ اللهُ أَحَدٌ} ثُلُثُ الْقُرْآنِ". (ن)', 'അബൂഅയ്യൂബ്(റ): നബി(സ) പറഞ്ഞു: "സൂറത്തു ഇഖ്ലാസ് ഖുർആനിന്റെ മൂന്നിലൊന്നാണ്." (ന)', 'أَبِي أَيُّوبَ', 'അബൂഅയ്യൂബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=29 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 126, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَقْرَأُ الْقُرْآنَ، وَفِينَا الْأَعْرَابِيُّ وَالْأَعْجَمِيُّ، فَقَالَ: "اقْرَءُوا فَكُلٌّ حَسَنٌ، وَسَيَجِيءُ أَقْوَامٌ يُقِيمُونَهُ كَمَا يُقَامُ الْقِدْحُ، يَتَعَجَّلُونَهُ وَلَا يَتَأَجَّلُونَهُ". (د)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഞങ്ങൾ ഖുർആൻ ഓതികൊണ്ടിരിക്കെ നബി(സ) ഞങ്ങളിലേക്ക് ഇറങ്ങിവന്നു. ഞങ്ങളിൽ ഗ്രാമീണനും നിരക്ഷരനും ഉണ്ടായിരുന്നു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പാരായണം ചെയ്യുക, എല്ലാം നല്ലതാണ്. പിന്നെ ചിലയാളുകൾ വരും. അമ്പുകുറ്റി ഒപ്പിക്കുന്നതുപോലെ ഖുർആനിനെ ഈണമൊപ്പിക്കുന്ന അവർ അതിന് ഐഹിക പ്രതിഫലത്തെയാണാഗ്രഹിക്കുന്നത്. പാരത്രിക പ്രതിഫലത്തെയല്ല." (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 127, 'عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَوْمًا وَنَحْنُ نَقْتَرِئُ، فَقَالَ : "الْحَمْدُ لِلَّهِ، كِتَابُ اللهِ وَاحِدٌ، وَفِيكُمُ الْأَحْمَرُ وَفِيكُمُ الْأَبْيَضُ وَفِيكُمُ الْأَسْوَدُ، اقْرَءُوهُ قَبْلَ أَنْ يَقْرَأَهُ أَقْوَامٌ يُقِيمُونَهُ كَمَا يُقَوَّمُ السَّهْمُ، يَتَعَجَّلُ أَجْرُهُ وَلَا يَتَأَجَّلُهُ". (د)', 'സഹ്ല്ബ്നു സഅദുസ്സാഇദീ(റ): ഒരു ദിവസം ഞങ്ങൾ ഖുർആൻ ഓതികൊണ്ടിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് ഇറങ്ങിവന്നു. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവിന് സ്തുതി, അല്ലാഹുവിന്റെ ഗ്രന്ഥം ഒന്നാണ്, നിങ്ങളിൽ ചുവന്നവനും, വെളുത്തവനും, കറുത്തവനും ഉണ്ട്; നിങ്ങൾ (ഖുർആൻ) പാരായണം ചെയ്യുക. അമ്പ് നേരെയാക്കുംപോലെ (ഖുർആൻ പാരായണത്തെ) നേരെയാക്കുന്ന (ഈണമൊപ്പിക്കുന്ന) ജനവിഭാഗങ്ങൾ അത് പാരായണം ചെയ്യുന്നതിനു മുമ്പ്. അവർ അതിന്റെ ഐഹിക പ്രതിഫലമാണ്, പാരത്രിക പ്രതിഫലത്തിന് പകരം ആഗ്രഹിക്കുന്നത്." (ദ)', 'سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ', 'സഹ്ല്ബ്നു സഅദുസ്സാഇദീ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 470, 470, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 128, 'عَنْ عَبْدِ اللهِ بْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُمَا قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنِّي لَا أَسْتَطِيعُ أَنْ آخُذَ مِنَ الْقُرْآنِ شَيْئًا، فَعَلِّمْنِي مَا يُجْزِئُنِي مِنْهُ. قَالَ: "قُلْ: سُبْحَانَ اللهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللهُ، وَاللهُ أَكْبَرُ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ الْعَلِيِّ الْعَظِيمِ". قَالَ: يَا رَسُولَ اللهِ، هَذَا لِلَّهِ عَزَّ وَجَلَّ، فَمَا لِي؟ قَالَ: "قُلِ: اللَّهُمَّ ارْحَمْنِي وَارْزُقْنِي وَعَافِنِي وَاهْدِنِي". فَلَمَّا قَامَ قَالَ هَكَذَا بِيَدِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أَمَّا هَذَا فَقَدْ مَلَأَ يَدَهُ مِنَ الْخَيْرِ". (د,ن)', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ): ഒരാൾ നബി(സ)യുടെ അടുത്തു വന്ന് പറഞ്ഞു: എനിക്ക് ഖുർആനിൽ നിന്നും യാതൊന്നും പഠിക്കുവാൻ കഴിയുന്നില്ല. അതിനാൽ അതിൽനിന്ന് എനിക്ക് പ്രതിഫലം ലഭിക്കുന്ന വല്ലതും പഠിപ്പിച്ചുതരിക. നബി(സ) പറഞ്ഞു: "നീ സുബ്ഹാനല്ലാഹ്, അൽഹംദുലില്ലാഹ്, വലാ ഇലാഹ ഇല്ലല്ലാ അല്ലാഹു അക്ബർ, ലാ ഹൗല വലാഖുവ്വത്ത ഇല്ലാ ബില്ലാഹിൽ അലിയ്യിൽ അളീം (അല്ലാഹു എത്ര പരിശുദ്ധൻ അല്ലാഹുവിനാകുന്നു സർവ്വസ്തുതിയും അല്ലാഹുവില്ലാതെ യാതൊരു ദൈവവുമില്ല. അല്ലാഹു ഏറ്റവും വലിയനാകുന്നു. ഉന്നതനും മഹാനുമായ അല്ലാഹുവിനല്ലാതെ യാതൊരു ശക്തിയും കഴിവുമില്ല) എന്നു പറയുക." അദ്ദേഹം ചോദിച്ചു: പ്രവാചകരേ, ഇതെല്ലാം അല്ലാഹുവിന്നുള്ളതാണ്. എനിക്കെന്താണുള്ളത്? നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, എനിക്ക് നീ കാരുണ്യം നൽകേണമേ, എനിക്ക് വിഭവങ്ങൾ നൽകേണമേ, സൗഖ്യം നൽകേണമേ, മാർഗ്ഗദർശനം നൽകേണമേ" എന്ന് നീ പറയുക." അയാൾ എഴുന്നേറ്റ്, കേട്ടു പഠിച്ചെന്ന് സൂചിപ്പിച്ചു കൊണ്ട് കൈ നീട്ടി. അപ്പോൾ നബി(സ) പറഞ്ഞു: "ഇദ്ദേഹം തന്റെ കരങ്ങളെ നന്മകൾ കൊണ്ട് നിറച്ചിരിക്കുന്നു." (ദ,ന)', 'عَبْدِ اللهِ بْنِ أَبِي أَوْفَى', 'അബ്ദുല്ലാഹിബ്നു അബീ ഔഫ(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 470, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 129, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كُنَّا نُصَلِّي التَّطَوُّعَ، نَدْعُو قِيَامًا وَقُعُودًا، وَنُسَبِّحُ رُكُوعًا وَسُجُودًا. (د)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഞങ്ങൾ ഐച്ഛിക നിസ്കാരം നിർവ്വഹിക്കുമ്പോൾ നിറുത്തത്തിലും ഇരുത്തത്തിലും പ്രാർത്ഥിക്കും, റുകൂഇലും സുജൂദിലും തസ്ബീഹ് ചൊല്ലാറുമുണ്ട്. (ദ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 130, 'عَنِ الْحَسَنِ رَضِيَ اللهُ عَنْهُ: كَانَ يَقْرَأُ فِي الظُّهْرِ وَالْعَصْرِ – إِمَامًا أَوْ خَلْفَ إِمَامٍ – بِفَاتِحَةِ الْكِتَابِ، وَيُسَبِّحُ وَيُكَبِّرُ وَيُهَلِّلُ قَدْرَ {ق} وَ{الذَّارِيَاتِ}. (د)', 'ഹസൻ(റ): അദ്ദേഹം ളുഹ്റിലും, അസ്റിലും ഫാത്തിഹ പാരായണം ചെയ്യും, - ഇമാമായിട്ടോ ഇമാമിനു പിന്നിലോ - തസ്ബീഹും തക്ബീറും തഹ്ലീലും ചൊല്ലും. സൂറത്തുഖാഫ്(ഓതുവാനെടുക്കുന്ന സമയത്തി)ന്റെയും, അദ്ദാരിയാത്ത്(ഓതുവാനെടുക്കുന്ന സമയത്തി)ന്റെയും അത്ര ദീർഘമായി. (ദ)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 131, 'عَنْ أَبِي مُوسَى الْأَشْعَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا قَرَأَ الْإِمَامُ فَأَنْصِتُوا، فَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ أَوَّلَ ذِكْرِ أَحَدِكُمُ التَّشَهُّدُ". (م,د,ن,جه)', 'അബൂമസൽ അശ്അരീ(റ): പ്രവാചകൻ(സ) പറഞ്ഞു: "ഇമാം പാരായാണം ചെയ്യുമ്പോൾ നിശ്ശബ്ദത പാലി(ച്ച് ശ്രദ്ധിച്ചു കേൾ)ക്കുക. ഇമാം ഇരുത്തത്തിലേക്ക് പ്രവേശിച്ചാൽ നിങ്ങൾ ആദ്യം ഉരുവിടുന്നത് തശഹ്ഹുദായിരിക്കണം." (മു,ദ,ന,ജ)', 'أَبِي مُوسَى الْأَشْعَرِيِّ', 'അബൂമസൽ അശ്അരീ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=30 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 132, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الظُّهْرِ أَوِ الْعَصْرِ، فَقَالَ: "أَيُّكُمْ قَرَأَ خَلْفِي بِ{سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى}. فَقَالَ رَجُلٌ: أَنَا، وَلَمْ أُرِدْ بِهَا إِلَّا الْخَيْرَ، قَالَ: "قَدْ عَلِمْتُ أَنَّ بَعْضَكُمْ خَالَجَنِيهَا". (م,ن)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): നബി(സ) ഞങ്ങളേയുമായി ളുഹ്റോ, അസ്റോ നിസ്കരിച്ചു. ശേഷം ചോദിച്ചു: "നിങ്ങളിലാരാണ് എന്റെ പിന്നിൽ ''സബ്ബിഹിസ്മ റബ്ബികൽ അഅ്ലാ'' ഓതിയത്?." അപ്പോൾ ഒരാൾ പറഞ്ഞു: ''ഞാനാണ്. ഞാൻ അതുകൊണ്ട് നല്ലതല്ലാതൊന്നും ഉദ്ദേശിച്ചിട്ടില്ല.'' നബി(സ) പറഞ്ഞു: "നിങ്ങളിൽ ചിലർ അതിൽ എന്നോട് മത്സരിക്കുന്നതായി എനിക്ക് മനസ്സിലായി." (മു,ന)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 133, 'أَنَّ أَبَا السَّائِبِ أَخْبَرَ لِأَبِي الْعَلَاءِ: أَنَّ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ صَلَّى صَلَاةً لَمْ يَقْرَأْ فِيهَا بِأُمِّ الْقُرْآنِ فَهِيَ خِدَاجٌ، غَيْرُ تَمَامٍ". فَقُلْتُ: يَا أَبَا هُرَيْرَةَ، فَإِنِّي أَكُونُ أَحْيَانًا وَرَاءَ الْإِمَامِ. فَغَمَزَ ذِرَاعِي وَقَالَ: يَا فَارِسِيُّ، اقْرَأْ بِهَا فِي نَفْسِكَ. (م,د,ت,ن,جه)', 'അലാഇനോട് അബൂസ്സാഇബ് പറയുന്നു: നബി(സ) ഇപ്രകാരം പറഞ്ഞതായി അബൂഹുറൈറ(റ) പറഞ്ഞു: "ഒരാൾ ഉമ്മുൽ ഖുർആൻ (ഫാത്തിഹ) പാരായണം ചെയ്യാതെ നിസ്കരിച്ചാൽ അവന്റെ നിസ്കാരം അപൂർണ്ണമാണ്." അപ്പോൾ ഞാൻ പറഞ്ഞു: അബൂഹുറൈറാ! ഞാൻ ചിലപ്പോൾ ഇമാമിന്റെ പിന്നിലായിരിക്കും (ആ സമയത്ത് ഓതേണ്ടതുണ്ടോ?) അദ്ദേഹം എന്റെ മുഴം കയ്യിന് തട്ടിക്കൊണ്ട് പറഞ്ഞു: പേർഷ്യക്കാരാ! അത് (ഫാത്തിഹ) പതുക്കെ പാരായണം ചെയ്യുക. (മു,ദ,തു,ന,ജ)', null, 'അലാഇനോട് അബൂസ്സാഇബ് പറയുന്നു', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 471, 471, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=31 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 134, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّى بِنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، فَلَمَّا قَضَى الصَّلَاةَ أَقْبَلَ عَلَيْنَا [بِوَجْهِهِ] فَقَالَ: "أَيُّهَا النَّاسُ، إِنِّي إِمَامُكُمْ، فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ وَلَا بِالِانْصِرَافِ، فَإِنِّي أَرَاكُمْ مِنْ أَمَامِي وَمِنْ خَلْفِي". ثُمَّ قَالَ: "وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا". قَالُوا: وَمَا رَأَيْتَ يَا رَسُولَ اللهِ؟ قَالَ: "رَأَيْتُ الْجَنَّةَ وَالنَّارَ". (م,ن)', 'അനസ്(റ): നബി(സ) ഒരിക്കൽ ഞങ്ങൾക്ക് ഇമാമായി നിസ്കരിച്ചു. നിസ്കാര ശേഷം ഞങ്ങളെ അഭിമുഖീകരിച്ചുകൊണ്ട് പറഞ്ഞു: "ജനങ്ങളേ, ഞാൻ നിങ്ങളുടെ ഇമാമാണ്. നിങ്ങൾ റുകൂഇലും, സുജൂദിലും, നിർത്തത്തിലും, (സലാം ചൊല്ലി)പിരിയുന്നതിലും എന്നെ മുൻകടക്കരുത്. ഞാൻ നിങ്ങളെ എന്റെ മുന്നിലും പിന്നിലും കാണുന്നുണ്ട്." പിന്നെ പറഞ്ഞു: "മുഹമ്മദിന്റെ ആത്മാവ് ആരുടെ കയ്യിലാണോ അവൻ തന്നെ സത്യം, ഞാൻ കാണുന്നതുപോലെ നിങ്ങൾ (കാര്യങ്ങളെ) കണ്ടിരുന്നെങ്കിൽ, നിങ്ങൾ കുറച്ചു മാത്രം ചിരിക്കുകയും ധാരാളം കരയുകയും ചെയ്യുമായിരുന്നു." അവർ ചോദിച്ചു: നബിയേ, അങ്ങെന്താണ് കാണുന്നത്? നബി(സ) പറഞ്ഞു: "ഞാൻ സ്വർഗ്ഗവും നരകവും കാണുന്നു." (മു,ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], 'بِوَجْهِهِ', null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 135, 'عَنْ أَبِي بَكْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ انْتَهَى إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ رَاكِعٌ، فَرَكَعَ قَبْلَ أَنْ يَصِلَ إِلَى الصَّفِّ، فَذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "زَادَكَ اللهُ حِرْصًا وَلَا تَعُدْ". (خ)', 'അബൂബക്റ(റ): നബി(സ) റുകൂഇലായിരിക്കെ അദ്ദേഹം അവിടേക്ക് ചെന്നു. അണിയിലേക്ക് എത്തുന്നതിനു മുമ്പെ റുകൂഅ് ചെയ്തു. നബി(സ)യോട് ഇക്കാര്യം പറഞ്ഞപ്പോൾ നബി(സ) പറഞ്ഞു: "അല്ലാഹു നിന്റെ ആർത്തി വർദ്ധിപ്പിക്കട്ടെ. ഇതു നീ ആവർത്തിക്കരുത്." (ബു)', 'أَبِي بَكْرَةَ', 'അബൂബക്റ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 136, 'عَنْ عِمْرَانَ بْنِ حُصَيْنٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى مَعَ عَلِيٍّ رَضِيَ اللهُ عَنْهُ بِالْبَصْرَةِ، فَقَالَ: ذَكَّرَنَا هَذَا الرَّجُلُ صَلَاةً كُنَّا نُصَلِّيهَا مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَذَكَرَ أَنَّهُ كَانَ يُكَبِّرُ كُلَّمَا رَفَعَ وَكُلَّمَا وَضَعَ. (خ)', 'ഇംറാനുബ്നു ഹുസൈൻ(റ): ബസറയിൽ അലി(റ)യോടൊപ്പം അദ്ദേഹം നിസ്കരിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചിരുന്നത് ഇദ്ദേഹം ഞങ്ങളെ അനുസ്മരിപ്പിച്ചിരിക്കുന്നു. അദ്ദേഹം പറഞ്ഞു: നബി(സ) ഓരോ പ്രാവശ്യവും ഉയരുമ്പോഴും താഴുമ്പോഴും തക്ബീർ ചൊല്ലാറുണ്ടായിരുന്നു. (ബു)', 'عِمْرَانَ بْنِ حُصَيْنٍ', 'ഇംറാനുബ്നു ഹുസൈൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 472, 472, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=32 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 137, 'عَنْ عُقْبَةَ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: أَلَا أُصَلِّي لَكُمْ كَمَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي؟ فَقُلْنَا: بَلَى. فَقَامَ، فَلَمَّا رَكَعَ وَضَعَ رَاحَتَيْهِ عَلَى رُكْبَتَيْهِ، وَجَعَلَ أَصَابِعَهُ مِنْ وَرَاءِ رُكْبَتَيْهِ، وَجَافَى إِبْطَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ رَفَعَ رَأْسَهُ فَقَامَ حَتَّى اسْتَوَى كُلُّ شَيْءٍ مِنْهُ، ثُمَّ سَجَدَ فَجَافَى إِبْطَيْهِ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ قَعَدَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ سَجَدَ حَتَّى اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ، ثُمَّ صَنَعَ كَذَلِكَ أَرْبَعَ رَكَعَاتٍ، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَهَكَذَا كَانَ يُصَلِّي بِنَا. (ن)', 'ഉഖ്ബതുബ്നു അംറ്(റ): അദ്ദേഹം പറഞ്ഞു: നബി(സ) നിസ്കരിച്ചു കാണിച്ചതു പോലെ ഞാൻ നിങ്ങൾക്ക് നിസ്കരിച്ചു കാണിച്ചു തരട്ടെയോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അപ്പോൾ അദ്ദേഹം നിന്നു. പിന്നീടദ്ദേഹം തന്റെ ഉള്ളംകൈ കാൽമുട്ടിൽ വെക്കുകയും തന്റെ വിരലുകൾ മുട്ടിന്നു പിന്നിലേക്കാക്കുകയും കക്ഷം അകറ്റിവെക്കുകയും ചെയ്തുകൊണ്ട് അടങ്ങും വരെ റുകൂഅ് നിർവ്വഹിച്ചു. പിന്നെ എല്ലാം നേരെയാവുന്നത് വരെ തന്റെ തല ഉയർത്തി. പിന്നെ എല്ലാം അടങ്ങുന്നതുവരെ കക്ഷം അകറ്റി വെച്ച് സുജൂദ് ചെയ്തു. ശേഷം എല്ലാം അടങ്ങും വരെ ഇരുന്നു. വീണ്ടും എല്ലാം അടുങ്ങും വരെ സുജൂദ് ചെയ്തു. ഇപ്രകാരം നാല് റക്അത്ത് നിർവ്വഹിച്ചു. പിന്നെ പറഞ്ഞു: നബി(സ) ഇപ്രകാരം നിസ്കരിച്ചതായി ഞങ്ങൾ കണ്ടു. അപ്രകാരമാണ് ഞങ്ങളോടൊപ്പം നബി(സ) നിസ്കരിച്ചത്. (ന)', 'عُقْبَةَ بْنِ عَمْرٍو', 'ഉഖ്ബതുബ്നു അംറ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 472, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=33 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 138, 'عَنْ عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ رَضِيَ اللهُ عَنْهُ قَالَ: اجْتَمَعَ أَبُو حُمَيْدٍ وَأَبُو أُسَيْدٍ وَسَهْلُ بْنُ سَعْدٍ وَمُحَمَّدُ بْنُ مَسْلَمَةَ، رَضِيَ اللهُ عَنْهُمْ، فَذَكَرُوا صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ أَبُو حُمَيْدٍ: أَنَا أَعْلَمُكُمْ بِصَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ رَكَعَ فَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، كَأَنَّهُ قَابِضٌ عَلَيْهِمَا، وَوَتَّرَ يَدَيْهِ فَنَحَّاهُمَا عَنْ جَنْبَيْهِ. حَسَنٌ صَحِيحٌ. (د,ت)', 'അബ്വാസുബ്നു സഹ്ലുബ്നു സഅദ്(റ): അബൂഹുമൈദ്, അബൂഉസൈദ്, സഹ്ലുബ്നു സഅ്ദ്, മുഹമ്മദ്ബ്നു മസ്ലമ(റ) എന്നിവർ ഒരുമിച്ചുകൂടി. അവർ റസൂലിന്റെ നിസ്കാരത്തെ അനുസ്മരിച്ചു. അപ്പോൾ അബൂഹുമൈദ് പറഞ്ഞു: ഞാനാണ് റസൂലിന്റെ നിസ്കാരത്തെക്കുറിച്ച് നിങ്ങളേക്കാൾ കൂടുതൽ അറിയുന്നവൻ. നബി(സ) റുകൂഇൽ കൈകൾ മുട്ടിൻകാലുകളിൽ അതിന്മേൽ പിടിക്കുന്നതുപോലെ വെച്ചിരുന്നു. രണ്ട് കൈകളും വളച്ച് ഇരുഭാഗങ്ങളിൽ നിന്നും അകറ്റി. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി. (ദ,തു)', 'عَبَّاسِ بْنِ سَهْلِ بْنِ سَعْدٍ', 'അബ്വാസുബ്നു സഹ്ലുബ്നു സഅദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 139, 'عَنْ سَالِمٍ الْبَرَّادِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَلَا أُرِيكُمْ كَيْفَ كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي؟ قُلْنَا: بَلَى. فَقَامَ فَكَبَّرَ، فَلَمَّا رَكَعَ جَافَى بَيْنَ إِبْطَيْهِ، حَتَّى لَمَّا اسْتَقَرَّ كُلُّ شَيْءٍ مِنْهُ رَفَعَ رَأْسَهُ، فَصَلَّى أَرْبَعَ رَكَعَاتٍ هَكَذَا، وَقَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي. (ن)', 'സാലിമുബ്നു ബറാദ്(റ): അബൂമസ്ഊദ്(റ) പറഞ്ഞു: നബി(സ) നിസ്കരിച്ചത് എങ്ങനെയെന്ന് ഞാൻ നിങ്ങൾക്ക് കാണിച്ച് തരട്ടെയോ? ഞങ്ങൾ പറഞ്ഞു: അതെ. അപ്പോൾ അദ്ദേഹം നിന്നു, തക്ബീർ ചൊല്ലി പിന്നെ കക്ഷങ്ങൾ അകറ്റി റുകൂഅ് ചെയ്തു. പിന്നെ എല്ലാം നേരെയാവുന്നതുവരെ തല ഉയർത്തി. ഇങ്ങനെ നാല് റക്അത്ത് നിസ്കരിച്ചു. എന്നിട്ട് പറഞ്ഞു: നബി(സ) ഇപ്രകാരം നിസ്കരിച്ചിരുന്നതായാണ് ഞാൻ കണ്ടത്. (ന)', 'سَالِمٍ الْبَرَّادِ', 'സാലിമുബ്നു ബറാദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 140, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَرْكَعُ فَيَضَعُ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَيُجَافِي بِعَضُدَيْهِ. [ز: إسناده ضعيف] (جه)', 'ആഇശ(റ): തിരുമേനി(സ) റുകൂഅ് ചെയ്യുമ്പോൾ കൈകൾ മുട്ടിന്മേൽ വെക്കുകയും മേൽക്കയ്യുകൾ അകറ്റി വെക്കുകയും ചെയ്യുമായിരുന്നു. ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു. (ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز: إسناده ضعيف', null, 473, 473, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=34 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 141, 'عَنِ الْأَسْوَدِ وَعَلْقَمَةَ قَالَا: أَتَيْنَا عَبْدَ اللهِ بْنَ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فِي دَارِهِ، فَقَالَ: أَصَلَّى هَؤُلَاءِ خَلْفَكُمْ فَقُلْنَا: لَا. قَالَ: فَقُومُوا فَصَلُّوا، فَلَمْ يَأْمُرْنَا بِأَذَانٍ وَلَا إِقَامَةٍ، قَالَ: وَذَهَبْنَا لِنَقُومَ خَلْفَهُ، فَأَخَذَ بِأَيْدِينَا: فَجَعَلَ أَحَدَنَا عَنْ يَمِينِهِ وَالْآخَرَ عَنْ شِمَالِهِ، قَالَ: فَلَمَّا رَكَعَ وَضَعْنَا أَيْدِيَنَا عَلَى رُكَبِنَا، قَالَ: فَضَرَبَ أَيْدِيَنَا، وَطَبَّقَ بَيْنَ كَفَّيْهِ، ثُمَّ أَدْخَلَهُمَا بَيْنَ فَخِذَيْهِ، قَالَ: فَلَمَّا صَلَّى قَالَ: إِنَّهُ سَتَكُونُ عَلَيْكُمْ أُمَرَاءُ يُؤَخِّرُونَ الصَّلَاةَ عَنْ مِيقَاتِهَا وَيَخْنُقُونَهَا إِلَى شَرَقِ الْمَوْتَى، فَإِذَا رَأَيْتُمُوهُمْ قَدْ فَعَلُوا ذَلِكَ فَصَلُّوا الصَّلَاةَ لِمِيقَاتِهَا، وَاجْعَلُوا صَلَاتَكُمْ مَعَهُمْ سُبْحَةً، وَإِذَا كُنْتُمْ ثَلَاثَةً فَصَلُّوا جَمِيعًا، وَإِذَا كُنْتُمْ أَكْثَرَ مِنْ ذَلِكَ فَلْيَؤُمَّكُمْ أَحَدُكُمْ، وَإِذَا رَكَعَ أَحَدُكُمْ فَلْيَفْرِشْ ذِرَاعَيْهِ عَلَى فَخِذَيْهِ، وَلْيَجْنَأْ وَلْيُطَبِّقْ بَيْنَ كَفَّيْهِ، فَلَكَأَنِّي أَنْظُرُ إِلَى اخْتِلَافِ أَصَابِعِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَرَاهُمْ. (م,د,ن)', 'അസ്വദ്(റ), അൽഖമഃ(റ): എന്നിവരിൽനിന്ന് നിവേദനം: ഞങ്ങൾ അബ്ദുല്ലാഹിബ്നുമസ്ഊദ്(റ)ന്റെ വീട്ടിൽ ചെന്നു. അന്നേരം അദ്ദേഹം ചോദിച്ചു: ''നിങ്ങളുടെ പിന്നിലുള്ള ഈ ജനങ്ങൾ നിസ്കരിച്ചുവോ? (പള്ളിയിലെ ഔദ്യോഗിക ജമാഅത്ത് നമസ്കാരം കഴിഞ്ഞോ?)'' ഞങ്ങൾ പറഞ്ഞു: ''ഇല്ല'' അപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ''എങ്കിൽ നിസ്കരിക്കുവിൻ''. ബാങ്കോ ഇഖാമത്തോ കൊടുക്കാൻ അദ്ദേഹം ഞങ്ങളോട് കൽപ്പിച്ചില്ല. - നിവേദകൻ പറയുന്നു - ഞങ്ങൾ അദ്ദേഹത്തിനു പിന്നിൽ നമസ്കരിക്കാനൊരുങ്ങി. അപ്പോൾ അദ്ദേഹം ഞങ്ങളുടെ കൈകളിൽ പിടിച്ച് ഒരാളെ വലതു ഭാഗത്തും മറ്റെയാളെ ഇടതുഭാഗത്തും നിർത്തി. നിവേദകൻ പറയുന്നു: അപ്പോൾ അദ്ദേഹം റുകൂഅ് ചെയ്തപ്പോൾ ഞങ്ങൾ ഞങ്ങളുടെ കൈകൾ (വിരലുകൾ) കോർത്ത് കാൽമുട്ടുകളിൽ വെച്ചു. അപ്പോൾ അദ്ദേഹം ഞങ്ങളുടെ കൈകൾ തട്ടിമാറ്റുകയും അദ്ദേഹത്തിന്റെ ഇരു തുടകളുടേയും മദ്ധ്യേ വെക്കുകയും ചെയ്തു. നിസ്കാരം കഴിഞ്ഞപ്പോൾ അദ്ദേഹം (അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്) പറഞ്ഞു: ''നമസ്കാരം അതിന്റെ സമയത്ത് നിർവ്വഹിക്കാതെ ഏറ്റവും അവസാന സമയത്തേക്ക് പിന്തിക്കുന്ന ഉമറാക്കൾ നിങ്ങൾക്ക് ഉണ്ടായേക്കും. അങ്ങനെ അവർ ചെയ്യുന്നതായി നിങ്ങൾ കണ്ടാൽ കൃത്യസമയത്തുതന്നെ സ്വന്തമായി നിങ്ങൾ നിസ്കരിക്കുക. (ശേഷം അവർ വൈകി നിസ്കരിക്കുമ്പോൾ) അവരുടെ കൂടെയുള്ള നിസ്കാരം ഐച്ഛികമെന്ന നിലയിൽ നിർവ്വഹിക്കുക. നിങ്ങൾ മൂന്നു പേരുണ്ടെങ്കിൽ (ഒരേ സ്വഫ്ഫിൽ നിന്ന്) സംഘടിതമായി നിസ്കരിക്കുക. മൂന്നിലധികമുണ്ടെങ്കിൽ ഒരാൾ മുന്നിൽ ഇമാമായി നിൽക്കട്ടെ. നിങ്ങൾ റുകൂഅ് ചെയ്യുമ്പോൾ മുഴങ്കൈകൾ തുടയുടെ മേൽ പരത്തിവെക്കുകയും കുനിഞ്ഞു നിൽക്കുകയും ഇരുകൈപത്തികളും കൂട്ടിപ്പിടിക്കുകയും ചെയ്യട്ടെ. നബി(സ)യുടെ വിരലുകൾ വിടർന്ന് നിൽക്കുന്നത് ഞാനിപ്പോൾ കാണുന്നതു പോലെ തോന്നുന്നു. അനന്തരം അദ്ദേഹം വിരലുകൾ വിടർത്തി കാണിച്ചു കൊടുക്കുകയും ചെയ്തു. (മു,ദ,ന)', 'الْأَسْوَدِ وَعَلْقَمَةَ قَالَا', 'അസ്വദ്(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 473, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=35 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 142, 'عَنِ الْأَسْوَدِ وَعَلْقَمَةَ قَالَا: صَلَّيْنَا مَعَ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فِي بَيْتِهِ فَقَامَ بَيْنَنَا، فَوَضَعْنَا أَيْدِيَنَا عَلَى رُكَبِنَا، فَنَزَعَهَا، فَخَالَفَ بَيْنَ أَصَابِعِنَا وَقَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُهُ. (ن)', 'അൽഖമ, അസ്വദ് എന്നിവരിൽ നിന്ന്: ഞങ്ങൾ ഇബ്നുമസ്ഊദി(റ)ന്റെ കൂടെ അദ്ദേഹത്തിന്റെ വീട്ടിൽനിന്ന് നിസ്കരിച്ചപ്പോൾ ഞങ്ങളിരുവർക്കിടയിൽ (ഞങ്ങൾക്ക് ഇമാമായി) നിന്നുകൊണ്ട് അദ്ദേഹം നിസ്കരിച്ചു. അപ്പോൾ ഞങ്ങൾ (റുകൂഇലേക്കു പോയപ്പോൾ) കൈകൾ മുട്ടിന്മേൽ വെച്ചു. അദ്ദേഹം അത് എടുത്തുമാറ്റി. എന്നിട്ട് ഞങ്ങളുടെ ഇരുകൈകളുടെ വിരലുകൾ പരസ്പരം അകറ്റിക്കൊണ്ട് വെച്ചു. അദ്ദേഹം പറഞ്ഞു: തിരുമേനി(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. (ന)', 'الْأَسْوَدِ وَعَلْقَمَةَ قَالَا', 'അൽഖമ, അസ്വദ് എന്നിവരിൽ നിന്ന്', null, null, array['ن']::text[], array['ന']::text[], null, null, 474, 474, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 143, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: عَلَّمَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ، فَقَامَ فَكَبَّرَ، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ طَبَّقَ يَدَيْهِ بَيْنَ رُكْبَتَيْهِ وَرَكَعَ. فَبَلَغَ ذَلِكَ سَعْدًا فَقَالَ: صَدَقَ أَخِي، قَدْ كُنَّا نَفْعَلُ هَذَا، ثُمَّ أُمِرْنَا بِهَذَا، يَعْنِي الْإِمْسَاكَ بِالرُّكَبِ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): പ്രവാചകൻ(സ) ഞങ്ങളെ നിസ്കാരം പഠിപ്പിച്ചു. തിരുമേനി(സ) എഴുന്നേറ്റു നിന്ന് തക്ബീർ ചൊല്ലുകയും ചെയ്തു. അവിടുന്ന് ഇരു കൈകളും (കൈവിരളും) കോർത്തുകൊണ്ട് മുട്ടുകൾക്കിടയിലാക്കി വെച്ചുകൊണ്ട് റുകൂഅ് ചെയ്തു. ഈ ഹദീസ് സഅ്ദിനോട് പറഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: എന്റെ സഹോദരൻ സത്യം പറഞ്ഞു: ഞങ്ങൾ അപ്രകാരം ചെയ്തിരുന്നു. പിന്നീട് ഇപ്രകാരം ചെയ്യാൻ - അതായത് ഇരുകൈകളും മുട്ടുകളിന്മേൻ പിടിക്കാൻ - ഞങ്ങൾ കൽപ്പിക്കപ്പെട്ടു. (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 474, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=36 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 144, 'عَنْ عُمَرَ رَضِيَ اللهُ عَنْهُ قَالَ: سُنَّتْ لَكُمُ الرُّكَبُ، فَأَمْسِكُوا بِالرُّكَبِ. وَفِي رِوَايَةٍ: إِنَّمَا السُّنَّةُ الْأَخْذُ بِالرُّكَبِ. (ت,ن)', 'ഉമർ(റ): കാൽമുട്ട് പിടിക്കുന്നത് നിങ്ങൾക്ക് സുന്നത്താക്കപ്പെട്ടിരിക്കുന്നു. അതിനാൽ നിങ്ങൾ കാൽമുട്ട് പിടിക്കുക. ഒരു റിപ്പോർട്ടിൽ: കാൽമുട്ട് പിടിക്കലാണ് സുന്നത്ത്. (തു,ന)', 'عُمَرَ', 'ഉമർ(റ)', null, null, array['ت','ن']::text[], array['തു','ന']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=144), 1, 'وَفِي رِوَايَةٍ: إِنَّمَا السُّنَّةُ الْأَخْذُ بِالرُّكَبِ. (ت,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 145, 'عَنْ مُصْعَبِ بْنِ سَعْدٍ قَالَ: صَلَّيْتُ إِلَى جَنْبِ أَبِي، وَجَعَلْتُ يَدَيَّ بَيْنَ رُكْبَتَيَّ، فَقَالَ لِي: اضْرِبْ بِكَفَّيْكَ عَلَى رُكْبَتَيْكَ. قَالَ: ثُمَّ فَعَلْتُ ذَلِكَ مَرَّةً أُخْرَى، فَضَرَبَ يَدَيَّ وَقَالَ: إِنَّا قَدْ نُهِينَا عَنْ هَذَا، وَأُمِرْنَا أَنْ نَضْرِبَ بِالْأَكُفِّ عَلَى الرُّكَبِ. (ق,د,ت,ن,جه)', 'മുസ്അബ് ബ്നുസഅദ്(റ): ഞാൻ എന്റെ പിതാവിന്റെ അടുത്ത് നിസ്കരിച്ചപ്പോൾ ഞാനെന്റെ കൈകൾ എന്റെ മുട്ടുകൾക്കിടയിൽ വെച്ചു. അപ്പോൾ അദ്ദേഹം എന്നോട് പറഞ്ഞു: നീ നിന്റെ കൈകൾ നിന്റെ കാൽമുട്ടുകളിൽ വെക്കുക. ഞാൻ പിന്നീടൊരിക്കൽ കൂടി മുൻപറഞ്ഞപോലെ കൈകൾ വെച്ചപ്പോൾ അദ്ദേഹം എന്റെ കൈകളിൽ തട്ടിക്കൊണ്ട് പറഞ്ഞു: ഇപ്രകാരം ചെയ്യുന്നതിൽ നിന്നും ഞങ്ങൾ വിലക്കപ്പെടുകയും, കൈകൾ മുട്ടുകളിൽ വെക്കുവാൻ ഞങ്ങൾ കൽപ്പിക്കപ്പെടുകയും ചെയ്തിട്ടുണ്ട്. (ബു,മു,ദ,തു,ന,ജ)', 'مُصْعَبِ بْنِ سَعْدٍ قَالَ', 'മുസ്അബ് ബ്നുസഅദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 146, 'عَنْ مُصْعَبِ ابْنِ سَعْدٍ قَالَ: رَكَعْتُ، فَطَبَّقْتُ، فَقَالَ أَبِي: إِنَّ هَذَا شَيْءٌ كُنَّا نَفْعَلُهُ، ثُمَّ ارْتَفَعْنَا إِلَى الرُّكَبِ. (ن)', 'മുസ്അബ്ബ്നു സഅ്ദ്(റ): ഞാൻ റുകൂഅ് ചെയ്തപ്പോൾ കൈവിരലുകൾ പരസ്പരം കോർത്ത് കൈകൾ മുട്ടുകൾക്കിടയിൽവെച്ചു. അപ്പോൾ എന്റെ പിതാവു പറഞ്ഞു: ഞങ്ങളും ഇപ്രകാരം ചെയ്യാറുണ്ടായിരുന്നു. പിന്നീട് (തിരുമേനി(സ)യുടെ കൽപ്പനപ്രകാരം) ഞങ്ങൾ മുട്ടുകളിൽ കൈകൾ വെച്ചു. (ന)', 'مُصْعَبِ ابْنِ سَعْدٍ قَالَ', 'മുസ്അബ്ബ്നു സഅ്ദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=37 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 147, 'عَنْ سَالِمٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَتَيْنَا أَبَا مَسْعُودٍ رَضِيَ اللهُ عَنْهُ فَقُلْنَا لَهُ: حَدِّثْنَا عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَقَامَ بَيْنَ أَيْدِينَا وَكَبَّرَ، فَلَمَّا رَكَعَ وَضَعَ رَاحَتَيْهِ عَلَى رُكْبَتَيْهِ، وَجَعَلَ أَصَابِعَهُ أَسْفَلَ مِنْ ذَلِكَ، وَجَافَى بِمِرْفَقَيْهِ، حَتَّى اسْتَوَى كُلُّ شَيْءٍ مِنْهُ، ثُمَّ قَالَ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقَامَ حَتَّى اسْتَوَى كُلُّ شَيْءٍ مِنْهُ. (ن)', 'സാലിം(റ): ഞങ്ങൾ അബൂമസ്ഊദി(റ)ന്റെ അടുക്കൽ ചെന്ന് നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ഞങ്ങൾക്ക് പറഞ്ഞു തരാൻ അദ്ദേഹത്തോട് പറഞ്ഞു. അദ്ദേഹം ഞങ്ങൾക്കു മുമ്പിൽ എഴുന്നേറ്റുനിന്ന് തക്ബീർ ചൊല്ലി. റുകൂഅ് ചെയ്തപ്പോൾ ഉള്ളൻകൈകൾ മുട്ടുകളിലും, വിരലുകൾ അതിനു താഴെയും വെച്ചു. കൈമുട്ടുകൾ അകറ്റിവെച്ചു, അദ്ദേഹത്തിന്റെ ശരീരം മുഴുവൻ ശരിയായ വിധത്തിൽ നിശ്ചലമാകും വരെ ഈ നില തുടർന്നു. പിന്നെ ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്നു പറഞ്ഞു. ശേഷം എല്ലാ അവയവങ്ങളും ശരിയാവുന്നതുവരെ എഴുന്നേറ്റു നിന്നു. (ന)', 'سَالِمٍ', 'സാലിം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 475, 475, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=38 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 148, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا افْتَتَحَ الصَّلَاةَ يَرْفَعُ يَدَيْهِ حَتَّى يُحَاذِيَ مَنْكِبَيْهِ، وَإِذَا رَكَعَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ. (ن)', 'ഇബ്നുഉമർ(റ): നിസ്കാരം തുടങ്ങുമ്പോഴും, റുകൂഇൽ പോകുമ്പോഴും റുകൂഇൽ നിന്ന് തല ഉയർത്തുമ്പോഴും കൈ ചുമലറ്റം വരെ ഉയർത്തിയ നിലയിൽ ഞാൻ നബി(സ)യെ കണ്ടു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 149, 'عَنْ عَبْدِ اللهِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَلَا أُخْبِرُكُمْ بِصَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: فَقَامَ فَرَفَعَ يَدَيْهِ أَوَّلَ مَرَّةٍ، ثُمَّ لَمْ يَعُدْ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): നബി(സ)യുടെ നിസ്കാരത്തെക്കുറിച്ച് ഞാൻ നിങ്ങളെ അറിയിക്കട്ടെയോ? അദ്ദേഹം പറഞ്ഞു: നബി(സ) നിന്ന് ഒരുപ്രാവശ്യം കൈകൾ ഉയർത്തും. പിന്നീടത് ആവർത്തിച്ചില്ല. (ന)', 'عَبْدِ اللهِ ابْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=39 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 150, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اعْتَدِلُوا فِي الرُّكُوعِ وَالسُّجُودِ، وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ كَالْكَلْبِ". (ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ റുകൂഇലും സുജൂദിലും നേരെയാകുവീൻ. നിങ്ങളിലാരും നായയെപ്പോലെ മുഴംകൈ വിരിക്കരുത്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 151, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ اعْتَدَلَ، فَلَمْ يَنْصِبْ رَأْسَهُ وَلَمْ يُقْنِعْهُ، وَوَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ. (ن)', 'അബൂഹുമൈദുസ്സാഇദീ(റ): പ്രവാചകൻ(സ) റുകൂഅ് ചെയ്യുമ്പോൾ മുതുക് നേരെയാക്കും. തിരുമേനിയുടെ തല കൂടുതൽ ഉയരുകയോ എന്നാൽ താഴുകയോ ചെയ്തില്ല. അവിടുത്തെ ഇരുകൈകൾ മുട്ടുകളിന്മേൽ വെച്ചു. (ന)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദുസ്സാഇദീ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 476, 476, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 152, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ دَخَلَ الْمَسْجِدَ فَدَخَلَ رَجُلٌ فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَدَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ السَّلَامَ وَقَالَ: "ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ". فَرَجَعَ الرَّجُلُ فَصَلَّى كَمَا كَانَ صَلَّى، ثُمَّ جَاءَ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ عَلَيْهِ، فَقَالَ لَهُ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "وَعَلَيْكَ السَّلَامُ". ثُمَّ قَالَ: "ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ". حَتَّى فَعَلَ ذَلِكَ ثَلَاثَ مِرَارٍ، فَقَالَ الرَّجُلُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ مَا أُحْسِنُ غَيْرَ هَذَا، فَعَلِّمْنِي. قَالَ: "إِذَا قُمْتَ إِلَى الصَّلَاةِ فَكَبِّرْ، ثُمَّ اقْرَأْ مَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَعْتَدِلَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ اجْلِسْ حَتَّى تَطْمَئِنَّ جَالِسًا، ثُمَّ افْعَلْ ذَلِكَ فِي صَلَاتِكَ كُلِّهَا". وَفِي رِوَايَةٍ: "فَإِذَا فَعَلْتَ هَذَا فَقَدْ تَمَّتْ صَلَاتُكَ، وَمَا انْتَقَصْتَ مِنْ هَذَا شَيْئًا فَإِنَّمَا انْتَقَصْتَهُ مِنْ صَلَاتِكَ". وَقَالَ فِيهِ: "إِذَا قُمْتَ إِلَى الصَّلَاةِ فَأَسْبِغِ الْوُضُوءَ". (ق,د,ت,ن,جه)', 'അബൂഹുറൈറ(റ): പ്രവാചകൻ(സ) പള്ളിയിൽ പ്രവേശിച്ചപ്പോൾ ഓരാൾ അവിടേക്കു കടന്നു വരികയും നിസ്കരിക്കുകയും ചെയ്തു. ശേഷം അദ്ദേഹം തിരുമേനിയുടെ അടുക്കൽ വന്ന് അവിടുത്തേട് സലാം പറഞ്ഞു: തിരുമേനി(സ) അദ്ദേഹത്തിന് സലാം മടക്കിപ്പറയുകയും, അദ്ദേഹത്തോട് "നീ മടങ്ങിച്ചെന്ന് നിസ്കരിക്കുക. നീ നിസ്കരിച്ചിട്ടില്ല" എന്നു പറയുകയും ചെയ്തു. അയാൾ മടങ്ങിച്ചെന്ന് മുമ്പ് നിസ്കരിച്ചതുപോലെത്തന്നെ നിസ്കരിക്കുകയും ശേഷം തിരുമേനി(സ)യിലേക്കു വന്ന് അവിടുത്തേക്ക് സലാം പറയുകയും ചെയ്തു. അപ്പോൾ തിരുമേനി(സ) "നിന്റെ മേലും അല്ലാഹുവിൽനിന്നുള്ള രക്ഷയുണ്ടാവട്ടെ" എന്നു പറയുകയും "നീ തിരിച്ചുചെന്ന് നിസ്കരിക്കുക, നിശ്ചയം നീ നിസ്കാരം നിർവ്വഹിച്ചിട്ടില്ല" എന്നു പറയുകയും ചെയ്തു. ഇപ്രകാരം മൂന്നു പ്രാവശ്യം ആവർത്തിക്കുകയുണ്ടായി. അപ്പോൾ അയാൾ പറഞ്ഞു: താങ്കളെ സത്യവുമായി നിയോഗിച്ചവൻ തന്നെയാണെ, എനിക്കിതിലേറെ നന്നായി നിർവ്വഹിക്കാനറിയില്ല. അതിനാൽ താങ്കൾ എന്നെ പഠിപ്പിച്ചുതന്നാലും! തുരുമേനി(സ) പറഞ്ഞു: "നീ നിസ്കാരത്തിനു നിന്നാൽ തക്ബീർ ചൊല്ലുക. ശേഷം നിനക്ക് എളുപ്പമുള്ള ഖുർആൻ വാക്യങ്ങൾ പാരായണം ചെയ്യുക. എന്നിട്ടു നീ അടങ്ങിയൊതുങ്ങിയ നിലയിലാവും വിധം റുകൂഅ് ചെയ്യുക. പിന്നെ നിന്റെ നിർത്തം നേരെയാവും വിധം നീ ഉയരുക. അനന്തരം അടങ്ങിയൊതുങ്ങിയ നിലയിലാവും വിധം നീ സുജൂദു നിർവ്വഹിക്കുക. ശേഷം നീ അടങ്ങിയൊതുങ്ങിയ നിലയിലാവും വിധം നീ ഇരിക്കുക. പിന്നെ നിന്റെ നിസ്കാരത്തിലുടനീളം നീ ഇപ്രകാരം തന്നെ ചെയ്യുക." മറ്റൊരു റിപ്പോർട്ടിൽ: "നീ ഇതു പ്രകാരം നിർവ്വഹിച്ചാൽ തീർച്ചയായും നിസ്കാരം പൂർണ്ണമായി. നീ ഇതിൽനിന്ന് വല്ലതും കുറച്ചാൽ നീ കുറവ് വരുത്തിയത് നിന്റെ നിസ്കാരത്തിൽ നിന്നാകുന്നു." ആ റിപ്പോർട്ടിൽ ഇങ്ങനെ കൂടിയുണ്ട്: "നീ നിസ്കാരത്തിനു നിന്നാൽ നിന്റെ വുദു പൂർണ്ണമാക്കുക." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 476, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=152), 1, 'وَفِي رِوَايَةٍ: "فَإِذَا فَعَلْتَ هَذَا فَقَدْ تَمَّتْ صَلَاتُكَ، وَمَا انْتَقَصْتَ مِنْ هَذَا شَيْئًا فَإِنَّمَا انْتَقَصْتَهُ مِنْ صَلَاتِكَ". وَقَالَ فِيهِ: "إِذَا قُمْتَ إِلَى الصَّلَاةِ فَأَسْبِغِ الْوُضُوءَ". (ق,د,ت,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: "നീ ഇതു പ്രകാരം നിർവ്വഹിച്ചാൽ തീർച്ചയായും നിസ്കാരം പൂർണ്ണമായി. നീ ഇതിൽനിന്ന് വല്ലതും കുറച്ചാൽ നീ കുറവ് വരുത്തിയത് നിന്റെ നിസ്കാരത്തിൽ നിന്നാകുന്നു." ആ റിപ്പോർട്ടിൽ ഇങ്ങനെ കൂടിയുണ്ട്: "നീ നിസ്കാരത്തിനു നിന്നാൽ നിന്റെ വുദു പൂർണ്ണമാക്കുക." (ബു,മു,ദ,തു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 153, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَجُلًا دَخَلَ الْمَسْجِدَ، فَذَكَرَ نَحْوَهُ، قَالَ فِيهِ: فَقَالَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهُ لَا تَتِمُّ صَلَاةٌ لِأَحَدٍ مِنَ النَّاسِ حَتَّى يَتَوَضَّأَ فَيَضَعَ الْوُضُوءَ – يَعْنِي مَوَاضِعَهُ – ثُمَّ يُكَبِّرُ وَيَحْمَدُ اللهَ جَلَّ وَعَزَّ وَيُثْنِي عَلَيْهِ، وَيَقْرَأُ بِمَا تَيَسَّرَ مِنَ الْقُرْآنِ، ثُمَّ يَقُولُ: اللهُ أَكْبَرُ، ثُمَّ يَرْكَعُ حَتَّى تَطْمَئِنَّ مَفَاصِلُهُ، ثُمَّ يَقُولُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، حَتَّى يَسْتَوِيَ قَائِمًا ثُمَّ يَقُولُ: اللهُ أَكْبَرُ، ثُمَّ يَسْجُدُ حَتَّى تَطْمَئِنَّ مَفَاصِلُهُ، ثُمَّ يَقُولُ: اللهُ أَكْبَرُ، وَيَرْفَعُ رَأْسَهُ حَتَّى يَسْتَوِيَ قَاعِدًا، ثُمَّ يَقُولُ: اللهُ أَكْبَرُ، ثُمَّ يَسْجُدُ حَتَّى تَطْمَئِنَّ مَفَاصِلُهُ، ثُمَّ يَرْفَعُ رَأْسَهُ فَيُكَبِّرُ، فَإِذَا فَعَلَ ذَلِكَ فَقَدْ تَمَّتْ صَلَاتُهُ". (د,ت)', 'റിഫാഅതുബ്നു റാഫിഅ്(റ): ഒരാൾ പള്ളിയിൽ പ്രവേശിച്ചു. - മുൻ ഹദീസിലേതു പോലെ വിവരിച്ചു - ഈ റിപ്പോർട്ടിൽ ഇപ്രകാരമുണ്ട്. അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "വുദു പൂർണ്ണമായി ചെയ്യാതെ ജനങ്ങളിൽ ഒരാളുടെയും നിസ്കാരം പൂർണ്ണമാവുകയില്ല. ശേഷം തക്ബീർ ചെയ്യുകയും, അല്ലാഹുവിനെ സ്തുതിക്കുകയും, അവനെ വാഴ്ത്തുകയും, എളുപ്പമായ ഖുർആൻ സൂക്തങ്ങൾ ഓതുകയും ചെയ്യുക. ശേഷം ''അല്ലാഹുഅക്ബർ'' എന്നു പറയുകയും അനന്തരം സന്ധികൾ അടങ്ങിയൊതുങ്ങിയ നിലയിലാവും വിധം റുകൂഅ് ചെയ്യുകയും, പിന്നെ ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' എന്ന് പറയുകയും നേരെ നിൽക്കുകയും ചെയ്യുക. ശേഷം തക്ബീർ ചൊല്ലുകയും അനന്തരം സന്ധികൾ അടങ്ങിയൊതുങ്ങിയ നിലയിലാവും വിധം സുജൂദ് ചെയ്യുകയും ചെയ്യുക. തുടർന്ന് ''അല്ലാഹു അക്ബർ'' എന്നു ചൊല്ലിക്കൊണ്ട് തലയുയർത്തുകയും ശരിയാംവിധം ഇരിക്കുകയും, പിന്നെ തലയുയർത്തുകയും തക്ബീർ ചൊല്ലുകയും ചെയ്യുക (അടുത്ത റക്അത്തിലേക്ക് പ്രവേശിക്കുക) ഇപ്രകാരം (ഓരോറക്അത്തിലും) ചെയ്താൽ നിന്റെ നിസ്കാരം പൂർണ്ണമായി." (ദ,തു)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'റിഫാഅതുബ്നു റാഫിഅ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 477, 477, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 154, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ، بِمَعْنَاهُ، قَالَ: فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِنَّهَا لَا تَتِمُّ صَلَاةُ أَحَدِكُمْ حَتَّى يُسْبِغَ الْوُضُوءَ كَمَا أَمَرَهُ اللهُ عَزَّ وَجَلَّ: فَيَغْسِلَ وَجْهَهُ وَيَدَيْهِ إِلَى الْمِرْفَقَيْنِ وَيَمْسَحَ بِرَأْسِهِ وَرِجْلَيْهِ إِلَى الْكَعْبَيْنِ، ثُمَّ يُكَبِّرَ اللهَ عَزَّ وَجَلَّ وَيَحْمَدَهُ، ثُمَّ يَقْرَأَ مِنَ الْقُرْآنِ مَا أَذِنَ لَهُ فِيهِ وَتَيَسَّرَ". فَذَكَرَ نَحْوَهُ، قَالَ: "ثُمَّ يُكَبِّرُ فَيَسْجُدُ فَيُمَكِّنُ وَجْهَهُ" وَرُبَّمَا قَالَ: "جَبْهَتَهُ مِنَ الْأَرْضِ حَتَّى تَطْمَئِنَّ مَفَاصِلُهُ وَتَسْتَرْخِيَ، ثُمَّ يُكَبِّرُ فَيَسْتَوِيَ قَاعِدًا عَلَى مَقْعَدِهِ وَيُقِيمَ صُلْبَهُ". فَوَصَفَ الصَّلَاةَ هَكَذَا أَرْبَعَ رَكَعَاتٍ حَتَّى تَفْرُغَ: "لَا تَتِمُّ صَلَاةُ أَحَدِكُمْ حَتَّى يَفْعَلَ ذَلِكَ". (د,ت,ن)', 'രിഫാഅ(റ): - മേൽഹദീസു പ്രകാരം വിവരിച്ചു - ഈ റിപ്പോർട്ടിൽ അദ്ദേഹം പറഞ്ഞു: അപ്പോൾ തിരുമേനി(സ) പറഞ്ഞു: "നിശ്ചയം, അല്ലാഹു കൽപ്പിച്ചതുപ്രകാരം വുദു പൂർണ്ണമായി ചെയ്യാതെ നിങ്ങളിലൊരാളുടെയും നിസ്കാരം പൂർണ്ണമാവുകയില്ല. (വുദു ചെയ്യുമ്പോൾ) ഒരാൾ തന്റെ മുഖം കഴുകുകയും, കൈകൾ മുട്ടുൾപ്പടെ കഴുകുകയും, തലതടവുകയും, കാലുകൾ നെരിയാണിവരെ, കഴുകുകയും ചെയ്യണം. ശേഷം അല്ലാഹുവിനെ മഹത്വപ്പെടുത്തുകയും, അവനെ സ്തുതിക്കുകയും, ഖുർആനിൽ നിന്നും എളുപ്പമായത് പാരായണം ചെയ്യുകയും ചെയ്യുക." മേൽഹദീസിൽ വന്നതുപോലെ വിവരിച്ചു...... അവിടുന്ന് പറഞ്ഞു: "മുഖം നിലത്ത് സ്വസ്ഥമാക്കിവെച്ച് സുജൂദ് ചെയ്യണം." അദ്ദേഹം പറഞ്ഞു: ചിലതിൽ ഇപ്രകാരവും റിപ്പോർട്ടു ചെയ്യപ്പെട്ടിട്ടുണ്ട്: "എല്ലുകൾ അതിന്റെതായ സ്ഥാനത്തുവന്ന് സ്വസ്ഥമാകും വിധം തന്റെ നെറ്റി നിലത്ത് വെച്ച് (കൊണ്ട് സുജൂദ് ചെയ്യുക). പിന്നെ തക്ബീർ ചൊല്ലുകയും പൃഷ്ടത്തിന്മേൽ ശരിയാം വണ്ണം ഇരിക്കുകയും മുതുക് നേരെയാക്കുകയും ചെയ്യുക." തിരുമേനി(സ) നാലുറക്അത്തുകളും പൂർത്തിയാക്കും വരെയുള്ളത് ഇപ്രകാരം വിവരിച്ചു. (ശേഷം പറഞ്ഞു) "നിങ്ങളിലൊരാളുടെയും നിസ്കാരം ഇപ്രകാരം ചെയ്യാതെ പൂർണ്ണമാവുകയില്ല." (ദ,തു,ദ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'രിഫാഅ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ദ']::text[], null, null, 477, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 155, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ، بِهَذِهِ الْقِصَّةِ، قَالَ: "إِذَا قُمْتَ فَتَوَجَّهْتَ إِلَى الْقِبْلَةِ فَكَبِّرْ، ثُمَّ اقْرَأْ بِأُمِّ الْقُرْآنِ وَبِمَا شَاءَ اللهُ أَنْ تَقْرَأَ، وَإِذَا رَكَعْتَ فَضَعْ رَاحَتَيْكَ عَلَى رُكْبَتَيْكَ وَامْدُدْ ظَهْرَكَ". وَقَالَ: "إِذَا سَجَدْتَ فَمَكِّنْ لِسُجُودِكَ، فَإِذَا رَفَعْتَ فَاقْعُدْ عَلَى فَخِذِكَ الْيُسْرَى". (د)', 'രിഫാഅതുബ്നു റാഫിഅ്(റ): മേൽ സംഭവം വിവരിക്കുന്ന, ഹദീസ്...... നബി(സ) അയാളോടു പറഞ്ഞു: "നീ നിസ്കാരത്തിന് നിൽക്കുകയും, ഖിബ്ലക്കു നേരെതിരിയുകയും ചെയ്താൽ തക്ബീർ ചൊല്ലുക. ശേഷം ഫാത്തിഹയും, നീ(ഖുർആനിൽനിന്ന്) പാരായണം ചെയ്യുവാൻ അല്ലാഹു ഉദ്ദേശിച്ചതെത്രയോ അത്രയും (ഖുർആൻവാക്യങ്ങളും) നീ പാരായണം ചെയ്യുക. നീ റുകൂഅ് ചെയ്യുമ്പോൾ നിന്റെ ഇരു കൈപ്പടങ്ങളും കാൽമുട്ടുകളിന്മേൽ വെക്കുകയും നിന്റെ മുതുക് നീളത്തിലാ(നേരെയാ)ക്കുകയും ചെയ്യുക. അവിടുന്ന് വീണ്ടും പറഞ്ഞു: നീ സുജൂദ് ചെയ്യുമ്പോൾ അത് പൂർണ്ണമായ നിലയിൽ ചെയ്യുക (അവയവങ്ങൾ സ്വസ്ഥമാകും വിധം), നീ (സുജൂദിൽ നിന്റെ) തലയുയർത്തിയാൽ നിന്റെ ഇടതു തുടയിന്മേൽ ഇരിക്കുക." (ദ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'രിഫാഅതുബ്നു റാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=40 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 156, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ رُكُوعُهُ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ، وَسُجُودُهُ، وَمَا بَيْنَ السَّجْدَتَيْنِ، قَرِيبًا مِنَ السَّوَاءِ. (ن)', 'ബറാഅ്ബുനു ആസിബ്(റ): നബി(സ)യുടെ റുകൂഉം, റുകൂഇൽ നിന്നുയരലും, സുജൂദും, സുജൂദുകൾക്കിടയിലുള്ള അടക്കവും ഏതാണ്ട് തുല്യ (സമയ)മായിരുന്നു. (ന)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഅ്ബുനു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 478, 478, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 157, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: مَا صَلَّيْتُ خَلْفَ رَجُلٍ أَوْجَزَ صَلَاةً مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي تَمَامٍ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ" قَامَ حَتَّى نَقُولَ: قَدْ أَوْهَمَ، ثُمَّ يُكَبِّرُ وَيَسْجُدُ، وَكَانَ يَقْعُدُ بَيْنَ السَّجْدَتَيْنِ حَتَّى نَقُولَ: قَدْ أَوْهَمَ. (د)', 'അനസ്(റ): തിരുമേനി(സ)യുടെ പിന്നിൽ പൂർണ്ണ രൂപത്തിൽ നിസ്കാരം നിർവ്വഹിച്ചതിനേക്കാൾ ഏറ്റവും ലഘുവായി ഞാൻ മറ്റൊരാളുടെ പിന്നിലും നിസ്കരിച്ചിട്ടില്ല. അത് പൂർണ്ണമാവുമായിരുന്നു. തിരുമേനി(സ) ''സമിഅല്ലാഹു ലിമൻ ഹമിദ'' എന്നു പറഞ്ഞ ശേഷം അവിടുന്ന് വിട്ടുകളഞ്ഞിരിക്കുന്നു എന്നു ഞങ്ങൾ പറയുമാറ് (ദീർഘമായി)നിന്നു. പിന്നെ തിരുമേനി(സ) തകബീർ ചൊല്ലുകയും സുജൂദു ചൊല്ലുകയും ചെയ്തു. തിരുമേനി(സ) ഏന്തോ വിട്ടുകളഞ്ഞിരിക്കുന്നു എന്ന് ഞങ്ങൾ പറയുമാറ് അവിടുന്ന് രണ്ട് സുജൂദുകൾക്കിടയിൽ ഇരിക്കാറുണ്ടായിരുന്നു. (ദ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 478, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=41 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 158, 'عَنِ الْبَرَاءِ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَرَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ: لَمْ يَحْنِ رَجُلٌ مِنَّا ظَهْرَهُ حَتَّى يَسْجُدَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَنَسْجُدَ. حَسَنٌ صَحِيحٌ. (ق,د,ت,ن)', 'ബറാഅ്(റ): ഞങ്ങൾ നബി(സ)ക്കു പിന്നിൽ നിസ്കരിക്കുകയാണെങ്കിൽ അവിടുന്ന് റുകൂഇൽ നിന്ന് തലയുയർത്തിയാൽ അവിടുന്ന് സുജൂദ് ചെയ്യുന്നതുവരെ ഞങ്ങളിലൊരാളും മുതുക് വളക്കുമായിരുന്നില്ല. (നബി സുജൂദിൽ പോയ) ശേഷം ഞങ്ങൾ സുജൂദ് ചെയ്യും. ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു. (ബു,മു,ദ,തു,ന)', 'الْبَرَاءِ', 'ബറാഅ്(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=42 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 159, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَا يَأْمَنُ الَّذِي يَرْفَعُ رَأْسَهُ فِي صَلَاتِهِ قَبْلَ الْإِمَامِ أَنْ يُحَوِّلَ اللهُ صُورَتَهُ فِي صُورَةِ حِمَارٍ". (م)', 'അബുഹുറൈറ(റ): റസൂൽ(സ) പറഞ്ഞു: "ഇമാമിനു മുമ്പായി നിസ്കാരത്തിൽ തല ഉയർത്തുന്ന ആളുകൾ അല്ലാഹു അവരെ കഴുതകളുടെ രൂപത്തിലാക്കുന്നതിൽ നിന്ന് നിർഭയരല്ല." (മു)', 'أَبِي هُرَيْرَةَ', 'അബുഹുറൈറ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=43 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 160, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ لَمْ يُشْخِصْ رَأْسَهُ وَلَمْ يُصَوِّبْهُ، وَلَكِنْ بَيْنَ ذَلِكَ. (م,د,جه)', 'ആഇശ(റ): നബി(സ) റുകൂഇൽ തല ഉയർത്തുകയോ താഴ്ത്തുകയോ ചെയ്തിട്ടില്ല. പക്ഷേ അത് രണ്ടിനുമിടയിലായിരുന്നു. (മു,ദ,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','جه']::text[], array['മു','ദ','ജ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 161, 'عَنْ أَبِي مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "لَا تُجْزِئُ صَلَاةٌ لَا يُقِيمُ الرَّجُلُ فِيهَا صُلْبَهُ فِي الرُّكُوعِ وَالسُّجُودِ". (ق,د,ت,ن,جه)', 'അബൂമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "റുകൂഇലും സുജൂദിലും നട്ടെല്ല് ക്രമീകരിക്കാത്തവന്റെ നിസ്കാരം മതിയായതാവുകയില്ല." (ബു,മു,ദ,തു,ന,ജ)', 'أَبِي مَسْعُودٍ', 'അബൂമസ്ഊദ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 479, 479, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 162, 'عَنْ عَلِيِّ بْنِ شَيْبَانَ رَضِيَ اللهُ عَنْهُ – وَكَانَ مِنَ الْوَفْدِ – قَالَ: خَرَجْنَا حَتَّى قَدِمْنَا عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَبَايَعْنَاهُ وَصَلَّيْنَا خَلْفَهُ، فَلَمَحَ بِمُؤْخِرِ عَيْنِهِ رَجُلًا لَا يُقِيمُ صَلَاتَهُ – يَعْنِي صُلْبَهُ – فِي الرُّكُوعِ وَالسُّجُودِ، فَلَمَّا قَضَى النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الصَّلَاةَ قَالَ: "يَا مَعْشَرَ الْمُسْلِمِينَ، لَا صَلَاةَ لِمَنْ لَا يُقِيمُ صُلْبَهُ فِي الرُّكُوعِ وَالسُّجُودِ". (جه)', 'അലിയ്യുബ്നു ശൈബാൻ(റ): അദ്ദേഹം ഒരു യാത്രാസംഘത്തിലായിരുന്നു, അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യുടെ അടുത്തെത്തി ബൈഅത്ത് ചെയ്തു. പിന്നെ നബി(സ)യുടെ പിന്നിൽ നിസ്കരിച്ചു. അപ്പോൾ റുകൂഇലും, സുജൂദിലും മുതുക് ശരിപ്പെടുത്താത്ത ഒരാളെ നബി(സ)യുടെ കൺകോണിൽ പതിഞ്ഞു. നിസ്കാരശേഷം നബി(സ) പറഞ്ഞു: "മുസ്ലിം സമൂഹമേ! റുകൂഇലും സുജൂദിലും മുതുക് ശരിപ്പെടുത്താത്തവന് നിസ്കാരമില്ല." (ജ)', 'عَلِيِّ بْنِ شَيْبَانَ', 'അലിയ്യുബ്നു ശൈബാൻ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 479, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 163, 'عَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَكَانَ إِذَا رَكَعَ سَوَّى ظَهْرَهُ، حَتَّى لَوْ صُبَّ عَلَيْهِ الْمَاءُ لَاسْتَقَرَّ. [ز:إسناده ضعيف] (جه)', 'വാബിസതുബ്നു മഅ്ബദ്(റ): നബി(സ) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. അവിടുന്ന് റുകൂഇൽ പോകുമ്പോൾ മുതുകിൽ വെള്ളം ഒഴിച്ചാൽ അത് ഒഴുകി പോകാത്ത വിധത്തിൽ മുതുക് ശരിപ്പെടുത്തുമായിരുന്നു. [ഇതിന്റെ പരമ്പര ദുർബ്ബലമാണെന്ന് ഇബ്നുമാജ പറയുന്നു] (ജ)', 'وَابِصَةَ بْنِ مَعْبَدٍ', 'വാബിസതുബ്നു മഅ്ബദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:إسناده ضعيف', null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=44 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 164, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَانِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنِ الْقَسِّيِّ وَالْحَرِيرِ وَخَاتَمِ الذَّهَبِ، وَأَنْ أَقْرَأَ وَأَنَا رَاكِعٌ. وَقَالَ مَرَّةً أُخْرَى: وَأَنْ أَقْرَأَ رَاكِعًا. (ق,د,ت,ن)', 'അലി(റ): ഖസിയ്യ്, ഹരീർ (പട്ടിന്റെ ഇനങ്ങൾ), സ്വർണ്ണ മോതിരം, റുകൂഇലെ ഖുർആൻ പാരായണം എന്നിവയിൽ നിന്ന് നബി(സ) എന്നെ വിലക്കി. (ബു,മു,ദ,തു,ന)', 'عَلِيٍّ', 'അലി(റ)', null, null, array['ق','د','ت','ن']::text[], array['ബു','മു','ദ','തു','ന']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 165, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَانِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – وَلَا أَقُولُ: نَهَاكُمْ – عَنْ تَخَتُّمِ الذَّهَبِ، وَعَنْ لُبْسِ الْقَسِّيِّ، وَعَنْ لُبْسِ الْمُفَدَّمِ وَالْمُعَصْفَرِ، وَعَنِ الْقِرَاءَةِ فِي الرُّكُوعِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): സ്വർണ്ണം കൊണ്ട് മോതിരം ഉണ്ടാക്കുന്നതും, പട്ടുവസ്ത്രം ധരിക്കുന്നതും, മഞ്ഞ ഛായവും ചുവപ്പ് ഛായവും മുക്കിയ വസ്ത്രം ധരിക്കുന്നതും, റുകൂഇൽ ഖുർആൻ പാരായണം ചെയ്യുന്നതും നബി(സ) എന്നോട് നിരോധിച്ചു. (എന്നാൽ) ഇക്കാര്യങ്ങൾ നിങ്ങളോട് നിരോധിച്ചു എന്നു ഞാൻ പറയുന്നില്ല. (ന)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 480, 480, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=45 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 166, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَمَّا نَزَلَتْ :{فَسَبِّحْ بِاسْمِ رَبِّكَ الْعَظِيمِ}. [الحاقة: ٥٢] قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "اجْعَلُوهَا فِي رُكُوعِكُمْ". فَلَمَّا نَزَلَتْ: {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} قَالَ: "اجْعَلُوهَا فِي سُجُودِكُمْ". وَفِي رِوَايَةٍ زَادَ: فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ قَالَ: "سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ" ثَلَاثًا، وَإِذَا سَجَدَ قَالَ: "سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ" ثَلَاثًا. (د,جه)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): അദ്ദേഹം പറഞ്ഞു: "ഫസബ്ബിഹ് ബിസ്മി റബ്ബികൽ അളീം"(മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമത്തെ വാഴ്ത്തുക) (അൽഹാഖ്: 52) എന്ന സൂക്തമിറങ്ങിയപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് നിങ്ങൾ റുകൂഇൽ പറയുക." "സബ്ബിഹ് ഇസ്മറബ്ബികൽ അഅ്ലാ" എന്ന ആയത്ത് ഇറങ്ങിയപ്പോൾ നബി(സ) പറഞ്ഞു: "അത് നിങ്ങൾ സുജൂദിൽ ചൊല്ലുക." മറ്റൊരു റിപ്പോർട്ടിൽ ഇപ്രകാരം കൂടി വന്നിട്ടുണ്ട്: നബി(സ) റുകൂഇൽ "സുബ്ഹാന റബ്ബിയൽ അളീം വബിഹംദിഹി" (മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം പ്രകീർത്തിക്കുന്നതോടൊപ്പം അവനെ സ്തുതിക്കുകയും ചെയ്യുന്നു) എന്ന് മൂന്നുപ്രാവശ്യവും സുജൂദിൽ "സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ വബിഹംദിഹി" (അത്യുന്നതനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം പ്രകീർത്തിക്കുന്നതോടൊപ്പം അവനെ സ്തുതിക്കുകയും ചെയ്യുന്നു) എന്ന് മൂന്നുപ്രാവശ്യവും പറയാറുണ്ടായിരുന്നു. (ദ,ജ)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], 'الحاقة: ٥٢', null, 480, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=46 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=166), 1, 'وَفِي رِوَايَةٍ زَادَ: فَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَكَعَ قَالَ: "سُبْحَانَ رَبِّيَ الْعَظِيمِ وَبِحَمْدِهِ" ثَلَاثًا، وَإِذَا سَجَدَ قَالَ: "سُبْحَانَ رَبِّيَ الْأَعْلَى وَبِحَمْدِهِ" ثَلَاثًا. (د,جه)', 'മറ്റൊരു നിവേദനിൽ ഇപ്രകാരം കൂടി വന്നിട്ടുണ്ട്: നബി(സ) റുകൂഇൽ "സുബ്ഹാന റബ്ബിയൽ അളീം വബിഹംദിഹി" (മഹാനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം പ്രകീർത്തിക്കുന്നതോടൊപ്പം അവനെ സ്തുതിക്കുകയും ചെയ്യുന്നു) എന്ന് മൂന്നുപ്രാവശ്യവും സുജൂദിൽ "സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ വബിഹംദിഹി" (അത്യുന്നതനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം പ്രകീർത്തിക്കുന്നതോടൊപ്പം അവനെ സ്തുതിക്കുകയും ചെയ്യുന്നു) എന്ന് മൂന്നുപ്രാവശ്യവും പറയാറുണ്ടായിരുന്നു. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 167, 'عَنِ ابْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إِذَا رَكَعَ أَحَدُكُمْ، فَقَالَ فِي رُكُوعِهِ: سُبْحَانَ رَبِّيَ الْعَظِيمِ – ثَلَاثَ مَرَّاتٍ – تَمَّ رُكُوعُهُ، وَإِذَا سَجَدَ فَقَالَ فِي سُجُودِهِ: سُبْحَانَ رَبِّيَ الْأَعْلَى – ثَلَاثَ مَرَّاتٍ – فَقَدْ تَمَّ سُجُودُهُ، وَذَلِكَ أَدْنَاهُ". (ت,جه)', 'ഇബ്നുമസ്ഊദ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും റുകൂഅ് ചെയ്താൽ ''സുബ്ഹാന റബ്ബിയൽ അളീം'' എന്ന് മൂന്നുപ്രാവശ്യം പറയുക അപ്പോൾ റുകൂഅ് പൂർണ്ണമായി. മൂന്ന്പ്രാവശ്യം ''സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ'' എന്ന് സുജൂദിൽ പറയുക, അപ്പോൾ സുജൂദ് പൂർണ്ണമായി. (പക്ഷെ) അത് ഏറ്റവും ചുരുങ്ങിയതാണ്." (തു,ജ)', 'ابْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 168, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَكَعَ قَالَ: "اللَّهُمَّ لَكَ رَكَعْتُ، وَلَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، خَشَعَ لَكَ سَمْعِي وَبَصَرِي وَعِظَامِي وَمُخِّي وَعَصَبِي". (ن)', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ): നബി(സ) റുകൂഇൽ "അല്ലാഹുവേ, നിനക്ക് വേണ്ടി ഞാൻ റുകൂഅ് ചെയ്തിരിക്കുന്നു, നിനക്ക് ഞാൻ വിധേയനായിരിക്കുന്നു, നിന്നിൽ ഞാൻ വിശ്വസിച്ചിരിക്കുന്നു, എന്റെ കേൾവിയും കാഴ്ചയും എന്റെ എല്ലുകളും മജ്ജയും നാഡികളും നിനക്ക് കീഴ്പ്പെട്ടിരിക്കുന്നു." എന്നു പറയാറുണ്ടായിരുന്നു. (ന)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലിയ്യുബ്നു അബീത്വാലിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 169, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: كَانَ إِذَا رَكَعَ قَالَ: "اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، وَعَلَيْكَ تَوَكَّلْتُ، أَنْتَ رَبِّي، خَشَعَ سَمْعِي وَبَصَرِي وَدَمِي وَلَحْمِي وَعَظْمِي وَعَصَبِي لِلَّهِ رَبِّ الْعَالَمِينَ". (ن)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): നബി(സ) റുകൂഇൽ ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ഞാൻ നിനക്കു വേണ്ടി റുകൂഅ് ചെയ്തിരിക്കുന്നു. നിന്നിൽ വിശ്വസിച്ചിരിക്കുന്നു. നിനക്ക് വിധേയമായിരിക്കുന്നു. നിന്നിൽ ഭരമേൽപിച്ചിരിക്കുന്നു, നീയാണ് എന്റെ നാഥൻ, എന്റെ കേൾവിയും, കാഴ്ചയും, രക്തവും, മാംസവും, എല്ലുകളും, നാഡികളും ലോകരക്ഷിതാവായ അല്ലാഹുവിന് കീഴ്പ്പെട്ടിരിക്കുന്നു." (ന)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 170, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُكْثِرُ أَنْ يَقُولَ فِي رُكُوعِهِ وَسُجُودِهِ: "سُبْحَانَكَ اللَّهُمَّ رَبَّنَا وَبِحَمْدِكَ، اللَّهُمَّ اغْفِرْ لِي" يَتَأَوَّلُ الْقُرْآنَ. (ق,د,ن,جه)', 'ആഇശ(റ): നബി(സ) "സുബ്ഹാനകല്ലാഹുമ്മ റബ്ബനാ വബിഹംദിക, അല്ലാഹുമ്മഗ്ഫിർലി" (അല്ലാഹുവേ നിന്റെ നാമം പ്രകീർത്തിക്കുന്നതോടൊപ്പം നിന്നെ സ്തുതിക്കുകയും ചെയ്യുന്നു. നീ എനിക്ക് പൊറുത്തു തരേണമേ!) എന്ന് റുകൂഇലും സുജൂദിലും ധാരാളമായി ചൊല്ലിയിരുന്നു. ഖുർആനിന്റെ വ്യാഖ്യാനമായിട്ടായിരുന്നു ഇത് പറഞ്ഞിരുന്നത്. (ബു,മു,ദ,ന,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 481, 481, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 171, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِهِ: "اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ، دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، عَلَانِيَتَهُ وَسِرَّهُ". (م,د)', 'അബൂഹുറൈറ(റ): നബി(സ) തന്റെ സുജൂദിൽ ഇങ്ങനെ പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവേ, ചെറുതും വലുതും ആദ്യത്തേതും അവസാനത്തേതും രഹസ്യമായതും പരസ്യമായതുമായ എന്റെ സകല പാപങ്ങളും എനിക്ക് പൊറുത്തു തരേണമേ!" (മു,ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 481, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 172, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَقَدْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَلَمَسْتُ الْمَسْجِدَ فَإِذَا هُوَ سَاجِدٌ وَقَدَمَاهُ مَنْصُوبَتَانِ، وَهُوَ يَقُولُ: "أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَأَعُوذُ بِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لَا أُحْصِي ثَنَاءً عَلَيْكَ، أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ". (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): ആഇശ(റ) പറഞ്ഞു: നബി(സ) ഒരു രാത്രിയിൽ എന്റെ അടുത്തു നിന്നും പോയി, ഞാൻ പള്ളിയിൽ അന്വേഷിച്ചു. അപ്പോൾ നബി(സ) തന്റെ കാൽപാദങ്ങൾ നാട്ടിവെച്ച് സുജൂദ് ചെയ്യുന്നതു കണ്ടു. നബി(സ) ഇപ്രകാരം പറയുന്നുണ്ടായിരുന്നു: (അല്ലാഹുവേ!) "നിന്റെ ദേഷ്യത്തിൽ നിന്ന് തൃപ്തി മുഖേന കാവൽ തേടുന്നു. നിന്റെ ശിക്ഷയിൽ നിന്ന് മാപ്പു കൊണ്ട് കാവൽ തേടുന്നു. നിന്നിൽ നിന്ന് നിന്നോട് കാവൽ തേടുന്നു. നിനക്കുള്ള സ്തുതി ഞാൻ പരിമിതപ്പെടുത്തുന്നില്ല, നിന്നെ നീ എപ്രകാരമാണോ സ്വയം സ്തുതിച്ചത് അതു പ്രകാരം തന്നെയാണ് നീ." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 173, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ يَقُولُ فِي رُكُوعِهِ: "سُبْحَانَ رَبِّيَ الْعَظِيمِ". وَفِي سُجُودِهِ: "سُبْحَانَ رَبِّيَ الْأَعْلَى". وَمَا مَرَّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ عِنْدَهَا فَسَأَلَ، وَلَا بِآيَةِ عَذَابٍ إِلَّا وَقَفَ عِنْدَهَا فَتَعَوَّذَ. (م,د,ت,ن,جه)', 'ഹുദൈഫ(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു: നബി(സ) റുകൂഇൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "സുബ്ഹാന റബ്ബിയൽ അളീം," (മഹാനായ എന്റെ രക്ഷിതാവ് എത്ര പരിശുദ്ധൻ) സുജൂദിൽ: "സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ"(ഉന്നതനായ എന്റെ രക്ഷിതാവ് എത്ര പരിശുദ്ധൻ) എന്നും. റഹ്മത്തിന്റെ ഒരായത്തും അവിടെ നിർത്തി റഹ്മത്ത് ചോദിച്ചിട്ടല്ലാതെ നബി(സ) പാരായണം ചെയ്തില്ല. ശിക്ഷയുടെ ഒരായത്തും അതിൽ നിന്നും ശരണം തേടിയിട്ടല്ലാതെ നബി(സ) ഓതിയില്ല. (മു,ദ,തു,ന,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 174, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ: "سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ". (م,د,ن)', 'ആഇശ(റ): നബി(സ) തന്റെ റുകൂഇലും സുജൂദിലും "സുബ്ബൂഹ്, ഖൂദ്ദൂസ്, റബ്ബുൽ മലാഇകത്തി വറൂഹ്" (സദാ വാഴ്ത്തപ്പെടുന്നവൻ, പരമപരിശുദ്ധൻ, മലക്കുകളുടെയും റൂഹിന്റെയും സക്ഷിതാവ്) എന്ന് പറയാറുണ്ടായിരുന്നു. (മു,ദ,ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 175, 'عَنْ عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: قُمْتُ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَقَامَ فَقَرَأَ سُورَةَ الْبَقَرَةِ: لَا يَمُرُّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ فَسَأَلَ، وَلَا يَمُرُّ بِآيَةِ عَذَابٍ إِلَّا وَقَفَ فَتَعَوَّذَ، قَالَ: ثُمَّ رَكَعَ بِقَدْرِ قِيَامِهِ، يَقُولُ فِي رُكُوعِهِ: "سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ". ثُمَّ سَجَدَ بِقَدْرِ قِيَامِهِ، ثُمَّ قَالَ فِي سُجُودِهِ مِثْلَ ذَلِكَ، ثُمَّ قَامَ فَقَرَأَ بِآلِ عِمْرَانَ، ثُمَّ قَرَأَ سُورَةً سُورَةً. (د,ت,ن)', 'ഔഫ്ബ്നു മാലിക്(റ): ഞാൻ നബി(സ)യോടൊപ്പം ഒരു രാത്രി നിസ്കരിച്ചു. അപ്പോൾ നബി(സ) എഴുന്നേറ്റു നിന്ന് സൂറത്തുൽ ബഖറ ഓതി. കാരുണ്യത്തിന്റെ ഒരായത്തും കടന്ന് പോയിട്ടില്ല. അവിടെ നിർത്തി അതിൽ നിന്നും ചോദിച്ചിട്ടല്ലാതെ. ശിക്ഷയുടെ ഒരായത്തും ഓതിയിട്ടില്ല, അവിടെ നിർത്തി അതിൽ നിന്ന് ശരണം തേടിയിട്ടല്ലാതെ. പിന്നെ നിർത്തത്തിന്റത്ര സമയം തന്നെ റുകൂഅ് ചെയ്തു. നബി(സ) പറഞ്ഞു: "എല്ലാ മഹത്വങ്ങളും ഔന്നത്യങ്ങളും ആധിപത്യങ്ങളും ശക്തികളും ഉടമപ്പെടുത്തിയവൻ പരിശുദ്ധൻ." പിന്നെ നിർത്തത്തിന്റെ അത്ര തന്നെ സമയം സുജൂദ് ചെയ്തു, സുജൂദിലും അപ്രകാരം പറഞ്ഞു. പിന്നെ എഴുന്നേറ്റു നിന്ന് ആലുഇംറാൻ ഓതി. പിന്നെ സൂറത്തുകൾ ഓരോന്നായി ഓതി. (ദ,തു,ന)', 'عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ', 'ഔഫ്ബ്നു മാലിക്(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 482, 482, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 176, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ، فَكَانَ يَقُولُ: "اللهُ أَكْبَرُ، ثَلَاثًا، ذُو الْمَلَكُوتِ وَالْجَبَرُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ". ثُمَّ اسْتَفْتَحَ فَقَرَأَ الْبَقَرَةَ، ثُمَّ رَكَعَ فَكَانَ رُكُوعُهُ نَحْوًا مِنْ قِيَامِهِ، وَكَانَ يَقُولُ فِي رُكُوعِهِ: "سُبْحَانَ رَبِّيَ الْعَظِيمِ، سُبْحَانَ رَبِّيَ الْعَظِيمِ". ثُمَّ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَكَانَ قِيَامُهُ نَحْوًا مِنْ رُكُوعِهِ، يَقُولُ: "لِرَبِّيَ الْحَمْدُ". ثُمَّ سَجَدَ فَكَانَ سُجُودُهُ نَحْوًا مِنْ قِيَامِهِ، فَكَانَ يَقُولُ فِي سُجُودِهِ: "سُبْحَانَ رَبِّيَ الْأَعْلَى". ثُمَّ رَفَعَ رَأْسَهُ مِنَ السُّجُودِ، وَكَانَ يَقْعُدُ فِيمَا بَيْنَ السَّجْدَتَيْنِ نَحْوًا مِنْ سُجُودِهِ، وَكَانَ يَقُولُ: "رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي". فَصَلَّى أَرْبَعَ رَكَعَاتٍ، فَقَرَأَ فِيهِنَّ الْبَقَرَةَ، وَآلَ عِمْرَانَ، وَالنِّسَاءَ، وَالْمَائِدَةَ، أَوِ الْأَنْعَامَ. (د,ت,ن)', 'ഹുദൈഫ(റ): നബി(സ) രാത്രി നിസ്കരിക്കുന്നത് അദ്ദേഹം കണ്ടു. നബി(സ) "അല്ലാഹു അക്ബർ" എന്ന് മൂന്നുപ്രാവശ്യം പറഞ്ഞു. "എല്ലാ മഹത്വങ്ങളും, ഔന്നത്യങ്ങളും, ആധിപത്യങ്ങളും, ശക്തികളും ഉള്ളവൻ." പിന്നെ പ്രാരംഭ പ്രാർത്ഥനക്കു ശേഷം "അൽബഖറഃ" പാരായണം ചെയ്തു. പിന്നെ റുകൂഅ് ചെയ്തു. ഏതാണ്ട് നിർത്തത്തിന്റെ അത്രയും. റുകൂഇൽ "മഹോന്നതനായ നാഥൻ പരിശുദ്ധൻ" എന്ന് രണ്ട് പ്രാവശ്യം പറഞ്ഞു. പിന്നെ റുകൂഇൽ നിന്നുയർന്നു, നിർത്തം എതാണ്ട് റുകൂഇന്റെ അത്രയും സമയം ദീർഘിച്ചു. അതിൽ "എന്റെ റബ്ബിന്ന് സ്തുതി" എന്ന് പറഞ്ഞു. പിന്നെ സുജൂദ് ചെയ്തു. ഏതാണ്ട് നിർത്തത്തിന്റെ അത്രയും സമയം, സുജൂദിൽ ഇപ്രകാരം പറഞ്ഞു: "പരമോന്നതനായ നാഥൻ പരിശുദ്ധൻ!" പിന്നെ സുജൂദിൽ നിന്നും തലയുയർത്തി. സുജൂദുകൾക്കിടയിൽ ഏതാണ്ട് സുജൂദിന്റെ അത്ര സമയം ഇരുന്നു. എന്നിട്ട് പറഞ്ഞു: "എന്റെ നാഥാ! എനിക്ക് പൊറുത്തുതരേണമേ! എന്റെ നാഥാ എനിക്ക് പൊറുത്ത് തരേണമേ!". അങ്ങനെ നാല് റക്അത്ത് നിസ്കരിച്ചു. അതിൽ സൂറത്തുൽ ബഖറ, ആലുഇംറാൻ, അന്നിസാഅ്, മാഇദ എന്നിവ പാരായണം ചെയ്തു. (ദ,തു,ന)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=47 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 177, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَقْرَبُ مَا يَكُونُ الْعَبْدُ مِنْ رَبِّهِ وَهُوَ سَاجِدٌ، فَأَكْثِرُوا الدُّعَاءَ". (م,د,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ഒരടിമ തന്റെ നാഥനുമായി ഏറ്റവും അടുക്കുന്നത് അവൻ സുജൂദിലായിരിക്കുമ്പോഴാണ്. അതിനാൽ നിങ്ങൾ പ്രാർത്ഥന വർദ്ധിപ്പിക്കുക." (മു,ദ,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 178, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَشَفَ السِّتَارَةَ وَالنَّاسُ صُفُوفٌ خَلْفَ أَبِي بَكْرٍ، فَقَالَ: "يَا أَيُّهَا النَّاسُ، إِنَّهُ لَمْ يَبْقَ مِنْ مُبَشِّرَاتِ النُّبُوَّةِ إِلَّا الرُّؤْيَا الصَّالِحَةُ، يَرَاهَا الْمُسْلِمُ أَوْ تُرَى لَهُ، وَإِنِّي نُهِيتُ أَنْ أَقْرَأَ رَاكِعًا أَوْ سَاجِدًا، فَأَمَّا الرُّكُوعُ فَعَظِّمُوا الرَّبَّ فِيهِ، وَأَمَّا السُّجُودُ فَاجْتَهِدُوا فِي الدُّعَاءِ، فَقَمِنٌ أَنْ يُسْتَجَابَ لَكُمْ". (م,د,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): ജനങ്ങൾ അബൂബക്കർ(റ)വിനു പിറകിൽ അണിയായി നിൽക്കുമ്പോൾ റസൂൽ(സ) (തന്റെ വീടിന്റെ) വിരി നീക്കുകയും ഇങ്ങനെ പറയുകയും ചെയ്തു: "ജനങ്ങളെ, പ്രവാചകത്വത്തിന്റെ സുവിശേഷങ്ങളിൽ നിന്നും അവശേഷിക്കുന്നത് ഒരു മുസ്ലിം കാണുന്ന, അല്ലെങ്കിൽ അവന്ന് കാണിക്കപ്പെടുന്ന നല്ല സ്വപ്നങ്ങൾ മാത്രമാണ്. അറിയുക, റുകൂഇലും സുജൂദിലും ഖുർആൻ പാരായണം ചെയ്യുന്നത് എനിക്ക് വിലക്കപ്പെട്ടിരിക്കുന്നു. റുകൂഇൽ റബ്ബിനെ മഹത്വപ്പെടുത്തുക, സുജൂദിൽ പ്രാർത്ഥിക്കുന്നതിൽ നിങ്ങൾ കഠിന പ്രയത്നം നടത്തുകയും ചെയ്യുക. അത് നിങ്ങൾക്ക് ഉത്തരം നൽകപ്പെടാൻ ഏറ്റവും അർഹമാണ്." (മു,ദ,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 483, 483, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=48 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 179, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَكْتَتَانِ حفظْتُهمَا عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَأَنْكَرَ ذَلِكَ عِمْرَانُ بْنُ حُصَيْنٍ رَضِيَ اللهُ عَنْهُمَا وَقَالَ: حَفِظْنَا سَكْتَةً. فَكَتَبْنَا إِلَى أُبَيِّ بْنِ كَعْبٍ رَضِيَ اللهُ عَنْهُ بِالْمَدِينَةِ، فَكَتَبَ أُبَيٌّ: أَنْ حفظَ سمُرَةُ. فَقِيلَ لِقَتَادَةَ: مَا هَاتَانِ السَّكْتَتَانِ؟ قَالَ: إِذَا دَخَلَ فِي صَلَاتِه، وَإِذَا فَرَغَ مِنَ الْقِرَاءَةِ. ثُمَّ قَالَ بَعْدَ ذَلِكَ :وَإِذَا قَرَأَ: {وَلَا الضَّالِّينَ}. قَالَ: وَكَانَ يُعْجِبُهُ إِذَا فَرَغَ مِنَ الْقِرَاءَةِ أَنْ يَسْكُتَ حَتَّى يَتَرَادَّ إِلَيْهِ نَفَسُهُ. حَسَنٌ. (د,ت,جه)', 'സമുറ(റ): അദ്ദേഹം പറഞ്ഞു: ഞാൻ നബി(സ)യിൽ നിന്ന് രണ്ട് നിശബ്ദ സമയങ്ങൾ മനസ്സിലാക്കി, ഇംറാനുബ്നു ഹുസൈൻ(റ) അവയെ നിഷേധിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ ഒരു സമയമാണ് മനസ്സിലാക്കിയത്. അങ്ങിനെ ഞങ്ങൾ മദീനയിലുള്ള ഉബയ്യുബ്നു കഅബ്(റ)വിലേക്ക് എഴുതി. സമുറ(റ) അത് മനസ്സിലാക്കിയിരിക്കുന്നു എന്ന് ഉബയ്യ്(റ) മറുപടി എഴുതി. അപ്പോൾ ഖതാദയോട് ചോദിക്കപ്പെട്ടു. ആ രണ്ട് നിശ്ശബ്ദ സമയങ്ങൾ ഏതൊക്കെയാണ്? ഖതാദ പറഞ്ഞു: നിസ്കാരത്തിൽ പ്രവേശിച്ച ശേഷവും പാരായണം കഴിഞ്ഞ ശേഷവും. പിന്നെ അദ്ദേഹം പറഞ്ഞു: ഫാതിഹയിൽ "വലള്ളാല്ലീൻ" എന്ന് ചൊല്ലിക്കഴിഞ്ഞാൽ (മൗനം പാലിക്കാറുണ്ട്). ശേഷം അദ്ദേഹം പറഞ്ഞു: പാരായണത്തിൽ നിന്ന് വിരമിച്ചശേഷം ശ്വാസം വീണ്ടെടുക്കും വരെ മിണ്ടാതിരിക്കുന്നത് നബി(സ)ക്ക് സന്തോഷകരമായിരുന്നു. (ഹദീസ് ഹസനാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു,ജ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 180, 'عَنِ الْحَسَنِ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ سَمُرَةُ رَضِيَ اللهُ عَنْهُ: حفظْتُ سَكْتَتَيْنِ فِي الصَّلَاةِ: سَكْتَةً قَبْلَ الْقِرَاءَةِ، وَسَكْتَةً عِنْدَ الرُّكُوعِ، فَأَنْكَرَ ذَلِكَ عَلَيْهِ عِمْرَانُ بْنُ الْحُصَيْنِ، فَكَتَبُوا إِلَى الْمَدِينَةِ إِلَى أُبَيِّ بْنِ كَعْبٍ، فَصَدَّقَ سَمُرَةَ. (د,جه)', 'ഹസൻ(റ): സമുറ(റ) പറഞ്ഞു: ഞാൻ രണ്ട് മൗനങ്ങൾ റസൂലി(സ)ൽ നിന്ന് പഠിച്ചു. ഖിറാഅത്തിനു മുമ്പ് ഒരു മൗനം, റുകൂഇന്റെ അവസരത്തിൽ ഒരു മൗനം. എന്നാൽ ഇംറാനുബ്നു ഹുസൈൻ(റ) അതിനെ നിഷേധിച്ചു. അങ്ങനെ അതിനെക്കുറിച്ച് മദീനയിൽ ഉബയ്യിബ്നു കഅ്ബിന്റെ അടുത്തേക്ക് കത്തയച്ചു. അദ്ദേഹം സമുറയുടെ അഭിപ്രായം സ്ഥിരീകരിച്ചു. (ദ,ജ)', 'الْحَسَنِ', 'ഹസൻ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 484, 484, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=49 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 181, 'عَنْ أبي سعيد الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: "رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السَّمَاوَاتِ وَالْأَرْضِ وَمَا بَيْنَهُمَا، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ – وَكُلُّنَا لَكَ عَبْدٌ – لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ". (م,د,ت,ن,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) റുകൂഇൽ നിന്ന് ഉയർന്നാൽ ഇപ്രകാരം പറഞ്ഞിരുന്നു: "ഞങ്ങളുടെ നാഥാ, ആകാശ ഭൂമികളും, അവക്കിടയിലുള്ളവയും, അതിനുശേഷം നീ ഉദ്ദേശിക്കുന്നതൊക്കെയും നിറയെ നിനക്ക് സ്തുതി. സ്തുതിയുടെയും ഔന്നത്യത്തിന്റെയും ഉടമയായവനേ, അടിമ പറയുന്നതിൽ ഏറ്റവും യഥാർത്ഥമായത് ഇതാണ്: ഞങ്ങളെല്ലാം നിന്റെ അടിമകളാണ്. നീ നൽകിയതിനെ തടയുന്നവനില്ല. നീ തടഞ്ഞതിനെ നൽകുന്നവനുമില്ല. ഐശ്വര്യവാന് തന്റെ ഐശ്വര്യം നിന്നിൽ നിന്നും ഉപകാരം നേടിക്കൊടുക്കില്ല.⁵" (മു,ദ,തു,ന,ജ)', 'أبي سعيد الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 484, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 182, 'عَنْ أنس رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَرْفَعُ يَدَيْهِ إِذَا دَخَلَ فِي الصَّلَاةِ، وَإِذَا رَكَعَ. (جه)', 'അനസ്(റ): നബി(സ) നിസ്കാരത്തിൽ പ്രവേശിക്കുമ്പോഴും റുകൂഇലേക്ക് പോകുമ്പോഴും കൈകൾ ഉയർത്തിയിരുന്നു. (ജ)', 'أنس', 'അനസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 183, 'عَنْ أبي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إذَا قَالَ الْإِمَامُ: سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ، فَإِنَّهُ مَنْ وَافَقَ قَوْلُهُ قَوْلَ الْمَلَائِكَةِ غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ". (د,جه)', 'അബൂസഈദിൽ ഖുദ്രി(റ): നബി(സ) പറയുന്നത് അദ്ദേഹം കേട്ടു: "ഇമാം സമിഅല്ലാഹു ലിമൻ ഹമിദ (അല്ലാഹുവിനെ സ്തുതിച്ചവന്റെ വിളി അല്ലാഹു കേൾക്കട്ടെ) എന്നു പറഞ്ഞാൽ നിങ്ങൾ ''അല്ലാഹുമ്മ റബ്ബനാലകൽ ഹംദ്'' (ഞങ്ങളുടെ രക്ഷിതാവായ അല്ലാഹുവേ നിനക്ക് സ്തുതി) എന്ന് പറയുക. കാരണം ഓരാളുടെയും മലക്കുകളുടെയും വാക്ക് യോജിച്ചു വന്നാൽ അവന് മുൻ കഴിഞ്ഞ പാപങ്ങൾ പൊറുക്കപ്പെടും." (ദ,ജ)', 'أبي هُرَيْرَةَ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 184, 'عَنِ ابْنِ أَبِي أَوْفَى رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ، اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ". (م,د,ن,جه)', 'ഇബ്നുഅബീ ഔഫ(റ): നബി(സ) റുകൂഇൽ നിന്ന് തല ഉയർത്തിയാൽ "സമിഅല്ലാഹു ലിമൻ ഹമിദ എന്നും അല്ലാഹുവേ, ആകാശവും, ഭൂമിയും നീ ഉദ്ദേശിച്ച മറ്റു ഏത് വസ്തുവും നിറയെ നിനക്ക് സ്തുതി എന്നു പറയും." (മു,ദ,ന,ജ)', 'ابْنِ أَبِي أَوْفَى', 'ഇബ്നുഅബീ ഔഫ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 485, 485, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 185, 'عَنْ أبي جُحَيْفَةَ رَضِيَ اللهُ عَنْهُ قَالَ: ذُكِرَتِ الْجُدُودُ عِنْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي الصَّلَاةِ، فَقَالَ رَجُلٌ: جَدُّ فُلَان فِي الْخَيْلِ. وَقَالَ آخَرُ: جَدُّ فُلَان فِي الْإِبِلِ. وَقَالَ آخَرُ: جَدُّ فُلَان فِي الْغَنَمِ. وَقَالَ آخَرُ: جَدُّ فُلَان فِي الرَّقِيقِ. فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاتَهُ، وَرَفَعَ رَأْسَهُ مِنْ آخِرِ الرَّكْعَةِ، قَالَ: "اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ، مِلْءَ السَّمَوَاتِ وَمِلْءَ الْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ. اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ". وَطَوَّلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَوْتَهُ بِ"الْجَدِّ" لِيَعْلَمُوا أَنَّهُ لَيْسَ كَمَا يَقُولُونَ. [ز: في إسناده مجهول] (جه)', 'അബൂജുഹൈഫ(റ): നബി(സ) നിസ്കാരത്തിലായിരിക്കെ നബി(സ)ക്കരികിൽ ഭാഗ്യങ്ങളെക്കുറിച്ച് പറഞ്ഞു. ഒരാൾ പറഞ്ഞു: കുതിരയാൽ ഇന്ന വ്യക്തി സൗഭാഗ്യവാനായി. ഒട്ടകത്താൽ ഇന്ന വ്യക്തി സൗഭാഗ്യവാനായെന്നും മറ്റൊരാൾ പറഞ്ഞു: ആടിനാൽ ഇന്ന വ്യക്തി സൗഭാഗ്യവാനായെന്ന് മൂന്നാമതൊരാൾ പറഞ്ഞു. മറ്റൊരാൾ പറഞ്ഞു: അടിമയുള്ളതിനാൽ ഇന്ന വ്യക്തി സൗഭാഗ്യവാനായി. അങ്ങനെ റസൂൽ(സ) തന്റെ നമസ്കാരം നിർവ്വഹിക്കുകയും ചെയ്തപ്പോൾ ഇപ്രകാരം പറഞ്ഞു: "ഞങ്ങളുടെ രക്ഷിതാവായ അള്ളാഹുവേ നിനക്കു ആകാശവും, ഭൂമിയും, അവയ്ക്കിടയിലുള്ളതും നിറയെ സ്തുതി, അല്ലാഹുവേ നീ നൽകിയതിനെ തടഞ്ഞു വെക്കുന്നവനില്ല, നീ തടഞ്ഞു വെച്ചതിനെ നൽകുന്നവനും ഇല്ല. സൗഭാഗ്യമുള്ളവന് തന്റെ സൗഭാഗ്യം നിന്റെ അടുക്കൽ നിന്നും ഉപകാരം നേടിക്കൊടുക്കില്ല." റസൂൽ(സ) ഇങ്ങനെ പ്രാർത്ഥിച്ചപ്പോൾ ''ജദ്ദ്'' (സൗഭാഗ്യം) എന്ന വാക്ക് ശബ്ദം നീട്ടിക്കൊണ്ടാണ് പറഞ്ഞത്. അവർ പറയുന്നതു പോലെയല്ല കാര്യം (സൗഭാഗ്യം ഉണ്ടാവുക) എന്ന് അവർ മനസ്സിലാക്കട്ടെ എന്നുദ്ദേശിച്ചാണ് തിരുമേനി(സ) ഇപ്രകാരം ചെയ്തത്. (ഇതിന്റെ പരമ്പരയിൽ അജ്ഞാതനായ ഒരു വ്യക്തിയുണ്ട്). (ജ)', 'أبي جُحَيْفَةَ', 'അബൂജുഹൈഫ(റ)', '⁵. ഒരാൾക്ക് തന്റെ സൽപ്രവർത്തിയും അല്ലാഹുവിന്റെ കടാക്ഷവും കാരുണ്യവും മൂലം മാത്രമേ പരലേക മേക്ഷം നേടാനാവുകയുള്ളു. അവന്റെ സമ്പൽ സമൃദ്ധിയോ മറ്റോ അല്ലാഹുവിന്റെ അടുത്ത് ഉപകരിക്കുകയില്ല.', null, array['جه']::text[], array['ജ']::text[], 'ز: في إسناده مجهول', null, 485, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 186, 'عَنْ أَبِي مُوسَى رَضِيَ اللهُ عَنْهُ قَالَ: إِنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ خَطَبَنَا وَبَيَّنَ لَنَا سُنَّتَنَا وَعَلَّمَنَا صَلَاتَنَا، فَقَالَ: "إِذَا صَلَّيْتُمْ فَأَقِيمُوا صُفُوفَكُمْ، ثُمَّ لِيَؤُمَّكُمْ أَحَدُكُمْ، فَإِذَا كَبَّرَ الْإِمَامُ فَكَبِّرُوا، وَإِذَا قَرَأَ: {غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ وَلَا الضَّالِّينَ} فَقُولُوا: آمِينَ يُجِبْكُمُ اللهُ، وَإِذَا كَبَّرَ وَرَكَعَ فَكَبِّرُوا وَارْكَعُوا، فَإِنَّ الْإِمَامَ يَرْكَعُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ". قَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَتِلْكَ بِتِلْكَ. وَإِذَا قَالَ سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَقُولُوا: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ، يَسْمَعِ اللهُ لَكُمْ، فَإِنَّ اللهَ قَالَ عَلَى لِسَانِ نَبِيِّهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ :سَمِعَ اللهُ لِمَنْ حَمِدَهُ، فَإِذَا كَبَّرَ وَسَجَدَ فَكَبِّرُوا وَاسْجُدُوا، فَإِنَّ الْإِمَامَ يَسْجُدُ قَبْلَكُمْ وَيَرْفَعُ قَبْلَكُمْ". قَالَ نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَتِلْكَ بِتِلْكَ. فَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أَوَّلِ قَوْلِ أَحَدِكُمْ: التَّحِيَّاتُ الطَّيِّبَاتُ، الصَّلَوَاتُ لِلَّهِ، سَلَامٌ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، سَلَامٌ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، سَبْعُ كَلِمَاتٍ، وَهِيَ تَحِيَّةُ الصَّلَاةِ". (ن,جه)', 'അബൂമൂസ(റ): നബി(സ) തന്റെ പ്രസംഗത്തിലൂടെ സുന്നത്തുകൾ ഞങ്ങൾക്ക് വ്യക്തമാക്കിതന്നു. ഞങ്ങൾക്ക് നിസ്കാരം പഠിപ്പിച്ചു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിച്ചാൽ അണികൾ ശരിയാക്കുക. പിന്നെ നിങ്ങളിലൊരാൾ ഇമാമാകട്ടെ, ഇമാം തക്ബീർ ചൊല്ലിയാൽ നിങ്ങളും തക്ബീർ ചൊല്ലുക. ''വലള്ളാല്ലീൻ'' എന്ന് പറഞ്ഞാൽ നിങ്ങൾ ''ആമീൻ'' പറയുക, നിങ്ങളെ അല്ലാഹു ഇഷ്ടപ്പെടും. തക്ബീർ ചൊല്ലി റുകൂഇൽ പോകുമ്പോൾ നിങ്ങളും തക്ബീർ ചൊല്ലി റുകൂഇൽ പോകുക. ഇമാമാണ് നിങ്ങൾക്ക് മുമ്പ് റുകൂഇൽ പോകേണ്ടതും എഴുന്നേൽക്കേണ്ടതും." നബി(സ) വീണ്ടും പറഞ്ഞു: "അത് അപ്രകാരമാണ്. ഇമാം ''സമിഅല്ലാഹു ലിമൻ ഹമിദഹു'' പറഞ്ഞാൽ നിങ്ങൾ ''അല്ലാഹുമ്മ റബ്ബനാ വലകൽ ഹംദ്'' എന്ന് പറയുക. അല്ലാഹു അത് നിങ്ങളിൽ നിന്നും കേൾക്കും. അല്ലാഹു അവന്റെ പ്രവാചകനിലൂടെ പറയുന്നു; അല്ലാഹു അവനെ സ്തുതിച്ചവന്റെ സ്തുതി കേട്ടിരിക്കുന്നു. ഇമാം തക്ബീർ ചൊല്ലി സുജൂദിൽ പോയാൽ നിങ്ങളും തക്ബീർ ചൊല്ലി സുജൂദിൽ പോകുക. ഇമാം നിങ്ങൾക്ക് മുമ്പായി സുജൂദ് ചെയ്യട്ടെ അവിടെനിന്ന് ഉയരുകയും ചെയ്യട്ടെ." നബി(സ) പറഞ്ഞു: "അത് അപ്രകാരമാണ്. ഇമാം ഇരുത്തത്തിൽ (അത്തഹിയ്യാത്തിൽ) ആയാൽ നിങ്ങളുടെ ആദ്യവാചകം ''അത്തഹിയ്യാത്തു അത്ത്വയ്യിബാത്തു അസ്വലവാത്തു ലില്ലാഹി, സലാമുൻ അലൈക അയ്യുഹന്നബിയ്യു വറഹ്മതുല്ലാഹി വ ബറകാതുഹു. സലാമുൻ അലൈനാ വഅലാ ഇബാദില്ലാഹിസ്സ്വാലിഹീൻ, അശ്ഹദു അൻലാഇലാഹ ഇല്ലല്ലാഹു വ അശ്ഹദു അന്ന മുഹമ്മദൻ അബ്ദുഹു വ റസൂലുഹു''. എന്നായിരിക്കട്ടെ, അവ ഏഴ് വചനങ്ങളാണ്, അത് നിസ്കാരത്തിലെ ഉപഹാരമാണ്." (ന,ജ)', 'أَبِي مُوسَى', 'അബൂമൂസ(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=50 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 187, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَجَدَ جَافَى يَدَيْهِ، فَلَوْ أَنَّ بَهْمَةً أَرَادَتْ أَنْ تَمُرَّ بَيْنَ يَدَيْهِ لَمَرَّتْ. (م,د,ن,جه)', 'മൈമൂന(റ): നബി(സ) സുജൂദ് ചെയ്യുമ്പോൾ തന്റെ കൈകൾ അകറ്റി വെക്കാറുണ്ടായിരുന്നു. നബി(സ)യുടെ കൈകൾക്കിടയിലൂടെ ഒരു ആട്ടിൻകുട്ടി നടക്കാൻ ഉദ്ദേശിച്ചാൽ അത് കടന്നുപോകും. (മു,ദ,ന,ജ)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 486, 486, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 188, 'عَنْ عَبْدِ اللهِ بْنِ أَقْرَمَ الْخُزَاعِيّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ مَعَ أَبِي بِالْقَاعِ مِنْ نَمِرَةَ، فَمَرَّ بِنَا رَكْبٌ، فَأَنَاخُوا بِنَاحِيَةِ الطَّرِيقِ، فَقَالَ لِي أَبِي:كُنْ فِي بَهْمِكَ حَتَّى آتِيَ هَؤُلَاءِ الْقَوْمَ فَأُسَائِلَهُمْ. قَالَ: فَخَرَجَ، وَجِئْتُ، يَعْنِي دَنَوْتُ، فَإِذَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَحَضَرَتِ الصَّلَاةُ فَصَلَّيْتُ مَعَهُمْ، فَكُنْتُ أَنْظُرُ إِلَى عُفْرَتَيْ إِبْطَيْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُلَّمَا سَجَدَ. (ت,ن,جه)', 'ഉബൈദുല്ലാഹിബ്നു അഖ്റമൽഖുസാഇ(റ): ഞാൻ എന്റെ പിതാവിനൊപ്പം നമിറക്ക് അടുത്തുള്ള സ്ഥലത്തായിരുന്നു. ഞങ്ങൾക്കരികിലൂടെ ഒരു വാഹന സംഘം കടന്നുപോയി. വഴിയരികിൽ അവർ വാഹനം നിർത്തി. എന്നോട് പിതാവ് പറഞ്ഞു: നീ ആട്ടിൻകുട്ടിയുടെ അടുത്ത് നിൽക്കുക. ഞാൻ അവരുടെ അടുത്തുചെന്ന് അന്വേഷിക്കട്ടെ. അദ്ദേഹം പുറപ്പെട്ടു. ഞാൻ അടുത്തുചെന്നു അത് (നബിയും സ്വഹാബത്തും) ആണെന്ന് മനസ്സിലായി. നിസ്കാരത്തിന് സമയമായി. ഞാൻ അവരോടൊപ്പം നിസ്കരിച്ചു. സുജൂദ് ചെയ്യുമ്പോഴൊക്കെ നബി(സ)യുടെ രണ്ട് കക്ഷത്തിലെ വെള്ളയിലേക്കും ഞാൻ നോക്കുമായിരുന്നു. (തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ أَقْرَمَ الْخُزَاعِيّ', 'ഉബൈദുല്ലാഹിബ്നു അഖ്റമൽഖുസാഇ(റ)', null, null, array['ت','ن','جه']::text[], array['തു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 189, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا سَجَدَ وَضَعَ رُكْبَتَيْهِ قَبْلَ يَدَيْهِ، وَإِذَا قَامَ مِنَ السُّجُودِ رَفَعَ يَدَيْهِ قَبْلَ رُكْبَتَيْهِ. (د,ت,ن,جه)', 'വാഇലുബ്നു ഹുജ്ർ(റ): നബി(സ) സുജൂദിലേക്ക് പോകുമ്പോൾ കൈകൾ വെക്കുന്നതിനു മുമ്പായി മുട്ടുകൾ വെക്കുന്നതായി കണ്ടു. സുജൂദിൽ നിന്നുയരുമ്പോൾ മുട്ടുകൾക്കു മുമ്പായി കൈകൾ ഉയർത്തുന്നതും. (ദ,തു,ന,ജ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 190, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعَةِ أَعْظُمٍ". (ق,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഏഴ് അവയവങ്ങളിൽ സുജൂദ് ചെയ്യാൻ ഞാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 191, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "أُمِرْتُ أَنْ أَسْجُدَ عَلَى سَبْعٍ، وَلَا أَكُفَّ شَعْرًا وَلَا ثَوْبًا". وَفِي رِوَايَةٍ: قَالَ ابْنُ طَاوُسٍ: فَكَانَ أَبِي يَقُولُ: الْيَدَيْنِ وَالرُّكْبَتَيْنِ وَالْقَدَمَيْنِ، وَكَانَ يَعُدُّ الْجَبْهَةَ وَالْأَنْفَ وَاحِدًا. (ق,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ഏഴ് അവയവങ്ങളിന്മേലായി സുജൂദ് ചെയ്യാൻ ഞാൻ കൽപ്പിക്കപ്പെട്ടു, മുടിയോ വസ്ത്രമോ ഞാൻ ചേർത്തു വെക്കില്ല." മറ്റൊരു റിപ്പോർട്ടിൽ ഇബ്നുത്വാഊസ് പറഞ്ഞു: എന്റെ പിതാവ് (സുജൂദിൽ തട്ടേണ്ട അവയങ്ങളെപ്പറ്റി ഇപ്രകാരം) പറയുമായിരുന്നു: രണ്ട് പാദങ്ങളും രണ്ടു കാൽ മുട്ടുകളും ഇരു കൈകളും; നെറ്റിയും മൂക്കും അദ്ദേഹം ഒറ്റ അവയവമായി കണക്കാക്കിയിരുന്നു. (ബു,മു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','ن','جه']::text[], array['ബു','മു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=191), 1, 'وَفِي رِوَايَةٍ: قَالَ ابْنُ طَاوُسٍ: فَكَانَ أَبِي يَقُولُ: الْيَدَيْنِ وَالرُّكْبَتَيْنِ وَالْقَدَمَيْنِ، وَكَانَ يَعُدُّ الْجَبْهَةَ وَالْأَنْفَ وَاحِدًا. (ق,ن,جه)', 'മറ്റൊരു നിവേദനിൽ ഇബ്നുത്വാഊസ് പറഞ്ഞു: എന്റെ പിതാവ് (സുജൂദിൽ തട്ടേണ്ട അവയങ്ങളെപ്പറ്റി ഇപ്രകാരം) പറയുമായിരുന്നു: രണ്ട് പാദങ്ങളും രണ്ടു കാൽ മുട്ടുകളും ഇരു കൈകളും; നെറ്റിയും മൂക്കും അദ്ദേഹം ഒറ്റ അവയവമായി കണക്കാക്കിയിരുന്നു. (ബു,മു,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 192, 'عَنِ الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِذَا سَجَدَ الْعَبْدُ سَجَدَ مَعَهُ سَبْعَةُ آرَابٍ: وَجْهُهُ وَكَفَّاهُ وَرُكْبَتَاهُ وَقَدَمَاهُ". (م,د,ت,ن,جه)', 'അബ്ബാസുബ്നു അബ്ദുൽ മുത്തലിബ്(റ): നബി(സ) പറയുന്നതായി അദ്ദേഹം കേട്ടു: "ഒരടിമ സുജൂദ് ചെയ്യുമ്പോൾ ഏഴ് അവയവങ്ങൾ അവനോടപ്പം സുജൂദ് ചെയ്യും. അവന്റെ മുഖം, കൈപത്തികൾ, കൈമുട്ടുകൾ കാൽപാദങ്ങൾ എന്നിവയാണത്." (മു,ദ,തു,ന,ജ)', 'الْعَبَّاسِ بْنِ عَبْدِ الْمُطَّلِبِ', 'അബ്ബാസുബ്നു അബ്ദുൽ മുത്തലിബ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 487, 487, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 193, 'عَنْ أَحْمَرَ رَضِيَ اللهُ عَنْهُ، صَاحِبُ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِنْ كُنَّا لَنَأْوِي لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِمَّا يُجَافِي بِيَدَيْهِ عَنْ جَنْبَيْهِ إِذَا سَجَدَ. (د,جه)', 'അഹ്മർ(റ): നബി(സ)യുടെ അനുചരനായ അദ്ദേഹം പറഞ്ഞു: ഞങ്ങൾ നബി(സ)യുടെ അടുത്താകുമ്പോൾ തന്റെ കൈകൾ പാർശ്വങ്ങളിൽ നിന്ന് അകറ്റി വെക്കാറുണ്ടായിരുന്നു. (ദ,ജ)', 'أَحْمَرَ', 'അഹ്മർ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 194, 'عَنْ أَبِي إِسْحَقَ رَضِيَ اللهُ عَنْهُ قَالَ: وَصَفَ لَنَا الْبَرَاءُ رَضِيَ اللهُ عَنْهُ السُّجُودَ، فَوَضَعَ يَدَيْهِ بِالْأَرْضِ، وَرَفَعَ عَجِيزَتَهُ، وَقَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ. (د,ن)', 'അബൂഇസ്ഹാഖ്(റ): സുജൂദ് എങ്ങിനെയെന്ന് ബറാഅ്(റ) ഞങ്ങൾക്ക് പറഞ്ഞുതന്നു. അപ്പോൾ അദ്ദേഹത്തിന്റെ കൈകൾ നിലത്തു വെച്ചു. മുതുക് ഉയർത്തി വെച്ചു. പിന്നെ പറഞ്ഞു: നബി(സ) ഇപ്രകാരം ചെയ്യുന്നത് ഞാൻ കണ്ടു. (ദ,ന)', 'أَبِي إِسْحَقَ', 'അബൂഇസ്ഹാഖ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 195, 'عَنْ حَكِيمِ بْنِ حِزَامٍ رَضِيَ اللهُ عَنْهُ قَالَ: بَايَعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا أَخِرَّ إِلَّا قَائِمًا. (ن)', 'ഹകീം(റ): ഞാൻ ''(റുകൂഇൽ നിന്ന് ഉയർന്ന് ശരിയാം വണ്ണം) നിൽക്കുന്നവനായിരിക്കെയല്ലാതെ സുജൂദിലേക്കു പോവുകയില്ല'' എന്ന് നബി(സ)യോട് ഉടമ്പടി ചെയ്തു. (ന)', 'حَكِيمِ بْنِ حِزَامٍ', 'ഹകീം(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 196, 'عَنِ الْبَرَّاءِ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى جَخَّى. (ن)', 'ബറാഅ്(റ): നബി(സ) നിസ്കരിക്കുമ്പോൾ കൈകൾ അകറ്റി വെക്കാറുണ്ടായിരുന്നു. (ന)', 'الْبَرَّاءِ', 'ബറാഅ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 197, 'عَنْ عَبْدِاللهِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا صَلَّى فَرَّجَ بَيْنَ يَدَيْهِ حَتَّى يَبْدُوَ بَيَاضُ إِبْطَيْهِ. (خ)', 'അബ്ദുല്ലാഹിബ്നു മാലിക്(റ): തിരുമേനി(സ) നിസ്കരിക്കുമ്പോൾ (സുജൂദിൽ) തന്റെ ഇരു കക്ഷത്തിലെയും വെളുപ്പ് കാണുമാറ് തന്റെ ഇരുകൈകളും വിടർത്തി വെക്കാറുണ്ടായിരുന്നു. (ബു)', 'عَبْدِاللهِ بْنِ مَالِكٍ', 'അബ്ദുല്ലാഹിബ്നു മാലിക്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 198, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "اعْتَدِلُوا فِي السُّجُودِ، وَلَا يَفْتَرِشْ أَحَدُكُمْ ذِرَاعَيْهِ افْتِرَاشَ الْكَلْبِ". (ق,د,ت,ن,جه)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ സുജൂദിൽ നേരെയാവുക. ഒരാളും അവന്റെ കൈകൾ നായ വിടർത്തുന്നതു പോലെ വിടർത്തി വെക്കരുത്. (ദ,തു,ന,ജ)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ق','د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 199, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أُمِرَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَسْجُدَ عَلَى سَبْعٍ، وَنُهِيَ أَنْ يَكُفَّ الشَّعْرَ وَالثِّيَابَ: عَلَى يَدَيْهِ وَرُكْبَتَيْهِ وَأَطْرَافِ أَصَابِعِهِ. قَالَ ابْنُ طَاوُسٍ: وَوَضَعَ يَدَيْهِ عَلَى جَبْهَتِهِ وَأَمَرَّهَا عَلَى أَنْفِهِ، وَقَالَ: هَذَا وَاحِدٌ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഏഴ് അവയവങ്ങളിൽ സുജൂദ് ചെയ്യുവാൻ നബി(സ) കൽപിക്കപ്പെട്ടു. തന്റെ കൈകൾ, മുട്ടുകൾ, കൈവിരൽ തുമ്പുകൾ എന്നിവയുടെ മേൽ വസ്ത്രവും മുടിയും ചേർത്തിവെക്കുന്നത് നബി(സ)ക്ക് നിരോധിക്കപ്പെട്ടു. ഇബ്നുതാഊസ് തന്റെ കൈകൾ നെറ്റിയിൽ വെച്ച് മൂക്കിനു മുകളിലേക്ക് നീക്കി പറഞ്ഞു: ഇത് ഒന്നാണ്. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 488, 488, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 200, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ، بِهَذِهِ الْقِصَّةِ، قَالَ: إِذَا قُمْتَ فَتَوَجَّهْتَ إِلَى الْقِبْلَةِ فَكَبِّرْ، ثُمَّ اقْرَأْ بِأُمِّ الْقُرْآنِ وَبِمَا شَاءَ اللهُ أَنْ تَقْرَأَ، وَإِذَا رَكَعْتَ فَضَعْ رَاحَتَيْكَ عَلَى رُكْبَتَيْكَ وَامْدُدْ ظَهْرَكَ. وَقَالَ: "إِذَا سَجَدْتَ فَمَكِّنْ لِسُجُودِكَ، فَإِذَا رَفَعْتَ فَاقْعُدْ عَلَى فَخِذِكَ الْيُسْرَى". (د)', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ): അദ്ദേഹം പറഞ്ഞു: നീ നിസ്കരിക്കാൻ നിന്നാൽ ഖിബ്ലയെ അഭിമുഖമാക്കുക. ശേഷം തക്ബീർ ചെല്ലുക, ശേഷം ഉമ്മുൽ ഖുർആനും (ഫാത്തിഹ) പാരായണം ചെയ്യാൻ കഴിയുന്നത്ര ഖുർആനും ഓതുക. റുകൂഇൽ ഇരുകൈപ്പടങ്ങളും മുട്ടുകളിൽ വെക്കുക. മുതുകിനെ നിവർത്തി വെക്കുക. സുജൂദിൽ കൈകളെ സുജൂദിന് ഊന്നി നൽകുക. ഉയർന്നാൽ ഇടത്തേ തുടയിൽ (കാലിൽ) ഇരിക്കുക. (ദ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 488, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 201, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِهَذِهِ الْقِصَّةِ قَالَ: "إِذَا أَنْتَ قُمْتَ فِي صَلَاتِكَ فَكَبِّرِ اللهَ تَعَالَى، ثُمَّ اقْرَأْ مَا تَيَسَّرَ عَلَيْكَ مِنَ الْقُرْآنِ". وَقَالَ فِيهِ: "فَإِذَا جَلَسْتَ فِي وَسَطِ الصَّلَاةِ فَاطْمَئِنَّ وَافْتَرِشْ فَخِذَكَ الْيُسْرَى، ثُمَّ تَشَهَّدْ، ثُمَّ إِذَا قُمْتَ فَمِثْلَ ذَلِكَ حَتَّى تَفْرُغَ مِنْ صَلَاتِكَ". (د)', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ): നബി(സ) പറഞ്ഞു: "നീ നിസ്കാരത്തിനു നിന്നാൽ അല്ലാഹുവിനു വേണ്ടി തക്ബീർ ചെല്ലുക. പിന്നീട് ഖുർആനിൽ നിന്ന് നിനക്ക് എളുപ്പമായത് പാരായണം ചെയ്യുക." ഈ നിവേദനത്തിൽ വീണ്ടും പറഞ്ഞു: "നിസ്കാരത്തിന് ഇടയിൽ ഇരിക്കുമ്പോൾ നിന്റെ ഇടതുകാൽ വിരിച്ച് അതിന്മേൽ ഇരിക്കുക. പിന്നീട് നീ തശഹ്ഹുദ് ചൊല്ലുക. നിസ്കാരം കഴിയുംവരെ ഈ നിലയിൽ തുടരുക." (ദ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 202, 'عَنْ رِفَاعَةَ بْنِ رَافِعٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَصَّ هَذَا الْحَدِيثَ، قَالَ فِيهِ: "فَتَوَضَّأْ كَمَا أَمَرَكَ اللهُ جَلَّ وَعَزَّ، ثُمَّ تَشَهَّدْ، فَأَقِمْ، ثُمَّ كَبِّرْ: فَإِنْ كَانَ مَعَكَ قُرْآنٌ فَاقْرَأْ بِهِ، وَإِلَّا فَاحْمَدِ اللهَ وَكَبِّرْهُ وَهَلِّلْهُ". وَقَالَ فِيهِ: "وَإِنِ انْتَقَصْتَ مِنْهُ شَيْئًا انْتَقَصْتَ مِنْ صَلَاتِكَ". (د)', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ): നബി(സ) പറഞ്ഞു: "യുക്തിമാനും പ്രതാപിയുമായ അല്ലാഹു കൽപ്പിച്ച പ്രകാരം വുദു ചെയ്യുക. പിന്നെ നീ തശഹ്ഹുദ് (വുദുവിന് ശേഷമുള്ള പ്രാർത്ഥന) ചെയ്യുക. പിന്നീട് തക്ബീർ ചൊല്ലുക. നിനക്കറിയാവുന്ന ഖുർആൻ പാരായണം ചെയ്യുക. അറിയില്ലെങ്കിൽ അല്ലാഹുവിനെ സ്തുതിക്കുക. തക്ബീറും തഹ്ലീലും ചൊല്ലുക." അതിൽ ഇതുകൂടി പറഞ്ഞു: "അതിൽ വല്ല കുറവും വരുത്തിയാൽ നിന്റെ നിസ്കാരത്തിൽ ന്യൂനതയായി." (ദ)', 'رِفَاعَةَ بْنِ رَافِعٍ', 'രിഫാഅത്തുബ്നു റാഫിഅ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 203, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: إشْتَكَى أَصْحَابُ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَشَقَّةَ السُّجُودِ عَلَيْهِمْ إِذَا انْفَرَجُوا، فَقَالَ: "اسْتَعِينُوا بِالرُّكَبِ". (د,ت)', 'അബൂഹുറൈറ(റ): നബി(സ)യുടെ അനുചരർ കൈകൾ അകറ്റിക്കൊണ്ട് സുജൂദിൽ പോകുന്നതു മൂലമുണ്ടാകുന്ന പ്രയാസത്തെക്കുറിച്ച് ആവലാതി ബോധിപ്പിച്ചു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "മുട്ടുകാൽ സഹായകമാക്കുക." (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 204, 'عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: بَصُرَتْ عَيْنَايَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى جَبِينِهِ وَأَنْفِهِ أَثَرُ الْمَاءِ وَالطِّينِ، مِنْ صُبْحِ لَيْلَةِ إِحْدَى وَعِشْرِينَ. (ن)', 'അബൂസഈദിൽ ഖുദ്രി(റ): ഇരുപത്തൊന്നാം രാത്രിയിലെ സുബ്ഹി നിസ്കരിച്ചതു കാരണത്താൽ, നബി(സ)യുടെ നെറ്റിയിലും മൂക്കിന്മേലും, മണ്ണിന്റേയും വെള്ളത്തിന്റേയും അടയാളം ഞാൻ എന്റെ കണ്ണുകൊണ്ട് കണ്ടു. (ന)', 'أَبِي سَعِيدٍ الْخُدْرِيِّ', 'അബൂസഈദിൽ ഖുദ്രി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 489, 489, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 205, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ قَرَأَ مِنْكُمْ: {وَالتِّينِ وَالزَّيْتُونِ} فَانْتَهَى إِلَى آخِرِهَا: {أَلَيْسَ اللهُ بِأَحْكَمِ الْحَاكِمِينَ} فَلْيَقُلْ: بَلَى، وَأَنَا عَلَى ذَلِكَ مِنَ الشَّاهِدِينَ. وَمَنْ قَرَأَ: {لَا أُقْسِمُ بِيَوْمِ الْقِيَامَةِ} فَانْتَهَى إِلَى: {أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى} فَلْيَقُلْ: آمَنَّا بِاللهِ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരെങ്കിലും ''വത്തീനി വസ്സൈതൂൻ'' ഓതിയാൽ അതിന്റെ അവസാനം ''അലൈസല്ലാഹു ബിഅഹ്കമിൽ ഹാകിമീൻ" (അല്ലാഹു വിധികർത്താക്കളിൽ വെച്ച് ഏറ്റവും വലിയ വിധി കർത്താവല്ലയോ?) എന്നു പറഞ്ഞാൽ; ''ബലാ വഅനാ അലാദാലിക മിനശ്ശാഹിദീൻ'' (അതെ, ഞാനതിന് സാക്ഷിയാണ്) എന്ന് പറയുക. ആരെങ്കിലും ''ലാ ഉഖ്സിമു ബിയൗമിൽ ഖിയാമ'' ഓതി ''അലൈസ ദാലിക ബി ഖാദിരീൻ അലാ അൻ യുഹ്യിയൽമൗത്താ'' (അങ്ങനെയുള്ളവൻ മരിച്ചവരെ ജീവിപ്പിക്കാൻ കഴിവുള്ളവനല്ലയോ?) എന്ന് ഓതിയാൽ; ആമന്നാ ബില്ലാഹി (ഞങ്ങൾ അല്ലാഹുവിൽ വിശ്വസിച്ചു.) എന്ന് പറയുക." (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 489, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 206, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: مَا صَلَّيْتُ وَرَاءَ أَحَدٍ بَعْدَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَشْبَهَ صَلَاةً بِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ هَذَا الْفَتَى، يَعْنِي عُمَرَ بْنَ عَبْدِ الْعَزِيزِ. قَالَ: فَحَزَرْنَا فِي رُكُوعِهِ عَشْرَ تَسْبِيحَاتٍ، وَفِي سُجُودِهِ عَشْرَ تَسْبِيحَاتٍ. (د,ن)', 'അനസുബ്നു മാലിക്(റ): റസൂലിന്റെ നിസ്കാരത്തോട് ഇത്രയേറെ സാമ്യമുള്ള നിസ്കാരം, ഈ യുവാവിന്റെ പിന്നിലല്ലാതെ നബി(സ)ക്ക് ശേഷം ഞാൻ ഒരാളുടേയും പിന്നിൽ നിസ്കരിച്ചിട്ടില്ല. ഉദ്ദേശിച്ചത് ഉമറുബ്നു അബദിൽ അസീസി(റ)നെയായിരുന്നു. അദ്ദേഹത്തിന്റെ റുകൂഇലും സുജൂദിലും ഞങ്ങൾ പത്ത് തസ്ബീഹുകളെങ്കിലും ചെല്ലിയിരുന്നു. (ദ,ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 207, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ قَالَ:كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا أَهْوَى إِلَى الْأَرْضِ سَاجِدًا جَافَى عَضُدَيْهِ عَنْ إِبِطَيْهِ، وَفَتَخَ أَصَابِعَ رِجْلَيْهِ. (ن)', 'അബൂഹുമൈദ സാഇദി(റ): നബി(സ) സുജൂദിന്നായി നിലത്തേക്ക് ചായുമ്പോൾ രണ്ട് തോളുകളും പാർശ്വങ്ങളിൽ നിന്ന് അകറ്റി വെക്കാറുണ്ടായിരുന്നു. കാൽവിരലുകൾ (ഖിബ്ലയിലേക്ക് തിരിയുമാറ്) നാട്ടി വെച്ചിരുന്നു. (ന)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദ സാഇദി(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=51 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 208, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ الْمَدِينَةَ، فَقُلْتُ: لَأَنْظُرَنَّ إِلَى صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَبَّرَ، وَرَفَعَ يَدَيْهِ حَتَّى رَأَيْتُ إِبْهَامَيْهِ قَرِيبًا مِنْ أُذُنَيْهِ، فَلَمَّا أَرَادَ أَنْ يَرْكَعَ كَبَّرَ وَرَفَعَ يَدَيْهِ، ثُمَّ رَفَعَ رَأْسَهُ فَقَالَ: "سَمِعَ اللهُ لِمَنْ حَمِدَهُ". ثُمَّ كَبَّرَ وَسَجَدَ، فَكَانَتْ يَدَاهُ مِنْ أُذُنَيْهِ عَلَى الْمَوْضِعِ الَّذِي اسْتَقْبَلَ بِهِمَا الصَّلَاةَ. (ن)', 'വാഇലുബ്നു ഹുജ്ർ(റ): മദീനയിൽ വന്നപ്പോൾ ഞാൻ പറഞ്ഞു: ഞാൻ നബി(സ)യുടെ നിസ്കാരത്തെ നോക്കികാണുക തന്നെ ചെയ്യും. നബി(സ) തക്ബീർ ചൊല്ലി, പിന്നീട് കൈവിരലുകൾ ചെവിക്കുനേരെ എത്തും വരെ കൈ ഉയർത്തി. റുകൂഅ് ചെയ്യാനുദ്ദേശിച്ചപ്പോഴും തക്ബീർ ചെല്ലി കൈ ഉയർത്തി, പിന്നെ "സമിഅല്ലാഹു ലിമൻ ഹമിദഹു" എന്ന് പറഞ്ഞു തലയുയർത്തി, പിന്നെ തക്ബീർ ചൊല്ലി സുജൂദ് ചെയ്തു. നബി(സ)യുടെ കൈകൾ നിസ്കാരത്തിന്റെ തുടക്കത്തിൽ ഉയർത്തിയ സ്ഥലത്ത് ചെവിക്ക് സമീപമാണ് ഉണ്ടായിരുന്നത്. (ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 490, 490, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=52 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 209, 'عَنْ عَبْدِ اللهِ بْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَأَى عَبْدَ اللهِ بْنَ الْحَارِثِ يُصَلِّي، وَرَأْسُهُ مَعْقُوصٌ مِنْ وَرَائِهِ، فَقَامَ فَجَعَلَ يَحُلُّهُ، فَلَمَّا انْصَرَفَ أَقْبَلَ إِلَى ابْنِ عَبَّاسٍ فَقَالَ: مَا لَكَ وَرَأْسِي؟ قَالَ: إِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "إِنَّمَا مَثَلُ هَذَا مَثَلُ الَّذِي يُصَلِّي وَهُوَ مَكْتُوفٌ". (م)', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): അദ്ദേഹം അബ്ദുല്ലാഹിബ്നു ഹാരിസ്(റ) നിസ്കരിക്കുന്നത് കണ്ടു. അദ്ദേഹത്തിന്റെ തല (മുടി) പിന്നിൽ നിന്ന് കെട്ടിയിട്ടുണ്ട്. അദ്ദേഹം അത് അഴിക്കാൻ തുടങ്ങി. നിസ്കാരം കഴിഞ്ഞപ്പോൾ അദ്ദേഹം ഇബ്നുഅബ്ബാസി(റ)ന്റെ അടുത്തുവന്ന് ചോദിച്ചു: നിങ്ങൾ എന്റെ തലയിൽ എന്താണ് ചെയ്തത്? അദ്ദേഹം പറഞ്ഞു: നബി(സ) പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "ഇങ്ങനെ നിസ്കരിക്കുന്നവന്റെ ഉപമ, കൈ ബന്ധിക്കപ്പെട്ട നിലയിൽ നിസ്കരിക്കുന്നവനെ പോലെയാണ്." (മു)', 'عَبْدِ اللهِ بْنِ عَبَّاسٍ', 'അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 210, 'عَنْ ثَابِتٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ أَنَسٌ أَنَّهُ كَانَ يَنْعَتُ لَنَا صَلَاةَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ يُصَلِّي فَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَامَ حَتَّى نَقُولَ قَدْ نَسِيَ. (خ)', 'സാബിത്(റ): അനസ്(റ) ഞങ്ങൾക്ക് നബി(സ)യുടെ നിസ്കാരത്തെ വിശേഷിപ്പിച്ചു തന്നു. നിസ്കാരത്തിൽ നബി(സ) റുകൂഇൽ നിന്നുയർന്നാൽ നേരെ നിൽക്കും. അദ്ദേഹം മറന്ന് പോയോ, എന്ന് ഞങ്ങൾ പറയുന്ന അത്രയും ദീർഘ സമയം. (ബു)', 'ثَابِتٍ', 'സാബിത്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=53 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 211, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا صَلَّيْنَا خَلْفَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالظَّهَائِرِ سَجَدْنَا عَلَى ثِيَابِنَا، اتِّقَاءَ الْحَرِّ. (ن)', 'അനസ്(റ): ഞങ്ങൾ നബി(സ)യുടെ കൂടെ ഉച്ച സമയങ്ങളിൽ നിസ്കരിക്കുമ്പോൾ ചൂട് തടുക്കാൻ വസ്ത്രത്തിനു മുകളിൽ സുജൂദ് ചെയ്യാറുണ്ടായിരുന്നു. (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=54 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 212, 'عَنْ أَنَسٍ رَضِيَ اللهُ عَنْهُ: عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ، فَوَاللهِ إِنِّي لَأَرَاكُمْ مِنْ خَلْفِ ظَهْرِي فِي رُكُوعِكُمْ وَسُجُودِكُمْ". (ن)', 'അനസ്(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ റുകൂഉം സുജൂദും പൂർണ്ണമാക്കുക. അല്ലാഹുവാണെ, നിങ്ങളുടെ റുകൂഉം സൂജൂദും ഞാനെന്റെ പിന്നിലൂടെ കാണുന്നുണ്ട്." (ന)', 'أَنَسٍ', 'അനസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=55 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 213, 'عَنِ السَّعْدِيِّ عَنْ أَبِيهِ أَوْ عَنْ عَمِّهِ رَضِيَ اللهُ عَنْهُمْ قَالَ: رَمَقْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاتِهِ، فَكَانَ يَتَمَكَّنُ فِي رُكُوعِهِ وَسُجُودِهِ قَدْرَ مَا يَقُولُ: "سُبْحَانَ اللهِ وَبِحَمْدِهِ" ثَلَاثًا. (د)', 'സഅദി(റ): തന്റെ പിതാവ്, അല്ലെങ്കിൽ പിതൃവ്യനിൽ നിന്ന്: ഞാൻ നബി(സ)യെ നിസ്കാരത്തിൽ നിരീക്ഷിച്ചു. നബി(സ) തന്റെ റുകൂഇലും സുജൂദിലും "സുബ്ഹാനല്ലാഹി വബിഹംദിഹി" എന്ന് മൂന്നുപ്രാവശ്യം പറയുന്നത്ര സമയം നിൽക്കാറുണ്ടായിരുന്നു. (ദ)', 'السَّعْدِيِّ عَنْ أَبِيهِ أَوْ عَنْ عَمِّهِ', 'സഅദി(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 491, 491, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 214, 'عَنْ عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَلَاثٍ: عَنْ نَقْرَةِ الْغُرَابِ، وَافْتِرَاشِ السَّبُعِ، وَأَنْ يُوَطِّنَ الرَّجُلُ الْمَقَامَ لِلصَّلَاةِ كَمَا يُوَطِّنُ الْبَعِيرُ. (د,ن,جه)', 'അബ്ദുറഹ്മാനുബ്നു ശബൽ(റ): നബി(സ) മൂന്ന് കാര്യങ്ങൾ വിരോധിച്ചു: കാക്കയുടെ കൊത്തു പോലെ (ധൃതികാട്ടി) നിസ്കരിക്കുൽ. വന്യമൃഗങ്ങളുടെ ഇരുത്തം പോലെ നിസ്കാരത്തിൽ ഇരിക്കൽ. ഒരാൾ, ഒട്ടകം സ്ഥലം സ്ഥിരമാക്കുന്ന പോലെ നിസ്കാരത്തിന് സ്ഥലം സ്ഥിരമാക്കൽ (എന്നിവയാണവ). (ദ,ന,ജ)', 'عَبْدِ الرَّحْمَنِ بْنِ شِبْلٍ', 'അബ്ദുറഹ്മാനുബ്നു ശബൽ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 215, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "يَعْمِدُ أَحَدُكُمْ فَيَبْرُكُ فِي صَلَاتِهِ بَرْكَ الْجَمَلِ". (د,ت,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരും മുട്ടു വെക്കുമ്പോൾ (സുജൂദിൽ) ഒട്ടകം മുട്ടുകുത്തും പോലെ ചെയ്യരുത്.⁶" (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=56 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 216, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا سَجَدَ أَمْكَنَ أَنْفَهُ وَجَبْهَتَهُ مِنَ الْأَرْضِ، وَنَحَّى يَدَيْهِ عَنْ جَنْبَيْهِ، وَوَضَعَ كَفَّيْهِ حَذْوَ مَنْكِبَيْهِ. حَسَنٌ صَحِيحٌ. (ت)', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ): നബി(സ) സുജൂദിൽ മൂക്കും നെറ്റിയും നിലത്ത് വെക്കുമായിരുന്നു. കൈകൾ പാർശ്വത്തിൽ നിന്നും അകറ്റിവെച്ചു. കൈപ്പത്തികൾ തോളിനുനേരെ വെക്കുകയും ചെയ്തു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (തു)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദിനിസ്സാഇദീ(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 217, 'عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُمَا سُئِلَ: أَيْنَ كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَضَعُ وَجْهَهُ إِذَا سَجَدَ؟ فَقَالَ: بَيْنَ كَفَّيْهِ. حَسَنٌ صَحِيحٌ. (ت)', 'ബറാഉബ്നു ആസിബ്(റ): അദ്ദേഹത്തോട് ചോദിക്കപ്പെട്ടു: നബി(സ) നിസ്കാരത്തിൽ സുജൂദ് ചെയ്യുമ്പോൾ മുഖം എവിടെയാണ് വെച്ചത്? അദ്ദേഹം പറഞ്ഞു: രണ്ട് കൈപ്പത്തികൾക്കിടയിൽ. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (തു)', 'الْبَرَاءِ بْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ت']::text[], array['തു']::text[], null, null, 492, 492, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=57 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 218, 'عَنْ مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: لَقِيتُ ثَوْبَانَ مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: أَخْبِرْنِي بِعَمَلٍ أَعْمَلُهُ يُدْخِلُنِي اللهُ بِهِ الْجَنَّةَ، أَوْ قَالَ: قُلْتُ: بِأَحَبِّ الْأَعْمَالِ إِلَى اللهِ. فَسَكَتَ، ثُمَّ سَأَلْتُهُ فَسَكَتَ، ثُمَّ سَأَلْتُهُ الثَّالِثَةَ فَقَالَ: سَأَلْتُ عَنْ ذَلِكَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "عَلَيْكَ بِكَثْرَةِ السُّجُودِ لِلَّهِ عَزَّ وَجَلَّ، فَإِنَّكَ لَا تَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَكَ اللهُ بِهَا دَرَجَةً، وَحَطَّ عَنْكَ بِهَا خَطِيئَةً". قَالَ مَعْدَانُ: ثُمَّ لَقِيتُ أَبَا الدَّرْدَاءِ، فَسَأَلْتُهُ، فَقَالَ لِي مِثْلَ مَا قَالَ ثَوْبَانُ. (م,ن)', 'മഅ്ദാനുബ്നു അബൂത്വൽഹ(റ): നബി(സ)യുടെ മൗലയായ സൗബാനി(റ)നെ ഞാൻ കണ്ടു. ഞാൻ ചോദിച്ചു: എന്നെ ഒരു കർമ്മം പഠിപ്പിച്ചാലും, ഞാൻ അത് ചെയ്താൽ അതുമുഖേന അല്ലാഹു എന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കും. (അല്ലെങ്കിൽ) അദ്ദേഹം പറഞ്ഞതിങ്ങനെയാണ്: ഞാൻ പറഞ്ഞു: അല്ലാഹുവിന് ഏറ്റവും ഇഷ്ടപ്പെട്ട കർമ്മം? (ഏതാണ്) അപ്പോൾ അദ്ദേഹം മൗനം പാലിച്ചു. വീണ്ടും ചോദിച്ചപ്പോഴും മൗനം പാലിച്ചു. മൂന്നാമത് ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഞാനിക്കാര്യം നബി(സ)യോട് ചോദിച്ചിരുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ അല്ലാഹുവിന് സുജൂദ് വർദ്ധിപ്പിക്കുക. നീ അല്ലാഹുവിന് സുജൂദ് ചെയ്യുകയില്ല, അതുമുഖേന അല്ലാഹു നിന്റെ പദവി ഉയർത്തിയിട്ടും നിന്റെ പാപത്തെ മായിച്ചിട്ടു മല്ലാതെ." മഅ്ദാൻ പറയുന്നു. പിന്നീട് ഞാൻ അബൂദ്ദർദാഇനെ കണ്ട് ചോദിച്ചപ്പോൾ സൗബാൻ പറഞ്ഞതുപോലെ അദ്ദേഹവും പറഞ്ഞു. (മു,ന)', 'مَعْدَانَ بْنِ أَبِي طَلْحَةَ الْيَعْمَرِيِّ', 'മഅ്ദാനുബ്നു അബൂത്വൽഹ(റ)', '⁶. കൈ നിലത്ത് കുത്തിയ ശേഷം മുട്ടുകുത്തുകയല്ല, മുട്ട് ആദ്യം നിലത്ത് കുത്തിയ ശേഷം ഇരു കൈകളും നിലത്ത് കുത്തിയാണ് സുജൂദ് ചെയ്യേണ്ടത്.', null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 492, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 219, 'عَنْ رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: كُنْتُ آتِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِوَضُوئِهِ وَبِحَاجَتِهِ، فَقَالَ: "سَلْنِي". قُلْتُ: مُرَافَقَتَكَ فِي الْجَنَّةِ. قَالَ: "أَوْ غَيْرَ ذَلِكَ". قُلْتُ: هُوَ ذَاكَ. قَالَ: "فَأَعِنِّي عَلَى نَفْسِكَ بِكَثْرَةِ السُّجُودِ". (ن)', 'റബീഅതുബ്നു കഅബ്(റ): ഞാൻ നബി(സ)ക്ക് വെള്ളമെടുത്തു കൊടുക്കുകയും ആവശ്യങ്ങൾ നിർവ്വഹിച്ച് കൊടുക്കുകയും ചെയ്യാറുണ്ടായിരുന്നു. ഒരിക്കൽ നബി(സ) പറഞ്ഞു: "നീ ചോദിക്കുക." ഞാൻ പറഞ്ഞു: അങ്ങയോടൊപ്പം സ്വർഗ്ഗത്തിലെ സാമീപ്യമാണ് എനിക്കു വേണ്ടത്. റസൂൽ(സ) പറഞ്ഞു: "അതല്ലാതെ മറ്റു വല്ലതും?". ഞാൻ പറഞ്ഞു: അതു തന്നെയാണ് വേണ്ടത്. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ സുജൂദ് വർദ്ധിപ്പിച്ചുകൊണ്ട് നിനക്കു വേണ്ടി എന്നെ സഹായിക്കുക." (ന)', 'رَبِيعَةَ بْنِ كَعْبٍ الْأَسْلَمِيِّ', 'റബീഅതുബ്നു കഅബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 220, 'عَنْ مَعْدَانَ بْنِ طَلْحَةَ الْيَعْمُرِيِّ قَالَ: لَقِيتُ ثَوْبَانَ مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: دُلَّنِي عَلَى عَمَلٍ يَنْفَعُنِي، أَوْ: يُدْخِلُنِي الْجَنَّةَ. فَسَكَتَ عَنِّي مَلِيًّا، ثُمَّ الْتَفَتَ إِلَيَّ فَقَالَ: عَلَيْكَ بِالسُّجُودِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللهُ عَزَّ وَجَلَّ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً". قَالَ مَعْدَانُ: ثُمَّ لَقِيتُ أَبَا الدَّرْدَاءِ رَضِيَ اللهُ عَنْهُ فَسَأَلْتُهُ عَمَّا سَأَلْتُ عَنْهُ ثَوْبَانَ، فَقَالَ لِي: عَلَيْكَ بِالسُّجُودِ، فَإِنِّي سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَا مِنْ عَبْدٍ يَسْجُدُ لِلَّهِ سَجْدَةً إِلَّا رَفَعَهُ اللهُ بِهَا دَرَجَةً، وَحَطَّ عَنْهُ بِهَا خَطِيئَةً". (ن)', 'മഅ്ദാനുബ്നുത്വൽഹ: ഞാൻ തിരുമേനി(സ)യുടെ മൗലയായ ഥൗബാനി(റ)നെ കുമുട്ടിയപ്പോൾ അദ്ദേഹത്തോട് ചോദിച്ചു: ''എന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിപ്പിക്കുന്ന ഒരു സൽകർമ്മം എനിക്കു പറഞ്ഞു തന്നാലും! അപ്പോൾ അദ്ദേഹം അൽപ്പനേരം എന്നെ വിട്ട് മൗനമവലംബിച്ചു. പിന്നീട് എന്നിലേക്കു തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: നീ സുജൂദ് വർദ്ധിപ്പിക്കുക. തിരുമേനി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹുവിന്ന് അവന്റെ ഒരു ദാസൻ സ്രാഷ്ടാഗം ചെയ്യുകയാണെങ്കിൽ അതുമുഖേന അല്ലാഹു ആ അടിമയുടെ പദവി ഉയർത്തുകയും, അവന്റെ പാപങ്ങൾ പൊറുത്തു കൊടുക്കുകയും ചെയ്യാതിരിക്കില്ല." മഅ്ദാൻ പറഞ്ഞു: പിന്നീടൊരിക്കൽ ഞാൻ അബുദ്ദർദാഇനെ കണ്ടുമുട്ടിയപ്പോൾ, ഞാൻ ഥൗബാനിനോട് ചോദിച്ചപോലെ അദ്ദേഹത്തോടു ചോദിച്ചപ്പോൾ അദ്ദേഹം പറഞ്ഞു: നീ സുജൂദ് അധികരിപ്പിക്കുക. നബി(സ) ഇപ്രകാരം പറയുന്നതു ഞാൻ കേട്ടിട്ടുണ്ട്: "അല്ലാഹുവിന്റെ അടിമ അല്ലാഹുവിന് സുജൂദ് ചെയ്താൽ അതുകാരണത്താൽ അവന്നു പദവി ഉയർത്തിക്കൊടുക്കുകയും, അവന്റെ പാപങ്ങൾ മായ്ച്ചു കളയുകയും ചെയ്യാതിരിക്കില്ല." (ന)', 'مَعْدَانَ بْنِ طَلْحَةَ الْيَعْمُرِيِّ قَالَ', 'മഅ്ദാനുബ്നുത്വൽഹ', null, null, array['ن']::text[], array['ന']::text[], null, null, 493, 493, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 221, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ أَنَّ النَّاسَ قَالُوا: يَا رَسُولَ اللهِ هَلْ نَرَى رَبَّنَا يَوْمَ الْقِيَامَةِ؟ قَالَ: "هَلْ تُمَارُونَ فِي الْقَمَرِ لَيْلَةَ الْبَدْرِ لَيْسَ دُونَهُ سَحَابٌ". قَالُوا: لَا يَا رَسُولَ اللهِ، قَالَ: "فَهَلْ تُمَارُونَ فِي الشَّمْسِ لَيْسَ دُونَهَا سَحَابٌ". قَالُوا: لَا يَا رَسُولَ اللهِ، قَالَ: "فَإِنَّكُمْ تَرَوْنَهُ كَذَلِكَ، يُحْشَرُ النَّاسُ يَوْمَ الْقِيَامَةِ، فَيَقُولُ: مَنْ كَانَ يَعْبُدُ شَيْئًا فَلْيَتَّبِعْ، فَمِنْهُمْ مَنْ يَتَّبِعُ الشَّمْسَ، وَمِنْهُمْ مَنْ يَتَّبِعُ الْقَمَرَ، وَمِنْهُمْ مَنْ يَتَّبِعُ الطَّوَاغِيتَ، وَتَبْقَى هَذِهِ الْأُمَّةُ فِيهَا مُنَافِقُوهَا، فَيَأْتِيهِمُ اللهُ فَيَقُولُ أَنَا رَبُّكُمْ فَيَقُولُونَ: هَذَا مَكَانُنَا حَتَّى يَأْتِيَنَا رَبُّنَا، فَإِذَا جَاءَ رَبُّنَا عَرَفْنَاهُ، فَيَأْتِيهِمُ اللهُ عَزَّ وَجَلَّ فَيَقُولُ: أَنَا رَبُّكُمْ فَيَقُولُونَ: أَنْتَ رَبُّنَا فَيَدْعُوهُمْ فَيُضْرَبُ الصِّرَاطُ بَيْنَ ظَهْرَانَيْ جَهَنَّمَ، فَأَكُونُ أَوَّلَ مَنْ يَجُوزُ مِنَ الرُّسُلِ بِأُمَّتِهِ، وَلَا يَتَكَلَّمُ يَوْمَئِذٍ أَحَدٌ إِلَّا الرُّسُلُ، وَكَلَامُ الرُّسُلِ يَوْمَئِذٍ: اللَّهُمَّ سَلِّمْ سَلِّمْ. وَفِي جَهَنَّمَ كَلَالِيبُ مِثْلُ شَوْكِ السَّعْدَانِ، هَلْ رَأَيْتُمْ شَوْكَ السَّعْدَانِ؟" قَالُوا: نَعَمْ، قَالَ: "فَإِنَّهَا مِثْلُ شَوْكِ السَّعْدَانِ غَيْرَ أَنَّهُ لَا يَعْلَمُ قَدْرَ عِظَمِهَا إِلَّا اللهُ، تَخْطَفُ النَّاسَ بِأَعْمَالِهِمْ، فَمِنْهُمْ مَنْ يُوبَقُ بِعَمَلِهِ، وَمِنْهُمْ مَنْ يُخَرْدَلُ ثُمَّ يَنْجُو، حَتَّى إِذَا أَرَادَ اللهُ رَحْمَةَ مَنْ أَرَادَ مِنْ أَهْلِ النَّارِ، أَمَرَ اللهُ الْمَلَائِكَةَ أَنْ يُخْرِجُوا مَنْ كَانَ يَعْبُدُ اللهَ، فَيُخْرِجُونَهُمْ وَيَعْرِفُونَهُمْ بِآثَارِ السُّجُودِ، وَحَرَّمَ اللهُ عَلَى النَّارِ أَنْ تَأْكُلَ أَثَرَ السُّجُودِ، فَيَخْرُجُونَ مِنَ النَّارِ، فَكُلُّ ابْنِ آدَمَ تَأْكُلُهُ النَّارُ إِلَّا أَثَرَ السُّجُودِ، فَيَخْرُجُونَ مِنَ النَّارِ قَدِ امْتَحَشُوا، فَيُصَبُّ عَلَيْهِمْ مَاءُ الْحَيَاةِ، فَيَنْبُتُونَ كَمَا تَنْبُتُ الْحِبَّةُ فِي حَمِيلِ السَّيْلِ، ثُمَّ يَفْرُغُ اللهُ مِنَ الْقَضَاءِ بَيْنَ الْعِبَادِ، وَيَبْقَى رَجُلٌ بَيْنَ الْجَنَّةِ وَالنَّارِ، وَهُوَ آخِرُ أَهْلِ النَّارِ دُخُولًا الْجَنَّةَ مُقْبِلٌ بِوَجْهِهِ قِبَلَ النَّارِ، فَيَقُولُ: يَا رَبِّ اصْرِفْ وَجْهِي عَنِ النَّارِ قَدْ قَشَبَنِي رِيحُهَا، وَأَحْرَقَنِي ذَكَاؤُهَا، فَيَقُولُ: هَلْ عَسَيْتَ إِنْ فُعِلَ ذَلِكَ بِكَ أَنْ تَسْأَلَ غَيْرَ ذَلِكَ، فَيَقُولُ: لَا وَعِزَّتِكَ، فَيُعْطِي اللهُ مَا يَشَاءُ مِنْ عَهْدٍ وَمِيثَاقٍ، فَيَصْرِفُ اللهُ وَجْهَهُ عَنِ النَّارِ، فَإِذَا أَقْبَلَ بِهِ عَلَى الْجَنَّةِ رَأَى بَهْجَتَهَا سَكَتَ مَا شَاءَ اللهُ أَنْ يَسْكُتَ، ثُمَّ قَالَ: يَا رَبِّ قَدِّمْنِي عِنْدَ بَابِ الْجَنَّةِ، فَيَقُولُ اللهُ لَهُ: أَلَيْسَ قَدْ أَعْطَيْتَ الْعُهُودَ وَالْمِيثَاقَ أَنْ لَا تَسْأَلَ غَيْرَ الَّذِي كُنْتَ سَأَلْتَ؟ فَيَقُولُ: يَا رَبِّ لَا أَكُونُ أَشْقَى خَلْقِكَ، فَيَقُولُ: فَمَا عَسَيْتَ إِنْ أُعْطِيتَ ذَلِكَ أَنْ لَا تَسْأَلَ غَيْرَهُ، فَيَقُولُ: لَا وَعِزَّتِكَ لَا أَسْأَلُ غَيْرَ ذَلِكَ، فَيُعْطِي رَبَّهُ مَا شَاءَ مِنْ عَهْدٍ وَمِيثَاقٍ، فَيُقَدِّمُهُ إِلَى بَابِ الْجَنَّةِ، فَإِذَا بَلَغَ بَابَهَا، فَرَأَى زَهْرَتَهَا وَمَا فِيهَا مِنَ النَّضْرَةِ وَالسُّرُورِ، فَيَسْكُتُ مَا شَاءَ اللهُ أَنْ يَسْكُتَ، فَيَقُولُ: يَا رَبِّ أَدْخِلْنِي الْجَنَّةَ، فَيَقُولُ اللهُ عَزَّ وَجَلَّ: وَيْحَكَ يَا ابْنَ آدَمَ مَا أَغْدَرَكَ!! أَلَيْسَ قَدْ أَعْطَيْتَ الْعُهُودَ وَالْمِيثَاقَ أَنْ لَا تَسْأَلَ غَيْرَ الَّذِي أُعْطِيتَ؟ فَيَقُولُ: يَا رَبِّ لَا تَجْعَلْنِي أَشْقَى خَلْقِكَ، فَيَضْحَكُ اللهُ عَزَّ وَجَلَّ مِنْهُ، ثُمَّ يَأْذَنُ لَهُ فِي دُخُولِ الْجَنَّةِ، فَيَقُولُ: تَمَنَّ، فَيَتَمَنَّى حَتَّى إِذَا انْقَطَعَ أُمْنِيَّتُهُ، قَالَ اللهُ عَزَّ وَجَلَّ: زِدْ مِنْ كَذَا وَكَذَا، أَقْبَلَ يُذَكِّرُهُ رَبُّهُ حَتَّى إِذَا انْتَهَتْ بِهِ الْأَمَانِيُّ، قَالَ اللهُ تَعَالَى: لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ". قَالَ أَبُو سَعِيدٍ الْخُدْرِيُّ لِأَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُمَا إِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "قَالَ اللهُ: لَكَ ذَلِكَ وَعَشَرَةُ أَمْثَالِهِ". قَالَ أَبُو هُرَيْرَةَ: لَمْ أَحْفَظْ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِلَّا قَوْلَهُ: "لَكَ ذَلِكَ وَمِثْلُهُ مَعَهُ". قَالَ أَبُو سَعِيدٍ: إِنِّي سَمِعْتُهُ يَقُولُ: "ذَلِكَ لَكَ وَعَشَرَةُ أَمْثَالِهِ". (خ)', 'അബൂഹുറൈറ(റ): അല്ലാഹുവിന്റെ ദൂതരേ! അന്ത്യനാളിൽ നാം നമ്മുടെ നാഥനെ ദർശിക്കുമോ? നബി(സ) പറഞ്ഞു: "ഒട്ടും മേഘമില്ലാത്ത രാവിൽ പൂർണ്ണ ചന്ദ്രനെ ദർശിച്ചാൽ അതിൽ വല്ല സംശയവുമുണ്ടാവുമോ?" അവർ പറഞ്ഞു: ''ഇല്ല'' "ആകാശത്ത് ഒട്ടും മേഘമില്ലാത്ത ദിനത്തിൽ സൂര്യനുദിച്ചുകണ്ടാൽ നിങ്ങൾക്കു സംശയം തോന്നുമോ? അതു പോലെത്തന്നെ നിങ്ങൾ നാഥനെ ദർശിക്കും. അന്ത്യനാളിൽ ജനങ്ങൾ ഒരുമിച്ചു കൂട്ടപ്പെടും. അപ്പോൾ അല്ലാഹു പറയും: ''വല്ലവനും(എന്നെ വിട്ടിട്ട്) വല്ല വസ്തുവിനെയും പൂജിച്ചു പേന്നിട്ടുണ്ടെങ്കിൽ അവൻ അതിന്റെ പിന്നാലെ പൊയ്ക്കൊള്ളട്ടെ - അങ്ങനെ മനുഷ്യരിൽ ചിലർ സൂര്യനേയും ചന്ദ്രനേയും, പിശാചുകളേയും പിന്തുടരും - അവസാനം ഈ സമുദായം (മുസ്ലിംകൾ) മാത്രം അവശേഷിക്കും - അവരിൽത്തന്നെ ചില കപടവിശ്വാസികളുമുണ്ടായിരിക്കും - (അവർക്ക് ഗ്രഹിക്കാൻ കഴിയാത്ത രൂപത്തിൽ) അല്ലാഹു അവരുടെയടുക്കൽ ചെല്ലും. ''ഞാനാണ് നിങ്ങളുടെ രക്ഷിതാവ്'' എന്ന് അവൻ പറയും. അവർ പറയും: ഞങ്ങളുടെ രക്ഷിതാവ് വരും വരേക്കും ഞങ്ങൾ ഈ സ്ഥലത്തുതന്നെ നിൽക്കും. ഞങ്ങളുടെ രക്ഷിതാവ് വന്നുകഴിഞ്ഞാലോ, അവനെ ഞങ്ങൾക്ക് (വ്യക്തമായി) മനസ്സിലാക്കാൻ കഴിയും. അപ്പോൾ (അവർക്കു വ്യകതമായി ഗ്രഹിക്കാൻ കഴിയുന്നവിധത്തിൽ) അവരുടെയടുക്കൽ അല്ലാഹു ചെല്ലും. എന്നിട്ടവൻ പറയും: ''ഞാനാണ് നിങ്ങളുടെ രക്ഷിതാവ്.'' ''നീ തന്നെയാണ് ഞങ്ങളുടെ രക്ഷിതാവ്'' എന്ന് അവർ ഏറ്റുപറയും. അല്ലാഹു അവരെ വിളിക്കും. നരകത്തിന്നു മുകളിലൂടെ ഒരു പാത സ്ഥാപിക്കപ്പെടും. ദൈവദൂതരിൽ വെച്ച്, അനുയായികളേയും കൊണ്ട് ഏറ്റവുമാദ്യം ആ പാതയിലൂടെ കടന്നു പോകുന്നത് ഞാൻ (മുഹമ്മദ് നബി) ആയിരിക്കും. അന്നു ദൈവദൂതന്മാരല്ലാതെ മറ്റാരും ആ മഹാസമ്മേളനത്തിൽ വെച്ച് സംസാരിക്കുകയില്ല - ''അല്ലാഹുവേ! രക്ഷിക്കേണമേ!'' എന്നായിരിക്കും ദൈവദൂതന്മാരുടെ വാക്കുകൾ - നരകത്തിൽ ''സഅദാന്റെ'' മുള്ള് പോലെ, കൊളുത്തി വലിക്കാനുള്ള ചില ഇരുമ്പുതോട്ടികളുണ്ടാരിക്കും. സഅദാനിന്റെ മുള്ള് നിങ്ങൾ കണ്ടിട്ടുണ്ടോ?" അനുചരന്മാർ അരുളി: ''അതെ, കണ്ടിട്ടുണ്ട്.'' തിരുമേനി(സ) പറഞ്ഞു: "എന്നാൽ അത് ''സഅദാനിന്റെ മുള്ള് പോലെയായിരിക്കും; അതിന്റെ വലിപ്പം അല്ലാഹുവിന്നല്ലാതെ മറ്റാർക്കും അറിയുകയില്ല. ആ തോട്ടികൾ, മനുഷ്യരെ അവരുടെ കർമ്മങ്ങളുടെ സ്ഥിതിക്കനുസരിച്ച് കൊളുത്തി വലിക്കും. തങ്ങളുടെ കർമ്മഫലമായി, അങ്ങേയറ്റം യാതനകളിലകപ്പെട്ട, മനുഷ്യരിൽ ചിലർ നശിച്ചുകൊണ്ടേയിരിക്കും. ചിലരുടെ ശരീരങ്ങൾ തുണ്ടുതുണ്ടായി മുറിഞ്ഞുപോകും. പിന്നീട് നരകവാസികളിൽനിന്നു താനുദ്ദേശിക്കുന്നവരെ തന്റെ കാരുണ്യം മൂലം അല്ലാഹു മോചിപ്പിക്കും. അല്ലാഹുവിനെ ആരാധിച്ചിരുന്നവരെ നരകത്തിൽനിന്നു മോചിപ്പിക്കുവാൻ മലക്കുകളോട് അല്ലാഹു കൽപിക്കും. മലക്കുകൾ അവരെ നരകത്തിൽനിന്നു പുറത്തേക്കു കൊണ്ടുവരും. (നെറ്റിയിലുള്ള) സുജൂദിന്റെ അടയാളങ്ങൾകൊണ്ടാണ് മലക്കുകൾ അവരെ തിരിച്ചറിയുക. സുജൂദിന്റെ ചിഹനമുള്ള സ്ഥലം കരിച്ചുകളയരുതെന്നു നരകത്തോട് അല്ലാഹു കൽപ്പിച്ചിട്ടുണ്ടായിരിക്കും. അവർ നരകത്തിൽ നിന്നു പുറത്തുവരും. സുജൂദിന്റെ അടയാളമുള്ള സ്ഥലമൊഴിച്ച് ബാക്കി ഭാഗങ്ങളെല്ലാം അഗ്നി കരിച്ചിട്ടുണ്ടായിരിക്കും. അവരുടെ ശരീരം കറുപ്പു നിറമായിരിക്കും. അപ്പോൾ ''മാഉൽഹയാത്ത്'' (ജീവജലം) അവരുടെ ശരീരത്തിലൊഴിക്കും. വഴിവെള്ളത്തിലൂടെ ഒലിച്ചുവരുന്ന ചണ്ടിയിൽ വിത്ത് മുളച്ചുവരും പോലെ അവർ വളർന്നു വികസിക്കും. അനന്തരം തന്റെ ദാസന്മാർക്കിടയിൽ വിധി കൽപ്പിക്കുന്ന ജോലിയിൽ നിന്നു അല്ലാഹു വിരമിക്കും. ഒടുവിൽ, ഒരു മനുഷ്യൻ സ്വർഗ്ഗത്തിന്നും നരകത്തിന്നുമിടക്ക് അവശേഷിക്കും - അവനാണ് നരകവാസികളിൽ ഏറ്റവും അവസാനമായി സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കുക - നരകത്തിന്റെ നേരെ മുഖം തരിച്ചുകൊണ്ടാണ് അവൻ നിൽക്കുക. ''രക്ഷിതാവേ! നരകത്തിന്റെ ഭാഗത്തുനിന്നു നീ എന്റെ മുഖത്തെ തിരിക്കേണമോ! അതിന്റെ ദുർഗ്ഗന്ധം എന്നിൽ വിഷം കലർത്തിയിരക്കുന്നു; അതിന്റെ ജ്വാലകൾ എന്നെ കരിക്കുകയും ചെയ്തിരിക്കുന്നു'' എന്ന് അവൻ പറഞ്ഞുകൊണ്ടിരിക്കും. അല്ലാഹു ചോദിക്കും: ''അക്കാര്യം നിനക്ക് ചെയ്തുതന്നാൽ മറ്റു വല്ലതും നീ ചോദിച്ചേക്കുമോ?'' അവൻ പറയും: ''ഇല്ല, ഞാൻ ചോദിക്കുകയില്ല. നിന്റെ പ്രതാപത്തെക്കൊണ്ടു സത്യം.'' അങ്ങനെ അവൻ അല്ലാഹുവിന്ന് പ്രതിജ്ഞയും കരാറുമെല്ലാം നൽകും. അല്ലാഹു അവന്റെ മുഖത്തെ നരകത്തിന്റെ ഭാഗത്തുനിന്നു തിരിച്ചുവിടും. ഒടുവിൽ അവനെ സ്വർഗ്ഗത്തിന്റെ ഭാഗത്തേക്ക് അല്ലാഹു തിരിച്ചു നിർത്തുമ്പോൾ അതിന്റെ തേജസ്സ് അവൻ കാണും. അല്ലാഹു ഉദ്ദേശിക്കുന്ന സമയം വരെ അവൻ അടങ്ങിനിൽക്കും. പിന്നീട് അവൻ പ്രാർത്ഥിക്കും: ''രക്ഷിതാവേ! എന്നെ നീ സ്വർഗ്ഗത്തിന്റെ വാതിൽക്കലേക്ക് അടുപ്പിച്ചുതരേണമേ!'' അല്ലാഹു ചോദിക്കും: ''നീ മുമ്പ് ആവശ്യപ്പെട്ടതല്ലാതെ, മറ്റൊന്നും ആവശ്യപ്പെടുകയില്ലെന്ന് കരാർ ചെയ്തിട്ടില്ലേ?'' അവൻ പറയും: എന്റെ റബ്ബേ, ഞാൻ നിന്റെ അടിമകളിൽ ഏറ്റവും പരാചിതനാവാൻ ആഗ്രഹിക്കുന്നില്ല. അപ്പോൾ അല്ലാഹു ചോദിക്കും: അക്കാര്യം നിനക്ക് നൽകപ്പെട്ടാൽ മറ്റു വല്ലതും ചോദിച്ചേക്കുമോ? അവൻ പറയും: ''നിന്റെ പ്രതാപത്തെകൊണ്ടു സത്യം ഇല്ല, മറ്റൊന്നും ഞാൻ ചോദിക്കുകയില്ല.'' അവൻ തന്റെ രക്ഷിതാവിന്ന്, അവനുദ്ദേശിച്ച പ്രതിജ്ഞകളും കരാറുകളുമെല്ലാം നൽകും. അപ്പോൾ അല്ലാഹു അവനെ സ്വർഗ്ഗത്തിന്റെ വാതിൽക്കലേക്ക് അടുപ്പിക്കും. സ്വർഗ്ഗത്തിന്റെ വാതിൽക്കലെത്തി, അതിന്റെ പ്രഭയും സ്വർഗ്ഗത്തിലുള്ള നിറപ്പകിട്ടുകളും ആനന്ദകരമായ കാഴ്ചകളും കാണുമ്പോൾ അല്ലാഹു ഉദ്ദേശിച്ച സമയം വരെ അവൻ അടങ്ങിയിരിക്കും. അവൻ പറയും ''രക്ഷിതാവേ! നീ എന്നെ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കേണമേ!'' അല്ലാഹു ചോദിക്കും: ''മനുഷ്യപുത്രാ! നിന്റെ കാര്യം വളരെ പരിതാപകരം തന്നെ! നീ എങ്ങനെ ഇത്രയും കടുത്ത പ്രതിജ്ഞാലംഘകനായിത്തീർന്നു?'' അപ്പോൾ അവൻ പറയും: റബ്ബേ, എന്നെ നീ നിന്റെ അടിമകളിൽ ഏറ്റവും പരാചിതനാക്കരുതേ. അപ്പോൾ അല്ലാഹു ചിരിക്കുകയും അവൻ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാൻ അനുവാദം നൽകുകയും ഇപ്രകാരം പറയുകയും ചെയ്യും: ''നിനക്ക് അപേക്ഷിക്കാനുള്ളതെല്ലാം അപേക്ഷിച്ചുകൊള്ളുക.'' തന്റെ അപേക്ഷകളെല്ലാം അവൻ ദൈവസന്നിധിയിൽ സമർപ്പിക്കും. അവന്റെ അപേക്ഷകളെല്ലാം സമർപ്പിച്ചുകഴിഞ്ഞാൽ അല്ലാഹു അവനോടു പറയും: ''നീ ഇന്നിന്ന കാര്യങ്ങളെല്ലാം അപേക്ഷിക്കുക.'' അവനെ അഭിമുഖീകരിച്ചിട്ട്, അവന്റെ രക്ഷിതാവ്, പല അപേക്ഷകളും അവനെ ഓർമ്മിപ്പിക്കും. അവന്റെ ആഗ്രഹങ്ങളെല്ലാം പൂർത്തിയായിക്കഴിഞ്ഞാൽ അല്ലാഹു പറയും: ഇക്കാര്യങ്ങളെല്ലാം നിനക്കിതാ അനുവദിച്ചു തന്നിരിക്കുന്നു. അതോടൊപ്പം അത്രയും അനുഗ്രഹങ്ങൾ വേറെയും." ''നിനക്ക് ഇക്കാര്യങ്ങളും ഇവയുടെ പത്തിരട്ടി അനുഗ്രഹങ്ങളും ഞാനിതാ അനുവദിച്ചു തന്നിരിക്കുന്നു'' എന്ന് അല്ലാഹു പറയുമെന്നാണ് തിരുമേനി(സ) അരുളിയതെന്നു അബൂഹുറൈറ(റ)യോട് അബൂസഈദുൽഖുദ്രി(റ) പറഞ്ഞു. "നിനക്ക് ഈ അനുഗ്രഹങ്ങളും ഇവയോടൊപ്പം തന്നെ ഇവക്ക് തുല്യമായ മറ്റനുഗ്രഹങ്ങളും ചെയ്തുതരുമെന്ന് അല്ലാഹു കൽപിക്കും" എന്നു തിരുമേനി(സ) അരുളിയതായിട്ടാണ് ഞാൻ ഓർമ്മിക്കുന്നതെന്ന് അബൂഹുറൈറ(റ) പറഞ്ഞു: അങ്ങനെയല്ല, "നിനക്ക് ഈ അനുഗ്രഹങ്ങൾ മുഴുവനും ഇവയുടെ പത്തിരട്ടി അനുഗ്രങ്ങളും ലഭിക്കുമെ"ന്ന് തിരുമേനി(സ) അരുളുന്നത് ഞാൻ കേട്ടിട്ടുണ്ടെന്നാണ് അബൂസഈദുൽ ഖുദ്രി(റ) പറയുന്നത്. (ബു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 493, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=58 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 222, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا جِئْتُمْ إِلَى الصَّلَاةِ وَنَحْنُ سُجُودٌ فَاسْجُدُوا، وَلَا تَعُدُّوهَا شَيْئًا، وَمَنْ أَدْرَكَ الرَّكْعَةَ فَقَدْ أَدْرَكَ الصَّلَاةَ". (د)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കാരത്തിന് വന്നാൽ ഞങ്ങൾ സുജൂദിലാണങ്കിൽ നിങ്ങളും സുജൂദ് ചെയ്യുക. നിങ്ങൾ അത് പരിഗണിക്കേണ്ടതില്ല, ആർക്കെങ്കിലും ഒരു റക്അത്ത് ലഭിച്ചാൽ അയാൾക്ക് ആ നിസ്കാരം ലഭിച്ചു." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=59 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 223, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا، وَبَاتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عِنْدَهَا، فَرَأَيْتُهُ قَامَ لِحَاجَتِهِ، فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ الْوُضُوءَيْنِ، ثُمَّ أَتَى فِرَاشَهُ فَنَامَ، ثُمَّ قَامَ قَوْمَةً أُخْرَى، فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا هُوَ الْوُضُوءُ، ثُمَّ قَامَ يُصَلِّي. وَكَانَ يَقُولُ فِي سُجُودِهِ: "اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ تَحْتِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا، وَاجْعَلْ أَمَامِي نُورًا، وَاجْعَلْ خَلْفِي نُورًا، وَأَعْظِمْ لِي نُورًا". ثُمَّ نَامَ حَتَّى نَفَخَ، فَأَتَاهُ بِلَالٌ فَأَيْقَظَهُ لِلصَّلَاةِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): ഞാൻ എന്റെ മാതാവിന്റെ സഹോദരിയായ മൈമൂനബിൻത് ഹാരിസിന്റെ വീട്ടിൽ രാത്രി താമസിച്ചു. നബി(സ) അന്ന് അവരുടെ അടുത്തായിരുന്നു. നബി(സ) വിസർജ്ജനാവശ്യത്തിന് എഴുന്നേറ്റ് തോൽപാത്രം അഴിച്ച് അതിൽ നിന്ന് വുളു ചെയ്തു, രണ്ട് വുദുകൾക്കിടയിൽ (അപൂർണ്ണമായ വുദു അഥവാ നജസ് ശുദ്ധീകരണം) പിന്നെ വിരിപ്പിൽ പോയി ഉറങ്ങി. വീണ്ടും ഉണർന്നു. തോൽപാത്രം കെട്ടഴിച്ച് വുദു ചെയ്തു. അത് പൂർണ്ണമായ വുദു ആയിരുന്നു. പിന്നീട് നിസ്കരിച്ചു. നബി(സ) സുജൂദിൽ ഇപ്രകാരം പറഞ്ഞു: "അല്ലാഹുവേ, എന്റെ ഹൃദയത്തിൽ നീ വെളിച്ചം നൽകേണമേ. എന്റെ കേൾവിയെ പ്രകാശപൂരിതമാക്കേണമേ, കാഴ്ചയിലും നീ പ്രകാശമേകേണമേ, എന്റെ കീഴ്ഭാഗത്തും മേൽഭാഗത്തും വലതുഭാഗത്തും ഇടതു ഭാഗത്തും മുന്നിലും പിന്നിലും പ്രകാശം നൽകേണമേ. നീ എനിക്ക് പ്രകാശം വർദ്ധിപ്പിക്കേണമേ." പിന്നീട് നബി(സ) കൂർക്കം വലിച്ചുറങ്ങി. ശേഷം ബിലാൽ(റ) അരികിലെത്തി നിസ്കാരത്തിന്നായി ഉണർത്തി. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 496, 496, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 224, 'عَنْ مُحَمَّدِ بْنِ مَسْلَمَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَامَ مِنَ اللَّيْلِ يُصَلِّي تَطَوُّعًا قَالَ إِذَا سَجَدَ: "اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ. اللَّهُمَّ أَنْتَ رَبِّي، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ". (ن)', 'മുഹമ്മദുബ്നു മസ്ലമ(റ): നബി(സ) രാത്രി എഴുന്നേറ്റാൽ സുന്നത്ത് നിസ്കരിക്കും. സുജൂദിൽ ഇപ്രകാരം പറയും: "അല്ലാഹുവേ, നിനക്കിതാ ഞാൻ സുജൂദ് ചെയ്യുന്നു, നിന്നിൽ വിശ്വസിക്കുന്നു, നിനക്കു വിധേയനായിരിക്കുന്നു, അല്ലാഹുവേ, നീയാണ് എന്റെ നാഥൻ. എന്റെ മുഖം നമിച്ചിരിക്കുന്നു, അതിനെ സൃഷ്ടിക്കുകയും രൂപപ്പെടുത്തുകയും ചെയ്തവന്, കാഴ്ചയും കേൾവിയും നൽകിയവന്. ഏറ്റവും നന്നായി സൃഷ്ടി നടത്തുന്ന അല്ലാഹു പരിശുദ്ധനാകുന്നു." (ന)', 'مُحَمَّدِ بْنِ مَسْلَمَةَ', 'മുഹമ്മദുബ്നു മസ്ലമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 225, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِ الْقُرْآنِ بِاللَّيْلِ: "سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ". (ن)', 'ആഇശ(റ): രാത്രിയിലെ ഖുർആൻ പാരായണത്തിനിടയിൽ സുജൂദ് ചെയ്യുമ്പോൾ നബി(സ) ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "എന്റെ മുഖം നമിച്ചിരിക്കുന്നു, അതിനെ സൃഷ്ടിക്കുകയും രൂപപ്പെടുത്തുകയും ചെയ്തവന്, തന്റെ ശക്തി കൊണ്ട് കാഴ്ചയും കേൾവിയും നൽകിയവന്." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 226, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: فَقَدْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَظَنَنْتُ أَنَّهُ ذَهَبَ إِلَى بَعْضِ نِسَائِهِ، فَتَحَسَّسْتُهُ فَإِذَا هُوَ رَاكِعٌ أَوْ سَاجِدٌ، يَقُولُ: "سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، لَا إِلَهَ إِلَّا أَنْتَ". فَقَالَتْ: بِأَبِي أَنْتَ وَأُمِّي، إِنِّي لَفِي شَأْنٍ وَإِنَّكَ لَفِي آخَرَ. (ن)', 'ആഇശ(റ): ഒരു രാത്രിയിൽ ഞാൻ തിരുമേനി(സ)യെ (എന്റെ അടുക്കൽ) കാണാതായി. അവിടുത്തെ മറ്റു പത്നിമാരുടെ അടുക്കൽ പോയതായിരിക്കും എന്നു ഞാൻ ധരിച്ചു. ഞാൻ തിരുമേനി(സ)യെ തിരഞ്ഞുനോക്കി. അപ്പോഴതാ അവിടുന്ന് റുകൂഅ് ചെയ്യുകയോ സുജൂദ് ചെയ്യുകയോ ആണ്. അന്നേരം തിരുമേനി(സ) ഇപ്രകാരം പറയുന്നുണ്ട്: "സുബ്ഹാനകല്ലാഹുമ്മ വബിഹംദിക, ലാഇലാഹ ഇല്ല അൻത" (അല്ലാഹുവേ, നിന്റെ പരിശുദ്ധിയെ വാഴ്ത്തുന്നതോടൊപ്പം തന്നെ ഞാൻ സ്തുതിക്കുന്നു. നീയല്ലാതെയാതൊരു ദൈവവുമില്ല) അപ്പോൾ ആഇശ(റ) പറഞ്ഞു: എന്റെ മാതാവും പിതാവും അങ്ങയ്ക്ക് ദണ്ഢമാണ്, ഞാനൊരു കാര്യത്തിൽ (മറ്റൊരു ചിന്തയിൽ) ആയിരുന്നു. താങ്കളാവട്ടെ, മറ്റൊന്നിലും (വ്യാപൃതനായരിക്കുന്നു). (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=60 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 227, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: نَهَانِي حِبِّي صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَنْ ثَلَاثٍ – لَا أَقُولُ: نَهَى النَّاسَ – نَهَانِي عَنْ تَخَتُّمِ الذَّهَبِ، وَعَنْ لُبْسِ الْقَسِّيِّ وَعَنِ الْمُعَصْفَرِ الْمُفَدَّمَةِ، وَلَا أَقْرَأُ سَاجِدًا وَلَا رَاكِعًا". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): അലി(റ) പറഞ്ഞു: എന്റെ പ്രിയപ്പെട്ടവർ (റസൂൽ) മൂന്ന് കാര്യങ്ങൾ എന്നെ വിലക്കി. ജനങ്ങളെ വിലക്കിയെന്ന് ഞാൻ പറയുന്നില്ല. സ്വർണ്ണ മോതിരവും, പട്ടുവസ്ത്രവും, കാവി വസ്ത്രവും ധരിക്കൽ, റുകൂഇലും സുജൂദിലും (ഖുർആൻ) പാരായണം ചെയ്യൽ എന്നിവയാണവ. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 497, 497, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=61 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 228, 'عَنْ شَدَّادٍ رَضِيَ اللهُ عَنْهُ قَالَ: خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي إِحْدَى صَلَاتَيِ الْعِشَاءِ وَهُوَ حَامِلٌ حَسَنًا أَوْ حُسَيْنًا، فَتَقَدَّمَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَهُ، ثُمَّ كَبَّرَ لِلصَّلَاةِ، فَصَلَّى فَسَجَدَ بَيْنَ ظَهْرَانَيْ صَلَاتِهِ سَجْدَةً أَطَالَهَا، قَالَ: فَرَفَعْتُ رَأْسِي، وَإِذَا الصَّبِيُّ عَلَى ظَهْرِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَهُوَ سَاجِدٌ، فَرَجَعْتُ إِلَى سُجُودِي، فَلَمَّا قَضَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ النَّاسُ: يَا رَسُولَ اللهِ، إِنَّكَ سَجَدْتَ بَيْنَ ظَهْرَانَيْ صَلَاتِكَ سَجْدَةً أَطَلْتَهَا، حَتَّى ظَنَنَّا أَنَّهُ قَدْ حَدَثَ أَمْرٌ، أَوْ أَنَّهُ يُوحَى إِلَيْكَ. قَالَ: "كُلُّ ذَلِكَ لَمْ يَكُنْ، وَلَكِنَّ ابْنِي ارْتَحَلَنِي، فَكَرِهْتُ أَنْ أُعَجِّلَهُ حَتَّى يَقْضِيَ حَاجَتَهُ". (ن)', 'ശദ്ദാദ്(റ): നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് പുറപ്പെട്ടു. രാത്രിയിലെ ഒരു നിസ്കാരം നിർവ്വഹിക്കാൻ വേണ്ടി അവിടുന്ന് ഹസനെയോ ഹുസൈനെയോ എടുത്തിരുന്നു. നബി(സ) മുന്നോട്ട് വന്ന് അവനെ താഴെ വെച്ച് നിസ്കാരത്തിന് തക്ബിർ ചൊല്ലി; പിന്നീട് നിസ്കാരത്തിനിടയിൽ സുജൂദിൽ പോയി. ദീർഘമായ ഒരു സുജൂദായിരുന്നു അത്. അദ്ദേഹം തുടർന്ന് പറഞ്ഞു: ഞാൻ തലയുയർത്തി നോക്കി, അപ്പോൾ കുട്ടി റസൂലിന്റെ മുതുകിലുണ്ടായിരുന്നു, ഞാൻ സുജൂദിലേക്ക് മടങ്ങി. നിസ്കാരം കഴിഞ്ഞപ്പോൾ ജനങ്ങൾ പ്രവാചകനോട് ചോദിച്ചു: അല്ലാഹുവന്റെ ദൂതരേ, താങ്കൾ നിസ്കാരത്തിൽ വളരെ ദീർഘിച്ച ഒരു സുജൂദ് ചെയ്തിരിക്കുന്നു, അങ്ങേയ്ക്ക് എന്തോ സംഭവിച്ചിട്ടുണ്ടായിരിക്കും, അല്ലെങ്കിൽ വഹ്യ് ഇറങ്ങിയിരിക്കും എന്ന് ഞങ്ങൾ വിചാരിച്ചു പോയി, അപ്പോൾ നബി(സ) പറഞ്ഞു: "അങ്ങനെയൊന്നുമായിരുന്നില്ല, എന്റെ മകൻ എന്നെ വാഹനമാക്കിയിരുന്നു (മുതുകിൽ ഇരുന്നു). അവന്റെ ആവശ്യം നിർവ്വഹിക്കാതെ ധൃതിപ്പെടുന്നത് ഞാൻ വെറുത്തു." (ന)', 'شَدَّادٍ', 'ശദ്ദാദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 229, 'عَنْ أَبِي قِلَابَةَ قَالَ: جَاءَنَا أَبُو سُلَيْمَانَ مَالِكُ بْنُ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ إِلَى مَسْجِدِنَا فَقَالَ: وَاللهِ إِنِّي لَأُصَلِّي بِكُمْ وَمَا أُرِيدُ الصَّلَاةَ، وَلَكِنِّي أُرِيدُ أَنْ أُرِيَكُمْ كَيْفَ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، وَذَكَرَ: أَنَّهُ كَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ الْآخِرَةِ فِي الرَّكْعَةِ الْأُولَى قَعَدَ ثُمَّ قَامَ. وَفِي رِوَايَةٍ قَالَ: فَقَعَدَ فِي الرَّكْعَةِ الْأُولَى حِينَ رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ الْآخِرَةِ. وَفِي رِوَايَةٍ: إِذَا كَانَ فِي وِتْرٍ مِنْ صَلَاتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا. (خ,د,ت,ن)', 'അബൂഖിലാബ(റ): അബൂസുലൈമാൻ മാലികുബ്നുൽ ഹുവൈരിസ്(റ) ഞങ്ങളുടെ പള്ളിയിലേക്കു വന്നു, എന്നിട്ടദ്ദേഹം പറഞ്ഞു: അല്ലാഹുവാണെ, ഞാൻ നിങ്ങളെയുമായി നിസ്കരിക്കും. ഞാൻ (ആ നിസ്കാരംകൊണ്ട്) യഥാർത്ഥമായ നിസ്കാരമല്ല ഉദ്ദേശിക്കുന്നത്. എന്നാൽ പ്രവാചകൻ(സ) എപ്രകാരം നിസ്കരിച്ചതായി ഞാൻ കണ്ടുവോ അത് നിങ്ങൾക്ക് കാണിച്ചു തരുവാനാണ് ഞാനുദ്ദേശിക്കുന്നത്. അദ്ദേഹം തുടർന്നു പറഞ്ഞു: അവിടുന്ന് ഒന്നാമത്തെ റക്അത്തിലെ രണ്ടാമത്തെ സുജൂദിൽ നിന്നു തലയുയർത്തിയപ്പോൾ ഇരിക്കുകയും ശേഷം എഴുന്നേൽക്കുകയും ചെയ്തു. മറ്റൊരു റിപ്പോർട്ടിൽ: അദ്ദേഹം പറഞ്ഞു: ഒന്നാമത്തെ റക്അത്തിൽ അവസാനത്തെ സുജൂദിൽ അവിടുന്ന് തന്റെ തലയുർത്തിയപ്പോൾ ഇരുന്നു. ഒരു റിപ്പോർട്ട്: അവിടുന്ന് ഒന്ന്, മൂന്ന് റക്അത്തുകൾ കഴിഞ്ഞാൽ ശരിയാം വിധം ഇരുന്ന ശേഷമല്ലാതെ എഴുന്നേൽക്കാറില്ല. (ബു,ദ,തു,ന)', 'أَبِي قِلَابَةَ قَالَ', 'അബൂഖിലാബ(റ)', null, null, array['خ','د','ت','ن']::text[], array['ബു','ദ','തു','ന']::text[], null, null, 498, 498, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=62 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=229), 1, 'وَفِي رِوَايَةٍ قَالَ: فَقَعَدَ فِي الرَّكْعَةِ الْأُولَى حِينَ رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ الْآخِرَةِ.', 'മറ്റൊരു നിവേദനിൽ: അദ്ദേഹം പറഞ്ഞു: ഒന്നാമത്തെ റക്അത്തിൽ അവസാനത്തെ സുജൂദിൽ അവിടുന്ന് തന്റെ തലയുർത്തിയപ്പോൾ ഇരുന്നു. ഒരു റിപ്പോർട്ട്: അവിടുന്ന് ഒന്ന്, മൂന്ന് റക്അത്തുകൾ കഴിഞ്ഞാൽ ശരിയാം വിധം ഇരുന്ന ശേഷമല്ലാതെ എഴുന്നേൽക്കാറില്ല. (ബു,ദ,തു,ന)');
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=229), 2, 'وَفِي رِوَايَةٍ: إِذَا كَانَ فِي وِتْرٍ مِنْ صَلَاتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ قَاعِدًا. (خ,د,ت,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 230, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ: أَنَّ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا دَخَلَ فِي الصَّلَاةِ رَفَعَ يَدَيْهِ، وَإِذَا رَكَعَ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ فَعَلَ مِثْلَ ذَلِكَ، وَإِذَا رَفَعَ رَأْسَهُ مِنَ السُّجُودِ فَعَلَ مِثْلَ ذَلِكَ كُلِّهِ، يَعْنِي: رَفْعَ يَدَيْهِ. (ن)', 'മാലികുബ്നു ഹുവൈരിസ്(റ): നബി(സ) നിസ്കാരത്തിൽ പ്രവേശിക്കുമ്പോൾ കൈകൾ ഉയർത്താറുണ്ടായിരുന്നു, റുകൂഇലേക്ക് പോകുമ്പോഴും അതിൽ നിന്നുയരുമ്പോഴും അപ്രകാരം ചെയ്തിരുന്നു. സുജൂദിൽ നിന്നുയരുമ്പോഴും അങ്ങനെ ചെയ്തു, അഥവാ കൈ ഉയർത്തി. (ന)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നു ഹുവൈരിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 231, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا افْتَتَحَ الصَّلَاةَ كَبَّرَ وَرَفَعَ يَدَيْهِ، وَإِذَا رَكَعَ، وَبَعْدَ الرُّكُوعِ، وَلَا يَرْفَعُ بَيْنَ السَّجْدَتَيْنِ. (ن)', 'ഇബ്നുഉമർ(റ): നബി(സ) നിസ്കാരം ആരംഭിക്കുമ്പോൾ തക്ബീർ ചൊല്ലുകയും കൈഉയർത്തുകയും ചെയ്യുമായിരുന്നു, റുകൂഇലേക്ക് പോകുമ്പോഴും റുകൂഇന് ശേഷം ഉയരുമ്പോഴും അപ്രകാരം ചെയ്തിരുന്നു. എന്നാൽ രണ്ട് സുജൂദുകൾക്കിടയിൽ അങ്ങിനെ ചെയ്തില്ല. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=63 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 232, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: "اللَّهُمَّ اغْفِرْ لِي وَارْحَمْنِي وَاجْبُرْنِي وَاهْدِنِي وَارْزُقْنِي". (د,ت,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) രണ്ട് സുജൂദുകൾക്കിടയിൽ ഇപ്രകാരം പറയുമായിരുന്നു: "അല്ലാഹുവേ, എനിക്ക് പൊറുത്തുതരേണമേ. എന്നോട് കരുണ ചെയ്യേണമേ, എനിക്ക് ഐശ്വര്യവും മാർഗ്ഗദർശനവും, വിഭവങ്ങളും നൽകേണമേ." (ദ,തു,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','ت','جه']::text[], array['ദ','തു','ജ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 233, 'عَنْ حُذَيْفَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: "رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي". (م,د,ت,ن,جه)', 'ഹുദൈഫ(റ): നബി(സ) സുജൂദുകൾക്കിടയിൽ ഇപ്രകാരം പറയുമായിരുന്നു: "നാഥാ, എന്നോട് പൊറുക്കേണമേ. പൊറുക്കേണമേ." (മു,ദ,തു,ന,ജ)', 'حُذَيْفَةَ', 'ഹുദൈഫ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=64 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 234, 'عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ رَضِيَ اللهُ عَنْهُمَا قَالَتْ: سَمِعْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: "مَنْ كَانَ مِنْكُنَّ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ، فَلَا تَرْفَعْ رَأْسَهَا حَتَّى يَرْفَعَ الرِّجَالُ رُءُوسَهُمْ". كَرَاهَةَ أَنْ يَرَيْنَ مِنْ عَوْرَاتِ الرِّجَالِ. (د)', 'അസ്മാഅ് ബിൻത് അബൂബക്ർ(റ): നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "നിങ്ങളിൽ അല്ലാഹുവിലും അന്ത്യദിനത്തിലും വിശ്വസിക്കുന്നവർ പുരുഷന്മാർ തല ഉയർത്തുന്നതുവരെ അവളുടെ തല ഉയർത്തരുത്." പുരുഷന്മാരുടെ നഗ്നത കാണുന്നതിലുള്ള വെറുപ്പാണത്. (ദ)', 'أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ', 'അസ്മാഅ് ബിൻത് അബൂബക്ർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 499, 499, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=65 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 235, 'عَنْ طَاوُسٍ رَضِيَ اللهُ عَنْهُ قَالَ: قُلْنَا لِابْنِ عَبَّاسٍ فِي الْإِقْعَاءِ عَلَى الْقَدَمَيْنِ فِي السُّجُودِ فَقَالَ: هِيَ السُّنَّةُ، قَالَ: قُلْنَا: إِنَّا لَنَرَاهُ جُفَاءً بِالرَّجُلِ، فَقَالَ ابْنُ عَبَّاسٍ: هِيَ سُنَّةُ نَبِيِّكَ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (م,د,ت)', 'ത്വാഊസ്(റ): അദ്ദേഹം പറഞ്ഞു: സുജൂദിൽ മടമ്പിനു മുകളിൽ പൃഷ്ടം ചേർത്ത് ഇരിക്കുന്നതിനെക്കുറിച്ച് ഞങ്ങൾ ഇബ്നുഅബ്ബാസിനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അത് സുന്നത്താണ്. ഞങ്ങൾ പറഞ്ഞു: ഞങ്ങൾ ഇത് പുരുഷന്റെ കാടത്തമായി കാണുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറഞ്ഞു: അത് നിന്റെ പ്രവാചകന്റെ ചര്യയാണ്.⁷ (മു,ദ,തു)', 'طَاوُسٍ', 'ത്വാഊസ്(റ)', null, null, array['م','د','ت']::text[], array['മു','ദ','തു']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 236, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُصَلِّيَ الرَّجُلُ مُخْتَصِرًا. (ن)', 'അബൂഹുറൈറയ്റ(റ): കൈകൾ ഊരക്കുമേൽ വെച്ചു കൊണ്ട് നിസ്കരിക്കുന്നതിനെ തിരുമേനി(സ) വിലക്കി. (ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറയ്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 237, 'عَنْ زِيَادِ بْنِ صُبَيْحٍ قَالَ: صَلَّيْتُ إِلَى جَنْبِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا، فَوَضَعْتُ يَدِي عَلَى خَصْرِي، فَقَالَ لِي هَكَذَا ضَرْبَةً بِيَدِهِ، فَلَمَّا صَلَّيْتُ قُلْتُ لِرَجُلٍ: مَنْ هَذَا؟ قَالَ عَبْدُ اللهِ بْنُ عُمَرَ. قُلْتُ: يَا أَبَا عَبْدِ الرَّحْمَنِ، مَا رَابَكَ مِنِّي؟ قَالَ: إِنَّ هَذَا الصَّلْبُ، وَإِنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ نَهَانَا عَنْهُ. (ن)', 'സിയാദ്ബ്ൻ സുബൈഹ്(റ): ഞാൻ ഇബ്നുഉമറിന്റെ അടുത്ത് വെച്ച് നിസ്കരിച്ചു. അന്നേരം ഞാൻ എന്റെ കൈ എന്റെ ഊരക്കുമേൽ വെച്ചു. അപ്പോൾ ഇബ്നുഉമർ(റ) എന്നോടു ആഗ്യം കാണിച്ചു. ഞാൻ നിസ്കാരം പൂർത്തിയാക്കിയപ്പോൾ ഞാൻ ഒരാളോടു ചോദിച്ചു: ''ഇതാരാണ്?'' അയാൾ പറഞ്ഞു: ഇബ്നുഉമർ(റ). ഞാൻ ചോദിച്ചു: ''അബൂഅദുറഹ്മാൻ! താങ്കൾക്ക് എന്റെ ഏതൊരു പ്രവർത്തിയാണ് തെറ്റായി തോന്നിയത്? അദ്ദേഹം പറഞ്ഞു: ഊരക്കുമേൽ കൈവെക്കൽ; നിശ്ചയം, ഇപ്രകാരം ചെയ്യുന്നത് തിരുമേനി(സ) ഞങ്ങളെ വിലക്കിയിട്ടുണ്ട്. (ന)', 'زِيَادِ بْنِ صُبَيْحٍ قَالَ', 'സിയാദ്ബ്ൻ സുബൈഹ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 238, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ لِي النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا رَفَعْتَ رَأْسَكَ مِنَ السُّجُودِ فَلَا تُقْعِ كَمَا يُقْعِي الْكَلْبُ، ضَعْ أَلْيَتَيْكَ بَيْنَ قَدَمَيْكَ، وَأَلْزِقْ ظَاهِرَ قَدَمَيْكَ بِالْأَرْضِ". ز: في اسناده متهم بالوضع (جه)', 'അനസുബ്നു മാലിക്(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "നീ സുജൂദിൽ നിന്ന് തലയുയർത്തിയാൽ നായ ഇരിക്കുന്നതുപോലെ ഇരിക്കരുത്. നിന്റെ കാൽപാദങ്ങൾക്കിടയിൽ പൃഷ്ടം വെക്കുക, പാദങ്ങളുടെ പുറം നിലത്ത് ചേർത്തുവെക്കുക." (ഇതിന്റെ പരമ്പരയിൽ ഹദീസ് കെട്ടിയുണ്ടാക്കുന്നവനാണെന്ന് ആരോപിക്കപ്പെട്ട വ്യക്തിയുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 239, 'عَنْ عَلِيٍّ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ لِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا عَلِيُّ، أُحِبُّ لَكَ مَا أُحِبُّ لِنَفْسِي، وَأَكْرَهُ لَكَ مَا أَكْرَهُ لِنَفْسِي، لَا تُقْعِ بَيْنَ السَّجْدَتَيْنِ". (ت,جه)', 'അലി(റ): നബി(സ) എന്നോട് പറഞ്ഞു: "ഓ അലീ! എനിക്ക് ഇഷ്ടമുള്ളത് ഞാൻ നിനക്ക് ഇഷ്ടപ്പെടുകയും എനിക്ക് വെറുക്കുന്നത് നിനക്കു വേണ്ടി വെറുക്കുകയും ചെയ്യുന്നു. സുജൂദുകൾക്കിടയിൽ മടമ്പിന്മേൽ പൃഷ്ടം ചേർത്ത് നീ ഇരിക്കരുത്." (തു,ജ)', 'عَلِيٍّ', 'അലി(റ)', '⁷. നിർബന്ധിത സാഹചര്യത്തിലോ വിരോധമില്ലെന്ന് വ്യക്തമാക്കാൻ വേണ്ടിയോ ഇങ്ങനെ ഇരുന്നുവെന്ന് മനസ്സിലാക്കാവുന്നതാണ്. താഴെ ഹദീസുകൾ ശ്രദ്ധിക്കുക.', null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 500, 500, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=66 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 240, 'عَنْ زِيَادِ بْنِ صُبَيْحٍ الْحَنَفِيِّ قَالَ: صَلَّيْتُ إِلَى جَنْبِ ابْنِ عُمَرَ فَوَضَعْتُ يَدِيَّ عَلَى خَاصِرَتِي، فَلَمَّا صَلَّى قَالَ: هَذَا الصَّلْبُ فِي الصَّلَاةِ، وَكَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْهُ. (د,ن)', 'സിയാദുബ്നു സ്വബീഹ്(റ): ഞാൻ ഇബ്നുഉമറി(റ)ന്റെ അരികിൽ നിസ്കരിച്ചു. അന്നേരം എന്റെ കൈകൾ എന്റെ ഊരക്കുമേൽ വെച്ചു. നിസ്കാരം നിർവ്വഹിച്ചു കഴിഞ്ഞപ്പോൾ അദ്ദേഹം പറഞ്ഞു: ഇതു തന്നെയാണ് നിസ്കാത്തിലെ ''സ്വൽബ്'' (കുരിശിലേറ്റപ്പെടുന്നതിന്റെ രൂപത്തിന് സദൃശ്യമാവൽ). തിരുമേനി(സ) ഇതിനെ വിലക്കിയിട്ടുണ്ട്. (ദ,ന)', 'زِيَادِ بْنِ صُبَيْحٍ الْحَنَفِيِّ قَالَ', 'സിയാദുബ്നു സ്വബീഹ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=67 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 241, 'عَنْ مَيْمُونَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا سَجَدَ خَوَّى بِيَدَيْهِ، حَتَّى يُرَى وَضَحُ إِبْطَيْهِ مِنْ وَرَائِهِ، وَإِذَا قَعَدَ اطْمَأَنَّ عَلَى فَخِذِهِ الْيُسْرَى. (ن)', 'മൈമൂന(റ): നബി(സ) സുജൂദ് ചെയ്താൽ തിരുമേനിയുടെ പിന്നിൽ നിന്നും (പിന്നിലുള്ളവർക്ക്) അവിടുത്തെ കൈവെള്ള (കക്ഷത്തിലെ വെളുപ്പ് നിറം) കാണുമാറ് കൈകൾ അകറ്റി വെക്കുമായിരുന്നു. ഇടയിലിരുന്നാൽ ഇടത്തേ തുടയുടെമേൽ ഊന്നിയിരുന്ന് (അനക്കമടങ്ങുക) സ്വസ്ഥമാകുമായിരുന്നു. (ന)', 'مَيْمُونَةَ', 'മൈമൂന(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 242, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا قَعَدَ فِي الصَّلَاةِ جَعَلَ قَدَمَهُ الْيُسْرَى بَيْنَ فَخِذِهِ وَسَاقِهِ، وَفَرَشَ قَدَمَهُ الْيُمْنَى، وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى رُكْبَتِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَأَشَارَ بِإِصْبَعِهِ. (م)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): റസൂൽ(സ) നിസ്കാരത്തിൽ ഇരിക്കുമ്പോൾ ഇടത്തേ കാൽ കണങ്കാലിനും തുടക്കും ഇടയിൽ വെക്കും. വലത്തേ കാൽ വിരിച്ചുവെക്കും. ഇടത്തേ കൈ ഇടതു കാൽമുട്ടിൽ വെക്കും. വലതുകൈ വലതു കാലിന്റെ തുടയിൽ വെക്കും. ചൂണ്ടു വിരൽ കൊണ്ട് ആംഗ്യം കാണിക്കും. (മു)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['م']::text[], array['മു']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 243, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أُرِيدُ أَنْ أُرِيَكُمْ كَيْفَ رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي. قَالَ: فَقَعَدَ فِي الرَّكْعَةِ الْأُولَى حِينَ رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ الْآخِرَةِ. (ن)', 'മാലിക്ബുൽ ഹുവൈരിഥ്(റ): അദ്ദേഹം (ആളുകളോട്) പറഞ്ഞു: തിരുമേനി(സ) എങ്ങിനെയാണ് നിസ്കരിച്ചതെന്ന് നിങ്ങൾക്കു കാണിച്ചു തരാൻ ഞാനുദ്ദേശിക്കുന്നു. അങ്ങനെ അദ്ദേഹം ഒന്നാമത്തെ റക്അത്തിലെ രണ്ടാമത്തെ സുജൂദിൽനിന്നും തലയുയർത്തിയ സന്ദർഭത്തിൽ ഇരുന്നു. (ന)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലിക്ബുൽ ഹുവൈരിഥ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 244, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي، فَإِذَا كَانَ فِي وَتْرٍ مِنْ صَلَاتِهِ لَمْ يَنْهَضْ حَتَّى يَسْتَوِيَ جَالِسًا. (ن)', 'മാലികുബ്നുൽ ഹുവൈരിഥ്(റ): തിരുമേനി(സ) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. അവിടുന്ന് ഒന്ന്, മൂന്ന് റക്അത്തുകൾ പൂർത്തീകരിച്ചാൽ ശരിയാംണ്ണം ഇരിക്കാതെ എഴുന്നേൽക്കാറില്ല. (ന)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിഥ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 501, 501, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=68 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 245, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إِذَا صَلَّيْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قُلْنَا: السَّلَامُ عَلَى اللهِ قَبْلَ عِبَادِهِ، السَّلَامُ عَلَى جِبْرَائِيلَ وَمِيكَائِيلَ، وَعَلَى فُلَانٍ وَفُلَانٍ. يَعْنُونَ الْمَلَائِكَةَ، فَسَمِعَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: "لَا تَقُولُوا: السَّلَامُ عَلَى اللهِ، فَإِنَّ اللهَ هُوَ السَّلَامُ. فَإِذَا جَلَسْتُمْ فَقُولُوا: التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ. فَإِنَّهُ إِذَا قَالَ ذَلِكَ أَصَابَتْ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمُ التَّشَهُّدَ... فَذَكَرَ نَحْوَهُ. (ق,د,ن,جه)', 'ഇബ്നുമസ്ഊദ്(റ): റസൂലി(സ)നോടൊപ്പം നിസ്കരിക്കുമ്പോൾ ഞങ്ങൾ ഇപ്രകാരം പറഞ്ഞു: ''അല്ലാഹുവിനുമേൽ അവന്റെ അടിമകൾക്ക് മുമ്പായി സമാധാനമുണ്ടാകട്ടെ, ജിബ്രീലിനും, മീകാഈലിനും മറ്റും സമാധാനമുണ്ടാകട്ടെ, ഇന്നവനും ഇന്നവും മേൽ സമാധാനമുണ്ടാവട്ടെ.'' നബി(സ) അതുകേട്ടപ്പോൾ പറഞ്ഞു: "നിങ്ങൾ അല്ലാഹുവിന് സമാധാനമുണ്ടാകട്ടെ എന്ന് പറയരുത്. കാരണം, അല്ലാഹു തന്നെയാണ് സമാധാനം. നിങ്ങൾ ഇരുന്നാൽ ഇപ്രകാരം പറയുക: ''എല്ലാ അഭിവാദനങ്ങളും അല്ലാഹുവിനാകുന്നു. സമർപ്പണങ്ങളും സൽകർമ്മങ്ങളുമെല്ലാം അവന്ന് തന്നെ, നബിയേ താങ്കൾക്കു മേൽ അല്ലാഹുവിന്റെ അടുക്കൽ നിന്നുള്ള രക്ഷയും അവന്റെ കാരുണ്യവും അനുഗ്രഹങ്ങളും ഉണ്ടാകട്ടെ. ഞങ്ങളുടെ മേലും, അല്ലാഹുവിന്റെ ഉൽകൃഷ്ടരായ അടിമകളുടെ മേലും ഉണ്ടാവട്ടെ.'' അപ്രകാരം പറഞ്ഞാൽ ആകാശത്തും ഭൂമിയിലുമുള്ള എല്ലാ നല്ല അടിമകൾക്കും അത് ബാധകമായി, ''അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ലെന്നും, മുഹമ്മദ്(സ) അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു.''" മറ്റൊരു റിപ്പോർട്ടിൽ: പ്രവാചകൻ(സ) തശഹ്ഹുദ് പഠിപ്പിക്കുമ്പോഴാണ് ഇപ്രകാരം പറഞ്ഞത്. (ബു,മു,ദ,ന,ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 501, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=245), 1, 'وَفِي رِوَايَةٍ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُعَلِّمُهُمُ التَّشَهُّدَ... فَذَكَرَ نَحْوَهُ. (ق,د,ن,جه)', 'മറ്റൊരു നിവേദനിൽ: പ്രവാചകൻ(സ) തശഹ്ഹുദ് പഠിപ്പിക്കുമ്പോഴാണ് ഇപ്രകാരം പറഞ്ഞത്. (ബു,മു,ദ,ന,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 246, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، فَكَانَ يَقُولُ: "التَّحِيَّاتُ الْمُبَارَكَاتُ الصَّلَوَاتُ الطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". (م,د,ت,ن,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): റസൂൽ(സ) ഞങ്ങൾക്ക് ഖുർആനിലെ ആയത്ത് പഠിപ്പിക്കും പോലെ തശഹ്ഹുദ് പഠിപ്പിച്ചുകൊണ്ട് പറഞ്ഞു: "എല്ലാ അഭിവാദ്യങ്ങളും, അനുഗ്രഹീത കർമ്മങ്ങളും, സൽകർമ്മങ്ങളും, പ്രാർത്ഥനകളും അല്ലാഹുവിനാകുന്നു. നബിയേ താങ്കൾക്ക് സമാധാനമുണ്ടാവട്ടെ, അല്ലാഹുവിന്റെ കാരുണ്യവും അനുഗ്രഹങ്ങളുമുണ്ടാകട്ടെ. ഞങ്ങൾക്കുമേൽ സമാധാനമുണ്ടാകട്ടെ. സൽകർമ്മികളായ എല്ലാ അടിമകൾക്കുമേലും. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല എന്നും മുഹമ്മദ് നബി(സ) അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." (മു,ദ,തു,ന,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 247, 'عَنْ جَابِرِ بْنِ عَبْدِ اللهِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ: "بِاسْمِ اللهِ وَبِاللهِ، التَّحِيَّاتُ لِلَّهِ وَالصَّلَوَاتُ وَالطَّيِّبَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَسْأَلُ اللهَ الْجَنَّةَ وَأَعُوذُ بِاللهِ مِنَ النَّارِ". (ن,جه)', 'ജാബിറുബ്നു അബ്ദുല്ല(റ): ഖുർആനിലെ സൂറത്തു പഠിപ്പിക്കും പോലെ നബി(സ) ഞങ്ങളെ നിസ്കാരത്തിലെ തശഹ്ഹുദ് പഠിപ്പിക്കുമായിരുന്നു: "അല്ലാഹുവിന്റെ നാമത്തിൽ, അല്ലാഹുവിനെ കൊണ്ടു ഞാൻ തുടങ്ങുന്നു, എല്ലാ അഭിവാദ്യങ്ങളും എല്ലാ പ്രാർത്ഥനകളും, എല്ലാ സൽകർമ്മങ്ങളും അല്ലാഹുവിനാകുന്നു. നബിയേ താങ്കൾക്ക് അല്ലാഹുവിന്റെ അടുക്കൽ നിന്നുള്ള രക്ഷയും അവന്റെ കാരുണ്യവും അനുഗ്രഹങ്ങളും ഉണ്ടാവട്ടെ. ഞങ്ങളിലും ഉത്തമരായ അടിമകളിലും സമാധാനമുണ്ടാകട്ടെ, അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനില്ല എന്നും മുഹമ്മദ് നബി(സ) അല്ലാഹുവിന്റെ ദൂതനും അടിമയുമാണെന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു. ഞാൻ അല്ലാഹുവിനോട് സ്വർഗ്ഗത്തെ ചോദിക്കുന്നു, അവനോട് നരകത്തിൽ നിന്ന് കാവൽ തേടുകയും ചെയ്യുന്നു." (ന,ജ)', 'جَابِرِ بْنِ عَبْدِ اللهِ', 'ജാബിറുബ്നു അബ്ദുല്ല(റ)', null, null, array['ن','جه']::text[], array['ന','ജ']::text[], null, null, 502, 502, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 248, 'عَنِ ابْنِ أَبِي لَيْلَى قَالَ: لَقِيَنِي كَعْبُ بْنُ عُجْرَةَ رَضِيَ اللهُ عَنْهُ فَقَالَ: أَلَ أُهْدِي لَكَ هَدِيَّةً؟ خَرَجَ عَلَيْنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: قَدْ عَرَفْنَا السَّلَامَ عَلَيْكَ، فَكَيْفَ الصَّلَاةُ عَلَيْكَ؟ قَالَ: "قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ". (ق,د,ت,ن,جه)', 'ഇബ്നുഅബീലൈല: കഅ്ബുബ്നു ഉജ്റ(റ) എന്നെ കണ്ടു. അദ്ദേഹം ചോദിച്ചു: ഞാൻ നിനക്കൊരു ഉപഹാരം നൽകട്ടെയോ? പിന്നെ പറഞ്ഞു: നബി(സ) ഞങ്ങളുടെ അടുത്തേക്ക് വന്നു, ഞങ്ങൾ ചോദിച്ചു: പ്രവാചകരേ, താങ്കളുടെ പേരിലുള്ള സലാം ഞങ്ങൾക്കറിയാം. സ്വലാത്ത് എപ്രകാരമാണ്?. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക; ഇബ്റാഹിം നബിക്ക് നീ ഗുണം നൽകിയതുപോലെ മുഹമ്മദിനും ഗുണം നൽകേണമേ, മുഹമ്മദിന്റെ കുടുംബത്തിനും ഗുണം നൽകേണമേ. നീ സ്തുത്യർഹനും, പ്രതാപവാനുമാകുന്നു. ഇബ്റാഹീം നബിക്ക് അനുഗ്രഹം നൽകിയതു പോലെ മുഹമ്മദ് നബി(സ)ക്കും കുടുംബത്തിനും അനുഗ്രഹം നൽകേണമേ. നീ സ്തുത്യർഹനും പ്രതാപവാനുമാകുന്നു." (ബു,മു,ദ,തു,ന,ജ)', 'ابْنِ أَبِي لَيْلَى قَالَ', 'ഇബ്നുഅബീലൈല', null, null, array['ق','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 249, 'عَنْ أَبِي حُمَيْدٍ السَّاعِدِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُمْ قَالُوا: يَا رَسُولَ اللهِ، أُمِرْنَا بِالصَّلَاةِ عَلَيْكَ، فَكَيْفَ نُصَلِّي عَلَيْكَ، فَقَالَ: "قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ. وَبَارِكْ عَلَى مُحَمَّدٍ وَأَزْوَاجِهِ وَذُرِّيَّتِهِ، كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ، فِي الْعَالَمِينَ إِنَّكَ حَمِيدٌ مَجِيدٌ". (ق,د,ن,جه)', 'അബൂഹുമൈദുസ്സാഇദി(റ): അവർ (സ്വഹാബത്ത്) നബി(സ)യോട് ചോദിച്ചു: ഞങ്ങളോട് സ്വലാത്ത് ചൊല്ലാൻ കൽപിക്കപ്പെട്ടിരിക്കുന്നുവല്ലോ, എങ്ങിനെയാണ് സ്വലാത്ത് ചൊല്ലേണ്ടത്? നബി(സ) പറഞ്ഞു: "നിങ്ങൾ പറയുക; നാഥാ!, ഇബ്റാഹീം നബിക്ക് ഗുണം നൽകിയതു പോലെ മുഹമ്മദ് നബിക്കും ഭാര്യ സന്താനങ്ങൾക്കും ഗുണം നൽകേണമേ! ലോകരിൽ ഇബ്റാഹീം നബിയുടെ കുടുംബത്തിന് ബർക്കത്ത് ചൊരിഞ്ഞത് പോലെ മുഹമ്മദ് നബിക്കും കുടുംബത്തിനും ബർക്കത്ത് ചൊരിയേണമേ! നിശ്ചയം, നീ സ്തുത്യർഹനും പ്രതാപവാനുമാണ്." (ബു,മു,ദ,ന,ജ)', 'أَبِي حُمَيْدٍ السَّاعِدِيِّ', 'അബൂഹുമൈദുസ്സാഇദി(റ)', null, null, array['ق','د','ن','جه']::text[], array['ബു','മു','ദ','ന','ജ']::text[], null, null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 250, 'عَنْ عَامِرِ بْنِ رَبِيعَةَ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَا مِنْ مُسْلِمٍ يُصَلِّي عَلَيَّ إِلَّا صَلَّتْ عَلَيْهِ الْمَلَائِكَةُ مَا صَلَّى عَلَيَّ، فَلْيُقِلَّ الْعَبْدُ مِنْ ذَلِكَ أَوْ لِيُكْثِرْ". [ز:إسناد ضعيف] (جه)', 'ആമിറു റബീഅ(റ): നബി(സ) പറഞ്ഞു: "ഒരു മുസ്ലിം എന്റെ പേരിൽ സ്വലാത്ത് ചെല്ലിയാൽ, അവൻ സ്വലാത്ത് ചൊല്ലുന്ന സമയത്തോളം മലക്കുകൾ അവന്റെ മേൽ സ്വലാത്ത് ചൊല്ലാതിരിക്കില്ല. അതിനാൽ അടിമ അത് വർദ്ധിപ്പിക്കുകയോ കുറക്കുകയോ ചെയ്യട്ടെ!" (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'عَامِرِ بْنِ رَبِيعَةَ', 'ആമിറു റബീഅ(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:إسناد ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 251, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "مَنْ نَسِيَ الصَّلَاةَ عَلَيَّ خَطِئَ طَرِيقَ الْجَنَّةِ". [ز:إسناده ضعيف] (جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും എന്റെ പേരിൽ സ്വലാത്ത് ചൊല്ലാൻ മറന്നാൽ അവന് സ്വർഗ്ഗത്തിലേക്കുള്ള പാത പിഴച്ചുപോകും." [ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ] (ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:إسناده ضعيف', null, 503, 503, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 252, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: إِذَا صَلَّيْتُمْ عَلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَأَحْسِنُوا الصَّلَاةَ عَلَيْهِ، فَإِنَّكُمْ لَا تَدْرُونَ لَعَلَّ ذَلِكَ يُعْرَضُ عَلَيْهِ. قَالَ: فَقَالُوا لَهُ: فَعَلِّمْنَا. قَالَ: قُولُوا: اللَّهُمَّ اجْعَلْ صَلَاتَكَ وَرَحْمَتَكَ وَبَرَكَاتِكَ عَلَى سَيِّدِ الْمُرْسَلِينَ، وَإِمَامِ الْمُتَّقِينَ، وَخَاتَمِ النَّبِيِّينَ، مُحَمَّدٍ عَبْدِكَ وَرَسُولِكَ، إِمَامِ الْخَيْرِ، وَقَائِدِ الْخَيْرِ، وَرَسُولِ الرَّحْمَةِ. اللَّهُمَّ ابْعَثْهُ مَقَامًا مَحْمُودًا يَغْبِطُهُ بِهِ الْأَوَّلُونَ وَالْآخِرُونَ. اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صَلَّيْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. اللَّهُمَّ بَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا بَارَكْتَ عَلَى إِبْرَاهِيمَ وَعَلَى آلِ إِبْرَاهِيمَ، إِنَّكَ حَمِيدٌ مَجِيدٌ. (جه)', 'അബ്ദുല്ലാഹുബ്നു മസ്ഊദ്(റ): നിങ്ങൾ നബി(സ)യുടെ പേരിൽ സ്വലാത്ത് ചെല്ലുമ്പോൾ അത് നന്നാക്കുക. റസൂലിന്റെ മുമ്പിൽ അത് പ്രദർശിപ്പിക്കപ്പെട്ടേക്കാം എന്ന് നിങ്ങൾക്കറിയില്ല. അപ്പോൾ അദ്ദേഹത്തോട് അവർ പറഞ്ഞു: ഞങ്ങൾക്ക് പഠിപ്പിച്ചു തന്നാലും, അദ്ദേഹം പറഞ്ഞു: നിങ്ങൾ പറയുക; അല്ലാഹുവേ, നിന്റെ രക്ഷയും കാരുണ്യവും അനുഗ്രഹങ്ങളും, ദൈവദൂതന്മാരുടെ നേതാവിന് ഉണ്ടാവട്ടെ, ഭക്തരുടെ ഇമാമും അന്ത്യപ്രവാചകനും, നിന്റെ അടിമയും നിന്റെ ദൂതനുമായ നന്മയുടെ നേതാവും, നന്മയുടെ നായകനും, കാരുണ്യത്തിന്റെ ദൂതനുമായ മുഹമ്മദ് നബി(സ)യിൽ. അല്ലാഹുവേ, മുൻഗാമികളും പിൻഗാമികളും ആഗ്രഹിക്കുന്ന സ്തുത്യർഹമായ സ്ഥാനം അവിടത്തേക്ക് നീ നൽകേണമേ. അല്ലാഹുവേ, ഇബ്റാഹീമിനും കുടുംബത്തിനും നീ ഗുണം നൽകിയതുപോലെ മുഹമ്മദിനും കുടുംബത്തിനും ഗുണം നൽകേണമേ. നീ സ്തുത്യർഹനും ശ്രേഷ്ഠനുമാകുന്നു. അല്ലാഹുവേ, ഇബ്റാഹീമിനും കുടുംബത്തിനും നൽകിയതുപോലെ മുഹമ്മദിനും കുടുംബത്തിനും നീ അനുഗ്രഹം നൽകേണമേ, നീ സ്തുത്യർഹനും പ്രതാപിയുമാകുന്നു. (ജ)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹുബ്നു മസ്ഊദ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 503, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 253, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا لَا نَدْرِي مَا نَقُولُ إِذَا صَلَّيْنَا، فَعَلَّمَنَا نَبِيُّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ جَوَامِعَ الْكَلِمِ، فَقَالَ لَنَا: "قُولُوا: التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ". عَنْ عَلْقَمَةَ قَالَ: لَقَدْ رَأَيْتُ ابْنَ مَسْعُودٍ يُعَلِّمُنَا هَؤُلَاءِ الْكَلِمَاتِ كَمَا يُعَلِّمُنَا الْقُرْآنَ. (ن)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): ഞങ്ങൾ നിസ്കരിക്കുമ്പോൾ പറയേണ്ടതെന്താണെന്ന് ഞങ്ങൾക്ക് അറിയില്ലായിരുന്നു. നബി(സ) അർത്ഥ സമ്പുഷ്ടമായ ചില വാക്യങ്ങൾ ഞങ്ങൾക്ക് പഠിപ്പിച്ചു തന്നു. നബി(സ) ഞങ്ങളോട് പറഞ്ഞു: "നിങ്ങൾ പറയുക; എല്ലാ അഭിവാദ്യങ്ങളും, എല്ലാ ഗുണങ്ങളും, നന്മകളും അല്ലാഹുവിനാകുന്നു. നബിയേ, താങ്കൾക്ക് അല്ലാഹുവിന്റെ പക്കൽനിന്നുമുള്ള സമാധാനമുണ്ടാകട്ടെ, അല്ലാഹുവിന്റെ കാരുണ്യവും അനുഗ്രഹങ്ങളും. ഞങ്ങൾക്കും സദ്വൃത്തരായ അടിമകൾക്കും സമാധാനമുണ്ടാവട്ടെ. അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല എന്നും, മുഹമ്മദ് അല്ലാഹുവിന്റെ അടിമയും ദൂതനുമാണ് എന്നും ഞാൻ സാക്ഷ്യം വഹിക്കുന്നു." അൽഖമ(റ) പറഞ്ഞു: ഖുർആൻ പഠിപ്പിക്കും പോലെ ഈ വചനങ്ങൾ ഞങ്ങൾക്ക് ഇബ്നുമസ്ഊദ്(റ) പഠിപ്പിച്ചു തരുന്നത് ഞാൻ കണ്ടു. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=69 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 254, 'عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ قَالَ لِرَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلَاتِي. فَقَالَ: "قُلْ: اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَبِيرًا – وَقَالَ قُتَيْبَةُ: كَثِيرًا – وَلَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ". (ق)', 'അബൂബക്കർ(റ): അദ്ദേഹം നബി(സ)യോട് ചോദിച്ചു: നിസ്കാരത്തിൽ പ്രാർത്ഥിക്കാനുള്ള ഒരു പ്രാർത്ഥന പഠിപ്പിച്ചു തന്നാലും. നബി(സ) പറഞ്ഞു: "അല്ലാഹുവേ, ഞാൻ എന്നോട് തന്നെ വലിയ - ഖുതൈബ(റ) പറഞ്ഞു: ധാരാളമായി - അതിക്രമം ചെയ്തു, നീയല്ലാതെ പാപങ്ങൾ പൊറുക്കന്നവനില്ല. എനിക്ക് നിന്നിൽ നിന്നുള്ള പാപമോചനം നൽകേണമേ, എന്നോട് കരുണ കാണിക്കേണമേ. നീ പൊറുക്കുന്നവനും കരുണാമയനുമല്ലോ." (ബു,മു)', 'أَبِي بَكْرٍ الصِّدِّيقِ', 'അബൂബക്കർ(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 504, 504, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 255, 'عَنْ أَبِي لَيْلَى رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ إِلَى جَنْبِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاةِ تَطَوُّعٍ، فَسَمِعْتُهُ يَقُولُ: "أَعُوذُ بِاللهِ مِنَ النَّارِ، وَيْلٌ لِأَهْلِ النَّارِ". (د,جه)', 'അബൂലൈലാ(റ): ഞാൻ തിരുമേനി(സ)യുടെ അടുക്കൽ ഐച്ഛിക നിസ്കാരം നിർവ്വഹിച്ചു. അപ്പോൾ തിരുമേനി(സ) ഇപ്രകാരം പറയുന്നത് ഞാൻ കേട്ടു: "അല്ലാഹുവിനോട് ഞാൻ നരകത്തിൽ നിന്നും രക്ഷ ചോദിക്കുന്നു. നരകക്കാർക്ക് നാശം." (ദ,ജ)', 'أَبِي لَيْلَى', 'അബൂലൈലാ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 504, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 256, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَرَأَ: {سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى} قَالَ: "سُبْحَانَ رَبِّيَ الْأَعْلَى". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): തിരുമേനി(സ) ''സബ്ബിഹിസ്മ റബ്ബിക്കൽ അഅ്ലാ'' (നീ അത്യുന്നതനായ നിന്റെ രക്ഷിതാവിന്റെ നാമം പരിശുദ്ധിപ്പെടുത്തുക) എന്ന് പാരായണം ചെയ്താൽ "സുബ്ഹാന റബ്ബിയൽ അഅ്ലാ" (അത്യുന്നതനായ എന്റെ രക്ഷിതാവിന്റെ പരിശുദ്ധിയെ ഞാൻ വാഴ്ത്തുന്നു) എന്ന് പറയും. (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 257, 'عَنْ مُوسَى بْنِ أَبِي عَائِشَةَ قَالَ: كَانَ رَجُلٌ يُصَلِّي فَوْقَ بَيْتِهِ، وَكَانَ إِذَا قَرَأَ: {أَلَيْسَ ذَلِكَ بِقَادِرٍ عَلَى أَنْ يُحْيِيَ الْمَوْتَى} قَالَ: سُبْحَانَكَ! فَبَكَى. فَسَأَلُوهُ عَنْ ذَلِكَ فَقَالَ: سَمِعْتُهُ مِنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (د)', 'മുസബ്നു അബീ ആഇശ(റ): ഒരാൾ തന്റെ വീടിന്റെ മുകൾ ഭാഗത്ത് നിസ്കരിക്കാറുണ്ടായിരുന്നു. അദ്ദേഹം ''അലൈസ ദാലിക ബി ഖാദിരിൻ അലാ അൻ യുഹ്യിയൽ മൗത്താ'' (അങ്ങനെയുള്ളവൻ മരിച്ചവരെ ജീവിപ്പിക്കാൻ കഴിവുള്ളവനല്ലേ?!) എന്ന ആയത്ത് ഓതിയപ്പോൾ ''അല്ലാഹുവേ! നീ എത്ര പരിശുദ്ധൻ! അതെ! (നീ കഴിവുള്ളവനാണ്) എന്നു പറയുകയും കരയുകയും ചെയ്തു. അപ്പോൾ ആളുകൾ അതിനെ സംബന്ധിച്ച് അദ്ദേഹത്തോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: ഇത് ഞാൻ തിരുമേനി(സ)യിൽ നിന്നും കേട്ടിട്ടുണ്ട്. (ദ)', 'مُوسَى بْنِ أَبِي عَائِشَةَ قَالَ', 'മുസബ്നു അബീ ആഇശ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=70 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 258, 'عَنْ عَبْدِ اللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُ: أَنَّهُ رَأَى رَجُلًا يُحَرِّكُ الْحَصَى بِيَدِهِ وَهُوَ فِي الصَّلَاةِ، فَلَمَّا انْصَرَفَ قَالَ لَهُ عَبْدُ اللهِ: لَا تُحَرِّكِ الْحَصَى وَأَنْتَ فِي الصَّلَاةِ، فَإِنَّ ذَلِكَ مِنَ الشَّيْطَانِ، وَلَكِنِ اصْنَعْ كَمَا كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ. قَالَ: وَكَيْفَ كَانَ يَصْنَعُ؟ قَالَ: فَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَأَشَارَ بِأُصْبُعِهِ الَّتِي تَلِي الْإِبْهَامَ فِي الْقِبْلَةِ، وَرَمَى بِبَصَرِهِ إِلَيْهَا أَوْ نَحْوِهَا، ثُمَّ قَالَ: هَكَذَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَصْنَعُ. (ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): ഒരാൾ നിസ്കാരത്തിൽ കൈ കൊണ്ട് കല്ലുകൾ നീക്കുന്നതായി അദ്ദേഹം കണ്ടു, നിസ്കാരം കഴിഞ്ഞപ്പോൾ അയാളോട് പറഞ്ഞു: നീ നിസ്കാരത്തിലായിരിക്കെ കല്ലുകൾ നീക്കരുത്. അത് പിശാചിൽ നിന്നുള്ളതാണ്. നീ നബി(സ) ചെയ്തതുപോലെ ചെയ്യുക. അയാൾ ചോദിച്ചു: നബി(സ) എങ്ങനെയാണ് ചെയ്തത്? ഇബ്നുഉമർ(റ) പറഞ്ഞു: നബി(സ) തന്റെ വലതുകൈ വലതു തുടയിൽ വെച്ചു, തന്റെ തള്ളവിരലിനോടടുത്ത വിരൽ കൊണ്ട് ഖിബ്ലക്കുനേരെ ചൂണ്ടി. അതിലേക്ക് അല്ലെങ്കിൽ അതിന്റെ ഭാഗത്തേക്ക് നോക്കുകയും ചെയ്തു. റസൂൽ(സ) ഇങ്ങനെ ചെയ്യുന്നതാണ് ഞാൻ കണ്ടത്. (ന)', 'عَبْدِ اللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=71 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 259, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إِذَا جَلَسَ فِي الثِّنْتَيْنِ أَوْ فِي الْأَرْبَعِ يَضَعُ يَدَيْهِ عَلَى رُكْبَتَيْهِ، ثُمَّ أَشَارَ بِأُصْبُعِهِ. (ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): റസൂൽ(സ) രണ്ടാമത്തെ റക്അത്തിലോ നാലാമെത്തേതിലോ ഇരുന്നാൽ കൈ തുടയിൽ വെക്കുകയും വിരൽ ചൂണ്ടുകയും ചെയ്യുമായിരുന്നു. (ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 505, 505, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 260, 'عَنْ نُمَيْرٍ الْخُزَاعِيِّ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَاضِعًا يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى فِي الصَّلَاةِ، وَيُشِيرُ بِإِصْبَعِهِ. (د,ن,جه)', 'നുമൈറുൽഖുസാഈ(റ): പ്രവാചകൻ(സ) നിസ്കാരത്തിൽ തന്റെ വലതുകൈ വലത്തെ തുടക്കുമേൽ വെക്കുന്നതും വിരൽകൊണ്ട് ചൂണ്ടുന്നതും ഞാൻ കണ്ടു. (ദ,ന,ജ)', 'نُمَيْرٍ الْخُزَاعِيِّ', 'നുമൈറുൽഖുസാഈ(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 261, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَدْ حَلَّقَ بِالْإِبْهَامِ وَالْوُسْطَى، وَرَفَعَ الَّتِي تَلِيهِمَا يَدْعُو بِهَا فِي التَّشَهُّدِ. (ن)', 'വാഇവുബ്നു ഹുജ്ർ(റ): നബി(സ) തശഹ്ഹുദിൽ തന്റെ തള്ളവിരലിനെയും, നടുവിരലിനെയും വൃത്താകൃതിയിലാക്കിവെക്കുന്നതും അവയ്ക്ക് തൊട്ടടുത്തുള്ള വിരലിനെ (ചൂണ്ടുവിരലിനെ) ഉയർത്തുന്നതും, അതുമുഖേന പ്രാർത്ഥിക്കുന്നതും ഞാൻ കണ്ടു. (ന)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇവുബ്നു ഹുജ്ർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 262, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا جَلَسَ فِي الصَّلَاةِ وَضَعَ يَدَيْهِ عَلَى رُكْبَتَيْهِ، وَرَفَعَ إِصْبَعَهُ الْيُمْنَى الَّتِي تَلِي الْإِبْهَامَ، فَيَدْعُو بِهَا. وَالْيُسْرَى عَلَى رُكْبَتِهِ، بَاسِطَهَا عَلَيْهَا. (م,ت,ن,جه)', 'ഇബ്നുഉമർ(റ): പ്രവാചകൻ(സ) നിസ്കാരത്തിലെ ഇരുത്തത്തിൽ തന്റെ കൈകൾ മുട്ടുകളിന്മേൽ വെക്കുകയും, വലതുകയ്യിന്റെ തള്ളവിരലിന് തൊട്ടടുത്തുള്ള വിരൽ ഉയർത്തുകയും അതുകൊണ്ട് പ്രാർത്ഥിക്കുകയും ചെയ്യും, ഇടതു കൈ (ഇടതു) മുട്ടിന്മേൽ പരത്തി വെക്കും. (മു,തു,ന,ജ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['م','ت','ن','جه']::text[], array['മു','തു','ന','ജ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=72 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 263, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: مِنَ السُّنَّةِ أَنْ يُخْفِيَ التَّشَهُّدَ. حَسَنٌ غَرِيبٌ. (د,ت)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ): തശഹ്ഹുദ് ഗോപ്യമാക്കലാണ് സുന്നത്ത്. (ഹദീസ് ഹസനും ഗരീബുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=73 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 264, 'عَنْ وَائِلِ بْنِ حُجْرٍ رَضِيَ اللهُ عَنْهُ قَالَ: قَدِمْتُ الْمَدِينَةَ، قُلْتُ: لَأَنْظُرَنَّ إِلَى صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. فَلَمَّا جَلَسَ لِلتَّشَهُّدِ افْتَرَشَ رِجْلَهُ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَنَصَبَ رِجْلَهُ الْيُمْنَى. حَسَنٌ صَحِيحٌ. (د,ت,ن,جه)', 'വാഇലുബ്നു ഹുജ്ർ(റ): ഞാൻ മദീനയിൽ വന്നു, നബി(സ)യുടെ നിസ്കാരം നോക്കി മനസ്സിലാക്കുമെന്ന് ഞാൻ ഉറപ്പിച്ചു പറഞ്ഞു. അങ്ങനെ നബി(സ) തശഹ്ഹുദിൽ ഇരിക്കുമ്പോൾ ഇടതുകാൽ വിരിച്ചുവെക്കുകയും ഇടതുകൈ ഇടതു തുടയിൽ വെക്കുകയും ചെയ്തു. വലതുകാൽ (മടമ്പ്) നാട്ടിയിരുന്നു. (ഹദീസ് ഹസനും സഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു) (ദ,തു,ന,ജ)', 'وَائِلِ بْنِ حُجْرٍ', 'വാഇലുബ്നു ഹുജ്ർ(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 506, 506, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 265, 'عَنْ عَبْدِاللهِ بْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ كَانَ يَتَرَبَّعُ فِي الصَّلَاةِ إِذَا جَلَسَ وَأَنَّهُ رَأَى وَلَدَهُ فَعَلَ ذَلِكَ فَنَهَاهُ وَقَالَ: إِنَّمَا سُنَّةُ الصَّلَاةِ أَنْ تَنْصِبَ رِجْلَكَ الْيُمْنَى وَتَثْنِيَ الْيُسْرَى، فَقَالَ لَهُ: إِنَّكَ تَفْعَلُ ذَلِكَ، فَقَالَ: إِنَّ رِجْلَيَّ لَا تَحْمِلَانِي. (خ)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): അദ്ദേഹം നിസ്കാരത്തിൽ ചമ്രം പടിഞ്ഞിരിക്കാറുണ്ടായിരുന്നു. തന്റെ മകൻ അങ്ങനെ ചെയ്തപ്പോൾ അദ്ദേഹം അത് വിലക്കി. എന്നിട്ട് പറഞ്ഞു: നിന്റെ വലതു കാൽ നാട്ടി ഇടതുകാൽ വിരിച്ചിരിക്കലാണ് സുന്നത്ത്. മകൻ പറഞ്ഞു: നിങ്ങൾ ഇങ്ങനെ ചെയ്തതോ? അദ്ദേഹം പറഞ്ഞു: എന്റെ കാൽ എന്നെ വഹിക്കാത്തതിനാലാണ്. (അസുഖം കാരണമാണ് ഞാൻ ഇപ്രകാരം ചെയ്യുന്നത്). (ബു)', 'عَبْدِاللهِ بْنِ عُمَرَ', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 506, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 266, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: مِنْ سُنَّةِ الصَّلَاةِ أَنْ تَنْصِبَ الْقَدَمَ الْيُمْنَى، وَاسْتِقْبَالُهُ بِأَصَابِعِهَا الْقِبْلَةَ، وَالْجُلُوسُ عَلَى الْيُسْرَى. (ن)', 'ഇബ്നുഉമർ(റ): വലതു പാദം നാട്ടി വെക്കലും, അതിന്റെ വിരലുകൾ ഖിബ്ലക്കഭിമുഖമാക്കലും, ഇടതുകാലിന്മേൽ ഇരിക്കലും, നിസ്കാരത്തിന്റെ വിഷയത്തിൽ പ്രവാചക(സ)ന്റെ ചര്യയിൽ പെട്ടതാകുന്നു. (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 267, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي الرَّكْعَتَيْنِ كَأَنَّهُ عَلَى الرَّضْفِ. قُلْتُ: حَتَّى يَقُومَ؟ قَالَ: ذَلِكَ يُرِيدُ. (ن)', 'ഇബ്നുമസ്ഊദ്(റ): തിരുമേനി(സ) ആദ്യ രണ്ടു റക്അത്തുകളിൽ (ആദ്യത്തെ തശഹ്ഹുദിൽ ഇരുന്നിരുന്നത്) ചുടുകല്ലിലിരിക്കുന്നതു പോലെയായിരുന്നു. ഞാൻ ചോദിച്ചു: അങ്ങനെ എഴുന്നേൽക്കുകയോ? അദ്ദേഹം (ഇബ്നുമസഊദ്) പറഞ്ഞു: അതെ, അതുതന്നെയാണുദ്ദേശിച്ചത്. (ന)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'ഇബ്നുമസ്ഊദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=74 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 268, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ كَانَ يَقُولُ بَعْدَ التَّشَهُّدِ: "اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ جَهَنَّمَ، وَأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ". (د)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) തശഹ്ഹുദിന് ശേഷം ഇപ്രകാരം പറയുമായിരുന്നു; "അല്ലാഹുവേ, നരകശിക്ഷയിൽ നിന്ന് ഞാൻ നിന്നോട് കാവൽ തേടുന്നു, ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും, ദജ്ജാലിന്റെ കുഴപ്പത്തിൽ നിന്നും, ജീവിതത്തിലേയും മരണത്തിലേയും കുഴപ്പത്തിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു." (ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 269, 'عَنْ مِحْجَنِ بْنِ الْأَدْرَعِ رَضِيَ اللهُ عَنْهُ قَالَ: دَخَلَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ قَدْ قَضَى صَلَاتَهُ وَهُوَ يَتَشَهَّدُ، وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ – يَا أَللهُ الْأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدْ – أَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ. قَالَ: فَقَالَ: "قَدْ غُفِرَ لَهُ، قَدْ غُفِرَ لَهُ" ثَلَاثًا. (د,ن)', 'മിഹ്ജനുബ്നു അദ്റഅ്(റ): നബി(സ) പള്ളിയിൽ പ്രവേശിച്ചു. അപ്പോൾ ഒരാൾ നിസ്കാരത്തിൽ തശഹ്ഹുദിലായിരുന്നു. അയാൾ ഇപ്രകാരം പറയുന്നതായി നബി(സ) കേട്ടു: അല്ലാഹുവേ!, ഏകനും അനാശ്രയനും സന്താനങ്ങളുമില്ലാത്തവനും തുല്ല്യരായി ആരുമില്ലാത്തവനുമായ അല്ലാഹുവേ, നീ എന്റെ പാപങ്ങൾ പൊറുത്തു തരേണമേ, നിശ്ചയം, നീ ഏറെ പൊറുക്കുന്നവനും കാരുണ്യവാനുമാകുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "അയാൾക്ക് പൊറുത്തു കൊടുക്കപ്പെട്ടിരിക്കുന്നു." തിരുമേനി(സ) മൂന്ന് പ്രാവശ്യം ഇത് ആവർത്തിച്ചു. (ദ,ന)', 'مِحْجَنِ بْنِ الْأَدْرَعِ', 'മിഹ്ജനുബ്നു അദ്റഅ്(റ)', null, null, array['د','ن']::text[], array['ദ','ന']::text[], null, null, 507, 507, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 270, 'عَنْ مُعَاذِ بْنِ جَبَلٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَخَذَ بِيَدِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: "إِنِّي لَأُحِبُّكَ يَا مُعَاذُ". فَقُلْتُ: وَأَنَا أُحِبُّكَ يَا رَسُولَ اللهِ. فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَلَا تَدَعْ أَنْ تَقُولَ فِي كُلِّ صَلَاةٍ: رَبِّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ". (ن)', 'മുആദുബ്നു ജബൽ(റ): നബി(സ) എന്റെ കൈ പിടിച്ചുകൊണ്ട് പറഞ്ഞു: "മുആദ്, ഞാൻ നിന്നെ ഇഷ്ടപ്പെടുന്നു." ഞാൻ പറഞ്ഞു: റസൂലേ ഞാൻ താങ്കളേയും ഇഷ്ടപ്പെടുന്നു. അപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ നിന്റെ എല്ലാ നിസ്കാരങ്ങളിലും ഇപ്രകാരം പ്രാർത്ഥിക്കാൻ ഒരിക്കലും വിട്ടു പോവരുത്, എന്റെ നാഥാ, നിന്നെ സ്മരിക്കുവാനും നിന്നോട് നന്ദി കാണിക്കാനും നിനക്ക് ആരാധനകൾ നന്നാക്കുവാനും എന്നെ നീ സഹായിക്കേണമേ." (ന)', 'مُعَاذِ بْنِ جَبَلٍ', 'മുആദുബ്നു ജബൽ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 507, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 271, 'عَنْ شَدَّادِ بْنِ أَوْسٍ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي صَلَاتِهِ: "اللَّهُمَّ إِنِّي أَسْأَلُكَ الثَّبَاتَ فِي الْأَمْرِ، وَالْعَزِيمَةَ عَلَى الرُّشْدِ، وَأَسْأَلُكَ شُكْرَ نِعْمَتِكَ وَحُسْنَ عِبَادَتِكَ، وَأَسْأَلُكَ قَلْبًا سَلِيمًا، وَلِسَانًا صَادِقًا، وَأَسْأَلُكَ مِنْ خَيْرِ مَا تَعْلَمُ، وَأَعُوذُ بِكَ مِنْ شَرِّ مَا تَعْلَمُ، وَأَسْتَغْفِرُكَ لِمَا تَعْلَمُ". (ن)', 'ശദ്ദാദുബ്നു ഔസ്(റ): നബി(സ) തന്റെ നിസ്കാരത്തിൽ ഇപ്രകാരം പറഞ്ഞിരുന്നു: "അല്ലാഹുവേ, ഞാൻ കാര്യങ്ങളിൽ സ്ഥൈര്യവ്യം സന്മാർഗ്ഗത്തിൽ ദൃഢതയും നിന്നോട് തേടുന്നു. നിന്റെ അനുഗ്രഹങ്ങൾക്ക് നന്ദിയുള്ളവനാകാനും, നിന്നെ ആരാധിക്കുന്നതിൽ നന്മ കൈവരിക്കാനുമുള്ള (സൗഭാഗ്യവും) നിന്നോട് യാചിക്കുന്നു. പാപങ്ങളിൽ നിന്നും സുരക്ഷിതമായ മനസ്സിനെയും നിന്നോട് ചോദിക്കുന്നു. സത്യം പറയുന്ന നാവും നിനക്കറിയുന്ന നന്മയും നിന്നോട് ഞാൻ ചോദിക്കുന്നു. നീ അറിയുന്ന തിന്മയിൽ നിന്ന് നിന്നേട് ഞാൻ കാവൽ തേടുകയും, നീ അറിയുന്നവയിൽ നിന്ന് നിന്നോട് ഞാൻ പാപമോചനം തേടുകയും ചെയ്യുന്നു." (ന)', 'شَدَّادِ بْنِ أَوْسٍ', 'ശദ്ദാദുബ്നു ഔസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 272, 'عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَتْ أُمُّ سُلَيْمٍ إِلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللهِ، عَلِّمْنِي كَلِمَاتٍ أَدْعُو بِهِنَّ فِي صَلَاتِي. قَالَ: "سَبِّحِي اللهَ عَشْرًا، وَاحْمَدِيهِ عَشْرًا، وَكَبِّرِيهِ عَشْرًا، ثُمَّ سَلِيهِ حَاجَتَكِ يَقُلْ: نَعَمْ، نَعَمْ". (ن)', 'അനസുബ്നു മാലിക്(റ): ഉമ്മു സുലൈം റസൂലി(സ)ന്റെ അടുത്തുവന്ന് പറഞ്ഞു: അല്ലാഹുവിന്റെ ദൂതരെ, നിസ്കാരത്തിൽ ചൊല്ലാനുള്ള പ്രാർത്ഥന എന്നെ പഠിപ്പിച്ചാലും, നബി(സ) പറഞ്ഞു: "പത്തു തവണ അല്ലാഹുവിനെ വാഴ്ത്തുക, പത്തു തവണ സ്തുതിക്കുക, പത്തു തവണ തക്ബീർ ചെല്ലുക. പിന്നെ നിന്റെ ആവശ്യങ്ങൾ ചോദിക്കുക, അല്ലാഹു ''അതെ'', ''അതെ'' എന്നു പറയും." (ന)', 'أَنَسِ بْنِ مَالِكٍ', 'അനസുബ്നു മാലിക്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 273, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "إِذَا فَرَغَ أَحَدُكُمْ مِنَ التَّشَهُّدِ الْأَخِيرِ فَلْيَتَعَوَّذْ بِاللهِ مِنْ أَرْبَعٍ: مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ. (م,د,ن,جه)', 'അബൂഹുറൈറ(റ): തിരുമേനി(സ) അരുളി: "നിങ്ങളിലൊരാൾ അവസാനത്തെ തശഹ്ഹുദ് ചൊല്ലിക്കഴിഞ്ഞാൽ അവൻ ഈ നാലു കാര്യങ്ങളിൽ നിന്നും രക്ഷതേടിക്കൊള്ളട്ടെ; നരക ശിക്ഷയിൽനിന്ന്, ഖബ്റിലെ ശിക്ഷയിൽനിന്ന്, ജീവിതത്തിലെയും മരണത്തിലെയും പരീക്ഷണങ്ങളിൽനിന്ന്, മസീഹുദ്ദജ്ജാലിന്റെ കുഴപ്പത്തിൽനിന്ന്." (മു,ദ,ന,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','د','ن','جه']::text[], array['മു','ദ','ന','ജ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 274, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ: "مَا تَقُولُ فِي الصَّلَاةِ". قَالَ: أَتَشَهَّدُ، ثُمَّ أَسْأَلُ اللهَ الْجَنَّةَ وَأَعُوذُ بِهِ مِنَ النَّارِ، أَمَا وَاللهِ مَا أُحْسِنُ دَنْدَنَتَكَ وَلَا دَنْدَنَةَ مُعَاذٍ. فَقَالَ: "حَوْلَهَا نُدَنْدِنُ". (جه)', 'അബൂഹുറൈറ(റ): നബി(സ) ഒരാളോട് ചോദിച്ചു: "താങ്കൾ എന്താണ് നിസ്കാരത്തിൽ ചൊല്ലാറുള്ളത്?" അദ്ദേഹം പറഞ്ഞു: ഞാൻ തശഹ്ഹുദ് ചൊല്ലും, ശേഷം സ്വർഗ്ഗത്തെ തേടുകയും നരകമോചനം തേടുകയും ചെയ്യും. എന്നാൽ താങ്കളുടെയോ മുആദിന്റെയോ പ്രാർത്ഥനയെ എനിക്കറിയില്ല. അപ്പോൾ അവിടുന്ന് പറഞ്ഞു: "ഞങ്ങളും ഏറെക്കുറെ അപ്രകാരം തന്നെയാണ് പ്രാർത്ഥിക്കുന്നത്." (ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['جه']::text[], array['ജ']::text[], null, null, 508, 508, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=75 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 275, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا قَالَ: نَهَى رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ يَجْلِسَ الرَّجُلُ فِي الصَّلَاةِ وَهُوَ مُعْتَمِدٌ عَلَى يَدِهِ. وَفِي رِوَايَةٍ: نَهَى أَنْ يَعْتَمِدَ الرَّجُلُ عَلَى يَدَيْهِ إِذَا نَهَضَ فِي الصَّلَاةِ. (د)', 'ഇബ്നു ഉമർ(റ): കൈ നിലത്തൂന്നിക്കൊണ്ട് നിസ്കാരത്തിൽ ഇരിക്കുന്നതിനെ നബി(സ) നിരോധിച്ചു. മറ്റൊരു റിപ്പോർട്ടിൽ: ഒരാൾ നിസ്കാരത്തിൽ എഴുന്നേൽക്കുമ്പോൾ തന്റെ കൈകൾ നിലത്തൂന്നുന്നതിനെ നിരോധിച്ചു. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നു ഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=275), 1, 'وَفِي رِوَايَةٍ: نَهَى أَنْ يَعْتَمِدَ الرَّجُلُ عَلَى يَدَيْهِ إِذَا نَهَضَ فِي الصَّلَاةِ. (د)', 'മറ്റൊരു നിവേദനിൽ: ഒരാൾ നിസ്കാരത്തിൽ എഴുന്നേൽക്കുമ്പോൾ തന്റെ കൈകൾ നിലത്തൂന്നുന്നതിനെ നിരോധിച്ചു. (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 276, 'عَنْ مَالِكِ بْنِ الْحُوَيْرِثِ رَضِيَ اللهُ عَنْهُ قَالَ: أَلَا أُحَدِّثُكُمْ عَنْ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ فَيُصَلِّي فِي غَيْرِ وَقْتِ الصَّلَاةِ، فَإِذَا رَفَعَ رَأْسَهُ مِنَ السَّجْدَةِ الثَّانِيَةِ فِي أَوَّلِ الرَّكْعَةِ اسْتَوَى قَاعِدًا، ثُمَّ قَامَ فَاعْتَمَدَ عَلَى الْأَرْضِ. (ن)', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ): നബി(സ)യുടെ നിസ്കാര(ത്തിന്റെ രൂപ)ത്തെക്കുറിച്ച് ഞാൻ നിങ്ങൾക്ക് അറിയിച്ചു തരട്ടെയോ എന്ന് പറഞ്ഞു കൊണ്ട് അദ്ദേഹം (നിസ്കാര രൂപം കാണിക്കാൻ വേണ്ടി) നിസ്കാര സമയത്തല്ലാതെ നിസ്കരിച്ചു. ആദ്യ റക്അത്തിൽ രണ്ടാമത്തെ സുജൂദിൽ നിന്നുയരുമ്പോൾ അടങ്ങി ഇരുന്നു, ശേഷം നിലത്ത് ഊന്നി എഴുന്നേറ്റു. (ന)', 'مَالِكِ بْنِ الْحُوَيْرِثِ', 'മാലികുബ്നുൽ ഹുവൈരിസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 277, 'عَنْ إِسْمَعِيلَ بْنِ أُمَيَّةَ رَضِيَ اللهُ عَنْهُ قَالَ: سَأَلْتُ نَافِعًا عَنِ الرَّجُلِ يُصَلِّي وَهُوَ مُشَبِّكٌ يَدَيْهِ؟ قَالَ: قَالَ ابْنُ عُمَرَ: تِلْكَ صَلَاةُ الْمَغْضُوبِ عَلَيْهِمْ. (د)', 'ഇസ്മാഈലുബ്നു ഉമയ്യ(റ): കൈകോർത്ത് നിസ്കരിക്കുന്നതിനെക്കുറിച്ച് ഞാൻ നാഫിഇനോട് ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞു: അത് കോപിക്കപ്പെട്ടവരുടെ നിസ്കാരമാണെന്ന് ഇബ്നു ഉമർ(റ) പറഞ്ഞിട്ടുണ്ട്. (ദ)', 'إِسْمَعِيلَ بْنِ أُمَيَّةَ', 'ഇസ്മാഈലുബ്നു ഉമയ്യ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 278, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّهُ رَأَى رَجُلًا يَتَّكِئُ عَلَى يَدِهِ الْيُسْرَى وَهُوَ قَاعِدٌ فِي الصَّلَاةِ – وَفِي رِوَايَةٍ: سَاقِطًا عَلَى شِقِّهِ الْأَيْسَرِ – فَقَالَ لَهُ: لَا تَجْلِسْ هَكَذَا، فَإِنَّ هَكَذَا يَجْلِسُ الَّذِينَ يُعَذَّبُونَ. (د)', 'ഇബ്നുഉമർ(റ): ഒരാൾ തന്റെ ഇടതുകൈ നിലത്തൂന്നിക്കൊണ്ട് നിസ്കാരത്തിൽ ഇരിക്കുന്നത് കണ്ടു. - ഒരു റിപ്പോർട്ടിൽ: ഇടതു ഭാഗത്തേക്ക് ചെരിഞ്ഞു കൊണ്ട് - അപ്പോൾ അദ്ദേഹം അയാളോട് പറഞ്ഞു: ഇപ്രകാരം ഇരിക്കരുത്, ശിക്ഷിക്കപ്പെടുന്നവരാണ് ഈ വിധം ഇരിക്കുന്നത്. (ദ)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=76 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=278), 1, 'وَفِي رِوَايَةٍ: سَاقِطًا عَلَى شِقِّهِ الْأَيْسَرِ – فَقَالَ لَهُ: لَا تَجْلِسْ هَكَذَا، فَإِنَّ هَكَذَا يَجْلِسُ الَّذِينَ يُعَذَّبُونَ. (د)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 279, 'عَنْ عِتْبَانَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْنَا مَعَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمْنَا حِينَ سَلَّمَ. (خ)', 'ഇത്ബാൻ(റ): ഞങ്ങൾ നബി(സ)യോടൊപ്പം നിസ്കരിച്ചു. നബി(സ) സലാം വീട്ടിയപ്പോൾ ഞങ്ങളും സലാം വീട്ടി. (ബു)', 'عِتْبَانَ', 'ഇത്ബാൻ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 280, 'عَنْ عَمَّارٍ ابْنِ يَاسِرٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يُسَلِّمُ عَنْ يَمِينِهِ، وَعَنْ يَسَارِهِ حَتَّى يُرَى بَيَاضُ خَدِّهِ: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ، السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللهِ". (م,د,ت,ن,جه)', 'അമ്മാറുബ്നു യാസിർ(റ): നബി(സ) ''അസ്സലാമു അലൈക്കും വറഹ്മത്തുല്ലാ,'' ''അസ്സലാമു അലൈക്കും വറഹ്മത്തുല്ലാ'' എന്ന് പറഞ്ഞുകൊണ്ട് തന്റെ കവിളിന്റെ വെള്ള കാണും വിധം ഇടത്തോട്ടും വലത്തോട്ടും സലാം വീട്ടിയിരുന്നു. (ബു,മു,ദ,തു,ന,ജ)', 'عَمَّارٍ ابْنِ يَاسِرٍ', 'അമ്മാറുബ്നു യാസിർ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['ബു','മു','ദ','തു','ന','ജ']::text[], null, null, 509, 509, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 281, 'عَنْ جابر بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كُنَّا إذا صَلَّيْنَا خَلْفَ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ، أحَدُنَا أشَارَ بيَدِه من عَنْ يمينه وَمِنْ عَنْ يسَارِه، فَلَمَّا صَلَّى قَالَ: "مَا بَالُ أحَدِكُمْ يُومِي بيَدِه كَأَنَّهَا أذْنَابُ خَيْلِ شُمْسٍ؟ إنَّمَا يَكْفِي أحَدَكُمْ – أوْ: ألَا يَكْفِي أحَدَكُمْ – أنْ يَقُولَ هَكَذَا – وَأشَارَ بأصْبَعِه – يُسَلِّمُ عَلَى أخِيه مِنْ عَنْ يمينه وَمِنْ عَنْ شماله". (م,د,ن)', 'ജാബിറുബ്നു സമുറ(റ): ഞങ്ങൾ റസൂലി(സ)ന്റെ പിന്നിൽ നിസ്കരിക്കുമ്പോൾ ഒരാൾ വിരലു കൊണ്ട് വലത്തോട്ടും ഇടത്തോട്ടും ചൂണ്ടികൊണ്ട് സലാം വീട്ടി. നിസ്കാരമവസാനിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "വിറളി പിടിച്ച കുതിരയുടെ വാലുകളെപ്പോലെ തന്റെ കൈവിരൽ ഇളക്കിയവന്റെ അവസ്ഥ എന്താണ്? നിങ്ങൾ ഇപ്രകാരം ചെയ്താൽ പോരേ, തന്റെ വലതുഭാഗത്തും ഇടതുഭാഗത്തുമുള്ള സഹോദരന് സലാം ചെല്ലുക." വിരലുകൊണ്ട് ഇടതും വലതും ചൂണ്ടിക്കൊണ്ട് തിരുമേനി പറഞ്ഞു. (മു,ദ,ന)', 'جابر بْنِ سَمُرَةَ', 'ജാബിറുബ്നു സമുറ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 282, 'عَنْ واسع بْنِ حَبَّانَ رَضِيَ اللهُ عَنْهُ قَالَ: قُلتُ لابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أخْبِرْنِي عَنْ صَلاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَيفَ كَانَتْ. قَالَ: فَذَكَرَ التَّكْبِيرَ، قَالَ: وَذَكَرَ: "السَّلَامُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ" عَنْ يمينه"السَّلَامُ عَلَيْكُمْ" عَنْ يَسَارِه. (ن)', 'വാസിഉബ്നു ഹബ്ബാൻ(റ): ഞാൻ ഇബ്നുഉമറി(റ)നോട് പറഞ്ഞു: നബി(സ)യുടെ നിസ്കാരം എപ്രകാരമായിരുന്നു എന്ന് എനിക്ക് പറഞ്ഞുതരിക! (അങ്ങനെ അദ്ദേഹം തക്ബീർ മുതൽ സലാം വീട്ടുന്നതുവരെയുള്ള [കർമ്മങ്ങൾ] വിവരിച്ചു). അദ്ദേഹം പറഞ്ഞു: "അസ്സലാമു അലൈക്കും വറഹ്മത്തുല്ലാ" വലത്തോട്ടും "അസ്സലാമു അലൈക്കും" ഇടത്തോട്ടും. (ന)', 'واسع بْنِ حَبَّانَ', 'വാസിഉബ്നു ഹബ്ബാൻ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 283, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يُسَلِّمُ تَسْلِيمَةً وَاحِدَةً تِلْقَاءَ وَجْهِهِ. (ت,جه)', 'ആഇശ(റ): നബി(സ) മുഖം മുന്നോട്ട് തിരിച്ച്കൊണ്ട് ഒറ്റ സലാം മാത്രം ചൊല്ലിയിരുന്നു. (തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ت','جه']::text[], array['തു','ജ']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 284, 'عَنْ سَلَمَةَ بْنِ الْأَكْوَعِ رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَّى، فَسَلَّمَ مَرَّةً وَاحِدَةً. [ز:في إسناده ضعيف] (جه)', 'സൽമതുബ്നു അക്വഅ്(റ): നബി(സ) നിസ്കരിക്കുന്നത് ഞാൻ കണ്ടു. ഒരു പ്രാവശ്യമാണ് നബി(സ) സലാം പറഞ്ഞത്. (ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു) (ജ)', 'سَلَمَةَ بْنِ الْأَكْوَعِ', 'സൽമതുബ്നു അക്വഅ്(റ)', null, null, array['جه']::text[], array['ജ']::text[], 'ز:في إسناده ضعيف', 'ഇതിന്റെ പരമ്പരയിൽ ദുർബ്ബലനുണ്ടെന്ന് ഇബ്നുമാജ പറയുന്നു', 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 285, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "إذا سَلَّمَ الْإِمَامُ فَرُدُّوا عَلَيْهِ". وَفِي رِوَايَةٍ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُسَلِّمَ عَلَى أَئِمَّتِنَا، وَأَنْ يُسَلِّمَ بَعْضُنَا عَلَى بَعْضٍ. (د,جه)', 'സമുറതുബ്നു ജുൻദബ്(റ): നബി(സ) പറഞ്ഞു: "ഇമാം സലാം പറഞ്ഞാൽ നിങ്ങൾ സലാം മടക്കുക."
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=285), 1, 'وَفِي رِوَايَةٍ قَالَ: أَمَرَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نُسَلِّمَ عَلَى أَئِمَّتِنَا، وَأَنْ يُسَلِّمَ بَعْضُنَا عَلَى بَعْضٍ. (د,جه)', 'മറ്റൊരു നിവേദനിൽ: നമ്മുടെ നേതാക്കൾക്കും, ഞങ്ങൾ പരസ്പരവും സലാം ചെല്ലാൻ നബി(സ) കൽപിച്ചു. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 286, 'عَنْ سَمُرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنَا النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ نَرُدَّ عَلَى الْإِمَامِ وَأَنْ نَتَحَابَّ، وَأَنْ يُسَلِّمَ بَعْضُنَا عَلَى بَعْضٍ. (د,جه)', 'സമുറ(റ): ഇമാമിന് സലാം മടക്കി ചൊല്ലണമെന്നും, പരസ്പരം സ്നേഹിക്കണമെന്നും, പരസ്പരം സലാം ചൊല്ലണമെന്നും നബി(സ) ഞങ്ങളോട് കൽപ്പിച്ചു. (ദ,ജ)', 'سَمُرَةَ', 'സമുറ(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 510, 510, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=77 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 287, 'عَنْ وَرَّاد مَوْلَى الْمُغِيرَةِ بْنِ شُعْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: كَتَبَ الْمُغِيرَةُ بْنُ شُعْبَةَ إلَى مُعَاوِيَةَ رَضِيَ اللهُ عَنْهُ: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إذَا فَرَغَ مِنَ الصَّلَاةِ وَسَلَّمَ قَالَ: "لَا إلَهَ إلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ". (ق,د,ن)', 'വർറാദ് (മുഗീറത്തുബ്നു ശുഅ്ബയുടെ മൗല): മുഗീറത്തുബ്നു ശുഅ്ബ(റ) മുആവിയ(റ)ക്ക് ഇപ്രകാരം എഴുതി: നബി(സ) നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചാൽ സലാം വീട്ടിയശേഷം പറയും: "അല്ലാഹുവല്ലാതെ യാതൊരു ആരാധ്യനുമില്ല, ഏകനാണവൻ, അവന് പങ്കുകാരില്ല, അവനാണ് ആധിപത്യം, അവനാണ് സ്തുതി, അവൻ എല്ലാത്തിനും കഴിവുള്ളവനാണ്. അല്ലാഹുവേ, നീ നൽകിയത് തടയുന്നവരായും, നീ തടഞ്ഞത് നൽകുന്നവരായും ആരുമില്ല. ധനമുള്ളവന് തന്റെ ധനം നിന്നിൽനിന്നും ഉപകാരം നേടിക്കൊടുക്കുകയില്ല." (ബു,മു,ദ,ന)', 'وَرَّاد مَوْلَى الْمُغِيرَةِ بْنِ شُعْبَةَ', null, null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 511, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 288, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: دَخَلَتْ عَلَيَّ امْرَأَةٌ مِنَ الْيَهُودِ فَقَالَتْ: إنَّ عَذَابَ الْقَبْرِ مِنَ الْبَوْلِ. فَقُلْتُ: كَذَبْتِ. فَقَالَتْ: بَلَى، إنَّا لَنَقْرِضُ مِنْهُ الْجِلْدَ وَالثَّوْبَ. فَخَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إلَى الصَّلَاةِ، وَقَدِ ارْتَفَعَتْ أَصْوَاتُنَا، فَقَالَ: "مَا هَذَا؟". فَأَخْبَرْتُهُ بِمَا قَالَتْ، فَقَالَ: "صَدَقَتْ". فَمَا صَلَّى بَعْدُ يَوْمَئِذٍ صَلَاةً إلَّا قَالَ فِي دُبُرِ الصَّلَاةِ: "رَبَّ جِبْرِيلَ وَمِيكَائِيلَ وَإِسْرَافِيلَ، أَعِذْنِي مِنْ حَرِّ النَّارِ وَعَذَابِ الْقَبْرِ". (ن)', 'ആഇശ(റ): ഒരു ജൂതസ്ത്രീ എന്റെ അടുത്ത് വന്നു. അവൾ പറഞ്ഞു: ഖബ്റിലെ ശിക്ഷ പ്രധാനമായും മൂത്രവുമായി ബന്ധപ്പെട്ടതാണ്. ഞാൻ പറഞ്ഞു: നീ കളവാണ് പറഞ്ഞത്. അവൾ പറഞ്ഞു: അതെ, ഞങ്ങൾ മൂത്രമായ ചർമ്മവും വസ്ത്രവും മുറിച്ചു കളയാറുണ്ട്. അപ്പോഴാണ് നബി(സ) നിസ്കരിക്കാൻ പുറത്തു വന്നത്, ഞങ്ങളുടെ ശബ്ദം ഉയർന്നിരുന്നു. നബി(സ) ചോദിച്ചു: "ഇതെന്താണ്?" അപ്പോൾ അവൾ പറഞ്ഞത് ഞാൻ റസൂലിനോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "അവൾ പറഞ്ഞത് സത്യമാണ്." അതിനുശേഷം എല്ലാ നിസ്കാര ശേഷവും നബി(സ) ഇപ്രകാരം പറയുമായിരുന്നു: "ജിബ്രീലിന്റെയും മീകാഈലിന്റെയും ഇസ്റാഫീലിന്റെയും (മലക്കുകളുടെ) നാഥാ, എന്നെ നരകത്തിലെ ചൂടിൽ നിന്നും ഖബറിലെ ശിക്ഷയിൽ നിന്നും രക്ഷിക്കേണമേ." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 511, 511, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 289, 'عَنْ عَبْدِ اللهِ بْنِ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا انْصَرَفَ مِنَ الصَّلَاةِ يَقُولُ: "لَا إلَهَ إلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا إلَهَ إلَّا اللهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ، أَهْلُ النِّعْمَةِ وَالْفَضْلِ وَالثَّنَاءِ الْحَسَنِ، لَا إلَهَ إلَّا اللهُ مُخْلِصِينَ لَهُ الدِّينَ وَلَوْ كَرِهَ الْكَافِرُونَ". وَفِي رِوَايَةٍ: كَانَ عَبْدُ اللهِ بْنُ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا يُهَلِّلُ فِي دُبُرِ كُلِّ صَلَاةٍ، فَذَكَرَ نَحْوَ هَذَا الدُّعَاءِ، زَادَ فِيهِ: "وَلَا حَوْلَ وَلَا قُوَّةَ إلَّا بِاللهِ، لَا إلَهَ إلَّا اللهُ، لَا نَعْبُدُ إلَّا إيَّاهُ، لَهُ النِّعْمَةُ...." وَسَاقَ الْحَدِيثَ. (م,د,ن)', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ): നബി(സ) നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ചാൽ ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു: "അല്ലാഹുവല്ലാതെ ഒരു ആരാധ്യനുമില്ല, അവൻ ഏകനാകുന്നു, അവന് പങ്കുകാരില്ല, അവന്നാണ് ആധിപത്യം, അവന്നാണ് സ്തുതി, അവൻ എല്ലാറ്റിനും കഴവുള്ളവനാകുന്നു. അല്ലാഹു ഒഴികെ ഒരു ആരാധ്യനുമില്ല, സത്യനിഷേധികൾ വെറുത്താലും. ഞങ്ങൾ നിഷ്കളങ്കമായി അവന്ന് കീഴ്പെട്ടിരിക്കുന്നു. അനുഗ്രഹങ്ങളുടെയും ഔദാര്യങ്ങളുടെയും സ്തുതികളുടെയും ഉടമസ്ഥനാണവൻ. അല്ലാഹുവല്ലാതെ യാതൊരു ആരാധ്യനുമില്ല, ഞങ്ങൾ നിഷ്കളങ്കമായി അവന് കീഴ്പെട്ടിരിക്കുന്നു. സത്യനിഷേധികൾ എത്ര വെറുത്താലും." മറ്റൊരു റിപ്പോർട്ടിൽ: അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) എല്ലാ നമസ്കാരത്തിനു ശേഷവും തഹ്ലീൽ ചൊല്ലുമായിരുന്നു. തുടർന്ന് പ്രസ്തുത പ്രാർത്ഥന ചൊല്ലും. അതിൽ ഇപ്രകാരം അധികരിപ്പിച്ചു: "അല്ലാഹുവിന്നൊഴികെ ഒരു ശക്തിയും കഴിവുമില്ല. അല്ലാഹു ഒഴികെ ഒരു ആരാധ്യനുമില്ല. അവനെയല്ലാതെ ഞങ്ങൾ ആരാധിക്കില്ല. അവന്റേത് മാത്രമാണ് അനുഗ്രഹങ്ങൾ...." ശേഷം അദ്ദേഹം ആ ഹദീസ് തുടർന്നു. (മു,ദ,ന)', 'عَبْدِ اللهِ بْنِ الزُّبَيْرِ', 'അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ)', null, null, array['م','د','ن']::text[], array['മു','ദ','ന']::text[], null, null, 511, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=289), 1, 'وَفِي رِوَايَةٍ: كَانَ عَبْدُ اللهِ بْنُ الزُّبَيْرِ رَضِيَ اللهُ عَنْهُمَا يُهَلِّلُ فِي دُبُرِ كُلِّ صَلَاةٍ، فَذَكَرَ نَحْوَ هَذَا الدُّعَاءِ، زَادَ فِيهِ: "وَلَا حَوْلَ وَلَا قُوَّةَ إلَّا بِاللهِ، لَا إلَهَ إلَّا اللهُ، لَا نَعْبُدُ إلَّا إيَّاهُ، لَهُ النِّعْمَةُ...." وَسَاقَ الْحَدِيثَ. (م,د,ن)', 'മറ്റൊരു നിവേദനിൽ: അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) എല്ലാ നമസ്കാരത്തിനു ശേഷവും തഹ്ലീൽ ചൊല്ലുമായിരുന്നു. തുടർന്ന് പ്രസ്തുത പ്രാർത്ഥന ചൊല്ലും. അതിൽ ഇപ്രകാരം അധികരിപ്പിച്ചു: "അല്ലാഹുവിന്നൊഴികെ ഒരു ശക്തിയും കഴിവുമില്ല. അല്ലാഹു ഒഴികെ ഒരു ആരാധ്യനുമില്ല. അവനെയല്ലാതെ ഞങ്ങൾ ആരാധിക്കില്ല. അവന്റേത് മാത്രമാണ് അനുഗ്രഹങ്ങൾ...." ശേഷം അദ്ദേഹം ആ ഹദീസ് തുടർന്നു. (മു,ദ,ന)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 290, 'عَنْ زَيْدِ بْنِ أَرْقَمَ رَضِيَ اللهُ عَنْهُ قَالَ سَمِعْتُ نَبِيَّ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي دُبُرِ صَلَاتِهِ: "اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ، أَنَّكَ أَنْتَ الرَّبُّ وَحْدَكَ لَا شَرِيكَ لَكَ. اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ أَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ. اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، أَنَا شَهِيدٌ أَنَّ الْعِبَادَ كُلَّهُمْ إخْوَةٌ. اللَّهُمَّ رَبَّنَا وَرَبَّ كُلِّ شَيْءٍ، اجْعَلْنِي مُخْلِصًا لَكَ وَأَهْلِي فِي كُلِّ سَاعَةٍ فِي الدُّنْيَا وَالْآخِرَةِ، يَا ذَا الْجَلَالِ وَالْإِكْرَامِ اسْمَعْ وَاسْتَجِبْ. اللَّهُ أَكْبَرُ الْأَكْبَرُ، اللَّهُمَّ نُورَ – وَفِي رِوَايَةٍ: رَبَّ – السَّمَوَاتِ وَالْأَرْضِ، اللَّهُ أَكْبَرُ الْأَكْبَرُ، حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ، اللَّهُ أَكْبَرُ الْأَكْبَرُ". (د)', 'സൈദുബ്നു അർഖം(റ): നിസ്കാര ശേഷം നബി(സ) പറയുന്നതായി ഞാൻ കേട്ടു: "അല്ലാഹുവേ, ഞങ്ങളുടെ നാഥാ, എല്ലാ വസ്തുക്കളുടെയും നാഥാ, നിശ്ചയം നീ ഏകനായ രക്ഷാധികാരിയാണ് എന്നതിന് ഞാൻ സാക്ഷിയാണ്. നിനക്ക് പങ്കുകാരില്ല. അല്ലാഹുവേ, ഞങ്ങളുടെ നാഥാ, എല്ലാ വസ്തുക്കളുടെയും നാഥാ, നിശ്ചയം മുഹമ്മദ്(സ) നിന്റെ ദാസനും ദൂതനുമാണ് എന്നതിന് ഞാൻ സാക്ഷിയാണ്. അല്ലാഹുവേ, ഞങ്ങളുടെ നാഥാ, എല്ലാ വസ്തുക്കളുടെയും നാഥാ, നിശ്ചയം എല്ലാ അടിമകളും സഹോദരങ്ങളാണ് എന്നതിനും ഞാൻ സാക്ഷിയാണ്. അല്ലാഹുവേ, ഞങ്ങളുടെയും എല്ലാ വസ്തുക്കളുടെയും നാഥാ, ഇഹലോകത്തെയും പരലോകത്തെയും എല്ലാ സമയത്തും എന്നെയും എന്റെ കുടുംബത്തെയും നിഷ്കളങ്കമായി നിന്നെ ആരാധിക്കുന്നവരാക്കേണമേ. മഹത്വവും ആദരവുമുള്ളവനെ, (ഈ പ്രാർത്ഥന) നീ കേൾക്കണേ, ഉത്തരം നൽകണേ, അല്ലാഹു മഹാന്മാരിൽ ഏറ്റവും മഹാനാകുന്നു. ആകാശങ്ങളുടെയും ഭൂമിയുടെയും പ്രകാശമാണ് - മറ്റൊരു നിവേദനത്തിൽ: നാഥനാണ് - അല്ലാഹു. അല്ലാഹു മഹാന്മാരിൽ ഏറ്റവും മഹാനാകുന്നു. എനിക്കല്ലാഹു മതി, ഭരമേൽപിക്കാൻ അർഹൻ അവനാകുന്നു. അല്ലാഹു ഏറ്റവും വലിയവനാകുന്നു." (ദ)', 'زَيْدِ بْنِ أَرْقَمَ', 'സൈദുബ്നു അർഖം(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=290), 1, 'وَفِي رِوَايَةٍ: رَبَّ – السَّمَوَاتِ وَالْأَرْضِ، اللَّهُ أَكْبَرُ الْأَكْبَرُ، حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ، اللَّهُ أَكْبَرُ الْأَكْبَرُ". (د)', 'മറ്റൊരു നിവേദനത്തിൽ: നാഥനാണ് - അല്ലാഹു. അല്ലാഹു മഹാന്മാരിൽ ഏറ്റവും മഹാനാകുന്നു. എനിക്കല്ലാഹു മതി, ഭരമേൽപിക്കാൻ അർഹൻ അവനാകുന്നു. അല്ലാഹു ഏറ്റവും വലിയവനാകുന്നു." (ദ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 291, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ إذَا جَلَسَ مَجْلِسًا أَوْ صَلَّى تَكَلَّمَ بِكَلِمَاتٍ، فَسَأَلَتْهُ عَائِشَةُ عَنِ الْكَلِمَاتِ فَقَالَ: "إنْ تَكَلَّمَ بِخَيْرٍ كَانَ طَابِعًا عَلَيْهِنَّ إلَى يَوْمِ الْقِيَامَةِ، وَإنْ تَكَلَّمَ بِغَيْرِ ذَلِكَ كَانَ كَفَّارَةً لَهُ: سُبْحَانَكَ اللَّهُمَّ وَبِحَمْدِكَ، أَسْتَغْفِرُكَ وَأَتُوبُ إلَيْكَ". (ن)', 'ആഇശ(റ): നബി(സ) ഒരിടത്തിരിക്കുകയോ നിസ്കരിക്കുകയോ ചെയ്താൽ ചില വചനങ്ങൾ പറയുമായിരുന്നു. ആഇശ(റ) അതിനെ കുറിച്ച് ചോദിച്ചപ്പോൾ നബി(സ) പറഞ്ഞു: "നീ നല്ലതാണ് സംസാരിക്കുന്നതെങ്കിൽ അന്ത്യനാൾ വരെ അത് സീൽ വെക്കപ്പെടുന്നതാവും, അതല്ലാത്തതാണ് സംസാരിക്കുന്നതെങ്കിൽ ഇങ്ങനെ ചൊല്ലൽ അതിന് പരിഹാരമാകും: പരിശുദ്ധനായ അല്ലാഹുവേ, നിന്നെ സ്തുതിക്കുന്നു, നിന്നോട് പൊറുക്കലിനെ തേടുകയും നിന്നിലേക്ക് പശ്ചാത്തപിച്ച് മടങ്ങുകയും ചെയ്യുന്നു." (ന)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 292, 'عَنْ عَائِشَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا سَلَّمَ لَا يَقْعُدُ إلَّا مِقْدَارَ مَا يَقُولُ: "اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالْإِكْرَامِ". حَسَنٌ صَحِيحٌ. (م,ت,جه)', 'ആഇശ(റ): നബി(സ) നിസ്കാരത്തിൽ നിന്ന് സലാം വീട്ടിയാൽ; "അല്ലാഹുവേ, നീയാണ് സമാധാനം, നിന്നിൽ നിന്നാണ് സമാധാനം, മഹത്വവും പ്രതാപവുമുള്ളവനേ നീ അനുഗ്രഹപൂർണ്ണനാകുന്നു" എന്ന് ചെല്ലുന്ന സമയമല്ലാതെ അവിടെ ഇരിക്കാറില്ല. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി). (മു,തു,ജ)', 'عَائِشَةَ', 'ആഇശ(റ)', null, null, array['م','ت','جه']::text[], array['മു','തു','ജ']::text[], null, null, 512, 512, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 293, 'عَنْ ثَوْبَانَ رَضِيَ اللهُ عَنْهُ – مَوْلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ – قَالَ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا أَرَادَ أَنْ يَنْصَرِفَ مِنْ صَلَاتِهِ اسْتَغْفَرَ اللهَ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: "اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ". حَسَنٌ صَحِيحٌ. (م,د,ت,ن,جه)', 'സൗബാൻ(റ): നബി(സ) നിസ്കാരം നിർവ്വഹിച്ച് തിരിഞ്ഞിരിക്കാൻ ഉദ്ദേശിച്ചാൽ മൂന്നുപ്രാവശ്യം അല്ലാഹുവിനോട് പാപമോചനത്തിന് (അസ്തഗ്ഫിറുല്ലാഹ്) പ്രാർത്ഥിക്കുകയും ഇപ്രകാരം ചൊല്ലുകയും ചെയ്യും: "അല്ലാഹുവേ നീയാണ് സമാധാനം, നിന്നിൽ നിന്നാണ് സമാധാനം, മഹത്വവും മാന്യതയുമുള്ള നീ അനുഗ്രഹ പൂർണ്ണനാകുന്നു." (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (മു,ദ,തു,ന,ജ)', 'ثَوْبَانَ', 'സൗബാൻ(റ)', null, null, array['م','د','ت','ن','جه']::text[], array['മു','ദ','തു','ന','ജ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 294, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ، ثُمَّ يَلْبَثُ فِي مَكَانِهِ يَسِيرًا قَبْلَ أَنْ يَقُومَ. (خ,د,ن,جه)', 'ഉമ്മുസലമ(റ): നബി(സ) സലാം വീട്ടിയാൽ സ്ത്രീകൾ എഴുന്നേറ്റ് പോകും, എഴുന്നേൽക്കുന്നതിന് മുമ്പ് നബി(സ) അൽപസമയം അവിടെ തന്നെ ഇരിക്കും. (ബു,ദ,ന,ജ)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ','د','ن','جه']::text[], array['ബു','ദ','ന','ജ']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 295, 'عَنِ ابْنِ عُمَرَ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَجُلًا رَأَى فِيمَا يَرَى النَّائِمُ قِيلَ لَهُ: بِأَيِّ شَيْءٍ أَمَرَكُمْ نَبِيُّكُمْ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: أَمَرَنَا أَنْ نُسَبِّحَ ثَلَاثًا وَثَلَاثِينَ، وَنَحْمَدَ ثَلَاثًا وَثَلَاثِينَ، وَنُكَبِّرَ أَرْبَعًا وَثَلَاثِينَ، فَتِلْكَ مِائَةٌ. قَالَ: سَبِّحُوا خَمْسًا وَعِشْرِينَ، وَاحْمَدُوا خَمْسًا وَعِشْرِينَ، وَكَبِّرُوا خَمْسًا وَعِشْرِينَ، وَهَلِّلُوا خَمْسًا وَعِشْرِينَ، فَتِلْكَ مِائَةٌ. فَلَمَّا أَصْبَحَ ذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "افْعَلُوا كَمَا قَالَ الْأَنْصَارِيُّ". (ن)', 'ഇബ്നുഉമർ(റ): ഒരാൾ ഉറക്കത്തിൽ കാണുന്നതുപോലെ കണ്ടു. അയാൾ ചോദിക്കപ്പെട്ടു: നിങ്ങളുടെ പ്രവാചകൻ എന്താണ് കൽപിച്ചത്? അയാൾ പറഞ്ഞു: മുപ്പത്തിമൂന്ന് പ്രാവശ്യം ''തസ്ബീഹ്'' ചെല്ലാനും, മുപ്പത്തിമൂന്ന് പ്രാവശ്യം ഹംദ് ചെല്ലാനും, മുപ്പത്തിനാല് പ്രാവശ്യം ''തക്ബീർ'' ചൊല്ലാനും, അങ്ങനെ നൂറ്. അയാൾ പറഞ്ഞു: ഇരുപത്തി അഞ്ച് പ്രാവശ്യം ''തസ്ബീഹ്'' ചൊല്ലുക, ഇരുപത്തി അഞ്ച് പ്രാവശ്യം ''ഹംദ്'' ചൊല്ലുക, ഇരുപത്തി അഞ്ച് പ്രാവശ്യം തക്ബീർ ചൊല്ലുക, ഇരുപത്തി അഞ്ച് പ്രാവശ്യം തഹ്ലീൽ ചൊല്ലുക, അങ്ങനെ നൂറ്. പ്രഭാതമായപ്പോൾ സംഭവം നബി(സ)യോട് പറഞ്ഞു. നബി(സ) പറഞ്ഞു: "നിങ്ങൾ അൻസാരി പറഞ്ഞതു പോലെ ചെയ്യുക." (ന)', 'ابْنِ عُمَرَ', 'ഇബ്നുഉമർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 296, 'عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا سَلَّمَ مِنَ الصَّلَاةِ قَالَ: "اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ وَ[أَنْتَ] الْمُؤَخِّرُ، لَا إلَهَ إلَّا أَنْتَ". (د,ن,جه)', 'അലി(റ): നബി(സ) നിസ്കാരത്തിൽ നിന്ന് സലാം വീട്ടിയാൽ ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: അല്ലാഹുവേ ഞാൻ മുന്തിച്ച് ചെയ്തതും പിന്തിച്ച് ചെയ്തതുമായ ദോഷങ്ങളും രഹസ്യമായും പരസ്യമായും അമിതമായും പ്രവർത്തിച്ച തെറ്റുകളും എന്നിൽ നിന്നും നിനക്ക് അറിയുന്ന മുഴുവൻ കുറ്റങ്ങളും പൊറുത്ത് തരേണമേ. നീയാണ് മുന്തിക്കുന്നവനും പിന്തിക്കുന്നവനും. നീയല്ലാതെ ഒരു ആരാധ്യനുമില്ല. (ദ,ന,ജ)', 'عَلِيِّ بْنِ أَبِي طَالِبٍ', 'അലി(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], 'أَنْتَ', null, 513, 513, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 297, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَدْعُو: "رَبِّ أَعِنِّي وَلَا تُعِنْ عَلَيَّ وَانْصُرْنِي وَلَا تَنْصُرْ عَلَيَّ وَامْكُرْ لِي وَلَا تَمْكُرْ عَلَيَّ وَاهْدِنِي وَيَسِّرْ هُدَايَ إلَيَّ وَانْصُرْنِي عَلَى مَنْ بَغَى عَلَيَّ، اللَّهُمَّ اجْعَلْنِي لَكَ شَاكِرًا لَكَ ذَاكِرًا لَكَ رَاهِبًا لَكَ مِطْوَاعًا إلَيْكَ مُخْبِتًا أَوْ مُنِيبًا، رَبِّ تَقَبَّلْ تَوْبَتِي وَاغْسِلْ حَوْبَتِي وَأَجِبْ دَعْوَتِي وَثَبِّتْ حُجَّتِي وَاهْدِ قَلْبِي وَسَدِّدْ لِسَانِي وَاسْلُلْ سَخِيمَةَ قَلْبِي". (د,جه)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഇപ്രകാരം പ്രാർത്ഥിക്കാറുണ്ടായിരുന്നു: "എന്റെ രക്ഷിതാവേ, നീ എന്നെ സഹായിക്കേണമേ, എനിക്കെതിരിൽ ആരെയും സഹായിക്കരുത്. എനിക്കനുകൂലമായി നീ തന്ത്രം പ്രയോഗിക്കുക. എനിക്കെതിരിൽ നീ പ്രയോഗിക്കരുത്. എന്നെ നേർമാർഗ്ഗത്തിലാക്കുകയും എന്റെ സന്മാർഗ്ഗം എളുപ്പമാക്കുകയും ചെയ്യേണമേ." മറ്റൊരു റിപ്പോർട്ടിൽ: എന്റെ മേൽ അക്രമം അഴിച്ചു വിടുന്നവർക്കെതിരിൽ എന്നെ നീ സഹായിക്കേണമേ. എന്നെ നീ നിനക്ക് നന്ദി ചെയ്യുന്ന, നിന്നെ ഓർക്കുന്ന, നിന്നെ ഭയക്കുന്ന ജീവിതം നയിക്കുന്ന, നിന്നെ കൂടുതൽ വഴിപ്പെടുന്ന, നിന്നിലേക്ക് ഖേദിച്ച് മടങ്ങുന്ന അടിമയാക്കേണമേ. എന്റെ രക്ഷിതാവേ, എന്റെ പശ്ചാതപം നീ സ്വീകരിക്കേണമേ. എന്റെ തെറ്റുകുറ്റങ്ങൾ കഴുകിക്കളയേണമേ. എന്റെ പ്രാർത്ഥനക്കുത്തരം നൽകേണമേ. എന്റെ തെളിവ് നീ സ്ഥിരപ്പെടുത്തേണമേ. എന്റെ ഹൃദയത്തിന് നീ നേർമാർഗ്ഗം കാണിച്ചു തരേണമേ. നാവ് ശരിപ്പെടുത്തിത്തരേണമേ. എന്റെ ഹൃദയത്തിൽ നിന്നും പോര് നീക്കിക്കളയേണമേ. (ദ,ജ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 513, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=78 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=297), 1, null, 'മറ്റൊരു നിവേദനിൽ: എന്റെ മേൽ അക്രമം അഴിച്ചു വിടുന്നവർക്കെതിരിൽ എന്നെ നീ സഹായിക്കേണമേ. എന്നെ നീ നിനക്ക് നന്ദി ചെയ്യുന്ന, നിന്നെ ഓർക്കുന്ന, നിന്നെ ഭയക്കുന്ന ജീവിതം നയിക്കുന്ന, നിന്നെ കൂടുതൽ വഴിപ്പെടുന്ന, നിന്നിലേക്ക് ഖേദിച്ച് മടങ്ങുന്ന അടിമയാക്കേണമേ. എന്റെ രക്ഷിതാവേ, എന്റെ പശ്ചാതപം നീ സ്വീകരിക്കേണമേ. എന്റെ തെറ്റുകുറ്റങ്ങൾ കഴുകിക്കളയേണമേ. എന്റെ പ്രാർത്ഥനക്കുത്തരം നൽകേണമേ. എന്റെ തെളിവ് നീ സ്ഥിരപ്പെടുത്തേണമേ. എന്റെ ഹൃദയത്തിന് നീ നേർമാർഗ്ഗം കാണിച്ചു തരേണമേ. നാവ് ശരിപ്പെടുത്തിത്തരേണമേ. എന്റെ ഹൃദയത്തിൽ നിന്നും പോര് നീക്കിക്കളയേണമേ. (ദ,ജ)');
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 298, 'عَنِ الْبَرَاءِ ابْنِ عَازِبٍ رَضِيَ اللهُ عَنْهُ قَالَ: رَمَقْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فِي صَلَاتِهِ، فَوَجَدْتُ: قِيَامَهُ، وَرَكْعَتَهُ، وَاعْتِدَالَهُ بَعْدَ الرَّكْعَةِ، فَسَجْدَتَهُ، فَجِلْسَتَهُ بَيْنَ السَّجْدَتَيْنِ، فَسَجْدَتَهُ فَجِلْسَتَهُ بَيْنَ التَّسْلِيمِ وَالِانْصِرَافِ، قَرِيبًا مِنَ السَّوَاءِ. (ن)', 'ബറാഉബ്നു ആസിബ്(റ): ഞാൻ നബി(സ)യുടെ നിസ്കാരം നിരീക്ഷിച്ചു. തിരുമേനി(സ)യുടെ നിർത്തവും, റുകൂഉം, ഇഅ്തിദാലും, സുജൂദും, സുജൂദുകൾക്കിടയിലുള്ള ഇരുത്തവും, സലാം വീട്ടുന്നതിന്നു മുമ്പുള്ള സുജൂദും, പിരിഞ്ഞു പോകലും, ഏതാണ്ട് തുല്യ സമയമായിരുന്നു എന്നെനിക്ക് മനസ്സിലായി. (ന)', 'الْبَرَاءِ ابْنِ عَازِبٍ', 'ബറാഉബ്നു ആസിബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 299, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا: أَنَّ النِّسَاءَ فِي عَهْدِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كُنَّ إذَا سَلَّمْنَ مِنَ الصَّلَاةِ قُمْنَ، وَثَبَتَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَمَنْ صَلَّى مِنَ الرِّجَالِ مَا شَاءَ اللهُ، فَإِذَا قَامَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَامَ الرِّجَالُ. (ن)', 'ഉമ്മുസൽമ(റ): നബി(സ)യുടെ കാലത്ത് സ്ത്രീകൾ സലാം വീട്ടിക്കഴിഞ്ഞാൽ എഴുന്നേറ്റു പോകും. നബി(സ)യും കൂടെയുള്ള പുരുഷന്മാരും ഉദ്ദേശിക്കുന്നത്ര ഇരിക്കും. നബി(സ) എഴുന്നേറ്റാൽ അവരും എഴുന്നേൽക്കും. (ന)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസൽമ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 514, 514, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=79 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 300, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا، عَنْ جُوَيْرِيَةَ بِنْتِ الْحَارِثِ رَضِيَ اللهُ عَنْهَا: أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مَرَّ عَلَيْهَا وَهِيَ فِي الْمَسْجِدِ تَدْعُو، ثُمَّ مَرَّ بِهَا قَرِيبًا مِنْ نِصْفِ النَّهَارِ، فَقَالَ لَهَا: "مَا زِلْتِ عَلَى حَالِكِ". قَالَتْ: نَعَمْ. قَالَ: "أَلَا أُعَلِّمُكِ كَلِمَاتٍ تَقُولِينَهُنَّ؟ سُبْحَانَ الله عدد خلقه، سُبْحَانَ الله عدد خلقه، سُبْحَانَ الله عدد خلقه، سُبْحَانَ الله رضا نفسه، سُبْحَانَ الله رضا نفسه، سُبْحَانَ الله رضا نفسه. سُبْحَانَ الله زنة عرشه، سُبْحَانَ الله زنة عرشه، سُبْحَانَ الله زنة عرشه. سُبْحَانَ الله مداد كلماته، سُبْحَانَ الله مداد كلماته، سُبْحَانَ الله مداد كلماته". (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ) ഒരിക്കൽ പത്നി ജുവൈരിയ്യ(റ)യുടെ അടുത്തു ചെന്നപ്പോൾ അവർ പള്ളിയിൽ പ്രാർത്ഥനയിലായിരുന്നു. ഉച്ച സമയത്ത് നബി(സ) അവളുടെ അടുത്തെത്തിയപ്പോൾ ചോദിച്ചു: "നീ പഴയ അവസ്ഥയിൽ തന്നെയാണല്ലോ?" അവർ പറഞ്ഞു: അതെ, നബി(സ) പറഞ്ഞു: "ഞാൻ നിനക്ക് ചൊല്ലാനുള്ള ചില വാക്കുകൾ പറഞ്ഞു തരട്ടെയോ? (ശേഷം തിരുമേനി(സ) ഇപ്രകാരം ചൊല്ലി): അല്ലാഹു പരിശുദ്ധനാകുന്നു, അവൻ സൃഷ്ടിച്ചവയുടെ അത്രയും (മൂന്ന് പ്രാവശ്യം), അല്ലാഹു പരിശുദ്ധനാണ് സ്വയം സംതൃപ്തനുമാണ് (മൂന്ന് പ്രാവശ്യം) അല്ലാഹു പരിശുദ്ധനാണ് അവന്റെ അർശിന്റെ അത്രയും (മൂന്ന് പ്രാവശ്യം), അല്ലാഹു പരിശുദ്ധനാണ്, അവന്റെ വാക്കുകളുടെ അത്രയും (മൂന്ന് പ്രാവശ്യം) (തസ്ബീഹുകൾ ചൊല്ലുക)". (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 514, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 301, 'عَنْ أُمِّ سَلَمَةَ رَضِيَ اللهُ عَنْهَا قَالَتْ: كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا سَلَّمَ قَامَ النِّسَاءُ حِينَ يَقْضِي تَسْلِيمَهُ وَمَكَثَ يَسِيرًا قَبْلَ أَنْ يَقُومَ. (خ)', 'ഉമ്മുസലമ(റ): നബി(സ) സലാം വീട്ടിയാൽ സ്ത്രീകൾ എഴുന്നേൽക്കും. നബി(സ) എഴുന്നേൽക്കുന്നതിനു മുമ്പ് അൽപ സമയം അവിടെത്തന്നെ ഇരിക്കും. (ബു)', 'أُمِّ سَلَمَةَ', 'ഉമ്മുസലമ(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 302, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا: أَنَّ رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنَ الْمَكْتُوبَةِ كَانَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ وَقَالَ ابْنُ عَبَّاسٍ: كُنْتُ أَعْلَمُ إذَا انْصَرَفُوا بِذَلِكَ إذَا سَمِعْتُهُ. (ق,د,ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ കാലത്ത് ജനങ്ങൾ ഫർള് നിസ്കരിച്ച് പിരിഞ്ഞ് പോകുമ്പോൾ ഉച്ചത്തിൽ ദിക്ർ ചൊല്ലാറുണ്ടായിരുന്നു. ഇബ്നുഅബ്ബാസ്(റ) പറയുന്നു: അവർ പിരിഞ്ഞുപോയി എന്ന് ഞാൻ മനസ്സിലാക്കിയിരുന്നത് അതിൽ നിന്നായിരുന്നു. (ബു,മു,ദ,ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ق','د','ن']::text[], array['ബു','മു','ദ','ന']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 303, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: جَاءَ الْفُقَرَاءُ إلَى النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: ذَهَبَ أَهْلُ الدُّثُورِ مِنَ الْأَمْوَالِ بِالدَّرَجَاتِ الْعُلَا وَالنَّعِيمِ الْمُقِيمِ، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فَضْلٌ مِنْ أَمْوَالٍ يَحُجُّونَ بِهَا، وَيَعْتَمِرُونَ وَيُجَاهِدُونَ وَيَتَصَدَّقُونَ. فَقَالَ: "أَلَا أُحَدِّثُكُمْ بِمَا إنْ أَخَذْتُمْ بِهِ أَدْرَكْتُمْ مَنْ سَبَقَكُمْ؟ وَلَمْ يُدْرِكْكُمْ أَحَدٌ بَعْدَكُمْ، وَكُنْتُمْ خَيْرَ مَنْ أَنْتُمْ بَيْنَ ظَهْرَانَيْهِمْ، إلَّا مَنْ عَمِلَ مِثْلَهُ: تُسَبِّحُونَ وَتَحْمَدُونَ وَتُكَبِّرُونَ خَلْفَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ". (خ,جه)', 'അബൂഹുറൈറ(റ): ദരിദ്രർ പ്രവാചക സന്നിധിയിൽ വന്നു പറഞ്ഞു: സമ്പന്നർ ധനവും പദവിയും മഹത്വവും അനുഗ്രഹങ്ങളും എല്ലാം കൊണ്ട് പോയിരിക്കുന്നു. ഞങ്ങൾ നിസ്കരിക്കും പോലെ അവരും നിസ്കരിക്കുന്നു. ഞങ്ങൾ നോമ്പെടുക്കുന്നത് പോലെ അവരും നോമ്പെടുക്കുന്നു, അവർക്ക് ധനമുള്ളത് കൊണ്ട് അവർ ഹജ്ജ് ചെയ്യുന്നു, ഉംറ നിർവ്വഹിക്കുന്നു, ജിഹാദ് നടത്തുന്നു, ദാനധർമ്മങ്ങൾ ചെയ്യുന്നു. നബി(സ) പറഞ്ഞു: "ഞാൻ ഒരു കാര്യം അറിയിച്ചു തരാം. അത് നിങ്ങൾ സ്വീകരിച്ചാൽ മുൻകടന്നുപോയവരോടൊപ്പം നിങ്ങൾക്കെത്താം. പിന്നീടുള്ളവരാരും നിങ്ങളോടൊപ്പമെത്തുകയില്ല. നിങ്ങൾ നിലകൊള്ളുന്ന സമൂഹത്തിൽ ഏറ്റവും ഉത്തമരായിരിക്കും നിങ്ങൾ. അപ്രകാരം ചെയ്ത കൂട്ടർക്കിടയിലൊഴികെ; എല്ലാ നിസ്കാരങ്ങൾക്കും ശേഷം മുപ്പത്തിമൂന്ന് തവണ വീതം തസ്ബീഹും, ഹംദും, തക്ബീറും ചെല്ലലാണത്." (ബു,ജ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['خ','جه']::text[], array['ബു','ജ']::text[], null, null, 515, 515, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 304, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ، عَنْ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ قَالَ: "مَنْ سَبَّحَ اللهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَحَمِدَ اللهَ ثَلَاثًا وَثَلَاثِينَ، وَكَبَّرَ اللهَ ثَلَاثًا وَثَلَاثِينَ، فَتِلْكَ تِسْعَةٌ وَتِسْعُونَ، وَقَالَ تَمَامَ الْمِائَةِ: لَا إلَهَ إلَّا اللهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. غُفِرَتْ خَطَايَاهُ، وَإنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". وَفِي رِوَايَةٍ: "مَنْ سَبَّحَ فِي دُبُرِ صَلَاةِ الْغَدَاةِ مِائَةَ تَسْبِيحَةٍ. وَهَلَّلَ مِائَةَ تَهْلِيلَةٍ، غُفِرَتْ لَهُ ذُنُوبُهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". (م,ن)', 'അബൂഹുറൈറ(റ): നബി(സ) പറഞ്ഞു: "ആരെങ്കിലും എല്ലാ നിസ്കാര ശേഷവും മുപ്പത്തിമൂന്ന് തവണ തസ്ബീഹും, മുപ്പത്തിമൂന്ന് തവണ ഹംദും, മുപ്പത്തിമൂന്ന് തവണ തക്ബീറും ചൊല്ലുകയും, ശേഷം നൂറ് പൂർത്തിയാക്കികൊണ്ട് ''അല്ലാഹുവല്ലാതെ ഒരു ദൈവവുമില്ല, അവൻ ഏകനാകുന്നു, അവന് പങ്കുകാരില്ല, അവനാകുന്നു ആധിപത്യം, അവനാകുന്നു സ്തുതി, അവൻ എല്ലാറ്റിനും കഴിവുള്ളവനാകുന്നു'' എന്ന് ചൊല്ലകയും ചെയ്താൽ അവന്റെ പാപങ്ങൾ പൊറുക്കപ്പെടും. അത് കടലിലെ കുമിളകളോളം ഉണ്ടങ്കിലും ശരി." ഒരു റിപ്പോർട്ടിൽ: "ആരെങ്കിലും സുബ്ഹി നിസ്കാരശേഷം നൂറ് പ്രാവശ്യം തസ്ബീഹും, നൂറ് തവണ തഹ്ലീലും ചൊല്ലിയാൽ അയാളുടെ പാപങ്ങൾ അല്ലാഹു പൊറുത്തു കൊടുക്കും. അത് കടലിലെ നുരയോളമുണ്ടായാലു ശരി." (മു,ന)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['م','ن']::text[], array['മു','ന']::text[], null, null, 515, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadith_variants (hadith_id, seq, arabic_text, malayalam_text) values ((select h.id from hadiths h join books b on b.id=h.book_id where b.volume_id=1 and b.book_no=20 and h.hadith_no=304), 1, 'وَفِي رِوَايَةٍ: "مَنْ سَبَّحَ فِي دُبُرِ صَلَاةِ الْغَدَاةِ مِائَةَ تَسْبِيحَةٍ. وَهَلَّلَ مِائَةَ تَهْلِيلَةٍ، غُفِرَتْ لَهُ ذُنُوبُهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". (م,ن)', null);
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 305, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "خَلَّتَانِ لَا يُحْصِيهِمَا رَجُلٌ مُسْلِمٌ إلَّا دَخَلَ الْجَنَّةَ، وَهُمَا يَسِيرٌ وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ". قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "الصَّلَوَاتُ الْخَمْسُ، يُسَبِّحُ أَحَدُكُمْ فِي دُبُرِ كُلِّ صَلَاةٍ عَشْرًا وَيَحْمَدُ عَشْرًا، وَيُكَبِّرُ عَشْرًا، فَهِيَ خَمْسُونَ وَمِائَةٌ فِي اللِّسَانِ، وَأَلْفٌ وَخَمْسُ مِائَةٍ فِي الْمِيزَانِ". وَأَنَا رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُهُنَّ بِيَدِهِ: "وَإذَا أَوَى أَحَدُكُمْ إلَى فِرَاشِهِ أَوْ مَضْجَعِهِ: سَبِّحَ ثَلَاثًا وَثَلَاثِينَ وَحَمِدَ ثَلَاثًا وَثَلَاثِينَ وَكَبَّرَ أَرْبَعًا وَثَلَاثِينَ، فَهِيَ مِائَةٌ عَلَى اللِّسَانِ وَأَلْفٌ فِي الْمِيزَانِ". قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "فَأَيُّكُمْ يَعْمَلُ فِي كُلِّ يَوْمٍ وَلَيْلَةٍ أَلْفَيْنِ وَخَمْسَ مِائَةِ سَيِّئَةٍ". قِيلَ يَا رَسُولَ اللهِ، وَكَيْفَ لَا نُحْصِيهِمَا؟ فَقَالَ: "إنَّ الشَّيْطَانَ يَأْتِي أَحَدَكُمْ وَهُوَ فِي صَلَاتِهِ فَيَقُولُ: اذْكُرْ كَذَا اذْكُرْ كَذَا، وَيَأْتِيهِ عِنْدَ مَنَامِهِ فَيُنِيمُهُ". (د,ت,ن,جه)', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ): നബി(സ) പറഞ്ഞു: "രണ്ടു കാര്യങ്ങൾ നിലനിർത്തുന്ന മുസ്ലിം സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാതിരിക്കില്ല. അത് എളുപ്പമുള്ളതാണ്, ചെയ്യുന്നവർ കുറവുമാണ്. അഞ്ചു നേരം നിസ്കരിക്കുക, എല്ലാ നിസ്കാര ശേഷവും പത്ത് തവണ തസ്ബീഹ് ചൊല്ലുക, പത്തുതവണ വീതം ''ഹംദും'' ''തക്ബീറും'' ചൊല്ലുക. അത് നാവിന്ന് നൂറ്റിഅമ്പത് ആയി, മീസാനിൽ ആയിരത്തി അഞ്ഞൂറ് ആയി." റസൂൽ(സ) കൈകൊണ്ട് അത് എണ്ണിക്കണക്കാക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. "നിങ്ങളിലാരെങ്കിലും തന്റെ വിരിപ്പിലേക്കോ കട്ടിലിലേക്കോ പോകാനൊരുങ്ങുമ്പോൾ മുപ്പത്തിമൂന്ന് തവണ ''തസ്ബീഹും'', ''ഹംദും'', മുപ്പത്തിനാല് തവണ ''തക്ബീറും'' അങ്ങനെ നൂറ് തികച്ചാൽ മീസാനിൽ അത് ആയിരം ആയിരിക്കും." നബി(സ) പറഞ്ഞു: "നിങ്ങളിലാരാണ് ഒരു പകലും രാത്രിയുമായി രണ്ടായിരത്തി അഞ്ഞൂറ് തെറ്റ് ചെയ്യുക?" അപ്പോൾ ചോദിക്കപ്പെട്ടു: അല്ലാഹുവിന്റെ ദൂതരെ, ഞങ്ങളെങ്ങിനെയാണത് എണ്ണി കണക്കാക്കുക? അപ്പോൾ നബി(സ) പറഞ്ഞു: "നിങ്ങൾ നിസ്കരിക്കുമ്പോൾ നിങ്ങളുടെ അടുത്ത് പിശാച് വരും, എന്നിട്ട് അവനോട് പറയും: നീ ഇന്നിന്ന കാര്യങ്ങൾ ഓർക്കുക, ഉറങ്ങുമ്പോൾ പിശാച് വന്ന് അവനെ ഉറക്കികളയും (അഥവാ നിസ്കാരത്തിൽ നിന്ന് ശ്രദ്ധ തിരിച്ചുകളയും)." (ദ,തു,ന,ജ)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു അംറ്(റ)', null, null, array['د','ت','ن','جه']::text[], array['ദ','തു','ന','ജ']::text[], null, null, 516, 516, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=80 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 306, 'عَنْ سَعْدِ بْنِ أَبِي وَقَّاصٍ رَضِيَ اللهُ عَنْهُ: أَنَّهُ دَخَلَ مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ عَلَى امْرَأَةٍ وَبَيْنَ يَدَيْهَا نَوًى، أَوْ حَصًى، تُسَبِّحُ بِهِ، فَقَالَ: "أُخْبِرُكِ بِمَا هُوَ أَيْسَرُ عَلَيْكِ مِنْ هَذَا، أَوْ أَفْضَلُ" فَقَالَ: "سُبْحَانَ اللهِ عَدَدَ مَا خَلَقَ فِي السَّمَاءِ، وَسُبْحَانَ اللهِ عَدَدَ مَا خَلَقَ فِي الْأَرْضِ، وَسُبْحَانَ اللهِ عَدَدَ مَا خَلَقَ بَيْنَ ذَلِكَ، وَسُبْحَانَ اللهِ عَدَدَ مَا هُوَ خَالِقٌ، وَاللهُ أَكْبَرُ مِثْلُ ذَلِكَ، وَالْحَمْدُ لِلهِ مِثْلُ ذَلِكَ، وَلَا إلَهَ إلَّا اللهُ مِثْلُ ذَلِكَ، وَلَا حَوْلَ وَلَا قُوَّةَ إلَّا بِاللهِ مِثْلُ ذَلِكَ". (د,ت)', 'സഅ്ദ് ബ്നു അബീ വഖാസ്(റ): ഒരു ദിവസം പ്രവാചക(സ)ന്റെ കൂടെ അദ്ദേഹം ഒരു സ്ത്രീയുടെ അടുത്തേക്ക് ചെന്നു. ആ സമയം അവൾ കയ്യിൽ ഈത്തപ്പഴക്കുരുവോ ചരൽകല്ലോ ഉപയോഗിച്ച് തസ്ബീഹ് ചൊല്ലുകയായിരുന്നു. ആ സമയം പ്രവാചകൻ(സ) അവളോട് ചോദിച്ചു: "ഇതിനെക്കാൾ എളുപ്പമായ അല്ലെങ്കിൽ ശ്രേഷ്ഠമായ ഒരു കാര്യം ഞാൻ നിനക്ക് പറഞ്ഞു തരട്ടയോ." എന്നിട്ട് പ്രവാചകൻ(സ) പറഞ്ഞു: "സുബ്ഹാനല്ലാഹി അദദ മാ ഖലഖ ഫിസ്സമാഇ വ സുബ്ഹാനല്ലാഹി അദദ മാ ഖലഖ ഫിൽഅർളി വ സുബ്ഹാനല്ലാഹി അദദ മാ ഖലഖ ബൈന ദാലിക വ സുബ്ഹാനല്ലാഹി അദദ മാ ഹുവ ഖാലിഖുൻ" (ആകാശത്തും ഭൂമിയിലും അവരണ്ടിനുമിടക്കും അല്ലാഹു സൃഷ്ടിച്ചതും സൃഷ്ടിച്ചേക്കുന്നതുമായ സൃഷ്ടികളുടെ എണ്ണത്തിന്റെ അത്രയും തവണ ഞാൻ അവന്റെ പരിശുദ്ധിയെ വാഴ്ത്തുന്നു) എന്നും ഇപ്രകാരം ''അല്ലാഹു അക്ബർ'' കൊണ്ടും ''അൽഹംദുലില്ല'' കൊണ്ടും ''ലാഇലാഹ ഇല്ലല്ല'' കൊണ്ടും ''ലാഹൗല വലാ ഖുവ്വത്ത ഇല്ലാ ബില്ല'' (അല്ലാഹുവിന്നല്ലാതെ യാതൊരു ശക്തിയും കഴിവുമില്ല) കൊണ്ടും തുടങ്ങി ഈ ദിക്റ് ചൊല്ലുക." (ദ,തു)', 'سَعْدِ بْنِ أَبِي وَقَّاصٍ', 'സഅ്ദ് ബ്നു അബീ വഖാസ്(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 516, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 307, 'عَنْ يُسَيْرَةَ، أَخْبَرَتْهَا: "أَنَّ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَمَرَهُنَّ أَنْ يُرَاعِينَ بِالتَّكْبِيرِ وَالتَّقْدِيسِ وَالتَّهْلِيلِ، وَأَنْ يَعْقِدْنَ بِالْأَنَامِلِ فَإِنَّهُنَّ مَسْئُولَاتٌ مُسْتَنْطَقَاتٌ". (د)', 'യുസൈറ(റ): ഒരു ദിവസം പ്രവാചകൻ(സ) മഹതിയോട് കൽപിച്ചു: "നിങ്ങൾ തക്ബീർ, തഹ്ലീൽ, തഖ്ദീസ് എന്നിവയെ പൂർണമായി പരിഗണിക്കുകയും വിരൽതുമ്പ് കൊണ്ട് അവയെ എണ്ണം പിടിക്കുകയും വേണം. കാരണം അവയെല്ലാം സംസാരിപ്പിക്കപ്പെടുന്നവയും ചോദിക്കപ്പെടുന്നവയുമാണ്." (ദ)', 'يُسَيْرَةَ، أَخْبَرَتْهَا', 'യുസൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 308, 'عَنْ عَبْدِ اللهِ بْنِ عَمْرٍو رَضِيَ اللهُ عَنْهُ قَالَ: رَأَيْتُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُ التَّسْبِيحَ، قَالَ ابْنُ قُدَامَةَ: بِيَمِينِهِ. (د,ت,ن)', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ): പ്രവാചകൻ(സ) തസ്ബീഹ് ചൊല്ലുമ്പോൾ എണ്ണം പിടിക്കുന്നത് ഞാൻ കണ്ടിട്ടുണ്ട്. ഇബ്നുഖുദാമ പറഞ്ഞു: വലത്തെ കൈകൊണ്ട് (ആണ് എണ്ണം പിടിച്ചത്). (ദ,തു,ന)', 'عَبْدِ اللهِ بْنِ عَمْرٍو', 'അബ്ദുല്ലാഹിബ്നു ഉമർ(റ)', null, null, array['د','ت','ن']::text[], array['ദ','തു','ന']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 309, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ مِنْ عِنْدِ جُوَيْرِيَةَ، وَكَانَ اسْمُهَا بُرَّةَ فَحَوَّلَ اسْمَهَا، فَخَرَجَ وَهِيَ فِي مُصَلَّاهَا وَرَجَعَ وَهِيَ فِي مُصَلَّاهَا، فَقَالَ: "لَمْ تَزَالِي فِي مُصَلَّاكِ هَذَا؟" قَالَتْ: نَعَمْ، قَالَ: "قَدْ قُلْتُ بَعْدَكِ أَرْبَعَ كَلِمَاتٍ ثَلَاثَ مَرَّاتٍ لَوْ وُزِنَتْ بِمَا قُلْتِ لَوَزَنَتْهُنَّ: سُبْحَانَ اللهِ وَبِحَمْدِهِ عَدَدَ خَلْقِهِ وَرِضَا نَفْسِهِ وَزِنَةَ عَرْشِهِ وَمِدَادَ كَلِمَاتِهِ". (م,د)', 'ഇബ്നുഅബ്ബാസ്(റ): ജുവൈരിയ(റ)യുടെ അടുത്ത് നിന്ന് പ്രവാചകൻ(സ) പുറപ്പെട്ടു. മഹതിയുടെ പേര് ബർറത്ത് എന്നായിരുന്നു. പ്രവാചകൻ(സ) ആ പേര് മാറ്റി. പ്രവാചകൻ(സ) പോകുമ്പോൾ മഹതി നിസ്കാരപ്പായയിലായിരുന്നു. മടങ്ങി വന്നപ്പോഴും അങ്ങനെത്തന്നെ. അപ്പോൾ പ്രവാചകൻ(സ) ചോദിച്ചു: "ഇതുവരെയും നീ ഈ മുസ്വല്ലയിൽ തന്നെയായിരുന്നോ?" മഹതി പറഞ്ഞു: അതെ. ആ സമയം പ്രവാചകൻ(സ) പറഞ്ഞു. ഞാൻ നിന്റെ ഈ സമയ ശേഷം നാലു വചനങ്ങൾ മൂന്നു തവണ ചൊല്ലി. ആ വചനങ്ങൾ നീ ചൊല്ലിയവയുമായി തൂക്കിനോക്കി തുലനം ചെയ്താൽ ഞാൻ ചൊല്ലിയതായിരിക്കും ഭാരം കൂടുതൽ. ആ വചനങ്ങൾ ''അല്ലാഹു വിന്റെ സൃഷ്ടികളുടെ എണ്ണമനുസരിച്ചും അവന്റെ തൃപ്തിയുടെ തോതനുസരിച്ചും അവന്റെ സിംഹാസനത്തിന്റെ ഭംഗിയനുസരിച്ചും അവന്റെ വചനങ്ങളുടെ എണ്ണമനുസരിച്ചും അവനെ സ്തുതിക്കുകയും അവന്റെ പരിശുദ്ധതയെ വാഴ്ത്തുകയും ചെയ്യുന്നു'' എന്നിവയാണ്." (മു,ദ)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['م','د']::text[], array['മു','ദ']::text[], null, null, 517, 517, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 310, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: قَالَ أَبُو ذَرٍّ: يَا رَسُولَ اللهِ، ذَهَبَ أَصْحَابُ الدُّثُورِ بِالْأُجُورِ، يُصَلُّونَ كَمَا نُصَلِّي وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فُضُولُ أَمْوَالٍ يَتَصَدَّقُونَ بِهَا، وَلَيْسَ لَنَا مَالٌ نَتَصَدَّقُ بِهِ، فَقَالَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ: "يَا أَبَا ذَرٍّ، أَلَا أُعَلِّمُكَ كَلِمَاتٍ تُدْرِكُ بِهِنَّ مَنْ سَبَقَكَ وَلَا يَلْحَقُكَ مَنْ خَلْفَكَ إلَّا مَنْ أَخَذَ بِمِثْلِ عَمَلِكَ" قَالَ: بَلَى يَا رَسُولَ اللهِ، قَالَ: "تُكَبِّرُ اللهَ [عَزَّ وَجَلَّ] دُبُرَ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَتَحْمَدُهُ ثَلَاثًا وَثَلَاثِينَ، وَتُسَبِّحُهُ ثَلَاثًا وَثَلَاثِينَ، وَتَخْتِمُهَا بِلَا إلَهَ إلَّا اللهُ وَحْدَهُ، لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، غُفِرَتْ لَهُ ذُنُوبُهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ". (د)', 'അബൂഹുറൈറ(റ): ഒരിക്കൽ അബൂദുർറ(റ) പ്രവാചകർ(സ)യോട് പറഞ്ഞു: പ്രവാചകരേ, പ്രതിഫലങ്ങളെല്ലാം സമ്പന്നർ കൊണ്ടുപോയി. ഞങ്ങൾ നിസ്കരിക്കുന്ന പോലെ അവരും നിസ്കരിക്കുന്നു. അവരും ഞങ്ങളെപ്പോലെ നോമ്പനുഷ്ഠിക്കുന്നു. അവർ അവരുടെ മിച്ചമുള്ള സമ്പത്തു കൊണ്ട് ദാനധർമ്മം ചെയ്യുന്നു. ഞങ്ങൾക്ക് ദാനധർമ്മത്തിന് സമ്പത്തില്ല. അന്നേരം പ്രവാചകൻ(സ) പറഞ്ഞു: "അബൂദർറേ, ഞാൻ നിനക്ക് ചില വാചകങ്ങൾ പഠിപ്പിച്ചു തരാം. അതുകൊണ്ട് നിന്നെ മുൻകടന്നവരുടെ കൂടെ നീ എത്തും. നിന്റെ പിന്നിലുള്ളവർ നീയുമായി ഒരിക്കലും അടുക്കുകയില്ല. ഇതുപോലെ പ്രവർത്തിച്ചവരൊഴികെ." ആ സമയം അബൂദർറ് അതെ എന്ന് പറഞ്ഞു. അന്നേരം പ്രവാചകൻ(സ) പറഞ്ഞു: "എല്ലാ നമസ്കാര ശേഷവും മുപ്പത്തിമൂന്ന് പ്രാവശ്യം നീ തക്ബീർ ചൊല്ലുക. അതു പോലെ മുപ്പത്തിമൂന്ന് തവണ നീ അൽഹംദുലില്ലാ ചൊല്ലുക. അപ്രകാരം മുപ്പത്തിമൂന്ന് തവണ തസ്ബീഹ് ചൊല്ലുക. അവസാനം ''ലാഇലാഹ ഇല്ലല്ലാ വഹ്ദഹൂ ലാ ശരീകലഹു ലഹുൽ മുൽകു വലഹുൽ ഹംദു വഹുവ അലാ കുല്ലി ശൈഇൻ ഖീർ'' (അല്ലാഹുവല്ലാതെ ആരാധ്യനില്ല, അവൻ ഏകനാണ്, അവന് പങ്കുകാരില്ല, അവനാണ് ആധിപത്യം, അവനാകുന്നു സർവ്വസ്തുതിയും, അവൻ എല്ലാത്തിനും കഴിയുന്നവനാകുന്നു) എന്നത് കൊണ്ട് അവസാനിപ്പിക്കുക. എന്നാൽ കടലിലെ നുരയോളം നിന്റെ ദോഷമുണ്ടെങ്കിലും അവ നിനക്ക് പൊറുക്കപ്പെടും." (ദ)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د']::text[], array['ദ']::text[], 'عَزَّ وَجَلَّ', null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=81 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 311, 'عَنْ مُسْلِمِ بْنِ أَبِي بَكْرَةَ قَالَ: كَانَ أَبِي – رَضِيَ اللهُ عَنْهُ – يَقُولُ فِي دُبُرِ الصَّلَاةِ: اللَّهُمَّ إنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ، وَعَذَابِ الْقَبْرِ. فَكُنْتُ أَقُولُهُنَّ، فَقَالَ أَبِي: أَيْ بُنَيَّ، عَمَّنْ أَخَذْتَ هَذَا؟ قُلْتُ: عَنْكَ. قَالَ: إنَّ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُهُنَّ فِي دُبُرِ الصَّلَاةِ. (ن)', 'മുസ്ലിമുബ്നു അബീബക്റ(റ): എന്റെ പിതാവ് നിസ്കാര ശേഷം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു; അല്ലാഹുവേ, കുഫ്റിൽ നിന്നും, ദാരിദ്ര്യത്തിൽ നിന്നും, ഖബ്റിലെ ശിക്ഷയിൽ നിന്നും ഞാൻ നിന്നോട് കാവൽ തേടുന്നു. ഞാനും അപ്രകാരം പറഞ്ഞപ്പോൾ എന്റെ പിതാവ് ചോദിച്ചു: മോനേ, നീ ആരിൽ നിന്നാണ് ഇത് മനസ്സിലാക്കിയത്. ഞാൻ പറഞ്ഞു: താങ്കളിൽ നിന്ന്. അദ്ദേഹം പറഞ്ഞു: നബി(സ) നിസ്കാരശേഷം ഇപ്രകാരം പറയാറുണ്ടായിരുന്നു. (ന)', 'مُسْلِمِ بْنِ أَبِي بَكْرَةَ قَالَ', 'മുസ്ലിമുബ്നു അബീബക്റ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=82 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 312, 'عَنْ يَزِيدَ بْنِ الْأَسْوَدِ رَضِيَ اللهُ عَنْهُ: أَنَّهُ صَلَّى مَعَ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ، فَلَمَّا صَلَّى انْحَرَفَ. (ن)', 'യസീദുബ്നുൽ അസ്വദ്(റ): അദ്ദേഹം നബി(സ)യോടൊപ്പം സുബ്ഹ് നിസ്കരിച്ചു, നിസ്കാരശേഷം നബി(സ) (മറ്റൊരു ഭാഗത്തേക്ക്) മാറി ഇരുന്നു. (ന)', 'يَزِيدَ بْنِ الْأَسْوَدِ', 'യസീദുബ്നുൽ അസ്വദ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 518, 518, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=83 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 313, 'عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللهُ عَنْهُمَا قَالَ: إنَّمَا كُنْتُ أَعْلَمُ انْقِضَاءَ صَلَاةِ رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالتَّكْبِيرِ. (ن)', 'ഇബ്നുഅബ്ബാസ്(റ): നബി(സ)യുടെ നിസ്കാരം കഴിഞ്ഞു എന്ന് ഞാൻ മനസ്സിലാക്കിയത് തക്ബീറിൽ നിന്നായിരുന്നു. (ന)', 'ابْنِ عَبَّاسٍ', 'ഇബ്നുഅബ്ബാസ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=84 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 314, 'عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللهُ عَنْهُ قَالَ: أَمَرَنِي رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ الْمُعَوِّذَاتِ دُبُرَ كُلِّ صَلَاةٍ. (ن)', 'ഉഖ്ബതുബ്നു ആമിർ(റ): എല്ലാ നിസ്കാര ശേഷവും മുഅവ്വിദാത്ത് (സൂറത്തുന്നാസ്, അൽ ഫലഖ്) പാരായണം നടത്താൻ നബി(സ) എന്നോട് കൽപിച്ചു. (ന)', 'عُقْبَةَ بْنِ عَامِرٍ', 'ഉഖ്ബതുബ്നു ആമിർ(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=85 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 315, 'عَنْ عَبْدِ اللهِ بْنِ مَسْعُودٍ رَضِيَ اللهُ عَنْهُ قَالَ: لَا يَجْعَلْ أَحَدُكُمْ لِلشَّيْطَانِ شَيْئًا مِنْ صَلَاتِهِ، يَرَى أَنَّ حَقًّا عَلَيْهِ أَنْ لَا يَنْصَرِفَ إلَّا عَنْ يَمِينِهِ لَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ كَثِيرًا يَنْصَرِفُ عَنْ يَسَارِهِ. (ق)', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ) പറയുന്നു: നിങ്ങളിലാരും തന്നെ തന്റെ നിസ്കാരത്തിൽ നിന്ന് ഒരംശവും പിശാചിന് വിട്ടുകൊടുക്കരുത്. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ച ശേഷം വലതു വശത്തുകൂടെ മാത്രമേ എഴുന്നേറ്റു പോകാവൂ എന്ന് ചിലർ ധരിക്കുന്നു. നിസ്കാരത്തിൽ നിന്ന് വിരമിച്ച ശേഷം ഇടതു വശത്തു കൂടെ പ്രവാചകൻ(സ) എഴുന്നേറ്റു പോകുന്നത് ഞാൻ പലതവണ കണ്ടിട്ടുണ്ട്. (ബു,മു)', 'عَبْدِ اللهِ بْنِ مَسْعُودٍ', 'അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്(റ)', null, null, array['ق']::text[], array['ബു','മു']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=86 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 316, 'عَنْ سِمَاكِ بْنِ حَرْبٍ قَالَ: قُلْتُ لِجَابِرِ بْنِ سَمُرَةَ رَضِيَ اللهُ عَنْهُ: كُنْتَ تُجَالِسُ رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: نَعَمْ، كَانَ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا صَلَّى الْفَجْرَ جَلَسَ فِي مُصَلَّاهُ حَتَّى تَطْلُعَ الشَّمْسُ، فَيَتَحَدَّثُ أَصْحَابُهُ: يَذْكُرُونَ حَدِيثَ الْجَاهِلِيَّةِ، وَيُنْشِدُونَ الشِّعْرَ، وَيَضْحَكُونَ، وَيَتَبَسَّمُ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ. (ن)', 'സിമാക്ബ്നു ഹർബ്(റ): ജാബിറുബ്നു സമുറ(റ)വിനോട് ഞാൻ ചോദിച്ചു: നീ നബി(സ)യോടൊപ്പം ഇരുന്നിരുന്നോ? അദ്ദേഹം പറഞ്ഞു: അതെ, നബി(സ) ഫജ്ർ നിസ്കരിച്ചാൽ സൂര്യൻ ഉദിക്കുവോളം മുസല്ലയിൽ ഇരിക്കും. അപ്പോൾ അവിടുത്തെ അനുചരന്മാർ സംസാരിക്കും. അവർ ജാഹിലിയ്യാ സംഭവങ്ങൾ സ്മരിക്കും. കവിത പാടും. അവർ ചിരിക്കും, നബി(സ) പുഞ്ചിരിക്കും. (ന)', 'سِمَاكِ بْنِ حَرْبٍ قَالَ', 'സിമാക്ബ്നു ഹർബ്(റ)', null, null, array['ن']::text[], array['ന']::text[], null, null, 519, 519, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=87 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 317, 'عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: حَذْفُ السَّلَامِ سُنَّةٌ. قَالَ عَبْدُ اللهِ بْنُ الْمُبَارَكِ: يَعْنِي أَنْ لَا يَمُدَّهُ مَدًّا. حَسَنٌ صَحِيحٌ. (د,ت)', 'അബൂഹുറൈറ(റ): സലാം നീട്ടാതിരിക്കൽ സുന്നത്താണ്. അബ്ദുല്ലാഹിബ്നു മുബാറക് പറഞ്ഞു: സലാമിനെ നീട്ടരുത് എന്നാണ് ഇത് കൊണ്ട് അർത്ഥമാക്കുന്നത്. (ഹദീസ് ഹസനും സ്വഹീഹുമാണെന്ന് തുർമുദി പറയുന്നു). (ദ,തു)', 'أَبِي هُرَيْرَةَ', 'അബൂഹുറൈറ(റ)', null, null, array['د','ت']::text[], array['ദ','തു']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=88 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 318, 'عَنْ أَنَسِ بْنِ حَكِيمٍ الضَّبِّيِّ قَالَ: أَتَى الْمَدِينَةَ، فَلَقِيَ أَبَا هُرَيْرَةَ رَضِيَ اللهُ عَنْهُ قَالَ: فَنَسَبَنِي فَانْتَسَبْتُ لَهُ، فَقَالَ: يَا فَتَى، أَلَا أُحَدِّثُكَ حَدِيثًا؟ قَالَ: قُلْتُ: بَلَى رَحِمَكَ اللهُ، قَالَ الرَّاوِي: وَأَحْسَبُهُ ذَكَرَهُ عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، قَالَ: "إنَّ أَوَّلَ مَا يُحَاسَبُ النَّاسُ بِهِ يَوْمَ الْقِيَامَةِ مِنْ أَعْمَالِهِمُ: الصَّلَاةُ، قَالَ: يَقُولُ رَبُّنَا جَلَّ وَعَزَّ لِمَلَائِكَتِهِ، وَهُوَ أَعْلَمُ: انْظُرُوا فِي صَلَاةِ عَبْدِي: أَتَمَّهَا أَمْ نَقَصَهَا، فَإنْ كَانَتْ تَامَّةً كُتِبَتْ لَهُ تَامَّةً، وَإنْ كَانَ انْتَقَصَ مِنْهَا شَيْئًا قَالَ: انْظُرُوا، هَلْ لِعَبْدِي مِنْ تَطَوُّعٍ؟ فَإنْ كَانَ لَهُ تَطَوُّعٌ قَالَ: أَتِمُّوا لِعَبْدِي فَرِيضَتَهُ مِنْ تَطَوُّعِهِ، ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى ذَاكُمْ". (د,ن,جه)', 'അനസുബ്നു ഹകീം(റ): ഞാൻ മദീനയിലെത്തിയപ്പോൾ അബൂഹുറൈറ(റ)യെ കണ്ടുമുട്ടി. അങ്ങനെ അദ്ദേഹം തന്റെ വംശത്തെ (തന്നെ) സ്വയം പരിചയപ്പെടുത്തുകയും, ഞാൻ അദ്ദേഹത്തിന്റെ വംശവുമായി ചേരുകയും ചെയ്തു. എന്നിട്ടദ്ദേഹം ചോദിച്ചു: ഏ യുവാവേ! ഞാൻ നിനക്ക് ഒരു ഹദീസ് പറഞ്ഞു തരട്ടെയോ? ഞാൻ പറഞ്ഞു: അതെ, അല്ലാഹു താങ്കൾക്കു കരുണ ചെയ്യട്ടെ, നിവേദകൻ പറയുന്നു: ഈ ഹദീസ് അദ്ദേഹം പ്രവാചകനിൽ നിന്നാണ് ഉദ്ധരിച്ചത് എന്നാണ് ഞാൻ വിചാരിക്കുന്നത്. അദ്ദേഹം പറഞ്ഞു: "ജനങ്ങൾ അന്ത്യദിനത്തിൽ അവരുടെ കർമ്മങ്ങളെ സംബന്ധിച്ചു വിചാരണ ചെയ്യപ്പെടുമ്പോൾ ആദ്യമായി വിചാരണ ചെയ്യപ്പെടുക നിസ്കാരത്തെക്കുറിച്ചായിരിക്കും. അബൂഹുറൈറ തുടർന്നു പറഞ്ഞു: മഹത്വവാനും പ്രതാപിയുമായ അല്ലാഹു തന്റെ മലക്കുകളോട് - അല്ലാഹു അക്കാര്യം നന്നായി അറിയുന്നവനാണ് എന്നിരിക്കെ തന്നെ - ചോദിക്കും: ''എന്റെ അടിമയുടെ നിസ്കാരം ന്യൂനതയുള്ളതാണോ അതോ പൂർണ്ണമായതാണോ എന്നു നോക്കുക'' അങ്ങനെയവ പൂർണ്ണമായതാണെങ്കിൽ അവന് വേണ്ടി സമ്പൂർണ്ണമായി രേഖപ്പെടുത്തപ്പെടും. അതിൽ വല്ലതും ന്യൂനത വന്നിട്ടുണ്ടെങ്കിൽ അവൻ പറയും: ''എന്റെ അടിമക്കു വേണ്ടി വല്ല ഐച്ഛിക കർമ്മവുമുണ്ടോ എന്ന് നിങ്ങൾ നോക്കുക''. അവന് വല്ല ഐച്ഛിക കർമ്മവുമുണ്ടെങ്കിൽ അല്ലാഹു മലക്കുകളോടു പറയും: എന്റെ അടിമക്ക് അവന്റെ ഐച്ഛിക കർമ്മം കൊണ്ട് അവന്റെ നിർബ്ബന്ധ കർമ്മങ്ങളെ പൂർണ്ണമായതാക്കിക്കൊടുക്കുക. പിന്നെ എല്ലാ കർമ്മങ്ങളും അപ്രകാരമാണ് പരിഗണിക്കപ്പെടുക." (ദ,ന,ജ)', 'أَنَسِ بْنِ حَكِيمٍ الضَّبِّيِّ قَالَ', 'അനസുബ്നു ഹകീം(റ)', null, null, array['د','ن','جه']::text[], array['ദ','ന','ജ']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 319, 'عَنْ تَمِيمٍ الدَّارِيِّ رَضِيَ اللهُ عَنْهُ، عَنِ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ، بِهَذَا الْمَعْنَى، قَالَ: "ثُمَّ الزَّكَاةُ مِثْلُ ذَلِكَ، ثُمَّ تُؤْخَذُ الْأَعْمَالُ عَلَى حَسَبِ ذَلِكَ". (د,جه)', 'തമീദുദ്ദാരി(റ): മേൽ ഹീദീസിന്റെ അതേ ആശയത്തിൽ അവിടുന്ന് പറഞ്ഞു: "പിന്നെ സകാത്ത് അപ്രകാരം പരിഗണിക്കപ്പെടും, പിന്നെ മറ്റ് കർമ്മങ്ങൾ അപ്രകാരം തന്നെ പരിഗണിക്കപ്പെടും." (ദ,ജ)', 'تَمِيمٍ الدَّارِيِّ', 'തമീദുദ്ദാരി(റ)', null, null, array['د','جه']::text[], array['ദ','ജ']::text[], null, null, 520, 520, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=89 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 320, 'عَنْ سَمُرَةَ بْنِ جُنْدَبٍ رَضِيَ اللهُ عَنْهُ قَالَ: كَانَ النَّبِيُّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ إذَا صَلَّى صَلَاةً أَقْبَلَ عَلَيْنَا بِوَجْهِهِ. (خ)', 'സമുറതുബ്നു ജുൻദബ്(റ): നബി(സ) നിസ്കാരം കഴിഞ്ഞാൽ ഞങ്ങൾക്ക് നേരെ തിരിഞ്ഞിരിക്കാറുണ്ടായിരുന്നു. (ബു)', 'سَمُرَةَ بْنِ جُنْدَبٍ', 'സമുറതുബ്നു ജുൻദബ്(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 321, 'عَنْ زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ رَضِيَ اللهُ عَنْهُ أَنَّهُ قَالَ: صَلَّى لَنَا رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ صَلَاةَ الصُّبْحِ بِالْحُدَيْبِيَةِ عَلَى إثْرِ سَمَاءٍ كَانَتْ مِنَ اللَّيْلَةِ، فَلَمَّا انْصَرَفَ أَقْبَلَ عَلَى النَّاسِ، فَقَالَ: "هَلْ تَدْرُونَ مَاذَا قَالَ رَبُّكُمْ؟" قَالُوا: اللهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: "أَصْبَحَ مِنْ عِبَادِي مُؤْمِنٌ بِي وَكَافِرٌ، فَأَمَّا مَنْ قَالَ مُطِرْنَا بِفَضْلِ اللهِ وَرَحْمَتِهِ، فَذَلِكَ مُؤْمِنٌ بِي وَكَافِرٌ بِالْكَوْكَبِ، وَأَمَّا مَنْ قَالَ: بِنَوْءِ كَذَا وَكَذَا فَذَلِكَ كَافِرٌ بِي، وَمُؤْمِنٌ بِالْكَوْكَبِ". (خ)', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനി(റ): ഹുദൈബിയ്യയിൽ വെച്ച് രാത്രി പെയ്ത മഴക്ക് ശേഷം നബി(സ) ഞങ്ങളേയും കൊണ്ട് സുബ്ഹി നിസ്കരിച്ചു, നിസ്കാര ശേഷം ജനങ്ങളുടെ നേർക്ക് തിരിഞ്ഞുകൊണ്ട് പറഞ്ഞു: "നിങ്ങളുടെ നാഥൻ എന്താണ് പറഞ്ഞത് എന്ന് നിങ്ങൾക്കറിയുമോ?" അവർ പറഞ്ഞു: അല്ലാഹുവും റസൂലുമാണ് കൂടുതൽ അറിവുള്ളവർ. റസൂൽ(സ) പറഞ്ഞു: "എന്റെ അടിമകൾ എന്നിൽ വിശ്വസിക്കുന്നവരും നിഷേധിക്കുന്നവരുമാകും. ഞങ്ങൾക്ക് അല്ലാഹുവിന്റെ ഔദാര്യം കൊണ്ട് മഴ ലഭിച്ചു എന്ന് ആർ പറഞ്ഞുവോ, അവൻ എന്നിൽ വിശ്വസിച്ചവനും നക്ഷത്രങ്ങളെ (കഴിവിനെ) നിഷേധിച്ചവരുമാണ്. ഇന്നിന്ന നക്ഷത്രങ്ങളാണ് ഞങ്ങൾക്ക് മഴ നൽകിയത് എന്നാരെങ്കിലും പറഞ്ഞാൽ, അവൻ എന്നെ നിഷേധിച്ചവനും നക്ഷത്രങ്ങളിൽ വിശ്വസിച്ചവനുമായി." (ബു)', 'زَيْدِ بْنِ خَالِدٍ الْجُهَنِيِّ', 'സൈദുബ്നു ഖാലിദുൽ ജുഹനി(റ)', null, null, array['خ']::text[], array['ബു']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
insert into hadiths (book_id, chapter_id, hadith_no, arabic_text, malayalam_text, narrator_ar, narrator_ml, explanation_ml, hadith_label, source_codes_ar, source_codes_ml, grading_note_ar, grading_note_ml, page_start, page_end, needs_review) select b.id, c.id, 322, 'عَنْ عُقْبَةَ رَضِيَ اللهُ عَنْهُ قَالَ: صَلَّيْتُ وَرَاءَ النَّبِيِّ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ بِالْمَدِينَةِ الْعَصْرَ فَسَلَّمَ، ثُمَّ قَامَ مُسْرِعًا فَتَخَطَّى رِقَابَ النَّاسِ إلَى بَعْضِ حُجَرِ نِسَائِهِ، فَفَزِعَ النَّاسُ مِنْ سُرْعَتِهِ، فَخَرَجَ عَلَيْهِمْ فَرَأَى أَنَّهُمْ عَجِبُوا مِنْ سُرْعَتِهِ، فَقَالَ: "ذَكَرْتُ شَيْئًا مِنْ تِبْرٍ عِنْدَنَا فَكَرِهْتُ أَنْ يَحْبِسَنِي، فَأَمَرْتُ بِقِسْمَتِهِ". (خ,ن)', 'ഉഖ്ബ(റ): ഞാൻ നബി(സ)യുടെ പിന്നിൽ മദീനയിൽ വെച്ച് അസ്ർ നിസ്കരിച്ചു, സലാം വീട്ടിയശേഷം നബി(സ) ധൃതിയിൽ ജനങ്ങളുടെ മുതുകിനെ ചാടിക്കടന്ന് തന്റെ ഭാര്യമാരിൽ ആരുടേയോ മുറിയിലേക്കു പോയി. നബി(സ)യുടെ ധൃതി കണ്ട് ജനങ്ങൾ പരിഭ്രാന്തരായി. പിന്നീട് ജനങ്ങളിലേക്ക് വന്നു. തന്റെ ഈ പ്രവർത്തി ജനങ്ങളിൽ ആശ്ചര്യം സൃഷ്ടിച്ചിട്ടുണ്ടെന്ന് മനസ്സിലാക്കിയ തിരുമേനി(സ) പറഞ്ഞു: "എന്റെ അടുക്കൽ വിഹിതം വെച്ചിട്ടില്ലാത്ത ഒരു സ്വർണ്ണക്കട്ടി ഉണ്ടെന്ന് ഓർമ്മ വന്നു. അത് എന്നെ (നിസ്കാരത്തിൽ) തടഞ്ഞു വെക്കുമെന്ന് ഞാൻ ഭയന്നു. അത് കൊണ്ടത് വീതംവെക്കാൻ കൽപിച്ചു." (ബു,ന)', 'عُقْبَةَ', 'ഉഖ്ബ(റ)', null, null, array['خ','ن']::text[], array['ബു','ന']::text[], null, null, 521, 521, false from books b left join chapters c on c.book_id=b.id and c.chapter_no=90 where b.volume_id=1 and b.book_no=20 on conflict (book_id, hadith_no) do update set chapter_id=excluded.chapter_id, arabic_text=excluded.arabic_text, malayalam_text=excluded.malayalam_text, source_codes_ar=excluded.source_codes_ar, source_codes_ml=excluded.source_codes_ml, grading_note_ar=excluded.grading_note_ar, grading_note_ml=excluded.grading_note_ml, narrator_ar=excluded.narrator_ar, narrator_ml=excluded.narrator_ml, explanation_ml=coalesce(excluded.explanation_ml, hadiths.explanation_ml), hadith_label=excluded.hadith_label, page_start=excluded.page_start, page_end=excluded.page_end, needs_review=excluded.needs_review;
